SELECT 'moj-all-verified-judgments-review-002-chunk-189' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"9d55df4e-c3c7-5e4a-95f7-470b5396c255","document_type":"judgment","category":"judicial","subcategory":"general","title":"تركة -قسمة إجبار -ال وصية لوارث -من سعى يف نقض ما مت على يديه فسعيه مردود عليه -شراء عقار ليس عليه صك ال يفيد التملك وال يغني عن استخراج حجة االستحكام -ألحد الورثة حق الشفعة يف العقار املباع ملجاورته له -احلكم ببيع امليراث اململوك بالصك باملزاد العلني ولكل وارث نصيبه الشرعي.","document_number":"33440804","case_number":"33205648","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":"الدائرة احلقوقية األولى مبحكمة الاستئناف مبنطقة عسير .","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/28","year":"1434","subject":"تركة -قسمة إجبار -ال وصية لوارث -من سعى يف نقض ما مت على يديه فسعيه مردود عليه -شراء عقار ليس عليه صك ال يفيد التملك وال يغني عن استخراج حجة االستحكام -ألحد الورثة حق الشفعة يف العقار املباع ملجاورته له -احلكم ببيع امليراث اململوك بالصك باملزاد العلني ولكل وارث نصيبه الشرعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪33440804 :‬تاريخه‪1433/10/28:‬هـ‬\n                   ‫رقم القضية‪33205648:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34179279‬تاريخه‪1434/4/6 :‬هـ‬\n\n\n‫تركــة ‪ -‬قســمة إجبــار ‪ -‬ال وصيــة لــوارث ‪ -‬مــن ســعى يف نقــض مــا مت‬\n‫علــى يديــه فســعيه مــردود عليــه ‪ -‬شــراء عقــار ليــس عليــه صــك ال‬\n‫يفيــد التملــك وال يغنــي عــن اســتخراج حجــة االســتحكام ‪ -‬ألحــد‬\n‫الورثــة حــق الشــفعة يف العقــار املبــاع ملجاورتــه لــه ‪ -‬احلكــم ببيــع امليــراث‬\n        ‫اململــوك بالصــك باملــزاد العلنــي ولــكل وارث نصيبــه الشــرعي‪.‬‬\n\n\n\n\n‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (إن اهلل قــد أعطــى كل ذي حــق حقــه‬\n                                                     ‫فــا وصيــة لــوارث)‪.‬‬\n‫‪ .2‬القاعــدة الفقهيــة‪ :‬مــن ســعى يف نقــض مــا مت علــى يديــه فســعيه‬\n                                                          ‫مــردود عليــه‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليهمــا بأنــه تــويف مــورث موكليــه‬\n‫وانحصــر إرثــه يف موكليــه واملدعــى عليهمــا وقــد تــرك بيتــن وحوش ـ ًا‬\n‫ويطلــب قســمة التركــه‪ .‬اجــاب املدعــى عليهمــا باملصادقــه علــى‬\n‫ا واجــاب احدهمــا بــان المانــع مــن القســمه‬    ‫الدعــوى جملــه وتفصي ـ ً‬\n‫وســيتولى شــراء احــد البيتــن وموافــق علــى بيــع العقــار االخــر واعطائــه‬\n‫حصتــه منــه ‪ ،‬اضــاف املدعــى عليــه االخــر أنــه موافــق علــى قســمة‬\n\n                                                                                         ‫‪330‬‬\n\f      ‫البيــت الشــعبي وهــو ملــك لوالــده امــا البيــت االخــر اململــوك بصــك‬\n      ‫فهــو ملــك لــه ومورثهــم أخــرج صــك ًا عليــه لكونــه كان يعمــل يف‬\n      ‫القطــاع العســكري ويطلــب اثبــات ملكيتــه لــه ‪.‬وأضــاف أن والــده قــد‬\n      ‫اوصــى لــه بالعقــار ‪ ،‬انكــر املدعــى الوصيــه وأن االصــل انــه الوصيــة‬\n      ‫لــوراث علــى فــرض ثبوتهــا‪ ،‬جــرت الكتابــه لقســم اخلبــراء الجــل تثمــن‬\n      ‫العقــارات وقســمتها بالتراضــي مــا امكــن فــورد جوابهــم متضمن ـ ًا ان‬\n      ‫العقــار اململــوك بالصــك يقــدر مبلــغ ثالثمائــة الــف ريــال والعقــار الثانــي‬\n      ‫يقــدر بســتة اآلف ريــال والميكــن القســمة بــن الورثــه بطريــق التراضــي‬\n      ‫ولــن يقســم دون عــوض‪ ،‬واملدعــى عليــه يدعــي أن الصــك داخــل عليــه‬\n      ‫يف ملكــه مــن اجلهــة الشــرقية وحســب طبيعــة البيــت ومشــمول الصــك‬\n      ‫وجدنــا الصــك حســب طبيعــة البيــوت داخــل يف غرفتــن مــن بيت املدعى‬\n      ‫عليــه مت ســؤال املدعــى عليــه ‪ ...‬بشــأن الغرفتــن الداخلــه يف الصــك‬\n      ‫هــل ميلــك عليهــا صــك ًا مســتقال فأجــاب بالنفــي ‪ ،‬ثــم أبــرز املدعــي‬\n      ‫وكالــه وصيــه للمــورث مصدقــه مــن شــيخ القبيلــه وفيهــا قــول املــورث ان‬\n      ‫البيــت الــذي يســكن فيــه فهــو بيتــي وباقــي أوالدي واخواتهــم الثــاث و‬\n      ‫والدتهــم ومؤرخــه الوصية‪1421/5/11‬ه ـ ويبطــل هــذا الصــك مضمــون‬\n      ‫الصــك اآلخــر ويبطــل بذلــك الوصيــه املزعومه التي ابرزهــا املدعى عليه‬\n      ‫وقــرر اجلميــع موافقتهــم أن يشــتري املدعــى عليــه البيــت الشــعبي الــذي‬\n      ‫قدرتــه اللجنــه بســتة اآلف ريــال ‪ .‬بنــاء علــى ماتقــدم مــن الدعــوى ومبــا أن‬\n      ‫طــريف الدعــوى ســبق منهمــا حصــر التركــه ووقعــا علــى ذلــك مبــا فيهــم‬\n      ‫املدعــى عليــه ‪ ،‬ومبــا ان املدعــى عليــه ظهــر تناقضــه ومحاولــة تأخيــر‬\n      ‫البــت يف الدعــوى ‪ ،‬ومبــا أن القاعــدة الشــرعيه علــى ان مــن ســعى يف‬\n      ‫نقــض مــامت علــى يديــه فســعيه مــردود عليــه ‪ ،‬كيــف واليوجــد للمدعــى‬\n\n\n‫‪331‬‬\n\f‫عليــه صــك يدفــع هــذا الصــك ولذلــك جميعــا‪ -:‬ثبــت شــراء ‪ ...‬للبيــت‬\n‫الشــعبي املوصــوف وإلزامــه بدفــع قيمتــه للورثــه كل حســب نصيبــه‬\n‫كمــا مت احلكــم علــى جميــع الورثــة ببيــع البيــت اململــوك بالصــك باملــزاد‬\n‫العلنــي ولــكل وارث نصيبــه‪ ،‬اقتنــع املدعــى وكالــه واملدعــى عليــه‪....‬‬\n‫وقــرر املدعــى عليــه اآلخــر عــدم القناعــة مت التصديــق علــى احلكــم مــن‬\n        ‫الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة عســير ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة بخميس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بخميــس مشــيط برقــم ‪ 33205648‬وتاريــخ ‪ 1433/03/22‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33546382‬وتاريــخ ‪ 1433/03/22‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1433/10/28‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 00‬‬\n‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بصفتــه وكيــا عــن كل مــن ‪ ...‬و‪ ...‬و‪ ...‬أبنــاء‪ ...‬و‪ ...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل خميــس مشــيط رقــم ‪370705023155‬‬\n‫يف ‪ 1433/2/29‬ه ـ والتــي تخولــه حــق املطالبــة واملرافعــة واملدافعــة‬\n‫واملخاصمــة ولــه حــق اإلقــرار واإلنــكار والصلــح وقبــول احلكــم‬\n‫واالعتــراض وبصفتــه وكيــا عــن ‪ ...‬و‪ ...‬أبنــاء ‪ ...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض رقــم ‪ 3311678‬يف‬\n‫‪ 1433/3/1‬هـ والتي تخوله حق املطالبة واملرافعة واملدافعة واملخاصمة‬\n‫ولــه حــق اإلقــرار واإلنــكار والصلــح وقبــول احلكــم واالعتــراض‬\n‫وحضــر حلضــوره‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n\n                                                                                    ‫‪332‬‬\n\f      ‫و‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬فادعــى األول‬\n      ‫قائــا لقــد تــويف مــورث موكلــي ‪ ...‬مبوجــب صــك حصــر الورثــة رقــم‬\n      ‫‪32196793‬يف ‪1432/8/9‬ه ـ وانحصــر إرثــه يف موكلــي ويف املدعــى‬\n      ‫عليهــم وقــد خلــف املتوفــى التركــة التاليــة ‪ -1‬البيــت واحلــوش الواقــع يف‬\n      ‫قريــة ‪...‬اململــوك بالصــك الصــادر مــن محكمــة أحدرفيــدة برقــم ‪187‬يف‬\n      ‫‪1415/5/19‬ه ـ ‪ -2‬البيــت الشــعبي الواقــع يف قريــة ‪ ...‬وهــو عبــارة عــن‬\n      ‫منــزل متهــدم قــدمي ومســاحته صغيــرة جــدا ويقــع يف قريــة مهجــورة وال‬\n      ‫يوجــد لــه طريــق للســيارة يحــده مــن الغــرب ملــك ‪ ...‬ومــن اجلنــوب ملــك‬\n      ‫‪ ...‬ولــم نتمكــن مــن عمــل رفــع مســاحي عليــه لصغــر مســاحته ومبــا أن‬\n      ‫املدعــى عليهمــا ال يرغبــان يف قســمة التركــة فإننــا نطلــب إجبارهــم‬\n      ‫علــى ذلــك هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليهمــا صادقــا‬\n      ‫علــى الدعــوى جملــة وتفصيــا وأجــاب املدعــى عليــه ‪ ...‬ال مانــع لــدي‬\n      ‫مــن القســمة وســأتولى شــراء البيــت الشــعبي وأوافــق علــى بيــع العقــار‬\n      ‫الثانــي وإعطائــي حصتــي منــه وأضــاف املدعــى عليــه ‪ ...‬أمــا البيــت‬\n      ‫الشــعبي فأوافــق علــى قســمته وهــو ملــك لوالــدي وأمــا البيــت اململــوك‬\n      ‫بصــك فهــو ملــك لــي فوالــدي أخــرج عليــه صــك وأنــا كنــت أعمــل يف‬\n      ‫القطــاع العســكري يف أزمــة اخلليــج وأطلــب إثبــات ملكــي لــه هكــذا‬\n      ‫أجابــا بعــد ذلــك جــرى ســؤال الطرفــن هــل علــى مورثكــم ديــن أو لــه‬\n      ‫وصيــة فأجابــا ليــس عليــه ديــن وال وصيــة وأضــاف املدعــى عليــه ‪ ...‬بــأن‬\n      ‫والــدي قــد أوصــى لــي بكامــل البيــت املذكــور يف الدعــوى اململــوك‬\n      ‫بالصــك وأبــرز صــورة لورقــة يدعــي أنهــا وصيــة والــده وذكــر بأنــه ال‬\n      ‫يعلــم عــن محــل أصلهــا وهــي مؤرخــة يف ‪1402/12/25‬ه ـ بعــد ذلــك‬\n      ‫جــرى اإلطــاع علــى صــك حصــر الورثــة وعلــى الــوكاالت وعلــى أســاس‬\n\n\n‫‪333‬‬\n\f‫الصــك املذكــور فوجدتهــا طبــق ماذكــر كمــا ســبق منــا طلــب طــريف‬\n‫الدعــوى حصــر تركــة مورثهــم فوقــع اجلميــع يف تاريــخ ‪1433/5/9‬ه ـ‬\n‫محضــرا لــدي يفيــد انحصــار التركــة يف الصــك والبيــت الشــعبي‬\n‫املذكوريــن يف الدعــوى وصــادق املدعــى عليــه ‪ ...‬علــى ذلــك كمــا‬\n‫جــرى منــي بعــث الصــك املذكــور ملصــدره لإلفــادة عــن ســجله باخلطــاب‬\n‫رقــم ‪33668403‬يف ‪1433/4/10‬ه ـ فوردنــا خطابهــم رقــم ‪859‬يف‬\n‫‪1433/4/24‬هـ واملتضمن أن الصك ال يزال ســاري املفعول كما جرى‬\n‫منــي الكتابــة لقســم الصلــح بهــذه احملكمــة حملاولــة اإلصــاح بــن‬\n‫الطرفــن وذلــك بخطابــي رقــم ‪33546382‬يف ‪1433/4/10‬ه ـ فوردتنــي‬\n‫منهــم اإلفــادة بتعــذر ذلــك باخلطــاب رقــم ‪33546382‬يف ‪1433/4/19‬ه ـ‬\n‫وبعــرض مــا ذكــره املدعــى عليــه ‪ ...‬علــى املدعــي وكالــة أجــاب أمــا‬\n‫البيــت اململــوك بالصــك فهــو ملــك للمــورث ثابــت شــرعا والوصيــة التــي‬\n‫أبرزهــا املدعــى عليــه ‪ ...‬ال صحــة لهــا ثــم إنــه يف األصــل ال وصيــة لــوارث‬\n‫علــى فــرض ثبوتهــا ثــم إنهــا مؤرخــة يف عــام ‪1402‬ه ـ والصــك يف عــام‬\n‫‪1415‬ه ـ ثــم إن املــورث لــم يفــرغ الصــك وكان ذلــك بإمكانــه فهــو لــم‬\n‫يتوفــى إال يف عــام ‪1423‬ه ـ وقــد حضــر املدعــى عليــه ‪ ...‬لديكــم وقــرر‬\n‫بــأن البيــت لوالــده يف محضــر حصــر التركــة بعــد ذلــك جــرى دراســة‬\n‫الصــك الــذي يدعــي ‪ ...‬ملكيتــه فوجــد مايلــي ‪ -1‬املنهــي هــو مــورث‬\n‫طــريف الدعــوى ‪ -2‬الصــك يحــدد امللــك حــدا وذرعــا ومســاحة ‪ -3‬يف‬\n‫الســطر الثامــن عشــر حضــر املدعــى عليــه ‪ ...‬وكيــا عــن والــده يف‬\n‫إثبــات ملكيــة البيــت للمنهــي وقــرر لــدى القاضــي يف حينــه مصادقتــه‬\n‫علــى مــا أنهــى بــه موكلــه حــدا وذرعــا وملــكا ومســاحة ‪ -4‬أحضــر‬\n‫املدعــى عليــه ‪ ...‬البينــة علــى أن مورثــه املالــك للمنهــى عنــه ‪ -5‬أثبــت‬\n\n\n                                                                                      ‫‪334‬‬\n\f      ‫مصــدر الصــك امللــك للمــورث واكتســب احلكــم القطعيــة بتصديــق‬\n      ‫محكمــة االســتئناف (انتهــى) كمــا ســبق منــي الكتابــة لقســم اخلبــراء‬\n      ‫بهــذه احملكمــة باخلطــاب رقــم ‪33546382‬يف ‪1433/5/9‬ه ـ ألجــل‬\n      ‫تثمــن العقــارات وقســمتها بالتراضــي مــا أمكــن فــورد قرارهــم رقــم‬\n      ‫‪33546382‬يف ‪1433/6/9‬ه ـ واملتضمــن أنــه بالوقــوف برفــق مكتبــن‬\n      ‫عقاريــن اتضــح أن العقــار اململــوك بالصــك يقــدر مببلــغ ثالثمائــة ألــف‬\n      ‫ريــال والعقــار الثانــي منــزل قــدمي متهــدم ومســاحته صغيــرة جــدا ويقــع يف‬\n      ‫قريــة مهجــورة وال يوجــد لــه طريــق للســيارة إال مــع الــوادي ويقــدر بســتة‬\n      ‫آالف ريــال (انتهــى) بعــد ذلــك جــرت الكتابــة لقســم اخلبــراء وذلــك‬\n      ‫باخلطــاب رقــم ‪33788135‬يف ‪1433/7/5‬ه ـ بطلــب تطبيــق الصــك‬\n      ‫واإلفــادة عــن إمكانيــة القســمة بالتراضــي دون الرجــوع للبيــع باملــزاد‬\n      ‫العلنــي فوردنــا قرارهــم رقــم ‪331777814‬يف ‪1433/10/8‬ه ـ وفيــه ((‬\n      ‫نفيــد فضيلتكــم فإنــه مت وقوفنــا وجــرى تطبيــق الصــك فوجــد مطابقــا‬\n      ‫وال ميكــن القســمة بــن الورثــة بطريــق التراضــي ولــن ينقســم بــدون رد‬\n      ‫عــوض واملدعــى عليــه ‪ ...‬يدعــي أن الصــك داخــل عليــه يف ملكــه مــن‬\n      ‫اجلهــة الشــرقية وحســب طبيعــة البيــت ومشــمول الصــك وبيــت املدعــى‬\n      ‫عليــه املتشــابكة بجانــب بعــض فقــد وجدنــا الصــك حســب طبيعــة‬\n      ‫البيــوت داخــل يف غرفتــن مــن بيــت املدعــى عليــه (انتهــى) بعــد ذلــك‬\n      ‫جــرى ســؤال املدعــى عليــه ‪ ...‬عــن الغرفتــن الداخلــة يف الصــك هــل‬\n      ‫ميلــك عليهــا صــكا مســتقال فأجــاب ال وبســؤاله ملــاذا لــم تثبــت ملــكك‬\n      ‫أو تعــارض علــى صــك أبيــك فأجــاب لــم أكــن موجــودا وال أعلــم عــن‬\n      ‫الصــك املذكــور شــيئا إال حــن معارضــة البلديــة هكــذا أجــاب بعــد‬\n      ‫ذلــك جــرى عــرض مــا ذكــر علــى املدعــي وكالــة فأجــاب جميــع مــا‬\n\n\n‫‪335‬‬\n\f‫حــواه الصــك ملــك للمــورث واملدعــى عليــه ‪...‬يعانــد باقــي الورثــة وال‬\n‫يرغــب يف القســمة مــع أنــه مــن ســعى إلخــراج الصــك لوالــده وهــو مــن‬\n‫أحضــر البينــة يف ذلــك الوقــت هكــذا أجــاب وأضاف املدعــى عليه ‪ ...‬لم‬\n‫أحضــر البينــة أثنــاء نظــر احلجــة عنــد القاضــي هكــذا أضــاف ثــم أبــرز‬\n‫املدعــي وكالــة وصيــة للمــورث مصدقــة مــن شــيخ القبيلــة وفيهــا قــول‬\n‫املــورث (أمــا البيــت الــذي أنــا ســاكن فيــه ويحدنــي مــن الشــرق بيــت ‪...‬‬\n‫هــو بيتــي وباقــي أوالدي ‪ ...‬و‪ ...‬وأخواتهــم الثــاث ووالدتهــم ‪ )...‬والوصيــة‬\n‫مؤرخــة يف ‪1421/5/11‬ه ـ وأضــاف ال نطالــب بهــا ولكنهــا تؤكــد أن‬\n‫البيــت للمــورث يحــده مــن الشــرق املدعــى عليــه ‪...‬وهــذا مضمــون الصــك‬\n‫ويبطــل بذلــك الوصيــة املزعومــة التــي أبرزهــا ‪...‬هكــذا أضــاف بعــد‬\n‫ذلــك قــرر اجلميــع موافقتهــم بــأن يشــتري املدعــى عليــه ‪ ...‬البيــت الشــعبي‬\n‫الــذي قدرتــه اللجنــة بســتة آالف ريــال يكــون نصيــب الزوجــة ســبعمائة‬\n‫وخمســن ريــاال ونصيــب ‪ ...‬و‪ ...‬و‪ ...‬تســعمائة وأربعــة وخمســون ريــاال‬\n‫وخمســة وخمســون هللــة لــكل واحــد منهــم ونصيــب ‪ ...‬و‪ ...‬و‪ ...‬أربعمائــة‬\n‫وســبعة وســبعون ريــاال وســبعة وعشــرون هللــة لــكل واحــدة منهــم وبعــد‬\n‫ذلــك جــرى عــرض الوصيــة التــي أبرزهــا املدعــي وكالــة علــى املدعــى‬\n‫عليهمــا فأجــاب ‪...‬ال أقرهــا وال أنكرهــا وال أطالــب بهــا وأجــاب ‪...‬ال‬\n‫أعلــم عنهــا وال أطالــب بهــا فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة‬\n‫ومبــا أن طــريف الدعــوى ســبق منهمــا حصــر التركــة لــدي أوال ووقعــا‬\n‫علــى ذلــك مبــا فيهــم املدعــى عليــه ‪ ...‬ومبــا أن املدعــى عليــه ‪ ...‬ظهــر‬\n‫تناقضــه ومحاولتــه تأخيــر البــت يف هــذه القســمة وتعطيلهــا مــع أن البيت‬\n‫اململــوك بالصــك املشــار إليــه قــد حضــره ممثــا عــن والــده أثنــاء إثباتــه‬\n‫مصادقــا علــى ملكيــة والــده لــه مســاحة وحــدا وذرعــا وأحضــر علــى‬\n\n\n                                                                                     ‫‪336‬‬\n\f      ‫ذلــك البينــة يف حينهــا والقاعــدة الشــرعية تنــص علــى أن مــن ســعى يف‬\n      ‫نقــض مــامت علــى يديــه فســعيه مــردود عليــه كيــف وال يوجــد للمدعــى‬\n      ‫عليــه ‪ ...‬صــك يدفــع هــذا الصــك ومــا أبــرزه مــن وصيــة فمــردودة بالصــك‬\n      ‫الشــرعي املــؤرخ بعدهــا مبــا يزيــد عــن عشــر ســنوات عــاوة علــى أن‬\n      ‫إقــراره لدينــا ولــدى مصــدر احلجــة دليــل ال يقبــل الرجــوع عنــه ويف تأخيــر‬\n      ‫القضيــة أكثــر ضــرر واضــح وتعطيــل ال فائــدة منــه وعليــه وبنــاء علــى‬\n      ‫إقــرار املدعــى عليــه ‪...‬بشــراء البيــت الشــعبي وإقــرار البقيــة باملوافقــة‬\n      ‫مقابــل أن تدفــع لهــم أنصبائهــم واســتنادا علــى قــول املصطفــى صلــى اهلل‬\n      ‫عليــه وســلم ( إن اهلل قــد أعطــى كل ذي حــق حقــه فــا وصيــة لــوارث‬\n      ‫) لذلــك جميعــا فقــد ثبــت لــدي شــراء ‪ ...‬للبيــت الشــعبي املوصــوف يف‬\n      ‫الدعــوى وألزمتــه بدفــع قيمتــه للورثــة كل حســب نصيبــه املقــرر شــرعا‬\n      ‫وأفهمتــه بــأن شــراءه ال يفيــد التملــك وال يغنــي عــن اســتخراج حجــة‬\n      ‫االســتحكام كمــا حكمــت علــى جميــع الورثــة ببيــع البيــت اململــوك‬\n      ‫بالصــك املشــار إليــه باملــزاد العلنــي ولــكل وارث نصيبــه مــن قيمتــه نقدا‬\n      ‫وال مينــع أحــد الورثــة مــن الشــراء ويكــون األحــق بذلــك املدعــى عليــه‬\n      ‫‪...‬فلــه حــق الشــفعة وصرفــت النظــر عمــا دفــع بــه املدعــى عليــه ‪ ...‬مــن‬\n      ‫ملكيــة البيــت لعــدم ثبــوت موجبــه وبــكل ذلــك قضيــت وبعــرض ذلــك‬\n      ‫علــى الطرفــن اقنــع املدعــي وكالــة واملدعــى عليــه ‪ ...‬وقــرر املدعــى‬\n      ‫عليــه ‪ ...‬عــدم القناعــة فجــرى تســليمه صــورة مــن صــك احلكــم علــى‬\n      ‫أن يقــدم اعتراضــه خــال شــهر مــن تاريخــه وبــاهلل التوفيــق وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد وحــرر يف ‪1433/10/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪337‬‬\n\f‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 3416069‬وتاريــخ‬\n‫‪1434/01/06‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪... /‬‬\n‫برقــم ‪ 33440804‬وتاريــخ ‪1433/10/28‬ه ـ اخلــاص بدعــوى ‪ /‬ورثــة ‪...‬‬\n‫و‪ ...‬ضــد ‪ ... /‬و‪ ...‬يف تركــة وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املوافقــة علــى احلكــم واهلل‬\n‫املوفــق‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪338‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":330,"source_page_end":338,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0be3fb1663e4707229b234f192c95f453ed3fd7218451e48303f7682d6dca955","normalized_text_hash":"766dbb8524c6f0e0f3b066a8fde7b007986d169816a1145dc9384e79c05f4fd9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p330-33440804"},{"id":"7aed11a7-c981-56b5-ac53-3e1f84a6c66c","document_type":"judgment","category":"judicial","subcategory":"general","title":"تركة -دعوى محاسبة -تنازل املدعين عن إحالة الدعوى حملاسب قانوني -محاسبة إدارة تركة -محاولة الصلح بن الورثة - مطالبة مبحاسبة يف ريع عقارات -الرجوع عن اإلقرار بحق آلدمي غير مقبول -قول األمن مقبول بيمينه ما لم تقم بينة على خالفه -ثبوت الدعوى.","document_number":"33334176","case_number":"13838","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/9","year":"1434","subject":"تركة -دعوى محاسبة -تنازل املدعين عن إحالة الدعوى حملاسب قانوني -محاسبة إدارة تركة -محاولة الصلح بن الورثة - مطالبة مبحاسبة يف ريع عقارات -الرجوع عن اإلقرار بحق آلدمي غير مقبول -قول األمن مقبول بيمينه ما لم تقم بينة على خالفه -ثبوت الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33334176 :‬تاريخه‪1433/7/9 :‬هـ‬\n                            ‫رقم الدعوى‪13838 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪34312231‬تاريخه‪1434/9/3 :‬هـ‬\n\n\n      ‫تركــة ‪ -‬دعــوى محاســبة‪ -‬تنــازل املدعيــن عــن إحالــة الدعــوى حملاســب‬\n      ‫قانونــي ‪ -‬محاســبة إدارة تركــة ‪ -‬محاولــة الصلــح بــن الورثــة ‪-‬‬\n      ‫مطالبــة مبحاســبة يف ريــع عقــارات‪ -‬الرجــوع عــن اإلقــرار بحــق آلدمــي‬\n      ‫غيــر مقبــول‪ -‬قــول األمــن مقبــول بيمينــه مــا لــم تقــم بينــة علــى‬\n                                                        ‫خالفــه‪ -‬ثبــوت الدعــوى‪.‬‬\n\n\n\n\n      ‫مــا هــو معتبــر عنــد عامــة أهــل العلــم أن الرجــوع عــن اإلقــرار يف حقــوق‬\n                                                               ‫اآلدمــي غيــر معتبــر‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــا املدعــن بــأن مورثهــم خلــف مــن ضمــن تركتــه عــدة‬\n      ‫عقــارات موصوفــة يف دعواهــم وأن املدعــى عليــه هــو املتولــي علــى تأجيــر‬\n      ‫تلــك العقــارات منــذ وفــاة املــورث إال أنــه يســلم الورثــة مبالــغ ماليــة دون‬\n      ‫بيــان مقــدار نصيــب كل واحــد منهــم كمــا أنــه أقــر بــأن ملورثهــم لديــه‬\n      ‫مبالــغ ماليــة مذكــورة يف الدعــوى‪ ،‬ولــذا فقــد طلبــا توضيــح دخــل تلــك‬\n      ‫العقــارات للمــدة املاضيــة وإجــراء محاســبة عليهــا وعلــى املبالــغ التــي‬\n      ‫أقــر بهــا ملورثهــم وتســليمهم املتبقــي مــن نصيبهــم منهــا‪ ،‬أقــر املدعــى‬\n      ‫عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه لــم يقــر للورثــة إال مببلــغ واحــد‬\n\n‫‪339‬‬\n\f‫فقــط عبــارة عــن عجــز علــى التركــة كان يظــن أنــه يتحملــه ثــم علــم‬\n‫أنــه يكــون مــن التركــة فقــام بحســمه منهــا كمــا أنــه ســلم جــزء منــه‬\n‫للمكلــف بقســمة التركــة وأمــا املبلــغ الثانــي فهــو داخــل يف األول‬\n‫وجــزء منــه وليــس مبلغ ـ ًا مســتقال عنــه‪ ،‬حصــر املدعــون دعواهــم يف‬\n‫مطالبــة املدعــى عليــه باملبالــغ التــي أقــر بهــا للتركــة وتنازلــوا عــن طلــب‬\n‫احملاســبة‪ ،‬طلبــت احملكمــة مــن املدعــن بينــة علــى إقــرار املدعــى عليــه‬\n‫باملبلــغ الثانــي فعجــزوا عــن إحضارهــا وطلبــوا ميينــه علــى نفيــه وعلــى‬\n‫أنــه ســلم جــزء مــن املبلــغ األول للمكلــف بقســمة التركــة فأداهــا طبــق‬\n‫مــا طلــب منــه‪ ،‬طلبــت احملكمــة مــن املدعــى عليــه بينــة علــى مــا دفــع‬\n‫بــه مــن أن املبلــغ األول الــذي أقــر بــه عجــز علــى التركــة فعجــز عــن‬\n‫إثبــات ذلــك‪ ،‬املدعــى عليــه أقــر باملبلــغ األول لصالــح الورثــة ثــم رجــع عــن‬\n‫إقــراره والرجــوع عــن اإلقــرار يف حقــوق اآلدمــي غيــر معتبــر كمــا أنــه‬\n‫أدى اليمــن علــى تســليم جــزء منــه لقاســم التركــة‪ ،‬قضــت احملكمــة‬\n‫بإلــزام املدعــى عليــه بــأن يســلم للمدعــن املبلــغ األول بعــد خصــم مــا‬\n‫ادعــى تســليمه منــه لقاســم التركــة وصرفــت النظــر عــن مطالبــة الورثــة‬\n‫بباقــي املبلــغ املدعــى بــه بعــد حلــف املدعــى عليــه اليمــن املطلوبــة‪،‬‬\n‫قنــع املدعــون باحلكــم وعــارض عليــه املدعــى عليــه‪ ،‬قــررت محكمــة‬\n                                           ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪340‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬مســاعد رئيــس احملكمــة العامــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 13838‬وتاريــخ ‪1431/10/12‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 3154393‬وتاريــخ ‪ 1431/10/12‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪ 1432/08/12‬ه ـ افتتحــت اجللســة الســاعة ‪: 26‬‬\n      ‫‪ 10‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫األصيــل عــن نفســه والوكيــل عــن ‪ .... .....‬أصالــة عــن نفســه وبصفتــه‬\n      ‫وصي ـ ًا علــى ‪ .....‬مبوجــب صــك القوامــة الصــادر مــن هــذه احملكمــة‬\n      ‫ا عــن ‪ .....‬بالوكالــة‬      ‫برقــم ‪ 9/100/545‬وتاريــخ ‪1429/3/8‬ه ـ ووكيـ ً‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 24421‬وتاريخ‬\n      ‫‪1432/4/16‬ه ـ وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة باملدينــة املنــورة برقــم ‪ 18434‬وتاريــخ ‪1432/3/26‬ه ـ وعــن ‪.....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n      ‫برقــم ‪ 20900‬وتاريــخ ‪1432/4/7‬ه ـ كمــا حضــر ‪ .....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬األصيــل عــن نفســه والوكيــل عــن ‪.....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n      ‫برقــم ‪ 98727‬وتاريــخ ‪1429/11/4‬ه ـ وعــن ‪ ..... ..... ..... ..... ..... .....‬بنــات‬\n      ‫‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n      ‫املنــورة برقــم ‪ 18729‬وتاريــخ ‪1429/3/22‬ه ـ وعــن ‪ .....‬مبوجب الوكالة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 11777‬وتاريخ‬\n      ‫‪1429/2/23‬ه ـ وعــن ‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العدل‬\n\n‫‪341‬‬\n\f‫الثانيــة باملدينــة املنــورة برقــم ‪ 61496‬وتاريــخ ‪1429/10/15‬ه ـ وعــن ‪.....‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n‫برقــم ‪ 66053‬وتاريــخ ‪1429/11/7‬ه ـ وعــن‪ .....‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 61497‬وتاريخ‬\n‫‪1429/10/15‬ه ـ وادعيــا علــى احلاضــر معهمــا ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬قائلــن يف دعواهمــا عليــه لقــد تــويف‬\n‫مورثنــا ومــورث املدعــى عليــه ‪ .....‬بتاريــخ ‪1429/2/14‬ه ـ وخلــف مــن‬\n‫ضمــن تركتــه عمــارة يف حــي ‪...‬جوار مســجد ‪ ...‬مبحافظــة جدة اململوك‬\n‫لــه بالصــك الصــادر مــن محكمــة جــدة برقــم ‪ 1549‬وتاريــخ ‪/ 5 / 4‬‬\n‫‪ 1400‬ه ـ وعمــارة يف حــي ‪ .....‬تقاطــع شــارع األميــر ‪ ...‬مــع شــارع ‪...‬‬\n‫مبحافظــة جــدة اململــوك لــه بالصــك الصــادر مــن محكمــة جــدة برقــم‬\n‫‪ 1613‬وتاريــخ ‪1421/8/26‬ه ـ ومبنــى مؤجــر علــى مطبــخ املســمى‬\n‫مبطبــخ ‪...‬الواقــع يف حــي ‪ ...‬باملدينــة املنــورة اململــوك لــه بالصــك الصــادر‬\n‫مــن كتابــة العــدل األولــى باملدينــة املنــورة برقــم ‪ 1/1254‬وتاريــخ‬\n‫‪1401/11/25‬ه ـ ومنــذ وفــاة مورثنــا واملتولــي علــى هــذه العقــارات‬\n‫وتأجيرهــا املدعــى عليــه وقــد طلبنــا منه إيضاح حســابات هــذه العقارات‬\n‫ا فلــم‬  ‫وبيــان نصيــب كل واحــد مــن الورثــة منهــا وتســليمه كام ـ ً‬\n‫يتجــاوب معنــا وإمنــا يســلمنا مبالــغ دون بيــان مقــدار نصيــب كل واحــد‬\n‫منــا كمــا أنــه أقــر ببيعــه لورشــتني ملورثنــا مببلــغ ثالثمائــة وســتني ألــف‬\n‫ريــال وأقــر بــأن ملورثنــا يف حســابه مبلــغ تســعمائة وســبعة وثالثــن ألف ـ ًا‬\n‫وثالثمائــة وثمانيــة وخمســن ريــال إضافــة إلــى مبلــغ خمســمائة ألــف‬\n‫ريــال لديــه ملورثنــا وقــد طالبنــاه بإجــراء احملاســبة يف ذلــك ويتهــرب مــن‬\n‫ذلــك نطلــب إلزامــه بتوضيــح دخــل هــذه العقــارات للمــدة املاضيــة‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫ومحاســبته عليهــا وعلــى املبالــغ التــي أقــر بهــا وتســليمنا املتبقــي مــن‬\n      ‫نصيبنــا منهــا علم ـ ًا بأنــه ســلم القاســم مبلــغ مليــون وتســعمائة وثالثــة‬\n      ‫عشــر ألف ـ ًا وخمســمائة ريــال عــن نصيــب التركــة الــذي لديــه وكان‬\n      ‫نصيب كل ابن منها مبلغ تســعة وســبعني ألف ًا ومائة وخمســة وخمســن‬\n      ‫ريــا ًال هــذه دعوانــا وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه مــا‬\n      ‫ذكــره املدعيــان يف دعواهمــا مــن وفــاة مورثنــا وأنــه خلــف مــن ضمــن‬\n      ‫تركتــه العقــارات املذكــورة فهــذا صحيــح وقــد كنــت قائم ـ ًا علــى‬\n      ‫العقــارات التــي يف جــدة وهــي عمــارة حــي ‪...‬وعمــارة حــي ‪ ...‬مــن تاريــخ‬\n      ‫شــرائهما إلــى الوقــت احلاضــر أمــا املبنــى الــذي يف املدينــة واملؤجــر علــى‬\n      ‫مطبــخ ‪...‬فلــم أســتلم أجــاره إال مــن بعــد دخــول والــدي يف غيبوبــة عــام‬\n      ‫‪1427‬ه ـ حتــى الوقــت احلاضــر ومجمــوع أجــارات عمــارة حــي ‪...‬مــن تاريخ‬\n      ‫شــرائها إلــى نهايــة عــام ‪1431‬ه ـ هــو مبلــغ مليــون ومائتــن وســبعة‬\n      ‫وخمســن ألف ـ ًا وثمامنائــة وريــاالن ومجمــوع أجــارات عمــارة حــي ‪ ...‬مــن‬\n      ‫تاريــخ شــرائها حتــى نهايــة عــام ‪1431‬ه ـ هــو مبلــغ مليــون وثالثمائــة‬\n      ‫وتســعة وثالثــن ألفـ ًا وســتمائة وعشــرة ريــاالت ومجمــوع أجــارات مطبــخ‬\n      ‫‪...‬مــن عــام ‪1427‬ه ـ حتــى نهايــة عــام ‪1431‬ه ـ هــو مبلــغ مائتــن وســتني‬\n      ‫ألف ريال كما أنني قمت بتقبيل ورشــتني كان مورثهما مســتأجرهما‬\n      ‫مــن ‪ .....‬مبوافقــة الورثــة ومجمــوع القيمــة مــع أجــرة ســنة قبــل التقبيــل‬\n      ‫هــي مبلــغ ثالثمائــة وســتني ألــف ريــال وأمــا مــا ذكــره املدعيــان مــن أننــي‬\n      ‫ســبق أن أقريــت مببالــغ للتركــة علــي فصحيــح أننــي ســبق أن ذكــرت‬\n      ‫ذلــك للورثــة وملصفــي التركــة أن للتركــة لــدي مبلــغ تســعمائة وســبعة‬\n      ‫وثالثــن ألف ـ ًا وثالثمائــة وثمانيــة وخمســن ريــا ًال هــي عبــارة عــن دخــل‬\n      ‫العقــارات وبقيــة التركــة إلــى وفــاة والــدي ولــم أقــر بــأن للتركــة يف‬\n\n\n‫‪343‬‬\n\f‫ذمتــي خمســمائة ألــف ريــال إضافــة إلــى املبلــغ وإمنــا ذكــرت أن هنــاك‬\n‫عجــز علــى التركــة هــو عبــارة عــن خســائر يف األســهم مببالــغ كانــت‬\n‫لوالــدي واســتثمرتها يف محفظتــي يف األســهم حيــث كانــت اخلســائر‬\n‫قرابــة أربعمائــة ألــف ريــال إضافــة إلــى مبلــغ مائــة ألــف ريــال مــن املبالــغ‬\n‫التــي كانــت لوالــدي قمــت بصرفهــا علــى عائلــة والــدي يف حياتــه‬\n‫ومجمــوع ذلــك مبلــغ خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة‬\n‫وســتني ريــا ًال وكنــت أظــن أننــي أحتمــل هــذا املبلــغ ثــم علمت أن خســائر‬\n‫األســهم واملبالــغ التــي أنفقتهــا علــى العائلــة تكــون مــن التركــة فقمــت‬\n‫بحســمها مــن املبالــغ التــي للتركــة علــي وســلمت الباقــي للورثــة وملصفــي‬\n‫التركــة ولــم يبــق لهــم لــدي أي شــيء فجــرى ســؤاله عــن املبالــغ التــي‬\n‫اســتثمرها لوالــده يف األســهم مــن أيــن أخذهــا فقــال إن والــدي ســبق أن‬\n‫ســلمني مبلــغ خمســة ماليــن ومائتــن وســبعني ألــف ريــال منهــا مبلــغ‬\n‫اثنــن مليــون ومائــة ألــف ريــال اســتلمتها مبوجــب شــيكني مــن والــدي‬\n‫ومبلــغ ثالثــة مليــون وســبعني ألــف ريــال مبوجــب أربــع حــواالت مــن ر‪.....‬‬\n‫بحقــوق كانــت لديــه لوالــدي وطلــب منــي والــدي اســتالمها فقمــت‬\n‫بشــراء عمــارة حــي ‪...‬وعمــارة حــي ‪ ...‬وقطعتــي أرض املدينــة مببلــغ أربعــة‬\n‫مليــون وســبعمائة وســبعة عشــر ألف ـ ًا وســتمائة ريــال والباقــي مــن املبلــغ‬\n‫وقــدره خمســمائة واثنــن وخمســن ألف ـ ًا وأربعمائــة ريــال إضافــة إلــى‬\n‫مبلــغ مــن دخــل العمــارات ال أذكــره بالضبــط قمــت باســتثماره يف‬\n‫األســهم وقــد حصلــت فيــه خســارة إضافــة إلــى مصاريــف للعائلــة نقديــة‬\n‫باملبلــغ الــذي ذكــرت ولــم يتبــق لهــم لــدي أي مبلــغ وأنــا مســتعد بإجــراء‬\n‫احملاســبة وإبــراز مــا لــدي مــن مســتندات للمدعــن ملراجعتهــا والتأكــد‬\n‫منهــا كمــا أضــاف بــأن عمــارة حــي ‪ ...‬ال يوجــد لهــا عقــود إال ثالثــة‬\n\n\n                                                                                          ‫‪344‬‬\n\f      ‫عقــود يف أول أيــام التأجيــر ثــم اكتفيــت بســندات القبــض التــي يذكــر‬\n      ‫فيهــا مــدة األجــرة ومبلغهــا يدفــع مقدم ـ ًا دون أن يكتــب عقــد حتــى ال‬\n      ‫يلزمنــي بالبقــاء باقــي مــدة العقــد دون أن يدفــع األجــرة وأمــا عمــارة حــي‬\n      ‫‪...‬فقــد اكتفيــت بعقــود املالــك الســابق علــى املؤجريــن ولم أجــدد العقود‬\n      ‫لهــم والــذي يتابــع تأجيــر املبنــى هــي مؤسســة ‪ .....‬الواقعــة يف حي ‪ ...‬ســوق‬\n      ‫‪ ....‬وقــد ســلمني كشــف ًا باإلجــارات مفصلــة ويوجــد مــن ضمنهــا صــراف‬\n      ‫بنــك ‪...‬مببلــغ ســتة وخمســن ألف ـ ًا وثمامنائــة ريــال وبإمكانهــم مراجعــة‬\n      ‫املؤسســة والتأكــد مــن ذلــك وأمــا املبنــى املؤجــر علــى مطبــخ ‪...‬فلــم‬\n      ‫اســتلم إال مــن عــام ‪1427‬ه ـ حتــى عــام ‪1431‬ه ـ بعــد دخــول والــدي يف‬\n      ‫غيبوبــة حتــى وفاتــه وكان اإليجــار ســنتني خمســة وأربعــن ألــف ريــال‬\n      ‫وثــاث ســنوات ســتني ألــف ريــال علمـ ًا بــأن مبلــغ خمســة آالف ريــال مــن‬\n      ‫أجــار الســنتني األوليــن كان أخــي ‪ .....‬يســتلمها ويســلمها لعمــي صدقــة‬\n      ‫علــى عــادة الوالــد وابــن عمــي يعــرف ذلــك ويشــهد بــه وبهــذا يكــون‬\n      ‫مجمــوع مــا اســتلمته مــن أجــار املطبــخ هــو مبلــغ مائتــن وســتني ألــف‬\n      ‫ريــال وجــرى تزويــد املدعــن بالســندات املذكــورة ملراجعتهــا وإحضــار‬\n      ‫مــا لديهمــا مــن مالحظــات إن وجــدت يف اجللســة القادمــة كمــا قــرر‬\n      ‫املدعيــان طلبهمــا عقــد البنــك ‪...‬يف عمــارة حــي ‪...‬وكشــف مختصــر‬\n      ‫للمــودع واملســحوب ومقــدار اخلســارة واملبلــغ املتبقــي حملفظــة املدعــى‬\n      ‫عليــه وعقــود عمــارة حــي ‪ ...‬التــي ذكــر املدعــى عليــه أن بهــا ثالثــة عقــود‬\n      ‫غيــر ســندات القبــض فأبــرز املدعــى عليــه عقــد البنــك ‪ .....‬وعقــود عمارة‬\n      ‫حــي ‪ ...‬وقــال أمــا حركــة احملفظــة فقــد ســبق تزويــد املدعيــن بهــا‬\n      ‫وموجــود فيهــا كل مــا يريــدان مــن حركــة وبإمكانهمــا مراجعتهــا مــن‬\n      ‫قبــل محاســب قانونــي وأنــه راجــع البنــك وذكــر بأنــه ال يوجــد لديــه إال‬\n\n\n‫‪345‬‬\n\f‫كشــف بحركــة تــداول احملفظــة فقــط هكــذا قــرر لــذا طلبــت مــن‬\n‫املدعيــن إحضــار جميــع مــا لديهمــا مــن مالحظــات علــى الكشــوف‬\n‫املقدمــة مــن املدعــى عليــه يف اجللســة القادمــة ورفعــت اجللســة لذلــك ثــم‬\n‫يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعيــن عــن‬\n‫مالحظاتهمــا علــى الكشــوفات واحلســابات املقدمــة مــن املدعــى عليــه‬\n‫فقــاال إن الكشــوفات واحلســابات التــي قدمهــا هــي جلميــع الســنوات‬\n‫منــذ اســتالمه للعمايــر إجمــا ًال ولــم يفصــل للمبالــغ التــي وردت بعــد‬\n‫الوفــاة ونطلــب أن يفصــل املبالــغ التــي بعــد الوفــاة ألن املدعــى عليــه أبــرز‬\n‫لنــا كشــوفات بعــد وفــاة مورثنــا مباشــرة باملبالــغ التــي لديــه وعنــد‬\n‫حســمها مــن املبالــغ اإلجماليــة التــي أبرزهــا أمامكــم يتبــن أنــه تبقــى‬\n‫لنــا مبالــغ مســتحقة بعــد الوفــاة لديــه وليــس كمــا ذكــر بأنــه لــم يتبــق‬\n‫لديــه شــيء وقــد تعمــد ذكــر املبالــغ اإلجماليــة دون أن يفصــل مــا بعــد‬\n‫الوفــاة حتــى ال تخالــف الكشــوفات التــي أبرزهــا لنــا ســابق ًا ونطلــب‬\n‫إلزامــه بتفصيــل املبالــغ التــي قبــل الوفــاة واملبالــغ احملصلــة بعــد الوفــاة‬\n‫يتضــح لكــم عــدم انطبــاق الكشــوفات التــي يقدمهــا كمــا أن لدينــا‬\n‫مالحظــات أخــرى ســنحضرها يف اجللســة القادمــة لــذا طلبــت مــن‬\n‫املدعــى عليــه تفصيــل املبالــغ احملصلــة لديــه قبــل وفــاة مورثهــم ومــا‬\n‫حتصــل بعــد الوفــاة مــن دخــل عمــارة ‪ ...‬و‪ ...‬و‪...‬وأجــرة كل ســنة علــى‬\n‫حــده فاســتعد بذلــك ثــم يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال‬\n‫املدعــى عليــه عــن تفاصيــل املبالــغ احملصلــة لديــه املطلوبــة منــه فقــال‬\n‫إننــي أحضرتهــا وأبــرز كشــف مكــون مــن ســت وعشــرين ورقــة قــال إن‬\n‫فيهــا تفاصيــل احلســابات وجــرى تزويــد املدعيــان بنســخة منهــا وقــال ال‬\n‫مانــع لــدي مــن إجــراء احملاســبة علــى جميــع مــا لــدي وقــال املدعيــان أننــا‬\n\n\n                                                                                        ‫‪346‬‬\n\f      ‫أحضرنــا بعــض املالحظــات علــى حســابات املدعــى عليــه وأبــرزا ورقــة‬\n      ‫قــاال إن فيهــا بعــض املالحظــات كمــا أن لدينــا مالحظــات أخــرى لباقــي‬\n      ‫املبالــغ وفروقــات الدخــل الســنوي ســوف نحضرهــا يف اجللســة القادمــة‬\n      ‫بعــد اســتالمنا لتقاريــر املدعــى عليــه مفصلــة وقــال املدعــى عليــه إن‬\n      ‫املدعيــان يف كل جلســة يذكــران أن لديهمــا مالحظــات أخــرى‬\n      ‫ويطلبــان جلســة أخــرى مــن أجــل إطالــة القضيــة وإتعابــي وأنــا مســتعد‬\n      ‫بإجــراء احملاســبة التــي يطالــب بهــا املدعيــان لــدى محاســب قانونــي‬\n      ‫واليمــن علــى نفــي مــا يدعــون هكــذا قــرر لــذا أفهمــت الطرفــن‬\n      ‫باختيــار محاســب قانونــي إلجــراء احملاســبة بينهمــا ومــا يقــرره احملاســب‬\n      ‫القانونــي يكــون ملزم ـ ًا لهمــا علــى أن يتحمــل املدعيــان تكاليــف‬\n      ‫احملاســب ويف حــال ظهــور عجــز لــدى املدعــى عليــه فإنهــا تضــاف إلــى ما‬\n      ‫عليــه مــن عجــز فطلــب املدعيــان مهلــة للبحــث عــن محاســب واإلفــادة يف‬\n      ‫اجللســة القادمــة ثــم يف جلســة أخــرى حضــر املدعيــان واملدعــى عليــه‬\n      ‫وجــرى ســؤال املدعيــان عــن احملاســب القانونــي فقــاال إننــا ال نريــد إحالة‬\n      ‫املدعــى عليــه إلــى محاســب قانونــي ألن احلســابات واألوراق كلهــا عنــده‬\n      ‫ويســتطيع أن يغيــر فيهــا بــن فتــرة وأخــرى وإننــا نقصــر دعوانــا علــى‬\n      ‫أمريــن همــا ســؤاله عــن إقــراره بعــد وفــاة مورثنــا مباشــرة بــأن لديــه‬\n      ‫للورثــة مبلــغ تســعمائة وســبعة وثالثــن ألفـ ًا وثالثمائــة وثمانيــة وخمســن‬\n      ‫ريــا ًال وإقــراره للورثــة بــأن لهــم يف ذمتــه مبلغ ـ ًا آخــر هــو خمســمائة ألــف‬\n      ‫ريــال وعنــد ســؤالنا لــه يف وقتهــا عنهــا قــال ال تســألوني عــن مصدرهــا‬\n      ‫وإمنــا هــي لكــم علــي وعنــد إجــراء القســمة لــدى القاســم احملامي الشــيخ‬\n      ‫‪ ...‬أقر املدعى عليه مببلغ اخلمســمائة ألف ريال وقام احملامي بإضافتها‬\n      ‫إلــى مبلــغ كل وارث ثــم طلــب احملامــي الشــيكات وقــام بتعديــل املبالــغ‬\n\n\n‫‪347‬‬\n\f‫وحســم نصيــب كل وارث مــن مبلــغ اخلمســمائة ألــف ريــال علــى أن‬\n‫حتســم عليــه عنــد بيــع العقــارات ثــم أفادنــا احملامــي بــأن املدعــى عليــه‬\n‫أنكــر أن للورثــة مبلــغ خمســمائة ألــف ريــال نطلــب ســؤاله عــن هذيــن‬\n‫املبلغــن الذيــن أقــر بهمــا للورثــة وإلزامــه بدفــع نصيبنــا منهــا هــذا مــا‬\n‫نطلبــه وال نريــد إحالتنــا حملاســب قانونــي فجرى إفهامهمــا بأن دعواهما‬\n‫هــي بطلــب محاســبته علــى مــا ذكــروا يف دعواهمــا فقــاال إننــا نقصــر‬\n‫دعوانــا علــى ســؤاله عــن األمريــن اللذيــن ذكرنــا وال نريــد محاســبته‬\n‫عــن بقيــة مــا ذكرنــا يف دعوانــا ألن منشــأ اخلــاف هــو إقــراره بهذيــن‬\n‫املبلغــن ثــم إنــكاره لذلــك ونحــن متنازلــون عــن مطالبتنــا مبحاســبته‬\n‫عــن دخــل العمائــر أمــا مبلــغ املائــة ألــف ريــال مــن أجــرة مطبــخ ‪...‬التــي‬\n‫ذكــر أخــو املدعــى عليــه ‪ ...‬أنــه ســلمها للمدعــى عليــه وأنكــر املدعــى‬\n‫عليــه اســتالمها مــن أخيــه فســنقدم بهــا دعــوى أخــرى علــى املدعــى عليــه‬\n‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب بــأن مــا ذكــره املدعــون قــد‬\n‫ســبق أن أجبــت عنــه يف اجللســة األولــى وهــو أن صحيــح أننــي أقريــت أن‬\n‫للورثــة مبلــغ تســعمائة وســبعة وثالثــن ألفـ ًا وثالثمائــة وثمانيــة وخمســن‬\n‫ريــا ًال ولــم أقــر بــأن لهــم يف ذمتــي إضافــة عليهــا مبلــغ خمســمائة ألــف‬\n‫ريــال وإمنــا ذكــرت أن لهــم مبلــغ خمســمائة ألــف ريــال هــي مــن ضمــن‬\n‫مبلــغ التســعمائة الــذي أقريــت بــه حيــث أن مبلــغ التســعمائة ألــف هــو‬\n‫عبــارة عــن مبلــغ خمســمائة وثمانيــة وثمانــن ألفـ ًا ومائتني وتســعة وســتني‬\n‫ريــا ًال عبــارة عــن جــزء منهــا خســائر يف األســهم حيــث كنــت وكي ـ ً‬\n‫ا‬\n‫عــن والــدي يف اســتثمار أموالــه التــي ســلمني وحصلــت خســارة يف‬\n‫األســهم فظننــت أنــي أحتمــل هــذه اخلســارة وعندما ســألت بعض املشــايخ‬\n‫قالــوا لــي إن اخلســارة ال تتحملهــا فحســمت منهــا هــذا املبلــغ الــذي هــو‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫عبــارة عــن خســارة األســهم وجــزء منــه مصاريــف علــى عائلــة والــدي‬\n      ‫وعالجــه أثنــاء مرضــه وباقــي مبلــغ التســعمائة وســبعة وثالثــن ألف ـ ًا‬\n      ‫وثالثمائــة وثمانيــة وخمســن ريــا ًال احتســبتها مــن املبالــغ التــي لهــم‬\n      ‫وســلمتها لهــم عــن طريــق احملامــي بعــد أن أصــدرت فيهــا شــيكات‬\n      ‫بنصيــب كل وارث مــن املبالــغ املســتحقة لهــم يف التركــة ولــم يبــق لهــم‬\n      ‫يف ذمتــي أي مبلــغ وبعــرض ذلــك علــى املدعيــن قــاال الصحيــح مــا‬\n      ‫ذكرنــاه وقــد أقــر يف مجلــس واحــد مببلــغ التســعمائة كمــا أقــر يف‬\n      ‫نفــس املجلــس بــأن للورثــة عليــه مبلغ ـ ًا آخــر هــو خمســمائة ألــف ريــال‬\n      ‫ممــا يــدل علــى أن مبلــغ اخلمســمائة ألــف ريــال غيــر مبلــغ التســعمائة‬\n      ‫ولدينــا مــا يثبــت ذلــك وهــو شــهود مــن غيــر الورثــة وســنحضرهم يف‬\n      ‫اجللســة القادمــة لــذا أفهمتهمــا بإحضــار جميــع مــا لديهمــا مــن بينــات‬\n      ‫علــى ذلــك وأن املدعــي قــد أقــر بهمــا يف مجلــس واحــد فاســتعدا لذلــك‬\n      ‫ثــم يف جلســة أخــرى حضــر املدعيــان أصالــة ووكالــة كمــا حضــر‬\n      ‫املدعــى عليــه وجــرى ســؤال املدعيــن عــن بينتهمــا علــى إقــراره مببلــغ‬\n      ‫اخلمســمائة ألــف ريــال إضافــة إلــى مبلــغ التســعمائة ألــف ريــال يف مجلــس‬\n      ‫واحــد فقــاال إن الشــهود غيــر متجاوبــن معنــا يف احلضــور وقــد أخذنــا‬\n      ‫خطابــات لهــم إلبالغهــم باحلضــور ولــم يتجاوبــوا وال نســتطيع إحضارهــم‬\n      ‫ويحتمــل أن املدعــى عليــه قــد طلــب منهــم عــدم التدخــل وليــس لدينــا بينة‬\n      ‫غيــر ذلــك وأضافــا بأنــه يف الســندات التــي أبرزهــا ســابق ًا ذكــر أن لديــه‬\n      ‫ســيولة مببلــغ تســعمائة ألــف ريــال وهــو موجــودة يف الســندات التــي‬\n      ‫أبرزهــا للقاســم ثــم جــرى ســؤال املدعــى عليه عــن املبالغ التي اســتثمرها‬\n      ‫يف األســهم ويف شــراء العمائــر هــل كانــت بــإذن مــن مورثــه فقــال إن‬\n      ‫املبالــغ التــي ســلمني والــدي والتــي طلــب منــي حتصيلهــا مــن رحيمنــا ‪.....‬‬\n\n\n‫‪349‬‬\n\f‫طلــب منــي والــدي اســتثمارها لــه وكان قــد أصــدر لــي وكالــة عامــة‬\n‫وطلــب منــي التصــرف مبوجبهــا وأبــرز أصــل الوكالــة العامــة الصــادرة‬\n‫مــن كتابــة عــدل املدينــة برقــم ‪ 26‬وتاريــخ ‪1418/11/04‬ه ـ واملتضمنــة‬\n‫توكيــل ‪ .....‬للمدعــى عليــه وكالــة عامــة وقــال إننــي اجتهــدت يف‬\n‫اســتثمارها واشــتريت ببعــض املبالــغ العمائــر التــي ذكــرت وذلــك يف‬\n‫حيــاة والــدي وســجلتها باســمه كمــا أنــي اجتهــدت يف اســتثمار املبالــغ‬\n‫املتبقيــة لــدي يف األســهم بنــاء علــى طلــب والــدي باســتثمار املبالــغ لــه‬\n‫واجتهــدت يف ذلــك وحصلــت اخلســارة يف بعضهــا كمــا ذكــرت وكنــت‬\n‫أظــن أننــي أحتملهــا وتبــن لــي أننــي ال أحتملهــا فحســمتها مــن املبلــغ‬\n‫الــذي ذكــرت أنــه للتركــة عنــدي وســلمت الباقــي للقاســم وقــد‬\n‫أحصيــت كل مــا للتركــة عنــدي وســلمته للقاســم وقســمه بينهــم ولــم‬\n‫يبــق لهــم عنــدي أي مبلــغ إال األجــارات اجلديــدة لعــام ‪1433‬ه ـ ومســتعد‬\n‫بتســليمها للقاســم هكــذا أجــاب ثــم يف جلســة أخــرى حضــر الطرفــان‬\n‫وجــرى محاولــة الصلــح بــن الطرفــن مراعــاة للرحــم بينهــم ومبــا يحفــظ‬\n‫ا فلــم يتفقــا علــى شــيء وطلبــا احلكــم يف القضيــة‬   ‫حــق القاصــر كامـ ً‬\n‫ثــم يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعــى عليــه عــن‬\n‫تفاصيــل املبلــغ الــذي أقــر بــه فقــال إن املبلــغ التســعمائة وســبعة وثالثــن‬\n‫ألــف ريــا ًال وثالثمائــة وثمانيــة وخمســن ريــا ًال الــذي أقريــت بــه وأنــه‬\n‫للتركــة يف ذمتــي وكنــت كتبتــه يف بعــض األوراق التــي قدمتهــا‬\n‫للقاســم لكــن تبــن لــي أن جــزء ًا مــن املبلــغ وقــدره خمســمائة وثمانيــة‬\n‫وثمانــون ألف ـ ًا ومائتــن وتســعة وســتني ريــا ًال غيــر صحيحــة وأنهــا ال‬\n‫تلزمنــي حيــث أن جــزء ًا منهــا خســائر يف األســهم واجلــزء اآلخــر نفقــات‬\n‫نقديــة كنــت أنفقتهــا علــى األســرة فجــرى ســؤاله عمــا يثبت هــذه املبالغ‬\n\n\n                                                                                      ‫‪350‬‬\n\f      ‫فقــال ليــس لــدي مــا يثبــت ذلــك والنفقــات كانــت نقديــة فجــرى ســؤاله‬\n      ‫كيــف يحتســب مبالــغ مــن التركــة وهــو يعلــم أنهــا نفقــات لألســرة ثــم‬\n      ‫يتبــن لــه فيمــا بعــد أنهــا غيــر داخلــة يف التركــة فقــال ألنهــا كانــت‬\n      ‫نفقــات نقديــة بــدون شــيكات لــذا فقــد احتســبتها للتركــة ألنــه ليــس‬\n      ‫لــدي مــا يثبتهــا ثــم تبــن أنــه ال يشــترط أن تكــون النفقــات مثبتــه لــذا‬\n      ‫جــرى حســمها مــن املبلــغ فجــرى ســؤاله عــن مقــدار املبالــغ التــي خســرها‬\n      ‫يف األســهم فقــال إننــي ال أعلــم مقدارهــا بالضبــط وقــد قدمــت كشــف‬\n      ‫حســاب حملفظــة األســهم ملكتــب محاســبة لبيــان مقــدار اخلســارة‬\n      ‫بالضبــط فجــرى ســؤاله كيــف احتســب مجمــوع اخلســائر يف األســهم‬\n      ‫والنفقــات باملبلــغ الــذي ذكــر وهــو ال يعلــم مقدراهــا بالضبــط فقــال‬\n      ‫إننــي احتســبت املبالــغ النقديــة املوجــودة لــدي واعتبــرت املتبقــي مــن‬\n      ‫املبلــغ خســائر يف األســهم ونفقــات علــى األســرة ولــم آخــذ لهــم ريــا ًال‬\n      ‫واحــد ًا وكان يجيــب علــى ذلــك بتــردد ويدعــي أنــه لــم يفهــم الســؤال‬\n      ‫هكــذا أجــاب ثــم يف جلســة أخــرى حضــر املدعــى عليهمــا أصالــة‬\n      ‫ووكالــة ‪ ..... .....‬كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ .....‬الوكيــل عــن ‪ .....‬مبوجــب الوكالــة الصــادرة من كتابة‬\n      ‫العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 25883‬وتاريــخ ‪1433/4/11‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وحضــور اجللســات وإقامــة‬\n      ‫وســماع الدعــاوى واجلــرح والتعديــل وطلــب تقدمي البينات وســماع الشــهود‬\n      ‫واســتجوابهم والطعــن فيهــم واإلجابــة واملطالبــة بكافــة احلقــوق‬\n      ‫واســتالمها مبوجــب شــيكات مصدقــة باســمه وللوكيــل احلــق يف‬\n      ‫اســتئناف األحــكام ومتييزهــا والقناعــة بهــا واالعتــراض عليهــا وتقســيم‬\n      ‫تركــة والــده قســمة إجبــار أو قســمة تراضــي حســب مــا يتــم االتفــاق‬\n\n\n‫‪351‬‬\n\f‫عليــه شــرع ًا واتخــاذ كافــة مــا تقتضيــه إجــراءات التقاضــي والدفــاع‬\n‫عنــه يف أي دعــوى تقــام منــه أو ضــده وقــال املدعــى عليــه وكالــة إن‬\n‫الطرفــن إخــوان وأطلــب إعطائــي مهلــة حملاولــة جمــع الطرفــن وإجــراء‬\n‫احملاســبة بينهمــا ومحاولــة تقريــب وجهــات النظــر لــذا جــرى رفــع اجللســة‬\n‫لذلــك كمــا طلبــت مــن املدعــى عليــه تفصيــل املبالــغ التــي ســلمها‬\n‫موكلــه للقاســم وقســمت بــن الورثــة فاســتعد بذلــك لــذا رفعــت اجللســة‬\n‫لذلــك ثــم يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال الطرفــن عــن‬\n‫الصلــح فقــاال إنــه لــم يتــم االتفــاق علــى شــيء وجــرى ســؤال املدعــى عليــه‬\n‫وكالــة عــن تفاصيــل املبالــغ التــي ســلمها موكلــه للقاســم فأبــرز ورقــة‬\n‫مــدون فيهــا بيــان باملبالــغ الــواردة واملنصرفــة ومــن ضمنهــا مبلــغ أربعمائة‬\n‫وســتة وعشــرين ألفـ ًا ومائــة وتســعة وســتني ريــا ًال رصيد بعد وفــاة مورثهم‬\n‫وقــال املدعــى عليــه إن هــذا املبلــغ هــو املتبقــي مــن مبلــغ التســعمائة‬\n‫وســبعة وثالثــن ألــف ريــال التــي ســبق أن أقــر بهــا قبــل حســم خســائر‬\n‫األســهم والنفقــات وبعــد أن حســم خســائر األســهم والنفقــات التــي بلغــت‬\n‫مبلــغ خمســمائة وأحــد عشــر ألفـ ًا ومائــة وتســعة وثمانــن ريــال ســلم هــذا‬\n‫املبلــغ املتبقــي للقاســم ضمــن مبلــغ مليــون وســتمائة وخمســة آالف ريــال‬\n‫كانــت تشــمل هــذا املبلــغ واملبالــغ األخــرى التــي لديــه مــن إيجــارات‬\n‫العمائــر وبعــرض ذلــك علــى املدعــن قالــوا إن املدعــى عليــه أصالــة قــد‬\n‫ســبق أن أقــر مبوجــب تقريــر ســابق أن مبالــغ خســائر األســهم والنفقــات‬\n‫بلغــت مبلــغ خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة وســتني‬\n‫ريــا ًال وذلــك بعــد حســم جميــع املبالــغ التــي ســلمها وليــس كمــا ذكــر‬\n‫وقــد ذكــر ذلــك يف ســند قدمــه بتاريــخ ‪1432/05/26‬ه ـ بتوقيعــه‬\n‫ومرفــق باملعاملــة ونطلــب إلزامــه بدفــع هــذا املبلــغ وباالطالع على الســند‬\n\n\n                                                                                       ‫‪352‬‬\n\f      ‫املرفــق باملعاملــة وجــد كمــا ذكــر املدعــون وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه قــال ســأرجع ملوكلــي يف ذلــك وأجيبكــم عــن ذلــك يف اجللســة‬\n      ‫القادمــة ثــم يف جلســة أخــرى حضــر املدعــون أصالــة ووكالــة ‪..... .....‬‬\n      ‫ابنــي ‪ .....‬كمــا حضــر املدعــي أصالــة مجــدي ‪ .....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وحضــر املدعــى عليــه وكالــة وجــرى‬\n      ‫ســؤال املدعــى عليــه وكالــة عمــا ذكــره املدعــون مــن إقــرار بأنــه حســم‬\n      ‫مبلــغ خمســمائة وثمانيــة وثمانــن ألفـ ًا ومائتــن وتســعة وســتني ريــا ًال مــن‬\n      ‫املبلــغ الــذي ســبق أن أقــر بــه فقــال إننــي رجعــت ملوكلــي وأفادنــي بأنــه‬\n      ‫حســم مبلــغ خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة وســتني‬\n      ‫ريــا ًال مــن مبلــغ التســعمائة ألف ـ ًا وســبعة وثالثــن ألف ـ ًا ومائتــن وثمانيــة‬\n      ‫وخمســن ريــا ًال الــذي ســبق أن أقــر بــه وباقــي املبلــغ ســلمه ‪ .....‬وقســم بــن‬\n      ‫الورثــة وبعــرض ذلــك علــى املدعــن قالــوا إننــا وموكلينــا نطالــب بهــذا‬\n      ‫املبلــغ الــذي حســمه ليدفــع للتركــة ويقســم بــن الورثــة حســب ميراثهــم‬\n      ‫الشــرعي وال نقبــل برجوعــه عــن إقــراره ونطلــب ميينــه علــى تســليمه‬\n      ‫لباقــي املبلــغ للقاســم وعلــى أنــه لــم يقــر مببلــغ خمســمائة ألــف ريــال‬\n      ‫أخــرى إضافــة إلــى مبلــغ التســعمائة وســبعة وثالثــن ألف ـ ًا ومائتــن‬\n      ‫وثمانيــة وخمســن ريــا ًال والتــي ســبق أن أنكرهــا وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال موكلــي مســتعد باليمــن التــي طلبهــا املدعــون لــذا‬\n      ‫طلبــت إحضــار موكلــه يف اجللســة القادمــة ثــم يف جلســة أخــرى حضــر‬\n      ‫املدعــون أصالــة ووكالــة كمــا حضــر املدعــى عليــه أصالــة وقــد جــرى‬\n      ‫االطــاع علــى صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 1/100/389‬وتاريــخ ‪1429/02/20‬ه ـ املتضمــن وفــاة ‪.....‬‬\n      ‫‪1429/02/14‬ه ـ وانحصــار إرثــه يف زوجاتــه ‪ .....‬و‪ .....‬و‪ .....‬ويف أوالده‬\n\n\n‫‪353‬‬\n\f‫‪..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... .....‬‬\n‫‪ ..... ..... ..... ..... .....‬بالغــون مــا عــدا ‪ .....‬معــاق عقلي ـ ًا وبعــرض اليمــن‬\n‫ا واهلل‬   ‫التــي طلبهــا املدعــون علــى املدعــى عليــه اســتعد بهــا ثــم حلــف قائـ ً‬\n‫العظيــم الــذي ال إلــه إال هــو إن املبلــغ الــذي ســبق أن أقريــت بــه للتركــة‬\n‫وقــدره تســعمائة وســبعة وثالثــن ألف ـ ًا ومائتــن وخمســن ريــا ًال قــد‬\n‫ســلمته ‪ .....‬ليقســمه بــن املســتحقني بعــد حســم خســائر االســهم‬\n‫والنفقــات وقدرهــا خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة‬\n‫وســتني ريــا ًال كمــا أننــي لــم أقــر مببلــغ خمســمائة ألــف ريــال زيــادة علــى‬\n‫مبلــغ التســعمائة وســبعة وثالثــن ألــف ومائتــن وثمانيــة وخمســن ريــا ًال‬\n‫وإمنــا هــي داخلــة فيــه واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى مــا ذكــره‬\n‫املدعــون مــن أنــه ســبق أن أقــر أن للورثــة يف ذمتــه مبلــغ تســعمائة وســبعة‬\n‫وثالثــن ألف ـ ًا ومائتــن وثمانيــة وخمســن ريــا ًال ثــم رجــع عــن إقــراره‬\n‫وذكــر بــأن جــزء ًا مــن املبلــغ خســائر يف األســهم ونفقــات نقديــة علــى‬\n‫الورثــة لــم يحســمها وقــد حســمها مــن املبلــغ وســلم الباقــي للقاســم‬\n‫وأنكــر إقــراره مببلــغ خمســمائة ألــف ريــال زيــادة علــى هــذا املبلــغ الــذي‬\n‫أقــر بــه وألن الرجــوع عــن اإلقــرار يف حقــوق اآلدمــي غيــر معتبــر عنــد‬\n‫عامــة أهــل العلــم ألن اإلقــرار مظهــر حلــق موجــود قبــل صــدوره وليــس‬\n‫منشــئ ًا حلــق لــم يكــن موجــود ًا وألن حقــوق العبــاد مبينــة علــى املشــاحة‬\n‫وملــا قــرره املدعــى عليــه عنــد ســؤاله مــن عــدم معرفتــه ملقــدار اخلســائر‬\n‫والنفقــات وعــدم اســتطاعته لتبيينهــا ممــا يؤكــد عــدم صحــة مــا ذكره‬\n‫مــن ســبب رجوعــه عمــا أقــر بــه إضافــة إلــى أن مــا ذكــره مــن مبــرر‬\n‫للرجــوع عــن اإلقــرار ال يقبــل مــن مثلــه ألن ذلــك ال يخفــى علــى مثلــه عــادة‬\n\n\n                                                                                                              ‫‪354‬‬\n\f      ‫ولطلــب املدعــن ميــن املدعــى عليــه بتســليمه لباقــي املبلــغ الــذي أقــر بــه‬\n      ‫للقاســم بعــد حســمه للمبلــغ الــذي ذكــر وعلــى نفــي إقــراره مببلــغ‬\n      ‫خمســمائة ألــف ريــال للورثــة زيــادة علــى مبلــغ التســعمائة وســبعة وثالثــن‬\n      ‫ألف ـ ًا ومائتــن وثمانيــة وخمســن ريــا ًال وحللــف املدعــى عليــه اليمــن‬\n      ‫املطلوبــة لــذا فقــد أفهمــت املدعــى عليــه أنــه يلزمــه دفــع مبلــغ خمســمائة‬\n      ‫وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة وســتني ريــا ًال لتقســم بــن جميــع‬\n      ‫ورثــة ‪ .....‬بالوجــه الشــرعي وصرفــت النظــر عــن مطالبــة الورثــة بباقــي‬\n      ‫املبلــغ املدعــى بــه بعــد حلــف املدعــى عليــه اليمــن املطلوبــة ومبــا تقــدم‬\n      ‫حكمــت وبعــرض ذلــك علــى الطرفــن أبــدى املدعــون قناعتهــم باحلكم‬\n      ‫أمــا املدعــى عليــه فلــم يقنــع باحلكــم وطلــب التمييــز وأجيــب لطلبــه‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                             ‫حرر يف ‪1433/07/08‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ‬\n      ‫افتتحت اجللســة وفيها حضر الطرفان وقد وردتنا املعاملة من محكمة‬\n      ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 33396939‬وتاريــخ ‪1433/8/28‬ه ـ‬\n      ‫املتضمــن مالحظــة أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة الثالثــة‬\n      ‫مايلــي‪ -1:‬اجلهــل مــن املدعــى عليــه فيمــا ذكــره يف محلــه فينبغــي‬\n      ‫مالحظــة ذلــك ‪ -2‬ذكــر املدعــى عليــه بوجــود اتفــاق مرفــق صورتــه‬\n      ‫وأن املدعــن أقــروا بأمانتــه فيتــم عــرض ذلــك علــى األطــراف وال يخفــى‬\n      ‫علــى فضيلتــه بــأن القــول قــول األمــن علــى ميينــه وعلــى فضيلتــه بــذل‬\n      ‫اجلهــد يف عــرض الصلــح بــن الطرفــن وال ســيما يف دعــوى عائليــة وعليــه‬\n      ‫أجيــب أصحــاب الفضيلــة بأنــه جــرى ســؤال املدعــى عليــه عمــا يذكــر‬\n      ‫مــن وجــود اتفــاق بــن الورثــة وأن املدعــن أقــروا بأمانــة موكلــه فقــال‬\n\n\n‫‪355‬‬\n\f‫نعــم يوجــد اتفــاق بــن موكلــي وبــن املدعــن بخصــوص التركــة وأبــرز‬\n‫صــورة اتفــاق مكونــة مــن ورقتــن بــن أبنــاء ‪ .....‬وقــال جــاء يف البنــد‬\n‫ا‬\n‫الثالــث مــا يلــي األخ ‪ .....‬كان والزال هــو األخ األكبــر وكان وكيـ ً‬\n‫لوالدنــا ومحــل ثقتــه ونحــن كذلــك نثــق فيــه ويف أمانتــه وعلــى ذلــك فهــو‬\n‫املســئول األول عــن حصــر التركــة يف احملكمــة ويتــم احلصــر يف مــدة‬\n‫أقصاهــا أســبوع مــن تاريــخ الورقــة وأضــاف بــأن هــذا يثبــت أن إخــوان‬\n‫موكلــي املدعــن شــهدوا لــه باألمانــة والثقــة خــال حيــاة والــده وبعــد‬\n‫وفاتــه فكيــف يتهمونــه بعــد ذلــك كمــا أنــه اســتعد بإجــراء احملاســبة‬\n‫لكنهــم رفضــوا ذلــك وبعــرض ذلــك علــى املدعــن قالــوا إن مــا جــاء يف‬\n‫الســند غيــر صحيــح والتوقيــع الــذي عليــه ليــس توقيعنــا كمــا أنــه لــم‬\n‫يحضــره طــوال اجللســات املاضيــة ممــا يــدل علــى عــدم صحتــه واملدعــي‬\n‫حــاول بعــد وفــاة مورثنــا توقيعنــا علــى أوراق باستشــارة محامــن ُليخــرج‬\n‫نفســه مــن أي محاســبة علــى أمــوال والــدي كمــا أنــه كان يتصــرف‬\n‫بأمــوال والــدي مــع أن والــدي كان يف غيبوبــة تامــة قبــل وفاتــه بأربــع‬\n‫ســنوات وكنــا نطلــب منــه عــدم التصــرف إال بعــد إقامتــه ولــي ولــم‬\n‫يســتجب لذلــك كمــا أنــه لــم يعــط الورثــة نصيبهــم مــن التركــة إال‬\n‫بعــد أن تقدمنــا بدعــوى عليــه يف احملكمــة إللزامــه بذلــك مــع وجــود‬\n‫ا يف الورثــة ومعــاق وســتة مــن إخوانــي بــدون وظيفــة أو‬    ‫قصــار ســن ًا وعقـ ً‬\n‫عمــل وتعمــد تــرك عشــرين شــقة مــن التركــة بــدون تأجيــر طــوال املــدة‬\n‫املاضيــة إضــرار ًا بالورثــة ألنــه وأشــقائه موظفــن بوظائــف كبيــرة وغيــر‬\n‫محتاجــن للتركــة كمــا أنــه جــاء يف البنــد األول مــن الســند املذكــور‬\n‫املصادقــة علــى الكشــوفات املقدمــة منــه وعددهــا خمــس أوراق وذكــر‬\n‫أنــه ال خــاف فيهــا وهــي التــي اســتند عليهــا يف إثبــات املبلــغ املدعــى بــه‬\n\n\n                                                                                        ‫‪356‬‬\n\f      ‫واآلن يرجــع عــن مبلــغ تســعمائة ألــف ريــال منهــا ويدعــي أنهــا خســارة‬\n      ‫يف األســهم فكيــف يقبــل منــه ذلــك كمــا جــرت محاولــة الصلــح بــن‬\n      ‫الطرفــن ومحاولــة تقريــب وجهــات النظــر وتذكيرهم بعظم حق الرحم‬\n      ‫فأصــر املدعيــان علــى احلكــم يف القضيــة وأن هــذا حــق للورثــة وفيهــم‬\n      ‫قصــار ولــم يتــم االتفــاق علــى شــيء أمــا مــا ذكــره أصحــاب الفضيلــة يف‬\n      ‫املالحظــة األولــى فاملدعــى عليــه متعلــم ومثلــه ال يعــذر باجلهــل يف مثــل مــا‬\n      ‫ذكــر خاصــة وأنــه لــم يبــن أي مســتند صالــح حلســم املبلــغ احملكــوم‬\n      ‫بــه والــذي ســبق أن أقــر بــه للتركــة ومــا ذكــره إمنــا هــي أمــور مجملــة ال‬\n      ‫ـزاء‬\n       ‫تســتند علــى أي حســابات أو مســتندات تثبــت ذلــك بــل ذكــر أن جـ ً‬\n      ‫كبيــر ًا منــه خســارة يف األســهم مــع عــدم وجــود أي حســابات لديــه تثبــت‬\n      ‫وجــود خســارة يف األســهم مــن عدمهــا ومقــدار اخلســارة إن وجــدت أمــا‬\n      ‫مــا ذكــره أصحــاب الفضيلــة مــن أن القــول قــول األمــن مــع ميينــه فــا‬\n      ‫يخفــى أن ذلــك يف حــال عــدم وجــود بينــة تثبــت خــاف ذلــك وهــي هنــا‬\n      ‫إقــراره الصريــح باســتحقاق التركــة للمبلــغ احملكــوم بــه عليــه فــا‬\n      ‫يقبــل رجوعــه بعــد مــدة عنــه إال ببينــة تثبــت ذلــك ولــم ُيحضــر املدعــي‬\n      ‫مــا يثبــت ذلــك لــذا لــم يظهــر لــي خــاف مــا حكمــت بــه وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                        ‫‪1433/11/1‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم األربعــاء املوافــق ‪1434/01/28‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر الطرفان وقــد عادت املعاملة من محكمة‬\n      ‫االســتئناف وبرفقهــا القــرار الصــادر مــن الدائــرة احلقوقيــة الثالثــة يف‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة رقــم ‪33473659‬‬\n      ‫وتاريــخ ‪1433/12/20‬ه ـ املتضمــن أنــه بدارســة احلكــم وصــورة ضبطــه‬\n\n\n‫‪357‬‬\n\f‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلتــه ملالحظــة أن مــا أجــاب بــه‬\n                   ‫عــن الفقــرة (‪ )2‬مــن قــرار محكمــة االســتئناف غيــر مـ ٍ‬\n‫ـوف ملــا طلــب منــه‬\n‫إذ نقــدر لفضيلتــه مــا أجــاب بــه إال أن مــا ذكــره املدعــى عليــه نحــو هــذا‬\n‫املبلــغ وســبب اإلقــرار بــه ثــم رجوعــه وادعائــه اخلســارة ومــا ذكــره مــن‬\n‫مصروفــات علــى العائلــة هــو محــل تأمــل فيتوجــه العــرض بذلــك علــى‬\n‫املدعيــن والتحقــق مــن حصــول اخلســارة يف هــذه األســهم بطلــب كشــف‬\n‫للمحفظــة وطلــب بيــان للمصروفــات العائليــة مــن نفقــات أو عــاج والــده‬\n‫وإذا تعــذر ذلــك فيرجــع فيــه للعــرف حــال مصادقــة املدعــن علــى بذلــه‬\n‫لهــذه النفقــات العائليــة والعــاج وإجــراء مــا يلــزم نحــوه حتري ـ ًا للحــق‬\n‫ـراء للذمــة إلكمــال الــازم اه ـ وعليــه أجيــب أصحــاب الفضيلــة‬        ‫وإبـ ً‬\n‫بأنــه جــرى محاولــة الصلــح بــن الطرفــن فلــم يتفقــا علــى شــيء وقــال‬\n‫املدعيــان إن رجــوع املدعــي عــن إقــراره ال يقبــل منــه وقــد أقــر إقــرار ًا‬\n‫تام ـ ًا باملبلــغ ومــا ذكــره مــن ســبب رجوعــه عــن اإلقــرار وأنــه بســبب‬\n‫عــدم احتســابه نفقــات فــا نوافــق عليــه ألنــه حســب حســاباته املفصلــة‬\n‫التــي أبرزهــا واملرفقــة باملعاملــة قــد صــرف مــا يزيــد علــى مبلــغ مليــون‬\n‫وخمســمائة ألــف ريــال مصاريــف للعائلــة مبوجــب شــيكات قبــل وفــاة‬\n‫والــدي فكيــف يزيــد علــى ذلــك بعــد هــذه احلســابات ويدعــي أن هنــاك‬\n‫مبلــغ مائــة ألــف ريــال زيــادة وهــو ال يصــرف شــيء إال بشــيك كمــا أن مــا‬\n‫يدعيــه مــن خســارة األســهم لــم يثبــت ذلــك ولــم يخــرج كشــف بهــا وقــد‬\n‫ســبق أن طلبتــم منــه ذلــك عــدة مــرات ولــم يحضــر ذلــك ويعتــذر بأعــذار‬\n‫كثيــرة وســبب رجوعــه عــن إقــراره هــو بســبب تقدمنــا بطلــب القســمة‬\n‫عــن طريــق احملكمــة وهــو كان يريــد أن تتــم خــارج احملكمــة وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قــال إن النفقات املذكورة يف احلســابات املرفقة‬\n\n\n                                                                                      ‫‪358‬‬\n\f      ‫باملعاملــة هــي املصروفــة مبوجــب شــيكات أمــا مبلــغ املائــة ألــف فقــد‬\n      ‫صــرف نقــد ًا بــدون شــيكات كمــا ســأعرض علــى موكلــي إحضــار ما‬\n      ‫يثبــت اخلســارة يف األســهم بكشــف مــن محاســب قانونــي مــن أول إيــداع‬\n      ‫املبالــغ العائــدة ملورثهــم يف احملفظــة وحتــى قســمة التركــة لــذا طلبــت‬\n      ‫منــه إحضــار مــا يثبــت ذلــك يف اجللســة القادمــة وعــدم املماطلــة يف ذلــك‬\n      ‫فاســتعد بذلــك ثــم يف جلســة أخــرى حضــر املدعيــان أصالــة ووكالــة‬\n      ‫كمــا حضــر املدعــى عليــه وكالــة وجــرى ســؤاله عمــا يثبــت اخلســارة يف‬\n      ‫األســهم فقال إن موكلي اســتخرج كشــف حســاب للمحفظة من تاريخ‬\n      ‫إنشــائها وحتــى هــذا اليــوم وقدمــه حملاســب قانونــي اســمه شــركة ‪.....‬‬\n      ‫وشــركاؤه وقــد طلــب احملاســب مهلــة شــهر ونصــف إلجــراء احملاســبة‬\n      ‫والتأكــد مــن وجــود الربــح أو اخلســارة وأطلــب إعطائــي مهلــة إلحضــار‬\n      ‫ذلــك فجــرى إفهامــه بأنــه ســبق أن قــرر موكلــه يف اجللســات املاضيــة أنــه‬\n      ‫قــدم كشــف حســاب للمحفظــة حملاســب قانونــي ولــم يحضــر مــا يثبــت‬\n      ‫ذلــك حتــى تاريخــه فقــال أطلــب إعطائــي هــذه املهلــة األخيــرة إلحضــار‬\n      ‫ذلــك فجــرى ســؤاله هــل احملفظــة خاصــة مبورثــه أم لــه فيهــا مبالــغ فقــال‬\n      ‫إننــي بعــد ســؤال موكلــي ذكــر لــي أنــه افتتــح احملفظــة مببلــغ ثالثمائــة‬\n      ‫ألــف ريــال خاصــة بــه ثــم أودع بعــد ذلــك مبلــغ ســتمائة ألــف ريــال مــن‬\n      ‫مبالــغ لوالــده وكان موكلــي يســحب مــن احملفظــة مبالــغ ويــودع أخــرى‬\n      ‫بعــد ذلــك وســأحضر مــا يثبــت اخلســارة يف اجللســة القادمــة ثــم يف جلســة‬\n      ‫أخــرى حضــر الطرفــان وجــرى ســؤال املدعــى عليــه عمــا يثبــت خســارة‬\n      ‫موكلــه يف األســهم فقــال إن احملاســب القانونــي رفــض إجــراء احملاســبة‬\n      ‫إال مببلــغ مائــة وعشــرين ألــف ريــال ورفــض موكلــي ذلــك الرتفــاع املبلــغ‬\n      ‫وقــد قمــت بإعــداد بيــان مــن ثــاث صفحــات بإجمالــي القيمــة املدفوعــة‬\n\n\n‫‪359‬‬\n\f‫للشــراء وعمــوالت البيــع وإجمالــي القيمــة احملصلــة مــن نتــاج بيــع األســهم‬\n‫فوجــدت أن هنــاك خســارة تعــادل مبلــغ أربعمائــة وثالثــة وعشــرين ألف ـ ًا‬\n‫وأربعمائــة وخمســة وعشــرين ريــا ًال وأربعــة وســتني هللــة وبهــذا يتبــن أن‬\n‫اخلســارة التــي ذكرهــا موكلــي صحيحــة وبعــرض ذلــك علــى املدعيــن‬\n‫قــاال إن هنــاك مبالــغ يف كشــف احلســاب الــذي ســبق أن أحضــره لــم‬\n‫تذكــر يف حركــة البيــع والشــراء باإلضافــة إلــى حــواالت كثيــرة لــم‬\n‫ا يف اجللســة القادمــة ومــا ذكــره مــن‬   ‫يشــر إليهــا وســنحضر ذلــك مفصـ ً‬\n‫حســابات ال نوافــق عليهــا ألنهــا ليســت مــن محاســب قانونــي وقــد ســبق‬\n‫أن التــزم بإحضــار مــا يثبــت ذلــك مــن محاســب قانونــي هكــذا قــررا ثــم‬\n‫يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعــن عمــا لديهمــا‬\n‫حيــال البيــان الــذي أبــرزه املدعــى عليــه يف اجللســة املاضيــة فقــاال إن بيــان‬\n‫املدعــى عليــه غيــر صحيــح ومخالــف للحقيقــة حســب كشــف حركــة‬\n‫احملفظــة حيــث بإجرائنــا محاســبة للمحفظــة تبــن أن يف احملفظــة‬\n‫أربــاح مببلــغ مليــون وســبعمائة وواحــد وخمســن ألف ـ ًا وأربعمائــة ريــال‬\n‫عبــارة عــن أربــاح مت ســحبها مــن احملفظــة مــن قبــل املدعــى عليــه ولــم‬\n‫يذكرهــا وبرفقــه بيــان مفصــل بهــا وبتأريخهــا ورقــم الصفحــة التــي‬\n‫تثبتهــا يف كشــف احلســاب وأبــرزا بيان ـ ًا مــن ورقتــن جــرى إرفاقــه‬\n‫باملعاملــة إضافــة إلــى ملحقــات صــور لهــذه املبالــغ يف كشــف احلســاب‬\n‫كمــا أضافــا بــأن البيــان الــذي أبــرزه املدعــى عليــه قــد أغفــل كثيــر ًا‬\n‫مــن احلــركات التــي متــت علــى احملفظــة وقــد بينــا بعض ـ ًا منهــا وأبــرزا‬\n‫بيان ـ ًا مــن ورقــة واحــدة موضــح فيــه املبلــغ والصفحــة التــي تشــير إليــه‬\n‫يف كشــف احلســاب وقــاال إن هــذا يبــن محاولــة املدعــى عليــه إخفــاء‬\n‫احلقيقــة كمــا أرفقــا صــور ًا مــن كشــف احلســاب مبــا يثبــت هــذه‬\n\n\n                                                                                         ‫‪360‬‬\n\f      ‫احلــركات كمــا أضافــا بــأن بيــان املدعــى عليــه فيــه أخطــاء كثيــرة‬\n      ‫وغيــر مطابــق ملــا جــاء يف كشــف احلســاب وأبــرزا بيانـ ًا مــن ورقــة واحــدة‬\n      ‫يوضــح األخطــاء املذكــورة يف املبالــغ ومــا يشــير إلــى أرقــام صفحاتهــا‬\n      ‫وصــور ًا مــن الصفحــة يف كشــف احلســاب وقــاال إن هــذا يوضــح ســبب‬\n      ‫رفــض املدعــى عليــه إحضــار تقريــر مــن محاســب قانونــي يثبــت اخلســارة‬\n      ‫ومحاولــة االيهــام باخلســارة بالبيــان الــذي أحضــره والــذي يخالــف‬\n      ‫احلقيقــة كمــا أوضحنــا وإن كل ذلــك محاولــة منــه إلنــكار مــا ســبق‬\n      ‫أن أثبتــه وأقــر بــه وحــاول الرجــوع عنــه عنــد اختالفنــا معــه ونحتفــظ‬\n      ‫بحقنــا مبطالبتــه باألربــاح التــي متــت علــى األســهم والتــي حــاول إخفاءهــا‬\n      ‫يف دعــوى مســتقلة وبعــرض ذلــك علــى املدعــى عليــه قــال إن مــا ذكــره‬\n      ‫املدعيــان مــن وجــود ســحوبات مــن موكلــي مــن احملفظــة فصحيــح وهــي‬\n      ‫أكثــر مــن املبلــغ الــذي ذكــراه حيــث ســحب مــن احملفظــة مبلــغ مليــون‬\n      ‫وثمامنائــة وأربعــة وســبعني ألف ـ ًا وأربعمائــة ريــال لكنــه يف املقابــل أودع‬\n      ‫مبالــغ يف احملفظــة تزيــد علــى مليونــن ومائــة ألــف ريــال مــع أن رأس‬\n      ‫املــال الــذي اســتثمره يف احملفظــة ال يتجــاوز ســتمائة ألــف ريــال ممــا‬\n      ‫يــدل علــى أن موكلــي أعــاد يف احملفظــة املبالــغ التــي ســحبها فجــرى‬\n      ‫ســؤاله عــن باقــي املالحظــات فقــال إنهــم اعتمــدوا علــى كشــف حســاب‬\n      ‫آخــر ســبق أن أحضــره موكلــي مــن البنــك وهــو غيــر الكشــف الــذي‬\n      ‫أحضــره موكلــي أخيــر ًا مــن البنــك والــذي ســحب مــن املقــر الرئيســي‬\n      ‫يف الريــاض وترتيــب الكشــفني يختلــف ممــا أحــدث املالحظــات التــي‬\n      ‫يذكرونهــا فجــرى إفهامــه بــأن تاريــخ كل حركــة ذكروهــا يحــدد‬\n      ‫مكانهــا فقــال إن الكشــف الــذي اعتمــدوا عليــه غيــر الكشــف الــذي‬\n      ‫لــدي ولــم أطلــع علــى كشــفهم الــذي ذكــروا هكــذا قــرر وبعــرض‬\n\n\n‫‪361‬‬\n\f‫ذلــك علــى املدعيــن قــاال إن املبالــغ التــي ســحبها مــن احملفظــة هــي غيــر‬\n‫حركــة البيــع والشــراء التــي تتــم داخــل احملفظــة وســحبه لهــا وإخراجهــا‬\n‫مــن احملفظــة دليــل علــى صرفــه للمبلــغ واملبالــغ التــي يذكــر أنــه أودعهــا‬\n‫تــدل علــى أن رأس املــال املــودع يف احملفظــة ليــس كمــا ذكــر وهــو‬\n‫مبلــغ ســتمائة ألــف ريــال بــل يــدل علــى أنــه أكثــر مــن ذلــك بكثيــر‬\n‫وأنــه يســحب مــن احملفظــة مبالــغ متــى أراد كمــا أنــه ال حاجــة ألن‬\n‫يســحب مبالــغ كبيــرة ثــم يودعهــا ألن املضاربــة بهــا تتــم وهــي باقيــة يف‬\n‫احملفظــة دون ســحب كمــا أن الســحوبات واإليداعــات لــم يذكرهــا يف‬\n‫الكشــف الــذي أحضــره يف اجللســة املاضيــة وبعــرض ذلــك علــى املدعــى‬\n‫عليــه قــال إن الكشــف الــذي أحضرتــه هــو بحــركات البيــع والشــراء‬\n‫فقــط ولــم أتطــرق للســحوبات وااليداعــات كمــا أضــاف املدعيــان أن‬\n‫ســحوبات املدعــى عليــه متــت بعــد دخــول مورثنــا يف غيبوبــة تامــة منــذ عــام‬\n‫‪2006‬م حســب التقاريــر الطبيــة حيــث بقــي يف غيبوبــة ملــدة عامــن ثــم‬\n‫تــويف وكثيــر مــن الســحوبات متــت بعــد هــذا التاريــخ وبعــرض ذلــك علــى‬\n‫املدعــى عليــه وكالــة قــال إن مــورث الطرفــن كان مقعــد ًا فقــط ولــم‬\n‫يكــن يف غيبوبــة إال يف الشــهرين األخيريــن تقريبـ ًا قبــل وفاتــه وبعــرض‬\n‫ذلــك علــى املدعيــن قــاال إن التقريــر الطبــي املرفــق باملعاملــة والصــادر‬\n‫مــن مستشــفى املدينــة يثبــت أنــه كان يف غيبوبــة منــذ دخولــه املستشــفى‬\n‫بتاريــخ ‪ 31‬ينايــر ‪2006‬م وأن تغذيتــه تتــم عــن طريــق أنبــوب مــن األنــف‬\n‫إلــى املعــدة وأن نســبة الوعــي ‪ 15/10‬كمــا أن مــوكل املدعــى عليــه‬\n‫مقــر بذلــك يف الكشــوفات التــي أحضرهــا هكــذا قــررا فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ولعــدم إحضــار املدعــى عليــه مــا يثبــت‬\n‫مــا يدعيــه مــن خســارة مــع وعــده بإحضــار ذلــك مــن محاســب قانونــي ثــم‬\n\n\n                                                                                      ‫‪362‬‬\n\f      ‫رجوعــه عــن ذلــك وملــا ذكــر بعاليــه مــن مــداوالت بــن الطرفــن تنفــي‬\n      ‫مــا يذكــره املدعــى عليــه مــن وجــود خســارة لــذا لــم يظهــر لــي خــاف‬\n      ‫مــا حكمــت بــه وليــس لــدي ســواه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/02‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة العامــة باملدينــة املنــورة والقائــم بعمــل‬\n      ‫املكتــب القضائــي الثانــي ففــي يــوم الثالثــاء املوافــق ‪1434/10/13‬ه ـ‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار الصــادر‬\n      ‫مــن الدائــرة احلقوقيــة الثالثــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة رقــم ‪ 34312231‬وتاريــخ ‪1434/09/03‬ه ـ املتضمــن مــا نصــه‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى منــا‬\n      ‫نحــن رئيــس الدائــرة الثالثــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة االطــاع علــى هــذا الصــك الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n      ‫القاضــي باحملكمــة العامــة باملدينــة املنــورة املســجل بعــدد ‪ .....‬وتاريــخ‬\n      ‫‪1433/07/09‬ه ـ املتضمــن دعــوى ع‪ .....‬أصالــة ووكالــة ضــد ‪.....‬‬\n      ‫يف تركــة‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق اه ـ‬\n      ‫قاضــي اســتئناف ‪ .....‬قاضــي اســتئناف ‪ .....‬رئيــس الدائــرة ‪ .....‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                                 ‫يف ‪1434/10/13‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم اخلميــس املوافــق ‪1434/11/06‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي ‪ .....‬وقــرر أنــه اســتلم مــن املدعــى‬\n      ‫عليــه ‪ .....‬مبلــغ مائــة وأربعــة وعشــرون ألف ـ ًا وتســعمائة وأربعــة وســبعون‬\n\n\n‫‪363‬‬\n\f‫ريــا ًال وســبع وثالثــون هللــة مــن املبلــغ احملكــوم بــه مبوجــب الشــيك‬\n‫املســحوب علــى بنــك ‪ .....‬برقــم ‪ 294498‬وتاريــخ ‪2013/08/27‬م وأنــه‬\n‫لــم يبــق لــه بذمــة املدعــى عليــه بخصــوص هــذه القضيــة أي شــيء وبهــذا‬\n‫تكــون الدعــوى منتهيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/11/06‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم يف يــوم االثنــن املوافــق ‪1434/11/10‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي ‪ .....‬وقــرر أنــه اســتلم مــن املدعــى‬\n‫عليــه ‪ .....‬مبلــغ مائتــن وخمســة وعشــرين ألفـ ًا وثالثمائــة وثالثــة وثمانــن‬\n‫ريــا ًال وتســعة وثمانــن هللــة مــن املبلــغ احملكــوم بــه مبوجــب الشــيك‬\n‫املســحوب علــى بنــك ‪ .....‬برقــم ‪ 294497‬وتاريــخ ‪2013/08/27‬م وأنــه‬\n‫لــم يبــق لــه وملوكليــه بذمــة املدعــى عليــه بخصــوص هــذه القضيــة أي‬\n‫شــيء وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم حــرر يف ‪1434/11/10‬هــ‪.‬‬\n\n\n\n\n                                                                                     ‫‪364‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":339,"source_page_end":364,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14925807a2b390394509e67a6b9b74e94fe47e8aa9e431781546c6438f6f7b92","normalized_text_hash":"873075aa555fd36bd56d6db0289e43fea97603b383ccf61d96e07580648f6260","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p339-33334176"},{"id":"b1c26d4e-5d92-5708-9f64-45959ba60e64","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وصية لبعض الورثة -ال وصية لوارث -ال يض ما زاد على ثلث التركة إال بإذن الورثة.","document_number":"33363338","case_number":"32322052","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/30","year":"1434","subject":"قسمة تركة -وصية لبعض الورثة -ال وصية لوارث -ال يض ما زاد على ثلث التركة إال بإذن الورثة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33363338 :‬تاريخه‪1433/7/30 :‬هـ‬\n                        ‫رقم الدعوى‪32322052 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34233526‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n      ‫قســمة تركــة ‪ -‬وصيــة لبعــض الورثــة ‪ -‬ال وصيــة لــوارث ‪ -‬ال ُيــض مــا‬\n                                        ‫زاد علــى ثلــث التركــة إال بــإذن الورثــة‪.‬‬\n\n\n\n                             ‫‪ .1‬قوله صلى اهلل عليه وسلم (ال وصية لوارث)‪.‬‬\n      ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم يف شــأن مــن أراد الوصيــة (الثلــث والثلث‬\n                                                                          ‫كثير)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليهــم بــأن مورثهــم خلــف عمــارة واســتراحة‬\n      ‫باعهــا أحــد املدعــى عليهــم مبائــة وخمســة عشــر ألــف ريــال وأربــع‬\n      ‫ســيارات تالفــة بيعــت بعشــرة آالف وتســعمائة ريــال ويطلــب ببيــع العمــارة‬\n      ‫وتســليم كل وارث نصيبــه الشــرعي‪ ،‬أجــاب املدعــى عليهــم باملصادقــة‬\n      ‫علــى الدعــوى وعــدم ممانعتهــم ببيعهــا وعلــى بيــع الســيارات واالســتراحة‬\n      ‫باملبالــغ املشــار إليهــا يف الدعــوى ومت توزيعهــا علــى الورثــة‪ ،‬وقــد أجابــت‬\n      ‫زوجــة مورثهــم بعــدم املوافقــة علــى بيــع العمــارة ألن املــورث أوصــى بهــا‬\n      ‫لبعــض الورثــة‪ ،‬اعتــرض املدعــي علــى الوصيــة ألن فيهــا جــور وصــادق‬\n      ‫علــى توزيــع قيمــة الســيارات واالســتراحة‪ ،‬قــرر املدعــي واملدعــى عليهــم‬\n      ‫بــأن البيــت ميثــل غالــب التركــة‪ ،‬ولقولــه صلى اهلل عليه وســلم (ال وصية‬\n\n‫‪365‬‬\n\f‫لــوارث)‪ ،‬وقولــه يف شــأن مــن أراد الوصيــة (الثلــث والثلــث كثيــر)‪ ،‬وملــا‬\n‫قــرره أهــل العلــم يف شــروط الوصيــة بــأن ال تزيــد علــى ثلــث التركــة‬\n‫وال يوصــى لــوارث وألن بعــض الورثــة لــم يوافــق علــى الوصيــة‪ ،‬ملــا تقــدم‬\n‫احلكــم ببيــع املنــزل محــل الدعــوى عــن طريــق جلنــة حتت إشــراف قاضي‬\n‫التنفيــذ وإيــداع ثلــث قيمتــه مــع ثلــث مــا مت بيعــه مــن بقيــة التركــة يف‬\n‫بيــت املــال إلــى حــن شــراء البــدل تنفيــذ ًا للوصيــة ويــوزع الباقــي علــى‬\n‫الورثــة حســب أنصبتهــم الشــرعية‪ ،‬اعتــرض بعــض املدعــى عليهــم علــى‬\n‫احلكــم‪ ،‬صــدق احلكــم بعــد مداولــة مــن دائــرة األحــوال الشــخصية‬\n                                               ‫مبحكمــة االســتئناف بالريــاض‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 32322052‬وتاريــخ ‪1432/08/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32978627‬وتاريــخ ‪1432/08/02‬ه ـ ففــي يــوم‬\n‫االربعــاء املوافــق ‪ 1433/3/9‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 22‬وفيهــا‬\n‫حضــر املدعــي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ 1034245447‬وحضر حلضوره املدعى عليهم ‪ ........‬سعودية مبوجب‬\n‫ســجل مدنــي رقــم ‪ ........‬و ‪ ........‬ســعودية مبوجــب ســجل مدنــي رقــم‬\n‫‪ ........‬و‪ ........‬ســعودية مبوجــب ســجل مدنــي رقــم ‪ ........‬واملعــرف بهــم‬\n‫من قبل ‪ ........‬سعودي مبوجب سجل مدني رقم ‪ ........‬و‪ ........‬سعودي‬\n‫مبوجــب ســجل مدنــي‪ ........‬ولــم يحضــر بقيــة الورثــة املدعــى عليهــم‬\n‫وهــم ‪ ........‬و‪ ........‬و‪ ........‬وال مــن ينــوب عنهــم ولــم يردنــا مــا يفيــد‬\n\n                                                                                      ‫‪366‬‬\n\f      ‫تبلغهــم وادعــى املدعــي قائــا يف دعــواه إن مورثــي ومــورث املدعــى‬\n      ‫عليهــم تــويف بتاريــخ ‪1429/10/7‬ه ـ وخلــف مــن ضمــن ورثتــه زوجتــه‬\n      ‫‪ ........‬وابنــه أنــا املدعــي ‪ ........‬وبناتــه ‪ ........ ........‬و‪ ........‬و‪ ........‬و‪........‬‬\n      ‫و‪ ........‬وقــد خلــف تركــة عبــارة عــن عمــارة يف حــي طويــق مبدينــة‬\n      ‫الريــاض مملوكــة لــه بالصــك الصــادر مــن كتابــة عــدل الريــاض‬\n      ‫األولــى برقــم ‪ 8/1592‬يف ‪1402/2/23‬ه ـ وإننــي أطلــب يف دعــواي هــذه‬\n      ‫ســؤال املدعــى عليهــم وبيــع العمــارة املذكــورة وتســليم كل وارث‬\n      ‫نصيبــه وإلــزام زوجتــه بتســليمنا صــك العمــارة املذكــورة هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليهــم أجابــوا جميعــا بــأن كل مــا ذكــره املدعــي يف‬\n      ‫دعــواه صحيــح وال مانــع لدينــا مــن بيــع العمــارة املذكــورة وتســليم كل‬\n      ‫وارث نصيبــه هــذا مــا لدينــا فجــرى ســؤالهم عــن صــك ملكيــة العقــار‬\n      ‫فقالــوا إنــه لــدى زوجــة مورثنــا ‪ ........‬وحضــر يف هــذه اجللســة ‪........‬‬\n      ‫ســعودي ‪ ........‬وقــال ‪ ........‬إننــي زوج ‪ ........‬وزوجــة املتوفــى خالتــي‬\n      ‫وأســتعد بإبالغهمــا باملوعــد القــادم وبنــاء عليــه فقــد قــررت رفــع اجللســة‬\n      ‫و يف جلســة اخــرى حضــر املدعــي أصالــة واملدعــى عليهــم ‪ ........‬و‪........‬‬\n      ‫و‪ ........‬بنــات ‪ ........‬املدونــة هوياتهــم ســابقا وحضــر حلضورهــم املدعــى‬\n      ‫عليهم ‪ ........‬ســعودية اجلنســية مبوجب الســجل املدني رقم ‪ ........‬و‪........‬‬\n      ‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬بصفتــه وكيــا عــن ‪........‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض‬\n      ‫برقــم ‪ 33108228‬يف ‪1433/6/8‬ه ـ املخــول لــه فيهــا بحــق املطالبــة‬\n      ‫واملرافعــة واملدافعــة واإلنــكار واإلقــرار والصلــح والتنــازل وقبــول‬\n      ‫األحــكام واالعتــراض عليهــا ‪ ،‬وقــد عــرف باملدعــى عليهــم جميعــا‬\n\n\n‫‪367‬‬\n\f‫كال مــن ‪ ........ :‬و‪ ........‬واملدونــة هويتهمــا ســابقا ‪ ،‬وبعــرض دعــوى‬\n‫املدعــي علــى بقيــة املدعــى عليهــم أجابــت املدعــى عليهــا ‪ ....‬قائلــة ‪ :‬إن مــا‬\n‫ذكــره املدعــي مــن وفــاة زوجــي ‪ ........‬وانحصــار ارثــه يف الورثــة‬\n‫املذكوريــن صحيــح وأمــا مــا ذكــره املدعــي مــن طلــب بيــع املنــزل‬\n‫املذكــور فأنــا ال أوافــق عليــه وذلــك أن العقــار املذكــور ملــك ملورثنــا‬\n‫وقــد أوصــى بــه يف حياتــه بــأن يكــون الدور الســفلي لبناتــه ‪ ........‬و‪........‬‬\n‫ووالدتهــم ‪ ........‬وعليهــم اضحيتــن وأمــا الــدور الثانــي فهــو لبناتــه‬\n‫املتزوجــات ‪ ........‬و‪ ........‬و‪ ........‬مــن احتــاج منهــن وابنــه ‪ ........‬وهــذا‬\n‫البيــت موصــى بــه للورثــة بــأن يســتفيدوا منــه وال أوافــق علــى بيعــه ‪،‬‬\n‫وأجابــت املدعــى عليهــا ‪ .....‬قائلــة ‪ :‬إن مــا ذكــره املدعــي مــن وفــاة مورثنا‬\n‫وانحصــار ارثــه يف الورثــة املذكوريــن وأنــه ميلــك املنــزل املذكــور كل‬\n‫هــذا صحيــح واملنــزل وقــف لوالــدي وال أوافــق علــى بيعــه هــذا مــا لــدي‬\n‫واجــاب املدعــى عليــه وكالــه ‪ ....‬قائــا‪ :‬مــا ذكــره املدعــي مــن وفــاة‬\n‫مــورث موكلتــي وانحصــار ارثــه يف الورثــة املذكوريــن وأنــه ميلــك املنــزل‬\n‫املذكــور كل هــذا صحيــح وموكلتــي ال توافــق علــى بيــع املنــزل‬\n‫لكونــه وقــف لوالدهــا هــذا مــا لــدي و بعــرض ذلــك علــى املدعــي قــال إن‬\n‫والــدي كان ميلــك يف حياتــه أربــع ســيارات تالفــه هــي ‪ ......‬موديــل‪1997‬م‬\n‫و‪ ......‬موديــل‪1990‬م وجرانــد كرافــان موديــل‪1994‬م وامبريــال‬\n‫كرايســلر موديــل‪1991‬م باعهــا وكيــل الورثــة ‪ ...‬هــذا احلاضــر مببلــغ‬\n‫عشــرة آالف وتســعمائة ريــال كمــا ميلــك مورثنــا اســتراحة يف جــو بعــد‬\n‫املزاحميــة ميلكهــا بصــك مت بيعهــا مببلــغ مائــة وخمســة عشــر ألــف ريــال‬\n‫وميلــك املنــزل محــل الدعــوى وأنــا ال ارضــى بوصيــة والــدي لوجــود اجلــور‬\n‫فيهــا إذ التصــرف فيهــا للمدعــى عليهــا ‪ ........‬وأطلــب بيعهــا وقيمــة‬\n\n\n                                                                                         ‫‪368‬‬\n\f      ‫الســيارات واالســتراحة مت توزيعهــا هــذا مــا لــدي ‪ ،‬وبعــرض ذلــك علــى‬\n      ‫املدعــى عليهــم أجابــوا بــأن مــا ذكــره املدعــي مــن حصــر التركــة وأنــه‬\n      ‫مت بيــع الســيارات واالســتراحة املذكــورة باملبالــغ املذكــورة صحيــح‬\n      ‫وقــد مت تســديد ديونــه ووزع الباقــي علينــا بحســب األنصبــة الشــرعية‬\n      ‫ه ـ ـ ــذا ما لـ ـ ــدينا هذا وأب ـ ــرزت املدعى عليها ‪ .......‬ال ـ ـ ــصك الصادر من‬\n      ‫كتابـ ــة ع ـ ـ ـ ــدل الريـ ـ ـ ــاض األولــى برقــم ‪ 8/1592‬يف‪1402/2/23‬ه ـ‬\n      ‫ووجدتــه مطابقــا ملــا جــاء يف دعــواه كمــا ابــرز صــك حصــر اإلرث‬\n      ‫الصــادر مــن هــذه احملكمــة رقــم‪ 32/100/141‬يف ‪1428/10/19‬ه ـ‬\n      ‫واملتضمــن ثبــوت وفــاة ‪ ........‬وانحصــار ارثــه يف زوجتــه ‪ ........‬ويف ابنــه‬\n      ‫‪ ........‬وبناتــه ‪ ........‬و‪ ........‬و‪ ........‬و‪ ، ........‬كمــا أبــرزت صــك صــادر‬\n      ‫مــن كتابــة عــدل الريــاض األولــى برقم‪1/82‬يف‪1412/11/4‬ه ـ‬\n      ‫املتضمــن اثبــات وصيــة ‪ ........‬ونــص احلاجــة منــه وأوصــي بالفيــا العائــدة‬\n      ‫لــي والواقعــة يف حــي ‪ ........‬بالريــاض اململــوك لــي مبوجــب الصــك‬\n      ‫الصــادر مــن عــدل الريــاض األولــى برقــم‪ 8/1592‬يف‪1402/2/3‬ه ـ بــان‬\n      ‫يكــون الــدور الســفلي منهــا بيــد بناتــي ‪ ........‬و‪ ........‬ووالدتهــم ‪........‬‬\n      ‫وعليهــم اضحيتــن لــي ولوالــدي مطلق الصقري ووالدتــي ‪ ........‬وزوجتي‬\n      ‫‪ ........‬امــا بالنســبة للــدور العلــوي مــن احتــاج الســكن مــن بناتــي‬\n      ‫املتزوجــات ‪ ........‬و‪ ........‬و‪ ........‬وابنــي ‪ ........‬فلــه ذلــك ويجــب عليهــم‬\n      ‫القيــام بتســديد قــروض البنــك ‪ ........‬مــع ســاكني الــدور الســفلي‬\n      ‫وكذلــك صيانــة العمــارة مــن جميــع احتياجاتهــا وان اســتغنوا عــن‬\n      ‫الســكن ومــا زاد مــن ايجارهــا فيقســم بينهــم حســب القســمة الشــرعية‬\n      ‫وقــال املدعــي واملدعــى عليهــم ان هــذه هــي وصيــة والدنــا هــذا مــا لدينــا‬\n      ‫كمــا قالــت املدعــى عليهمــا ‪ ........‬و‪ ..........‬اننــا نقــرر لديكــم توكيــل‬\n\n\n‫‪369‬‬\n\f‫‪ ........‬يحمــل الســجل املدنــي رقــم‪ ........‬يف هــذه الدعــوى ولــه حــق‬\n‫املرافعــة واملدافعــة واملخاصمــة واإلقــرار واإلنــكار وســماع البينــات‬\n‫واإلفــراغ وقبولــه واســتالم كل مــا يخصنــا فيمــا يتعلــق بالتركــة كمــا‬\n‫قــررت املدعــى عليهــا ج‪ ........‬قائلــة اننــي أوكل اخــي ‪ ........‬املدعــي يف‬\n‫هــذه الدعــوى ولــه حــق املرافعــة واملدافعــة وســماع الدعــوى واإلقــرار‬\n‫واإلنــكار واإلفــراغ واســتالم الثمــن وقــد شــهد علــى توكيلهــم جميعــا‬\n‫كاتبــه واملعرفــن املذكوريــن وبنــاء عليــه فقــد ثبــت لــدي توكيــل‬\n‫املدعــى عليهــم املذكــورات ‪ ........‬و‪ ........‬و‪ ........‬للــوكالء املذكوريــن‬\n‫وعليــه قــررت رفــع اجللســة و يف جلســة اخــرى حضــر املدعــي ‪........‬‬\n‫وحضــر حلضــوره املدعــى عليهــم كال مــن ‪ ........‬و‪ ........‬و‪ ........‬واملدعــى‬\n‫عليهــم وكالــة ‪ ........‬و‪ ........‬وقــد عــرف باملدعــى عليهــم احلاضــر ‪........‬‬\n‫و‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬هــذا وقــد‬\n‫وردنــا خطــاب كتابــة العــدل األولــى بالريــاض رقــم ‪ 331116733‬يف‬\n‫‪ 1433/6/23‬ه ـ املتضمــن أن الصــك رقــم ‪8/1592‬يف ‪ 1402/2/23‬ال‬\n‫زال ســاري املفعــول وقــال املدعــي واملدعــى عليهــم ‪ ........‬و‪ ........‬و‪........‬‬\n‫إننــا ال نوافــق علــى وصيــة والدنــا ونطلــب بيــع املنــزل كمــا قــال املدعــي‬\n‫واملدعــى عليهــم جميعــا إن املنــزل املذكــور ميثــل غالــب التركــة وبنــاء‬\n‫علــى مــا ســبق مــن الدعــوى واإلجابــة و لقولــه صلــى اهلل عليــه وســلم ال‬\n‫وصيــة لــوارث وقولــه صلــى اهلل عليــه وســلم الثلــث والثلــث كثيــر يف‬\n‫شــأن مــن أراد الوصيــة وقــد قــرر أهــل العلــم شــروطا للوصيــة هــي أن ال‬\n‫تخــرج عــن ثلــث التركــة وال يوصــى لــوارث ومبــا أن املدعــي واملدعــى‬\n‫عليهــم ‪ ........‬و‪ ........‬و‪ ........‬لــم يوافقــوا علــى وصيــة والدهــم ومبــا أن‬\n‫املدعــي واملدعــى عليهــم قــرروا أن املنــزل املذكــور ميثــل غالــب التركــة‬\n\n\n                                                                                      ‫‪370‬‬\n\f      ‫والوصيــة بــه تخــرج عــن الثلــث لذلــك كلــه فقــد حكمــت ببيــع املنــزل‬\n      ‫محــل الدعــوى عــن طريــق جلنــة حتــت إشــراف قاضــي التنفيــذ وقــررت‬\n      ‫إيــداع ثلــث قيمتــه مــع ثلــث مــا مت بيعــه مــن بقيــة التركــة يف بيــت املــال‬\n      ‫إلــى حــن شــراء البــدل تنفيــذا للوصيــة ويــوزع الباقــي علــى الورثــة حســب‬\n      ‫أنصبتهــم الشــرعية وبعــرض احلكــم علــى املدعــي واملدعــى عليهــم قــرر‬\n      ‫املدعــي واملدعــى عليهــم ‪ ........‬و‪ ........‬و‪ ........‬القناعــة أمــا املدعــى‬\n      ‫عليهــم وكالــة فلــم يقتنعــوا باحلكــم وطلبــوا رفــع املعاملــة إلــى محكمــة‬\n      ‫االســتئناف فأجبتهــم لطلبهــم وأفهمتهــم أنــه ســوف يســلم لهــم صــورة مــن‬\n      ‫نســخة احلكــم يــوم األثنــن املوافــق ‪ 1433/8/5‬ه ـ وأن لهــم مهلــة ثالثــن‬\n      ‫يومــا لتقــدمي لوائحهــم االعتراضيــة وإذا انتهــت املهلــة ولــم يتقدمــوا‬\n      ‫بلوائحهــم ســقط حقهــم يف االعتــراض ومت رفــع املعاملــة إلــى محكمــة‬\n      ‫االســتئناف حلــق الوقــف وبــه ختمــت اجللســة يف متــام الســاعة الثانيــة عشــر‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪ 1433/07/30‬ه ـ احلمــد هلل وحــده وبعــد‪ -:‬ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/04/24‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــر املدعــى عليهــم‪ ........ /‬و‪ ........‬و‪ ........‬بنــات ‪ ........‬املعــرف‬\n      ‫بهــم مــن قبــل‪ ........ /‬املدونــة هويتــه ســابقا‪ ،‬واملدعــى عليــه وكالــة‪/‬‬\n      ‫‪ ، ........‬وأمــا املدعــي‪ ، ........ /‬واملدعــى عليهــا‪ ........ /‬فلــم يحضــرا‪،‬‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم‪( :‬‬\n      ‫‪ )331753100‬يف ‪1433/11/2‬ه ـ ـ وبرفقهــا قــرار دائــرة األحــوال‬\n      ‫الشــخصية الثانيــة برقــم‪ )33431531(:‬وتاريــخ ‪1433/10/18‬ه ـ ـ‬\n      ‫املتضمــن مــا نصــه‪« :‬لوحــظ مــا يلــي ‪/1‬يظهــر أن العقــار موضــع الدعــوى‬\n      ‫مرهــون لصنــدوق التنميــة العقــاري ولــم جنــد‪ ،‬فضيلتــه خاطــب‬\n\n\n‫‪371‬‬\n\f‫الصنــدوق؛ ألخــذ مــا لديــه حيــال الرهــن‪ ،‬وأخــذ ذلــك يف االعتبــار عنــد‬\n‫احلكــم بالبيــع‪/2 .‬ذكــر املدعــى عليهــم املعترضــون يف الئحتهــم‬\n‫االعتراضيــة رغبتهــم يف عــدم بيــع العمــارة وإمنــا تثمينهــا وإبقــاء الثلــث‬\n‫الوصيــة ونصيبهــم فيهــا بعــد إخــراج نصيــب املدعــن ملــا ذكــروه مــن‬\n‫املبــررات املذكــورة ممــا يســتدعي النظــر يف ذلــك وحتــري األصلــح‬\n‫للجميــع ودفعــا للضــرر لقولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضرار)‬\n‫ممــا هــو مناســب وموافــق شــرعا»ا‪.‬ه ـ ـ ‪ ،‬وبعــرض ذلــك عليهــم‪ ،‬قالــوا‬\n‫جميعــا‪ :‬إن العقــار محــل الدعــوى كان مرهونــا‪ ،‬وقــد مت فــك الرهــن‬\n‫عنــه‪ ،‬وقالــت كال مــن ‪ ........‬و‪ ........‬و‪ : ........‬إننــا نطلــب بيــع العقــار‬\n‫وإعطــاء كل وارث نصيبــه بعــد فــرز قيمــة الثلــث للوصيــة‪ ،‬وقــال‬\n‫املدعــى عليــه وكالــة ‪ : ........‬إن موكلتــي يطلبــان إبقــاء الوصيــة بحالها‬\n‫حســبما ورد فيهــا‪ ،‬وإال بيــع العقــار وإعطــاء كل مــن الورثــة نصيبــه وال‬\n‫تســتطيعان شــراء نصيــب بقيــة الورثــة‪ ،‬هــذا مــا لــدي‪ .‬هــذا وقــد جــرى‬\n‫االطــاع علــى صــك العقــار املذكــور وقــد همــش عليــه بفــك الرهــن عــن‬\n‫العقــار‪ ،‬وقــال املعــرف املذكــور‪ :‬إننــي وكيــل عــن املدعــي ولــم أحضــر‬\n‫وكالتــي‪ ،‬وأطلــب إمهالــي إلحضارهــا‪ ،‬وبنــاء عليــه مت رفــع اجللســة ‪ ،‬ثم‬\n‫يف جلســة أخــرى حضــر املدعــى عليهــن ‪ .......‬و‪ ........‬و‪ ........‬بنــات ‪........‬‬\n‫املعــرف بهــن مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ........‬ولــم يحضــر املدعــي و ال بقيــة املدعــى عليهــم و بنــاء عليــه و مبــا ان‬\n‫املدعــى عليهــم يف اجللســة الســابقة قــرروا رغبتهــم يف بيــع العقــار وعــدم‬\n‫املوافقــة علــى الوصيــة بــه و انــه ميثــل اكثــر مــن الثلــث و مبــا انــه ال‬\n‫ميكــن القســمة اال ببيعــه لــذا فلــم يظهــر لــي مــا يؤثــر علــى مــا حكمــت‬\n‫بــه وقــرر بعــث املعاملــة الــى محكمــة االســتئناف و بــه ختمــت اجللســة يف‬\n\n\n                                                                                         ‫‪372‬‬\n\f      ‫متــام الســاعة الثالثــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/04/30‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331947006‬وتاريخ‪1434/5/11‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪........ /‬‬\n      ‫املســجل برقــم ‪ ........‬وتاريــخ‪ 1433/7/30‬ه ـ اخلــاص بدعــوى‪........ /‬‬\n      ‫ضــد ‪ ........ /‬بشــأن قســمة تركــه وقــد تضمــن الصــك حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصك وصــورة ضبطه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا رقــم ‪33431531‬‬\n      ‫وتاريــخ ‪1433/10/18‬ه ـ تقــرر الدائــرة املصادقــة بعــد اجلــواب األخيــر‪،‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪373‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":365,"source_page_end":373,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7fb06679eaaa82d4ef8c8eeb84731804083a77bc59b18eaca6591b95c8d23100","normalized_text_hash":"837bf7f5a3ee2d9258ae501315b04623e651094c3989c3a28d80752558286c6f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p365-33363338"},{"id":"1eebeb53-f2a9-5167-8132-56d580e46263","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة مورث وترك أرض -قيام بعض الورثة ببيع األرض ورفض البعض للبيع -مطالبة الرافضن إمتام البيع -إدخال مشتري األرض يف الدعوى -إثبات البيع بشاهد عدل ومين -إقرار جميع الورثة ببيع األرض -ثبوت بيع جميع الورثة -تقسيم مبلغ األرض على الورثة كل حسب نصيبه الشرعي وإيداع نصيب من يرفض االستالم بيت مال المحكمة وإفراغ الصك محل الدعوى بعد اكتساب احلكم القطعية .","document_number":"33411128","case_number":"32216222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/13","year":"1434","subject":"قسمة تركة -وفاة مورث وترك أرض -قيام بعض الورثة ببيع األرض ورفض البعض للبيع -مطالبة الرافضن إمتام البيع -إدخال مشتري األرض يف الدعوى -إثبات البيع بشاهد عدل ومين -إقرار جميع الورثة ببيع األرض -ثبوت بيع جميع الورثة -تقسيم مبلغ األرض على الورثة كل حسب نصيبه الشرعي وإيداع نصيب من يرفض االستالم بيت مال المحكمة وإفراغ الصك محل الدعوى بعد اكتساب احلكم القطعية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33411128 :‬تاريخه‪1433/9/13 :‬هـ‬\n                   ‫رقم الدعوى‪32216222 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3458162‬تاريخه‪1434/3/9 :‬هـ‬\n\n\n‫قســمة تركــة‪ -‬وفــاة مــورث وتــرك أرض‪ -‬قيــام بعــض الورثــة ببيــع‬\n‫األرض ورفــض البعــض للبيــع‪ -‬مطالبــة الرافضــن إمتــام البيع‪ -‬إدخال‬\n‫مشــتري األرض يف الدعــوى‪ -‬إثبــات البيــع بشــاهد عــدل وميــن‪ -‬إقــرار‬\n‫جميــع الورثــة ببيــع األرض‪ -‬ثبــوت بيــع جميــع الورثــة‪ -‬تقســيم مبلــغ‬\n‫األرض علــى الورثــة كل حســب نصيبــه الشــرعي وإيــداع نصيــب مــن‬\n‫يرفــض االســتالم بيــت مــال احملكمــة وإفــراغ الصــك محــل الدعــوى‬\n                                       ‫بعــد اكتســاب احلكــم القطعيــة ‪.‬‬\n\n\n\n‫حديــث أبــي هريــرة رضــي اهلل عنــه (أن النبــي صلــى اهلل عليــه وســلم‬\n                          ‫قضــى بالشــاهد واليمــن) أخرجــه أحمــد ‪.‬‬\n\n\n\n\n‫ادعــى املدعيــان أصالــة ووكالــة ضــد املدعــى عليــه أصالــة ووكالــة بــأن‬\n‫مورثهــم خلــف لهــم أرض ـ ًا وقــد باعــوا األرض مببلــغ أربعمائــة وخمســن‬\n‫ألــف ريــال والســعي عليهــم ولكــن املدعــى عليهمــا رفضا البيــع ويطلبون‬\n‫إلزامهمــا بالبيــع‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى أن مورثهــم خلــف‬\n‫لهــم األرض وأنكــر البيــع وصــادق علــى رفضــه البيــع وموكلــه وأن‬\n‫الســبب يف ذلــك هــو أن مورثهــم خلــف عمــارة بجــوار األرض وقــد رفــض‬\n\n                                                                                  ‫‪374‬‬\n\f      ‫املدعــون بيعهــا ويرغــب هــو وموكلــه ببيعهــا واألرض باملــزاد العلنــي‪،‬‬\n      ‫أجــاب املدعــون بأنهــم يعترضــون علــى بيعهــا باملــزاد العلنــي ألنهــا قــد‬\n      ‫تتضــرر مــن نقــص القيمــة عــن الســعر احلالــي‪ ،‬تداخــل املشــتري وقــرر‬\n      ‫بــأن الورثــة باعــوه األرض ومــن ضمنهــم املدعــى عليــه وأنــه خســر قرابــة‬\n      ‫عشــرة آالف إلكمــال الناقــص يف الصــك مــن إجــراءات التعقيب والرفع‬\n      ‫املســاحي‪،‬صادق املدعــون علــى البيــع وأنكــره املدعــى عليه‪،‬أحضــر‬\n      ‫املتداخــل بينــة وهمــا شــاهدان مت تعديلهمــا شــهدا طبــق مــا ذكــره‬\n      ‫بخصــوص البيــع‪ ،‬حلــف اليمــن املتممــة لبينتــه بعــد عرضهــا عليــه‪ ،‬بنــاء‬\n      ‫علــى شــهادة أحــد الشــهود واملعدلــة شــرع ًا واليمــن املتممــة لهــذه البينــة‪،‬‬\n      ‫وحلديــث (أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــاهد واليمــن)‬\n      ‫أخرجــه أحمــد‪ ،‬ثبــوت بيــع جميــع الورثــة مبــا فيهــم املدعــى عليهمــا‬\n      ‫األرض العائــدة ملورثهــم علــى املتداخــل بيع ـ ًا صحيح ـ ًا بثمــن قــدره‬\n      ‫أربعمائــة وثمانيــة وثالثــون ألف ـ ًا وخمســمائة ريــال واحلكــم بصحتــه‬\n      ‫ولزومــه علــى الورثــة‪ ،‬واحلكــم بإفــراغ الصــك محــل الدعــوى للمتداخــل‬\n      ‫بعــد اكتســاب احلكــم القطعيــة وتقســيم املبلــغ علــى الورثــة كل‬\n      ‫حســب نصيبــه الشــرعي وإيــداع نصيــب مــن يرفــض االســتالم ببيــت مــال‬\n      ‫احملكمــة‪ ،‬بعــث احلكــم لتبليــغ املدعــى عليهمــا بــه‪ ،‬صــدق احلكــم‬\n                                                            ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪375‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فلــدي‬\n‫أنــا ‪ .....‬القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء على املعاملة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم‬\n‫‪ 32216222‬وتاريــخ ‪1432/06/07‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 32674093‬وتاريــخ ‪1432/06/07‬ه ـ يف يــوم االربعــاء املوافــق‬\n‫‪1433/01/19‬ه ـ أفتتحــت اجللســة الســاعة الثامنــة والنصــف صباح ـ ًا‬\n‫ال مــن ‪ .....‬ســعودي اجلنســية مبوجــب‬       ‫وفيهــا حضــر ورثــة ‪ .....‬وهــم ك ً‬\n‫الســجل املدنــي رقــم ‪ ..... .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬و‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬أصالـ ًة‬\n‫عــن نفســه وبوكالتــه عــن ‪ ..... ..... ..... ..... ..... ..... .....‬أوالد ‪.....‬‬\n‫بالوكالتــن رقــم ‪ 38472‬يف ‪1431/6/18‬ه ـ ورقــم ‪ 11600‬يف‬\n‫‪1432/2/25‬ه ـ الصادرتــن مــن كتابــة عــدل املدينــة وحضــر حلضورهم‬\n‫املدعــى عليــه‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n‫أصالــة عــن نفســه وبوكالتــه عــن ‪ .....‬بالوكالــة رقــم ‪ 65614‬يف‬\n‫‪1432/11/10‬ه ـ الصــادرة مــن كتابــة عــدل املدينــة بصفتــه وارثــا ألمــه‬\n‫‪ .....‬وهــي أحــد بنــات ‪ .....‬وبســؤال احلاضريــن عــن دعواهــم أدعــو أصالــة‬\n‫ووكالــة علــى املدعــى عليهمــا قائلــن ‪ :‬إننــا مــن ورثــة والدنــا ‪ ....‬الــذي‬\n‫خلــف لنــا أرض يف حــارة ‪ .....‬مملوكــة ملورثنــا مبوجــب ‪ 1/750‬يف‬\n‫‪1400/6/22‬ه ـ الصــادر مــن كتابــة عــدل املدينــة املنــورة وقــد بعنــا‬\n‫األرض علــى املدعــو ‪ .....‬بقيمــة أربعمائــة وخمســن ألــف ريــال والســعي‬\n‫علينــا ورفــض البيــع املدعــى عليهمــا نطلــب إلزامهمــا بالبيــع ‪ .‬وبعــرض‬\n\n                                                                                       ‫‪376‬‬\n\f      ‫ا مــا ذكــره املدعــي‬   ‫ذلــك علــى املدعــى عليــه أصالــة ووكالــة أجــاب قائـ ً‬\n      ‫مــن أن والدنــا قــد خلــف لنــا األرض املذكــورة فصحيــح وأمــا البيــع فغير‬\n      ‫صحيــح ولــم نبــع علــى أحــد إطالقـ ًا ومــا ذكره مــن رفضي أنــا وموكلي‬\n      ‫للبيــع املذكــور فهــو صحيــح وســبب ذلــك أن مورثنــا قــد تــرك لنــا عمــارة‬\n      ‫قريبــة مــن هــذه األرض وقــد رفــض املدعــن بيــع هــذه العمــارة وإننــا‬\n      ‫نرغــب أنــا وموكلــي ببيــع األرض والعمــارة جميع ـ ًا باملــزاد العلنــي‬\n      ‫ونرفــض البيــع بغيــر هــذه الطريقــة كمــا نرفــض بيــع االرض لوحدهــا‬\n      ‫أضمــن حلقنــا؛ علمـ ًا أن هنــاك بعــض الورثــة وورثتهــم رافضــن للبيــع ولــم‬\n      ‫يحضــروا ولــم يوكلــوا حتــى اآلن أطلــب إلزامهــم ببيــع العمــارة التــي‬\n      ‫خلفهــا لنــا والدنــا عــن طريــق املــزاد العلنــي كمــا هــو املتبــع هكــذا‬\n      ‫اجــاب وبعــرض ذلــك علــى املدعــن أصالــة ووكالــة أجابــوا قائلــن‪ :‬أننــا‬\n      ‫ســبق وأن بعنــا علــى املذكــور هــذه وال نعلــم عــن بيــع املدعــى عليهــم‬\n      ‫شــيئ ًا وأننــا نعتــرض علــى بيعهــا باملــزاد ألنــه قــد نتضــرر من نقــص القيمة‬\n      ‫باملزاد عن الســعر احلالي ‪ .‬ويف نفس اجللســة حضر ‪ .....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وطلــب التداخــل يف الدعــوى وبســؤاله‬\n      ‫ا ‪ :‬إنــي يف شــهر ربيــع الثانــي مــن عــام‬  ‫عــن وجــه تداخلــه أجــاب قائ ـ ً‬\n      ‫‪1432‬ه ـ بــاع علــي جميــع الورثــة مبــا فيهــم احلاضــر ‪ .....‬مببلــغ أربعمائــة‬\n      ‫وخمســن ألــف ريــال مبــا فيهــا الداللــة وألــف وخمســمائة ريــال للمكتــب‬\n      ‫وحضــر الورثــة لكتابــة العــدل األولــى إال أن الــوكاالت املوجــودة وجــد‬\n      ‫بهــا أخــت متوفيــه فطلبــوا منهــم جتديــد الوكالــة علم ـ ًا أننــي أكملــت‬\n      ‫مــا نقــص يف الصــك مــن إجــراءات وكلفنــي عشــرة آالف ريــال للتعقيــب‬\n      ‫والكروكــي والرفــع املســاحي وحــررت شــيك مببلــغ أربعمائــة وثمانيــة‬\n      ‫وثالثــن ألفـ ًا وخمســمائة ريــال املبلــغ املتبقــي‪ .‬هكــذا تداخــل‪ .‬وبعــرض‬\n\n\n‫‪377‬‬\n\f‫ذلــك علــى املدعــن أجابــوا قائلــن مــا ذكــره املتداخــل كلــه صحيــح إال‬\n‫بيــع ‪ .....‬وموكليــه فــا نعــرف عنــه شــيئ ًا ‪.‬هكــذا أجابــوا‪ .‬وبعــرض ذلــك‬\n‫ا مــا ذكره مــن حضوري‬       ‫علــى املدعــى عليــه أصالــة ووكالــة أجــاب قائـ ً‬\n‫وبيعــي لــأرض فغيــر صحيــح إطالق ـ ًا ‪.‬هكــذا أجــاب‪ .‬والنتهــاء وقــت‬\n‫اجللســة رفعــت اجللســة ‪ ،‬ثــم يف يــوم الســبت املوافــق ‪1433/02/27‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة والنصــف صباحـ ًا وفيهــا حضــر املدعــي‬\n‫‪ .....‬واملدعــي ‪ .....‬واملتداخــل ‪ .....‬ولــم يحضــر املدعــي الثالــث ‪ .....‬ولــم‬\n‫يحضــر املدعــى عليــه أصالــة ووكالــة ولــم يوقــع علــى ضبــط اجللســة‬\n‫الســابقة املنعقــدة بتاريــخ ‪1433/1/19‬ه ـ ‪ ،‬وقــد حــرر محضــر بذلــك‬\n‫أســفل الضبــط وكان ذلــك بشــهادة كل مــن كاتــب الضبــط ‪.....‬‬\n‫والعســكري ‪ ......‬وذكــر املتداخــل أن لديــه شــهود علــى البيــع ويطلــب‬\n‫إمهالــه إلحضارهــم؛ لــذا رفعــت اجللســة إلــى يــوم األربعــاء املوافــق‬\n‫‪1433/03/09‬ه ـ الســاعة العاشــرة والنصــف ‪ ،‬ثــم يف يــوم األربعــاء‬\n‫‪1433/3/9‬ه ـ حضــر املدعــن الثالثــة و حضــر املتداخــل ولــم يحضــر‬\n‫املدعــى عليــه ولــم يتبلــغ مبوعــد هــذه اجللســة وقــد أحضــر املتداخــل معــه‬\n‫للشــهادة ‪ .....‬ســعودي اجلنســية بســجل مدنــي رقــم ‪ .....‬وبســؤاله عمــا‬\n‫لديــه قــال ‪ :‬إننــي أبلــغ مــن العمــر واحــد وأربعــن عامــا و أعمــل مســتخدم‬\n‫يف مدرســه ‪ .....‬اإلبتدائيــة وأقيــم يف املدينــة املنــورة و أعــرف املتداعــن‬\n‫واملتداخــل ‪ ....‬متــام املعرفــة وليــس لــي أي قرابــة باملتداعــن أمــا املتداخــل‬\n‫فأمــه ابنــة عمــي و أشــهد هلل تعالــى ‪ :‬أنــه قبــل أربعــة أشــهر مــن اآلن كنــا‬\n‫واقفــن أنــا و‪( ..........‬املشــتري) واملدعــى عليهمــا و‪ ، .....‬املدعــى عليــه‬\n‫و‪ .....‬عنــد بــاب بيــت خالــه ‪ .....‬يف حــي ‪ .....‬و ســمعت املدعــى عليهمــا ‪.....‬‬\n‫‪ .....‬يقــوالن نحــن بائعــن عليــك مــع بقيــة الورثــة والنيــة لــك‪ ،‬يقصــدون‬\n\n\n                                                                                        ‫‪378‬‬\n\f      ‫‪ .....‬فلمــا طلــب ‪ .....‬منهــم احلضــور لإلفــراغ اعتــذر ‪ .....‬بــأن لــه شــغل يف‬\n      ‫جــده ووعــد بــأن يحضــر بعــد عودتــه مــن جــده بــأن يحضــر لإلفــراغ ‪.‬‬\n      ‫هكــذا اشــهد‪ .‬ثــم طلبــت مــن املتداخــل زيــادة بينــه علــى ذلــك فقــال لــدي‬\n      ‫شــاهد وهــو املدعــي األول ‪ .....‬فأفهمتــه أنــه ال تقبــل شــهادته لعــدم انتفــاء‬\n      ‫التهمــة؛ فاســتعد باليمــن املتممــة لبينتــه ثــم طلبــت مــن املتداخــل إحضــار‬\n      ‫معدلني لبينته؛ لذا رفعت اجللسة إلى يوم السبت بتاريخ ‪1433/3/26‬هـ‬\n      ‫الســاعة العاشــرة والنصــف‪ ،‬ثــم يف يــوم الســبت املوافق‪1433/03/26‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العاشــرة والنصــف صباحــا‪ ،‬وفيهــا حضــر‬\n      ‫املدعــن الثالثــة وحضــر املتداخــل‪ ،‬وحضــرت ‪ .....‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وبعــد تعريفهــا مــن قبــل ابنهــا ‪.....‬‬\n      ‫ســعودي بالســجل املدنــي رقــم ‪ ، .....‬كمــا حضــر مــن ورثــة‪ .....‬ســعودي‬\n      ‫بالســجل املدني ‪ .....‬و‪ .....‬ســعودي بالســجل املدني رقم ‪ .....‬و‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، .....‬أصالــة عــن نفســه وبوكالته‬\n      ‫عــن بنتــن مــن ورثــة والدتــه ‪ .....‬وهمــا ‪ ..... .....‬بنتــي ‪ .....‬التــي تخــول لــه‬\n      ‫البيــع‪ ،‬والشــراء‪ ،‬واإلفــراغ‪ ،‬وقبولــه‪ ،‬واســتالم الثمــن‪ ،‬وتســليم املثمن‪،‬‬\n      ‫والتأجيــر واملداعــاة‪ ،‬واملخاصمــة‪ ،‬وســماع الدعــاوي‪ ،‬والــرد عليهــا‪،‬‬\n      ‫وإقامــة البينــة‪ ،‬والدفــع‪ ،‬وقبــول احلكــم‪ ،‬واالعتــراض عليــه‪ ،‬واســتالم‬\n      ‫جميــع مــا يخصنــا مــن إرث والدتنــا ‪ ، .....‬والعائــد لهــا مــن مورثهــا والدها‬\n      ‫‪ .‬ثــم جــرى ســؤال املتداخــل عمــا وعــد بــه مــن مزكــن لشــاهده فأحضــر‬\n      ‫ال مــن ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و‪.....‬‬        ‫ك ً‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وبســؤالهما عمــا‬\n      ‫لديهمــا قــاال ‪ :‬نشــهد هلل أن الشــاهد ‪ .....‬صاحــب ديــن وأمانــة وصــدق‬\n      ‫وصالــح للشــهادة‪ .‬هكــذا شــهدا ‪ .‬ثــم قــرر احلاضــرون جميع ـ ًا قائلــن ‪:‬‬\n\n\n‫‪379‬‬\n\f‫إن املدعــى عليــه وموكلــه لــم يحضــرا لظــرف لديهمــا وقــد جلســنا‬\n‫مجلــس صلــح واتفقنــا علــى بيــع هــذه األرض علــى املتداخــل ‪ .....‬مببلــغ‬\n‫أربعمائــة وخمســن ألــف ريــال مبــا فيهــا الداللــة البالغــة أحــد عشــر ألفــا‬\n‫وخمســمئة ريــال‪ ،‬وتأجيــل بيــع العمــارة املذكــورة يف جــواب املدعــى‬\n‫عليــه إلــى أجــل غيــر مســمى‪ ،‬وســيحضر املدعــى عليهمــا غــد ًا إلقــرار‬\n‫هــذا البيــع والتنــازل عــن طلــب بيــع العمــارة املذكــورة‪ .‬ونحــن نقــرر‬\n‫أمامكــم أنــه ال مانــع لدينــا مــن إفــراغ األرض املذكــورة للمتداخــل وال‬\n‫مانــع لدينــا مــن إيــداع قيمــة هــذه األرض لبيــت مــال احملكمــة وتســليمه‬\n‫للورثــة بعــد ذلــك كل حســب اســتطاعته وفراغــه يحضر ويســتلم نصيبه‬\n‫‪ .‬هكــذا قــرروا جميع ـ ًا ‪ .‬لــذا رفعــت اجللســة وحــدد لهــا موعــد غــد ًا‬\n‫األحــد املوافــق ‪1433/03/27‬ه ـ الســاعة الواحــدة ألخــذ موافقــة املدعى‬\n‫عليهمــا‪ .‬وتعهــد املدعــي ‪ .....‬بإحضــار املدعــى عليهمــا غــد ًا إلقــرار هــذا‬\n‫الصلــح مــع شــاهدين يشــهدان عليهــا بالصلــح ‪ .‬كمــا حــدد جلســة ثانيــة‬\n‫يــوم الســبت املوافــق ‪1433/05/22‬ه ـ الســاعة التاســعة والنصــف‬\n‫لالطــاع علــى صكــوك حصــر اإلرث للمتوفــن الثالثــة‪ ،‬والتأكــد مــن‬\n‫الــوكاالت والتأمــل يف مــا ســبق ضبطــه مــن دعــوى وإجابــات وإقــرارات‬\n‫‪.‬ثــم يف يــوم اإلثنــن املوافق‪1433/03/28‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الواحــدة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــى عليــه أصالــة عــن‬\n‫نفســه وبوكالتــه عــن املدعــى عليــه ‪ .....‬بالوكالــة رقــم ‪ 65614‬وتاريــخ‬\n‫‪1432/11/10‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة التــي‬\n‫تخــول لــه البيــع واإلفــراغ واســتالم ثمــن مــا يخصــه مــن األرض والعمــارة‬\n‫اململوكــة ملورثــه ‪ .....‬ويحــق لــه توكيــل الغيــر ‪ ،‬ثــم قــرر أصالــة عــن‬\n‫ا ‪ :‬إننــي أنــا وموكلــي‬    ‫نفســه وبوكالتــه عــن املدعــى عليــه ‪ .....‬قائ ـ ً‬\n\n\n                                                                                      ‫‪380‬‬\n\f      ‫املذكــور قــد بعنــا األرض العائــدة ملورثينــا الواقعــة يف حــي ‪ .....‬يف املدينــة‬\n      ‫املنــورة‪ ،‬واململوكــة لوالــدي رحمــه اهلل بالصــك رقــم ‪1/750‬‬\n      ‫يف‪1400/06/22‬ه ـ علــى املتداخــل ‪ .....‬مببلــغ أربعمائــة وخمســن ألــف‬\n      ‫ريــال مبــا فيهــا الداللــة البالغــة أحد عشــر ألفا وخمســمئة ريــال‪ ،‬وتأجيل‬\n      ‫بيــع العمــارة املذكــورة يف جوابــي ســابقا إلــى أجــل غيــر مســمى ‪،‬‬\n      ‫والتنــازل عــن طلــب بيــع العمــارة املذكــورة ‪ ،‬وال مانــع لدينــا مــن إيــداع‬\n      ‫قيمــة هــذه األرض لبيــت مــال احملكمــة وتســليمه للورثــة بعــد ذلــك كل‬\n      ‫حســب اســتطاعته وفراغــه يحضــر ويســتلم نصيبــه ‪ .‬هكــذا قــرر ‪ .‬وألن‬\n      ‫وكالتــه تخــول لــه البيــع واإلفــراغ واســتالم الثمــن فقــد ثبــت لــدي إقراره‬\n      ‫بالبيــع أعــاه علــى املتداخــل ورفعــت اجللســة ومت تبليــغ املدعــى عليــه‬\n      ‫أصالــة ووكالــة مبوعــد اجللســة القادمــة يف يــوم الســبت املوافــق‬\n      ‫‪1433/05/22‬ه ـ الســاعة التاســعة والنصــف ‪ .‬ثــم يف يــوم الســبت‬\n      ‫املوافق‪1433/05/22‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‪،‬‬\n      ‫وفيهــا حضــر املدعــن مــن ورثــة ‪ .....‬الثالثة املذكوريــن أصالة ووكالة‪،‬‬\n      ‫ولــم يحضــر املدعــى عليهمــا ‪ ،‬ولــم يوقــع املدعــى عليــه علــى مــا أقــر بــه‬\n      ‫لدينــا يف اجللســة املاضيــة والزالــت بطاقــة األحــوال التابعــة لــه لــدى‬\n      ‫املوظــف حتــى هــذه اجللســة‪ ،‬فقــررت الســير يف هــذه القضيــة غيابيــا‬\n      ‫وبعــث بطاقــة األحــوال التابعــة للمدعــى عليــه عــن طريــق الشــرطة‬\n      ‫لتســليمها لــه وتبليغــه باملوعــد القــادم‪ ،‬ثــم جــرى عــرض اليمــن املتممــة‬\n      ‫لبينتــه املتداخــل عليــه؛ فاســتعد بهــا‪ ،‬ثــم حلــف‪ ،‬قائــا ‪ :‬واهلل العظيــم‬\n      ‫الــذي ال إلــه إال هــو وال رب ســواه‪ ،‬أن املدعــى عليهمــا ‪ .....‬و‪ .....‬قــد باعــا‬\n      ‫علـ ّـي األرض الواقعــة يف حــي ‪ ، .....‬واململوكــة ملورثيهمــا بالصــك رقــم‬\n      ‫‪ 1/750‬يف ‪1400/6/22‬ه ـ مببلــغ أربعمئــة وخمســن ألــف ريــال‪ ،‬مبــا‬\n\n\n‫‪381‬‬\n\f‫فيهــا الداللــة أحــد عشــر ألــف ريــال وخمســمئة ريــال للرفــع املســاحي‪،‬‬\n‫يخصمــان مــن إجمالــي مبلــغ البيــع ‪ ،‬وواهلل إنــي صــادق يف ذلــك ‪ .‬هكذا‬\n‫حلــف ‪ .‬ثــم جــرى اإلطــاع علــى صــك التملــك الــذي أحضــره املدعــن‬\n‫والصــادر مــن كتابــة عــدل املدينــة املنــورة‪ ،‬برقــم ‪ 1/750‬يف‬\n‫‪1400/6/22‬ه ـ فوجــد يتضمــن متلــك ‪ .....‬لقطعــة األرض الواقعــة يف‬\n‫املغيســلة يف املدينــة املنــورة‪ ،‬واملبينــة حدودهــا وأطوالهــا ومســاحتها‬\n‫باطنــه‪ ،‬ثــم جــرى االطــاع علــى صــك حصــر الورثــة الصــادر مــن‬\n‫احملكمة العامة باملدينة املنورة‪ ،‬برقم ‪ 11/19‬وتاريخ ‪1415/4/27‬هـ‪،‬‬\n‫املتضمــن وفــاة ‪ ، .....‬بتاريــخ ‪1414/06/03‬ه ـ وانحصــار ورثتــه يف‬\n‫زوجتــه ‪ .....‬ويف أوالده منهــا ‪ .....‬و ‪ ..... ..... ..... ..... .....‬و ابنتيــه ‪، ..... .....‬‬\n‫و يف زوجتــه األخــرى ‪ ، .....‬و يف أوالده منهــا وهــم ‪ ..... ..... ..... .....‬ال‬\n‫وارث لــه ســواهم‪ ،‬كمــا جــرى اإلطــاع علــى صــك حصــر الورثــه رقــم‬\n‫‪ 6/31‬يف ‪1426/4/16‬ه ـ الصــادر مــن احملكمــة العامــة باملدينــة‬\n‫املنــورة‪ ،‬واملتضمــن وفــاة ‪ ، .....‬وانحصــار إرثهــا يف أوالدهــا ‪ ، .....‬و ‪.....‬‬\n‫و‪ .....‬و‪ .....‬و‪ .....‬أوالد ‪ ، .....‬ال وراث لهــا ســواهم ‪ ،‬كمــا جــرى اإلطــاع‬\n‫علــى صــك حصــر الورثــة رقــم ‪ 10/100/337‬يف ‪1430/11/02‬ه ـ‬\n‫الصــادر مــن احملكمــة العامــة باملدينــة املنــورة‪ ،‬واملتضمــن وفــاة ‪، .....‬‬\n‫وانحصار إرثها يف أوالدها ‪ ..... ..... ..... ..... ..... ..... .....‬و‪ .....‬أوالد‪، .....‬‬\n‫ال وارث لهــا ســواهم‪ ،‬وألن جميــع الورثــة أعــاه قــد حضــروا‪ ،‬وأقــروا‬\n‫بالبيــع أصالــة أو وكالــة‪ ،‬ســوى املدعــى عليهمــا ‪ ،‬والوارثــن ‪ .....‬و ‪.....‬‬\n‫‪ ،‬وبســؤال املدعــن عــن األخيريــن‪ ،‬أجابــوا قائلــن ‪ :‬إنهــم بائعــن معنــا‪،‬‬\n‫وال مانــع لديهــم مــن اإلفــراغ‪ ،‬ونتعهــد بإحضارهمــا يف اجللســة القادمــة‪،‬‬\n‫ألخــذ إقرارهمــا بالبيــع ‪ .‬هكــذا أجابــوا ‪ .‬ثــم جــرى رفــع اجللســة ملخاطبــة‬\n\n\n                                                                                                 ‫‪382‬‬\n\f      ‫مصــدر الصــك كتابــة العــدل املدينــة املنــورة‪ ،‬للتأكــد مــن ســريان‬\n      ‫مفعــول الصــك وهــل قابــل لإلفــراغ‪ ،‬ولــورود اجلــواب رفعــت اجللســة إلــى‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/7/8‬ه ـ الســاعة التاســعة صباحــا ‪ ،‬ثــم يف‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/07/08‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n      ‫‪ ،‬وفيهــا حضــر مــن املدعــن الثالثــة مــن ورثــة ‪ .....‬وحضــر املتداخــل‪،‬‬\n      ‫كمــا حضــر مــن بقيــة الورثــة وارث الزوجــة ‪ ،.....‬ســعودي اجلنســية ‪،‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وقــرر بطوعــه واختيــاره قائــا ‪ :‬إننــي‬\n      ‫بصفتــي وارثــا لوالدتــي ‪ .....‬وهــي زوجــة املالــك ‪ ، .....‬أقــرر أمامكــم‬\n      ‫طائعــا مختــارا بأنــي قــد بعــت نصيبــي مــن األرض محــل الدعــوى العائــدة‬\n      ‫لــزوج والدتــي املتوفــى ‪ ......‬علــى املتداخــل احلاضــر ‪ .....‬مببلــغ إجمالــي‬\n      ‫لــأرض قــدره أربعمئــة وخمســن ألــف مبــا فيهــا الداللــة ‪ ،‬وال مانــع لــدي‬\n      ‫مــن إفــراغ العقــار باســم املتداخــل يف أي وقــت ‪ ،‬وتســليم الورثــة حقوقهــم‬\n      ‫منهــا ‪ .‬هكــذا أقــر ‪ .‬كمــا حضــر اجللســة ‪ ، .....‬ســعودي اجلنســية ‪،‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وقــرر بطوعــه واختيــاره قائال ‪ :‬بصفتي‬\n      ‫وارثــا لوالدتــي ‪ .....‬وهــي بنــت املالــك املتوفــى والــد املدعــن ‪ ، ....‬أقــرر‬\n      ‫أمامكــم طائعــا مختــارا بأنــي قــد بعــت نصيبــي مــن األرض محــل‬\n      ‫الدعــوى العائــدة لــزوج والدتــي املتوفــى ‪ ......‬علــى املتداخــل احلاضــر ‪.....‬‬\n      ‫مببلــغ إجمالــي لــأرض قــدره أربعمئــة وخمســن ألــف مبــا فيهــا الداللــة‪،‬‬\n      ‫وال مانــع لــدي مــن إفــراغ العقــار باســمه ‪ ،‬وتســليم الورثــة حقوقهــم منهــا‬\n      ‫‪ .‬هكــذا أقــر ‪ .‬وبإقــرار األخيريــن يكــون جميــع الورثــة األحيــاء وورثــة‬\n      ‫املتوفــن منهــم قــد حضــروا‪ ،‬وأقــروا بالبيــع إمــا أصالــة أو وكالــة ‪ ،‬وأنه‬\n      ‫ال مانــع لديهــم مــن إفــراغ األرض محــل الدعــوى للمتداخــل احلاضــر ‪،‬‬\n      ‫وكان قــد مت إرســال الصــك إلــى كتابــة العــدل االولــى باملدينــة‬\n\n\n‫‪383‬‬\n\f‫للكشــف عــن ســجل الصــك ‪ ،‬واالستفســار عــن ســريان مفعولــه ‪ ،‬ولــم‬\n‫يردنــا اجلــواب منهــم حتــى موعــد هــذه اجللســة ‪ ،‬لــذا جــرى رفــع اجللســة‬\n‫إلــى يــوم الســبت املوافــق ‪1433/09/02‬ه ـ الســاعة احلاديــة عشــر ‪ .‬ثــم يف‬\n‫يــوم الســبت املوافق‪1433/09/02‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــر صباحـ ًا ‪ ،‬وفيهــا حضــر املدعــن أصالــة ووكالــة ‪ ،.....، .....‬و‪.....‬‬\n‫‪ ،‬كمــا حضــر املتداخــل ‪ ، .....‬ولــم يحضــر املدعــى عليهمــا ‪ ،‬ولــم أجــد‬\n‫يف طيــات املعاملــة مــا يفيــد تبلغهمــا ‪ ،‬وفيهــا جــرى اإلطــاع علــى اإلفــادة‬\n‫علــى الصــك محــل الدعــوى والــواردة مــن كتابــة العــدل األولــى باملدينــة‬\n‫املنــورة برقــم ‪ 1324745‬وتاريــخ ‪1433/7/19‬ه ـ واملتضمنــة ‪ :‬أن الصــك‬\n‫مطابقــة لســجله وســاري مفعولــه ‪ .‬أ ‪ .‬ه ـ ‪ .‬كمــا أحضــر املتداخل الشــيك‬\n‫رقم ‪ 861488‬يف ‪1433/9/12‬هـ والصادر من مصرف ‪ .....‬واملتضمن‬\n‫ـاء علــى مــا‬\n             ‫مبلــغ أربعمائــة وثمانيــة وثالثــون ألــف وخمســمائة ريــال ‪ .‬بنـ ً‬\n‫تقــدم مــن الدعــوى وإجابــات املدعــى عليهمــا ‪ ،‬وبنــاء علــى إقــرار املدعــي‬\n‫يف اجللســة اخلامســة ‪ ،‬وألن املدعــى عليــه حضــر اجللســة األولــى واجللســة‬\n‫اخلامســة ولكنــه عنــد حتريــر محضــر ضبــط اجللســة يخــرج مــن غيــر‬\n‫توقيــع ‪ ،‬لــذا فقــد توجــه لــي إحضــار البينــة علــى البيــع ‪ ،‬وألن جميــع‬\n‫الورثــة حضــروا وأقــروا لــدي بالبيــع علــى املتداخــل احلاضــر مبــا فيهــم‬\n‫املدعــى عليــه أصالــة ووكالــة ‪ ،‬وبنــاء علــى مــا شــهد بــه الشــاهد ‪ .....‬يف‬\n‫اجللســة الرابعــة واملعــدل طبــق األصــول الشــرعية‪ ،‬وبنــاء علــى اليمــن‬\n‫املتممــة لهــذه البينــة ‪ ،‬وملــا يف مســند اإلمــام أحمــد مــن حديــث أبــي‬\n‫هريــرة رضــي اهلل عنــه أن النبــي صلــى عليــه وســلم قضــى بالشــاهد‬\n‫واليمــن ‪ ،‬فقــد ثبــت لــدي بيــع جميــع ورثــة ‪ .....‬وورثــة ورثتــه املتوفــن مبــا‬\n‫فيهــم املدعــى عليهمــا ‪ ،‬لــأرض العائــدة ملورثيهــم واململوكــة لهــم‬\n\n\n                                                                                         ‫‪384‬‬\n\f      ‫بالصــك رقــم ‪ 1/ 750‬يف ‪1400/06/22‬ه ـ علــى ‪ .....‬بيعـ ًا صحيحـ ًا حــال‬\n      ‫ســامتهم وصحــة تصرفاتهــم بثمــن قــدره أربعمائــة وثمانيــة وثالثــون‬\n      ‫ألــف وخمســمائة ريــال ‪ ،‬وحكمــت بصحتــه ولزومــه علــى الورثــة‪،‬‬\n      ‫وحكمــت علــى املدعــى عليهمــا الغائبــن بذلــك ‪ ،‬وقــررت إفــراغ الصــك‬\n      ‫محــل الدعــوى باســم املتداخــل بعــد اكتســاب احلكــم القطعيــة ‪،‬‬\n      ‫وتقســيم املبلــغ علــى الورثــة كل حســب نصيبــه الشــرعي ‪ ،‬وإيــداع‬\n      ‫نصيــب مــن يرفــض االســتالم لبيــت مــال احملكمــة ‪ ،‬كمــا قــررت بعــث‬\n      ‫نســخة من هذا احلكم للمدعى عليهما الغائبني ‪ .....‬و‪ ، .....‬وإفهامهما‬\n      ‫بــأن لهمــا حــق االعتــراض علــى احلكــم ملــدة شــهر كامــل مــن تاريــخ‬\n      ‫اســتالمها لصــورة الصــك ‪ ،‬وأنهمــا إن لــم يقدمــا الئحــة اعتراضيــة‬\n      ‫خالل تلك املدة ‪ ،‬فإنه يسقط حقهما يف طلب االستئناف ‪ ،‬ويكتسب‬\n      ‫احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آله وصحبه وسلم ‪ .‬حرر يف ‪1433/09/02‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القائــم بعمــل الشــيخ ‪ : .....‬فقــد‬\n      ‫متــت الكتابــة لقســم احملضريــن باخلطــاب رقــم ‪ 331746158‬يف‬\n      ‫‪1433/9/24‬هـ واخلطاب رقم ‪ 331746207‬يف ‪1433/9/24‬هـ لتسليم‬\n      ‫احملكــوم عليهمــا‪ .....‬و‪ .....‬صــورة مــن صــك احلكــم لتقــدمي مــا لديهمــا‬\n      ‫خــال املــدة النظاميــة فأعيــد إلينــا اجلــواب من قســم احملضريــن متضمن ًا‬\n      ‫بأنــه مت االنتقــال ملوقــع املدعــى عليهمــا ولــم يجــدا أحــد ًا ومت الوقــوف‬\n      ‫مبرافقــة املدعــي والتــردد عــدة مــرات بأوقــات مختلفــة ولــم يجــدوا أحــد ًا‬\n      ‫ومت الوقــوف مــع عمــدة احلــي ونائبــه كمــا متــت الكتابــة لهمــا مــرة‬\n      ‫أخــرى باخلطــاب رقــم ‪ 331951176‬يف ‪1433/11/3‬ه ـ واخلطــاب رقــم‬\n      ‫‪ 331950593‬يف ‪1433/11/3‬ه ـ فــورد اجلــواب مــن قســم احملضريــن‬\n\n\n‫‪385‬‬\n\f‫متضمنـ ًا بأنــه مت االنتقــال ملوقــع املدعــى عليهمــا والتــردد عــدة مــرات وال‬\n‫يجيــب أحــد داخــل املنــزل وقــام شــخص باالتصــال بنــا وذكــر أنه وكيل‬\n‫املدعــى عليهمــا واســتعد باحلضــور الســتالم اخلطــاب ولكنــه لــم يحضــر‬\n‫ومت االتصــال عليــه ولــم يجــب كمــا وجــد مصادقــة عمــدة احلــي متضمنـ ًا‬\n‫‪ .‬أصــادق علــى أقــوال احملضــر حيــث مت الوقــوف علــى منــزل املذكوريــن‬\n‫حســب العنــوان املشــار إليــه ولــم جنــد أحــد‪ .‬كمــا متــت الكتابــة لســعادة‬\n‫مديــر شــرطة قبــاء باملدينــة املنــورة باخلطــاب رقــم ‪ 3439676‬و اخلطــاب‬\n‫رقــم ‪ 3439735‬لتســليم املدعــى عليهمــا صــورة مــن صــك احلكــم لتقــدمي‬\n‫مــا لديهمــا خــال املــدة النظاميــة فــورد اجلــواب مــن مديــر مركــز شــرطة‬\n‫قبــاء باملدينــة برقــم ‪ 464/13/6‬يف ‪1434/1/24‬هـ ورقم ‪463/13/6‬يف‬\n‫‪1434/1/24‬ه ـ متضمنـ ًا بأنــه مت الوقــوف مــع منــدوب احملكمــة ســابق ًا‬\n‫أكثــر مــن مــرة ومت طــرق البــاب ولــم يتجــاوب معنــا وأفــاد بعض ســكان‬\n‫احلــي بــأن ‪ .....‬انتقــل إلــى حــي‪ ......‬لــذا فقــد أمــرت ببعــث املعاملــة إلــى‬\n‫محكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪..‬‬\n‫فلــدي أنــا ‪ .....‬املــازم القضائــي يف احملكمــة العامــة باملدينــة املنــورة‬\n‫يــوم األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n‫عشــرة وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ال مــن ‪ ..... ..... ..... ..... .....‬أوالد‬\n                                         ‫‪ .....‬عــن نفســه ‪ ،‬وبوكالتــه عــن ك ً‬\n‫‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n‫املنــورة برقــم ‪ 38472‬وتاريــخ ‪1431/06/08‬ه ـ وجــرى تســليمه الشــيك‬\n‫املســحوب علــى مصــرف ‪ .....‬برقــم ‪ 995383‬وتاريــخ ‪2013/02/18‬م‬\n\n\n                                                                                         ‫‪386‬‬\n\f      ‫مببلــغ وقــدره مائتــان وخمســة وأربعــون ألفـ ًا وثالثمائــة وأربعــة وعشــرون‬\n      ‫ريــا ًال وثمانيــة وســتون هللــة ‪ . ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/10‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪..‬‬\n      ‫فلــدي أنــا ‪ .....‬املــازم القضائــي يف احملكمــة العامــة باملدينــة املنــورة‬\n      ‫ففــي يــوم األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الواحــدة بعــد الظهــر ‪ ،‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ، .....‬وجــرى تســليمه الشــيك املســحوب علــى‬\n      ‫مصــرف ‪ .....‬برقــم ‪ 995384‬وتاريــخ ‪2013/02/18‬م مببلــغ وقــدره‬\n      ‫الفـ ًا وســتمائة وأربعــة ريــاالت وتســع وأربعــون هللــة ‪،‬ويف‬\n                                                                    ‫أربعــة وأربعــون ً‬\n      ‫يــوم األحــد املوافق‪1434/04/14‬ه ـ افتتحــت اجللســة الســاعة الواحــدة‬\n      ‫‪ ،‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫اصالــة عــن نفســه ‪،‬ووكالــة عــن كل مــن ‪ .....‬و‪ .....‬بالوكالــة رقــم‬\n      ‫‪ 57739‬يف ‪1432/9/24‬ه ـ صــادرة مــن كتابــة عــدل املدينــة املنــورة‬\n      ‫وجــرى تســليمه الشــيك املســحوب علــى مصــرف ‪ .....‬برقــم ‪995388‬‬\n      ‫وتاريــخ ‪2013/02/18‬م مببلــغ وقــدره ســبعة آالف وثمامنائــة وثالثــة‬\n      ‫وســبعون ريــال وهــو نصيــب ‪ .....‬ونصيــب ‪ .....‬ونصيــب‪......‬ويف يــوم األثنــن‬\n      ‫املوافق‪1434/04/15‬ه ـ افتتحــت اجللســة الســاعة التاســعة ‪ ،‬وفيهــا‬\n      ‫حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬اصالــة‬\n      ‫عــن نفســه وجــرى تســليمه الشــيك املســحوب علــى مصــرف ‪ .....‬برقــم‬\n      ‫‪ 995390‬وتاريــخ ‪2013/02/18‬م مببلــغ وقــدره ثالثــة الــف وتســعة مائــة‬\n      ‫وســتة وثالثــون ريــال ‪ .‬ويف هــذا اليــوم الثالثــاء ‪1434/04/23‬هـ افتتحت‬\n      ‫اجللســة وفيهــا حضــر كل مــن‪ ..... :‬صاحــب الســجل املدنــي رقــم ‪.....‬‬\n\n\n‫‪387‬‬\n\f‫و‪ .....‬صاحــب الســجل املدنــي رقــم ‪ .....‬وجــرى تســليمهما الشــيكني‬\n‫رقــم ‪ 995387‬يف ‪2013/02/18‬م املســحوب علــى مصــرف‪ .....‬وميثــل‬\n‫مبلــغ وقــدره ســتة آالف وثمامنائــة وواحــد وخمســون ريــا ًال فقــط الغيــر‬\n‫ألمــر ‪ .....‬والشــيك رقــم ‪ 995393‬يف ‪2013/02/18‬م املســحوب علــى‬\n‫مصــرف ‪ .....‬وميثــل مبلــغ وقــدره ســبعة وأربعــون ألــف ومائتــان وتســعة‬\n‫وثالثــون ريــا ًال فقــط ال غيــر ألمــر‪، .....‬وحتــى ال يخفــى جــرى إثباتــه ويف‬\n‫هــذا اليــوم االربعاء‪1434/05/01‬ه ـ افتتحــت اجللســة وفيهــا حضــر كل‬\n‫مــن ‪ ..... :‬رقــم ســجل ‪ .....‬وجــرى تســليمها الشــيك رقــم ‪995392‬يف‪18‬‬\n‫‪2013/2/‬م ‪ .‬املســحوب علــى مصــرف ‪ .....‬وميثــل مبلــغ وقــدره ثالثــة‬\n‫وعشــرون ألفـ ًا وســتمائة وعشــرون ريــال وخمســة وثمانــون هللــه فقــط ال‬\n‫غيــر ‪ .‬وكمــا حضــر‪ .....‬ســجل مدنــي رقــم ‪ .....‬وجــرى تســليمه الشــيك‬\n‫رقــم ‪ 995391‬يف ‪2013/02/18‬م ‪ .‬املســحوب علــى مصــرف ‪ .....‬وميثــل‬\n‫مبلــغ وقــدره ثالثــة آالف وتســعمائة وســتة وثالثــون ريــاال وأربعــة وســتون‬\n‫هللــه فقــط ال غيــر ‪ .‬وحتــى ال يخفــى جــرى إثباتــه ثــم لــدي أنــا ‪ .....‬يف يــوم‬\n‫االربعاء‪1434/06/07‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة ظهــر ًا‬\n‫‪ ،‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n‫وجرى تســليمه الشــيك رقم ‪99539‬يف ‪2013/02/18‬م ‪ .‬املســحوب على‬\n‫مصــرف ‪ .....‬وميثــل مبلــغ وقــدره ثالثــة آالف وتســعة مائــة وســتة وثالثــن‬\n‫ريــا ًال فقــط ‪ ،‬وحتــى ال يخفــى جــرى حتريــره يف ‪1434/06/07‬ه ـ وباهلل‬\n       ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n\n\n                                                                                          ‫‪388‬‬\n\f      ‫الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي باحملكمــة العامــة باملدينــة‬\n      ‫املنــورة‪ ،‬واملســجل بع ــدد ‪ 33411128‬وتاريــخ ‪1433/9/13‬هـ‪ ،‬املتضمن‬\n      ‫دعــوى ورثــة ‪ .....‬ضــد ‪ ،.....‬احملكــوم في ــه مبــا دون باطنــه‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ ،‬واهلل املوفــق‬\n                      ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪389‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":374,"source_page_end":389,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dcf83cc7db62ea8b334857a41532febeb831c5346d2c56ecf5565e354a463aee","normalized_text_hash":"9ccda006723890ad41bf969f672739c71ee40978498df6b8ec78da438eca4405","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p374-33411128"},{"id":"5661a8b0-4ed8-5c85-8f41-484ff17bfc1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -مطالبة املدعية ببيع عقار مورثها وإعطائها نصيبهما الشرعي -تخلف املدعى عليهم عن احلضور عدا واحد -مصادقة املدعى عليه على الدعوى عدا صفة العقار (أرض فضاء) -صعوبة تقسيم العقار محل الدعوى -بيع العقار باملزاد العلني وقسمة ثمنه بن الورثة بحسب أنصابهم الشرعية -حكم غيابي والغائب على حجته متى حضر .","document_number":"33439471","case_number":"56230207","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/25","year":"1434","subject":"قسمة تركة -مطالبة املدعية ببيع عقار مورثها وإعطائها نصيبهما الشرعي -تخلف املدعى عليهم عن احلضور عدا واحد -مصادقة املدعى عليه على الدعوى عدا صفة العقار (أرض فضاء) -صعوبة تقسيم العقار محل الدعوى -بيع العقار باملزاد العلني وقسمة ثمنه بن الورثة بحسب أنصابهم الشرعية -حكم غيابي والغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33439471 :‬تاريخه‪1433/10/25 :‬هـ‬\n                   ‫رقم الدعوى‪56230207 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34301102‬تاريخه‪1434/8/21 :‬هـ‬\n\n\n ‫قســمة تركــة‪ -‬مطالبــة املدعيــة ببيع عقار مورثهــا وإعطائها نصيبهما‬\n ‫الشــرعي‪ -‬تخلــف املدعــى عليهــم عــن احلضــور عــدا واحــد‪ -‬مصادقــة‬\n ‫املدعــى عليــه علــى الدعــوى عــدا صفــة العقــار (أرض فضــاء)‪ -‬صعوبــة‬\n ‫تقســيم العقــار محــل الدعــوى ‪ -‬بيــع العقــار باملــزاد العلنــي وقســمة‬\n ‫ثمنــه بــن الورثــة بحســب أنصابهــم الشــرعية‪ -‬حكــم غيابــي والغائــب‬\n                                                  ‫علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n ‫‪ .1‬جــاء يف املقنــع ‪( 46/29‬وقســمة األمــاك جائــزة وهــي نوعــان قســمة‬\n ‫تراضــي وهــي مــا فيهــا ضــرر أورد عــوض من أحدهما كالــدور الصغار)‪.‬‬\n ‫‪ .2‬جاء يف الكايف ‪( 336/4‬وإذا كان يف القســمة رد عوض فهي بيع ألن‬\n ‫صاحــب الــرد بــذل املــال عوض ـ ًا عمــا حصــل لــه مــن حــق شــريكه وهــذا‬\n                                                                   ‫هــو البيــع)‪.‬‬\n ‫‪ .3‬جــاء يف اإلنصــاف ‪( 48/29‬مــن دعــى شــريكه إلــى البيــع يف قســمة‬\n             ‫التراضــي أجبــر فــإن أبــى بيــع عليهمــا وقســم الثمــن ‪.)...‬‬\n ‫‪ .4‬جــاء يف قواعــد ابــن رجــب ص ‪( 348‬فأمــا مــاال يقبــل القســمة فإنــه‬\n ‫يجبــر أحدهمــا علــى بيعــه إذا طلــب اآلخــر بيعــه نــص أحمــد علــى‬\n                                                                         ‫ذلــك)‪.‬‬\n         ‫‪ .5‬املادة ‪ 6/34‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n         ‫‪ .6‬املادة ‪ 4/56‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n                                                                                    ‫‪390‬‬\n\f      ‫ادعــت املدعيــة ضــد املدعــى عليهــم بأنــه تــويف والدهــا وانحصــر ارثــه‬\n      ‫يف زوجتيــه ويف أوالده ‪ ..........‬ولقــد خلــف مصنعـ ًا يقــع مبكــة املكرمــة‬\n      ‫واململــوك ملورثهــم مبوجــب الصــك الصــادر مــن هــذه احملكمــة وتطلــب‬\n      ‫احلكــم علــى الورثــة ببيــع ذلــك العقــار وإعطائهــا نصيبهــا منــه هكــذا‬\n      ‫ادعــت‪ ،‬لــم يحضــر مــن املدعــى عليهــم إال ‪ .....‬والســير يف القضيــة بنــاء‬\n      ‫علــى الالئحــة السادســة مــن املــادة الرابعــة والثالثــن مــن نظــام املرافعات‬\n      ‫الشــرعية‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وعــدم ممانعته‬\n      ‫مــن بيــع العقــار وتقســيم ثمنــه علــى الورثــة وأضــاف بــأن العقــار لــم يعــد‬\n      ‫مصنع ـ ًا وأصبــح أرض ـ ًا فضــاء‪ ،‬جــرى االستفســار عــن ســريان مفعــول‬\n      ‫صــك ملكيــة العقــار فــورد اجلــواب مــن مصــدره بــأن ســاري املفعــول‬\n      ‫ومطابــق لســجله‪ ،‬الكتابــة لهيئــة النظــر للوقــوف علــى العقــار محــل‬\n      ‫الدعــوى واإلفــادة هــل يف قســمته ضــرر أو رد عــوض فــورد جوابهــم‬\n      ‫املتضمــن بأنــه ال ميكــن قســمة العقــار علــى الورثــة ألنــه حــوش علــي‬\n      ‫شــارعني وهــو ســكني‪ ،‬ملــا تقــدم صــدر احلكــم ببيــع العقــار املوصــوف‬\n      ‫يف الدعــوى بواســطة املــزاد العلنــي ومــن ثــم قســمة ثمنــه بــن الورثــة‬\n      ‫بحســب أنصبائهــم الشــرعية‪ ،‬واحلكــم غيابــي يف حــق باقــي املدعــي‬\n      ‫عليهــم وســوف يتــم تبليغهــم باحلكــم والغائــب علــى حجتــه متــى حضــر‬\n      ‫اســتناد ًا علــى الالئحــة الرابعــة مــن املــادة السادســة واخلمســن مــن نظــام‬\n      ‫املرافعــات الشــرعية‪ ،‬بعــرض احلكــم علــى املتداعيــن قــررا القناعــة‬\n      ‫بــه‪ ،‬صــدق احلكــم بعــد مداولــة مــن الدائــرة احلقوقيــة األولــى مبحكمــة‬\n                                             ‫االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n‫‪391‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 56230207‬وتاريــخ ‪1432/03/04‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3222104‬وتاريــخ ‪1432/02/29‬ه ـ املتعلقــة‬\n‫بدعوى ‪.....‬ضد ورثة ‪.....‬ففي هذا اليوم الثالثاء املوافق‪1432/05/22‬هـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 10 : 50‬وفيهــا حضــرت املدعيــة ‪..... /‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬وحضــر حلضورهــا مــن املدعــى‬\n‫عليهــم املدعــو ‪ ...../‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪.....‬واملعــرف‬\n‫باملدعيــة وبنــاء علــى الالئحــة السادســة مــن املــادة الرابعــة والثالثــن‬\n‫مــن نظــام املرافعــات الشــرعية فقــد أذنــت للمدعيــة بتحريــر دعواهــا‬\n‫فادعــت قائلــة يف حتريــر دعواهــا لقــد تــويف والــدي ‪ ...‬وانحصــر ارثــه‬\n‫مبوجــب صــك حصــر اإلرث الصــادر مــن هــذه احملكمــة برقــم ‪1101‬‬\n‫يف ‪1397/8/14‬ه ـ املتضمــن وفاتــه يف ‪1397/4/28‬ه ـ وانحصــار ارثــه‬\n‫الشــرعي يف زوجتيــه الباقيتــن علــى عقــد نكاحــه إلــى حــن وفاتــه ‪......‬‬\n‫و‪.....‬ويف أوالده ‪..... ..... ..... .....‬ولقــد خلــف لنــا والدنــا املذكــور مصنعـ ًا‬\n‫يقــع مبكــة املكرمــة باملســفلة احملــدود شــرقا ملــك ‪ .....‬وغربــا الســكة‬\n‫النافــذة وشــماال الســكة النافــذة وبهــا بــاب وجنوبــا ملــك ‪.....‬واململــوك‬\n‫لوالدنــا مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 13/147‬يف‬\n‫‪1405/5/14‬ه ـ لــذا فإنــي أطلــب احلكــم علــى الورثــة ببيــع ذلــك العقــار‬\n‫وإعطائــي نصيبــي منــه حســب الفريضــة الشــرعية هــذه دعــواي ثــم‬\n‫ســألتها عــن باقــي الورثــة فأجابــت إن باقــي الورثــة لــم يأتــوا ولــم يحضــر‬\n\n                                                                                         ‫‪392‬‬\n\f      ‫منهــم ســوى هــذا احلاضــر ‪.....‬وأطلــب الســير يف دعــواي هــذه ألنــي‬\n      ‫متضــررة مــن حرمانــي حلقــي هكــذا قالــت ثــم عرضــت دعــوى املدعيــة‬\n      ‫علــى املدعــى عليــه احلاضــر فأجــاب قائــا إن مــا ورد يف دعــوى املدعيــة‬\n      ‫مــن وفــاة والدنــا بالتاريــخ املذكــور يف دعواهــا وانحصــار ورثتــه فيمــن‬\n      ‫ذكرتهــم بأســمائهم املدونــة يف صــك حصــر اإلرث املذكــور برقــم‬\n      ‫وتاريخــه يف الدعــوى فصحيــح ومــا ذكرتــه مــن أن والدنــا املذكــور‬\n      ‫خلــف العقــار املوصــوف يف دعواهــا بحــدوده واململــوك بالصــك الــذي‬\n      ‫ذكرتــه برقمــه وتاريخــه ومصــدره فصحيــح كذلــك وال أنكــر منــه‬\n      ‫شــيئا مطلقــا غيــر أن العقــار اآلن لــم يعــد مصنعــا كمــا ذكرتــه املدعيــة‬\n      ‫بــل أصبــح أرضــا فضــاء يف الوقــت احلاضــر وأمــا طلبهــا بيــع احملــدود‬\n      ‫املذكــور وقســمة ثمنــه وإعطائهــا نصيبهــا منــه فليــس لــدي أي مانــع‬\n      ‫يف ذلــك هكــذا أجــاب ثــم جــرى منــي اإلطــاع علــى صكــي امللكيــة‬\n      ‫وحصــر اإلرث فوجدتهمــا مطابقــن ملــا عطــف عليهمــا ثــم جــرى‬\n      ‫االستفســار عــن ســجالتهما فوردنــا جــواب مديــر الســجل باحملكمــة‬\n      ‫رقــم ‪ 32/596739‬يف ‪1432/5/23‬ه ـ املتضمــن أنــه ال يوجــد علــى‬\n      ‫ســجل الصــك رقــم ‪ 13/147‬يف ‪1405/5/14‬ه ـ أي شــرح يذكــر حتــى‬\n      ‫تاريخــه ‪1432/5/27‬ه ـ وكذلــك وردنــا جــواب مديــر الســجل رقــم‬\n      ‫‪ 32/596710‬يف ‪1432/5/23‬ه ـ املتضمــن أن صــورة الصــك رقم ‪4/27‬‬\n      ‫يف ‪1397/8/14‬ه ـ غيــر مطابقــة لســجلها نأمــل تزويدنــا بأصــل الصــك‬\n      ‫‪ .‬إ ‪ .‬ه ـ ‪ .‬ثــم قــررت الكتابــة لهيئــة النظــر للوقــوف علــى العقــار محــل‬\n      ‫الدعــوى واإلفــادة هــل يف قســمته ضــرر أو رد عــوض إضافــة إلــى طلــب‬\n      ‫صــورة مصدقــة مــن ســجل حصــر اإلرث وإلــى حــن ورود املعاملــة تأجلــت‬\n      ‫ويف يــوم الثالثــاء ‪ 1433/10/17‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n\n\n‫‪393‬‬\n\f‫املدعيــة وحضــر حلضورهــا املدعــى عليــه ‪.....‬وكانــت قــد وردتنــا إفــادة‬\n‫هيئــة النظــر ذات الــر قــم ‪ 3222104‬يف ‪1433/4/21‬ه ـ وتتضمــن فقــد‬\n‫مت الوقــوف علــى العقــار املذكــور وهــو عبــارة عــن حــوش علــى شــارعني‬\n‫وهــي ركنيــة ومت تطبيــق الصــك علــى العقــار ووجدنــا أنــه منطبــق علــى‬\n‫العقــار املذكــور وبالتالــي ال ميكــن قســمة العقــار علــى الورثــة ملــا ذكــر‬\n‫ســابق ًا ألنــه حــوش علــي شــارعني وهــو ســكني كمــا هــو موضــح أعــاه‬\n‫هــذا مــا نــراه واهلل الهــادي إلــى ســواء الســبيل والســبيل ‪.‬فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وملــا ورد يف قــرار هيئــة النظــر املرصــودة‬\n‫أعــاه وألن القســمة التــي فيهــا ضــرر هــي املعروفــة لــدى الفقهــاء بقســمة‬\n‫التراضــي قــال صاحــب املقنــع ( وقســمة األمــاك جائــزة وهــي نوعــان‬\n‫قســمة تراضــي وهــي مــا فيهــا ضــرر أورد عــوض مــن أحدهمــا كالــدور‬\n‫الصغــار ) أنظــره مــع الشــرح الكبيــر واإلنصــاف ‪ 46/29‬وقــال يف‬\n‫الــكايف ( وإذا كان يف القســمة رد عــوض فهــي بيــع ألن صاحــب‬\n‫الــرد بــذل املــال عوض ـ ًا عمــا حصــل لــه مــن حــق شــريكه وهــذا هــو‬\n‫البيــع )‪ 336/4‬وقــال صاحــب اإلنصــاف فائــدة ( مــن دعــى شــريكه‬\n‫إلــى البيــع يف قســمة التراضــي أجبــر فــإن أبــى بيــع عليهمــا وقســم الثمــن‬\n‫نقلــه امليمونــي وحنبــل وذكــره القاضــي وأصحابــه وذكــره يف اإلرشــاد‬\n‫والفصــول واإليضــاح واملســتوعب والترغيــب وغيرهــا) انظــره مــع الشــرح‬\n‫الكبيــر علــى املقنــع ‪ 48/29‬وقــال ابــن رجــب يف قواعــده ( فأمــا مــاال‬\n‫يقبــل القســمة فإنــه يجبــر أحدهمــا علــى بيعــه إذا طلــب اآلخــر بيعــه نــص‬\n‫أحمــد علــى ذلــك ) ص‪ 348‬بنــاء علــى ذلــك فقــد حكمــت ببيــع العقــار‬\n‫املوصــوف يف الدعــوى بواســطة املــزاد العلنــي ومــن ثــم قســمة ثمنــه بــن‬\n‫الورثــة بحســب أنصبائهــم الشــرعية وبذلــك حكمــت واعتبرتــه غيابي ـ ًا‬\n\n\n                                                                                       ‫‪394‬‬\n\f      ‫يف حــق باقــي املدعــي عليهــم وســوف يتــم تزويدهــم بنســخة منــه لتقــدمي‬\n      ‫مالديهــم حيالــه مــن اعتــراض خــال ثالثــن يوم ـ ًا مــن تاريــخ االســتالم‬\n      ‫والغائــب علــى حجتــه متــى حضــر اســتناد ًا علــى الالئحــة الرابعــة مــن‬\n      ‫املــادة السادســة واخلمســن مــن نظــام املرافعــات الشــرعية وبعرضــه‬\n      ‫علــى املتداعيــن احلاضريــن قــررا القناعــة بــه وبــاهلل التوفيــق حــرر يف‬\n                                                                      ‫‪1433/10/17‬ه ـ‬\n      ‫احلمــد هلل وحــده فقــد عــادت أوراق املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫برقــم ‪ 34329377‬يف ‪1434/3/10‬ه ـ وبرفقهــا قــرار مالحظــة الدائــرة‬\n      ‫احلقوقيــة األولــى ذو الرقــم ‪ 3453127‬يف ‪1434/03/02‬ه ـ ونــص‬\n      ‫احلاجــة منــه بدارســة احلكــم وصــوة ضبطــه تقــرر إعادتهــا للتمشــي‬\n      ‫باملادتــن ‪ 4/176‬واملــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية أه ـ عليــه‬\n      ‫فإنــي أجيــب أصحــاب الفضيلــة قضــاة اإلســتئناف وفقهــم اهلل تعالــى‬\n      ‫لــكل خيــر بأنــه بالرجــوع إلــى الالئحــة الرابعــة للمــادة ‪ 176‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ونصهــا «إذا كان احلكــم غيابي ـ ًا فيكــون تبليــغ‬\n      ‫احملكــوم عليــه أو وكيلــه نســخة احلكــم يف محــل إقامتــه أو عملــه‬\n      ‫وفــق إجــراءات التبليــغ ويبــدأ ميعــاد االعتــراض علــى احلكــم مــن تاريــخ‬\n      ‫التبليــغ وإذا لــم يقــدم اعتراضــه خــال املــدة املقــررة نظام ـ ًا يكتســب‬\n      ‫احلكــم القطعيــة وفــق املــادة ‪ »178‬والتــي نصهــا مــدة االعتــراض بطلــب‬\n      ‫التمييــز ثالثــون يومـ ًا فــإذا لــم يقــدم اخلصــم اعتراضـ ًا خــال هــذه املــدة‬\n      ‫ســقط حقــه يف طلــب التمييــز وعلــى احملكمــة اتخــاذ محضــر بذبــك‬\n      ‫يف ضبــط القضيــة والتهميــش علــى الصــك وســجله بــأن احلكــم قــد‬\n      ‫اكتســب القطعيــة وغيــر خــاف علــى أصحــاب الفضيلــة وفقهــم اهلل‬\n      ‫تعالــى بــأن مــا أشــير إليــه يف املادتــن املذكورتــن أعــاه هــي أمــور‬\n\n\n‫‪395‬‬\n\f‫إجرائيــة املقصــد منهــا حفــظ حــق احملكــوم عليــه الغائــب وغيــر خــاف‬\n‫علــى أصحــاب الفضيلــة كذلــك مــا جــاء يف املــادة السادســة مــن نظــام‬\n‫ا إذا نــص النظــام‬  ‫املرافعــات الشــرعية ونصهــا يكــون اإلجــراء باط ـ ً‬\n‫علــى بطالنــه أو شــابه عيــب تخلــف بســببه الغــرض مــن اإلجــراءات وال‬\n‫يحكــم بالبطــان إذا ثبــت حتقــق الغايــة مــن اإلجــراء وعليــه فإنــه ال‬\n‫ا فإنــه ال يعتــد بــه وجتــب‬  ‫ريــب أن األصــل أن اإلجــراء إذا وقــع باط ـ ً‬\n‫إعادتــه علــى وجــه الصحــة مــا أمكــن لكــن ثــم حالتــان يجــب حلظهمــا‬\n‫عنــد النظــر يف البطــان اإلجرائــي احلالــة األولــى تصحيــح اإلجــراء مــا‬\n‫أمكــن فــإذا أمكــن حمــل اإلجــراء الــذي يتجــه بطالنــه علــى إجــراء‬\n‫صحيــح حمــل عليــه وأعمــل فاإلجــراء مهمــا أمكــن حملــه علــى وجــه‬\n‫صحيــح لــم يصــر إلــى بطالنــه فمــن املقــرر عنــد الفقهــاء أن إعمــال‬\n‫الــكالم أولــى مــن إهمالــه ومثلــه اإلجــراء املتخــذ احلالــة الثانيــة تصحيــح‬\n‫اإلجــراء الــذي حتقــق الغــرض منــه ولــو توجــه فيــه البطــان وهــذه احلالــة‬\n‫اســتثناء يــرد علــى البطــان اإلجرائــي فــإذا حتقــق الغــرض والغايــة مــن‬\n‫اإلجــراء حمــل علــى الصحــة حفاظ ـ ًا علــى حقــوق املترافعــن وصيانــة‬\n‫للقضــاء مــن الضيــاع أخيــر ًا بينــت الفقــرة األولــى مــن الالئحــة التنفيذيــة‬\n‫للمــادة املذكــورة ســلف ًا أن الــذي يقــرر حتقــق الغايــة مــن اإلجــراء هــو‬\n‫ناظــر القضيــة ونصهــا «الــذي يقــدر حتقــق الغايــة مــن اإلجــراء هــو ناظــر‬\n‫القضيــة» وعليــه فلــم يظهــر مــا يؤثــر علــى مــا أجريتــه وأمــرت بإعــادة‬\n‫أوراق املعاملــة حملكمــة اإلســئتناف لتدقيقهــا وبــاهلل التوفيــق‪ .‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/04/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n\n\n                                                                                       ‫‪396‬‬\n\f      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪34329377‬‬\n      ‫وتاريــخ ‪1434/8/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪.....‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل بعــدد‬\n      ‫‪ 33439471‬وتاريــخ ‪1433/10/25‬هـ ـ واملتضمــن دعوى‪..... /‬ضد‪ /‬ورثة‬\n      ‫‪.....‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد االجــراء االخيــر واهلل املوفــق‪ .‬وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪397‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":390,"source_page_end":397,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"45136f27a14d0cad42d4a29c45bb1fb8825620f01f2515308ca070c537689768","normalized_text_hash":"32d5ac0c677ecb2733d9295de27f4f4dc36d3dc49e0121276f8509df50c9a3aa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p390-33439471"},{"id":"1903fe54-d013-5f6f-9d81-7d946bdabc8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة املورث والتركة عقار -وصية -املطالبة ببيع العقار واعطاء كل وارث نصيبه الشرعي -مصادقة املدعى عليهم (الورثة) على الدعوى -وجود قاصر ضمن الورثة -بيع العقار باملزاد العلني وتسليم كل وارث نصيبه شرع ا -رفع احلكم إلى محكمة اإلستئناف لوجود قاصر ضمن الورثة .","document_number":"33461017","case_number":"33208497","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"قسمة تركة -وفاة املورث والتركة عقار -وصية -املطالبة ببيع العقار واعطاء كل وارث نصيبه الشرعي -مصادقة املدعى عليهم (الورثة) على الدعوى -وجود قاصر ضمن الورثة -بيع العقار باملزاد العلني وتسليم كل وارث نصيبه شرع ا -رفع احلكم إلى محكمة اإلستئناف لوجود قاصر ضمن الورثة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33461017 :‬تاريخه‪1433/11/21 :‬هـ‬\n                    ‫رقم الدعوى‪33208497 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3426645‬تاريخه‪1434/2/2 :‬هـ‬\n\n\n ‫قســمة تركــة‪ -‬وفــاة املــورث والتركــة عقــار‪ -‬وصيــة‪ -‬املطالبــة ببيــع‬\n ‫العقــار واعطــاء كل وارث نصيبــه الشــرعي‪ -‬مصادقــة املدعــى عليهــم‬\n ‫(الورثــة) علــى الدعــوى‪ -‬وجــود قاصــر ضمــن الورثــة‪ -‬بيــع العقــار باملزاد‬\n ‫العلنــي وتســليم كل وارث نصيبــه شــرع ًا‪ -‬رفــع احلكــم إلــى محكمــة‬\n                                   ‫اإلســتئناف لوجــود قاصــر ضمــن الورثــة ‪.‬‬\n\n\n\n\n ‫مطالــب أولــى النهــى (ومــن دعــا شــريكه فيهــا أي قســمة التراضــي إلــى‬\n ‫بيــع أجبــر علــى البيــع معــه فــإن أبــى أي شــريكه مــن بيــع معــه بيــع‬\n ‫أي باعــه حاكــم عليهمــا وقســم الثمــن بينهمــا علــى قــدر حصيتهمــا‬\n                                                                       ‫نصــا) ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي وكالــة ضــد املدعــى عليهــم بــأن مــورث موكلتــه قد تويف‬\n ‫وخلــف عقــار ًا مملــوك ًا لــه بصــك شــرعي ويطلــب بيــع العقــار وإعطــاء‬\n ‫كل وارث نصيبــه‪ ،‬أجــاب املدعــى عليهــم باملصادقــة علــى الدعــوى‬\n ‫ا وعــدم ممانعتهــم مــن بيــع العقــار‪ ،‬ليــس علــى مورثهــم‬\n                                                             ‫جملــة وتفصي ـ ً‬\n ‫ديــن وال وصيــة‪ ،‬أحــد الورثــة وهــي والدتــه توفيــت وأوصــت بالثلــث مــن‬\n ‫مالهــا‪ ،‬جــرى االستفســار عــن صــك امللكيــة فــورد اجلــواب بأنــه مطابــق‬\n\n                                                                                   ‫‪398‬‬\n\f      ‫لســجله‪ ،‬مبــا أن الورثــة جميعــا ًيرغبــون ببيــع العقــار ولكثــرة الورثــة‬\n      ‫وصعوبــة قســمته بينهــم‪ ،‬وألنــه يصــار إلــى البيــع مــع عــدم إمــكان‬\n      ‫القســمة‪ ،‬وملــا قــرره الفقهــاء مــن وجــوب إجابــة مــن طلــب القســمة إلزالــة‬\n      ‫ضــرر الشــركة حيــث جــاء يف مطالــب أولــى النهــى (ومــن دعــا شــريكه‬\n      ‫فيهــا أي قســمة التراضــي إلــى بيــع أجبــر علــى البيــع معــه فــإن أبــى أي‬\n      ‫شــريكه)‪ ،‬ونظــر ًا لثبــوت وصيــة والــدة مالــك العقــار بالثلــث ونصيبهــا‬\n      ‫منــه الســدس‪ ،‬ملــا تقــدم احلكــم ببيــع العقــار باملــزاد العلني وتســليم كل‬\n      ‫وارث نصيبــه منــه حســب الوجــه الشــرعي بعــد إحــراز الثلــث مــن نصيــب‬\n      ‫والدتــه وهــو ثلــث الســدس وحفظــه يف بيــت املــال لصالــح وصيتهــا‪ ،‬قنــع‬\n      ‫األطــراف باحلكــم‪ ،‬وألن مــن ضمــن الورثــة قاصــر وللوصيــة رفعــت‬\n                                 ‫املعاملــة حملكمــة االســتئناف‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪،‬‬\n      ‫فلــدي ‪ ...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n      ‫املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة برقــم ‪ 33208497‬يف ‪1433/3/23‬ه ـ املقيــدة يف احملكمــة‬\n      ‫برقم ‪ 33554752‬يف ‪1433/3/23‬هـ ففي يوم االثنني ‪1433/11/15‬هـ‬\n      ‫الســاعة احلاديــة عشــرة والنصــف صباح ـ ًا افتتحــت اجللســة للنظــر يف‬\n      ‫دعوى ‪ ...‬ضد ورثة ‪ ...‬وفيها حضر ‪ ...‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بغــرب مكــة برقــم ‪ 33117836‬يف ‪1433/6/15‬ه ـ واملخــول لــه يف‬\n\n‫‪399‬‬\n\f‫الوكالــة حــق إقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن‬\n‫وإحضــار الشــهود واجلــرح والتعديــل وقبــول األحــكام واالعتــراض‬\n‫عليهــا وطلــب االســتئناف ‪...‬الــخ وحضــر حلضــوره ول‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬باألصالــة عــن نفســه وبالوكالــة عــن‬\n‫كل مــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬و‪ ...‬و‪ ...‬و‪...‬‬\n‫و‪ ...‬و‪ ...‬و‪ ...‬بنــات ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة مبكــة املكرمــة برقــم ‪ 2149‬يف ‪1432/1/20‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق إقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن‬\n‫وإحضــار الشــهود واجلــرح والتعديــل وقبــول األحــكام واالعتــراض‬\n‫عليهــا وطلــب االســتئناف ‪...‬الــخ واملذكــورون أعــاه عــدا املدعي وكالة‬\n‫مــع ‪ ...‬هــم جميعـ ًا ورثــة ‪ ...‬وذلــك مبوجــب صــك حصــر ورثــة الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 9/5/5‬يف ‪1413/1/7‬ه ـ وبالوكالــة عــن كل‬\n‫مــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة غــرب مكــة برقــم ‪ .......‬يف‪1431/2/24‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق إقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن‬\n‫وإحضــار الشــهود واجلــرح والتعديــل وقبــول األحــكام واالعتــراض عليها‬\n‫وطلــب االســتئناف ‪...‬الــخ وبالوكالــة عــن ‪ .....‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة مبكــة املكرمــة برقــم ‪ 6782‬يف ‪1431/2/29‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق البيــع واإلفــراغ واالســتالم ‪...‬الــخ وبالوكالــة عــن أمــه ‪...‬‬\n\n\n                                                                                    ‫‪400‬‬\n\f      ‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬أصالــة عــن نفســها‬\n      ‫وبصفتهــا الوليــة علــى ابنهــا القاصــر ‪ ...‬املولــود يف عــام ‪1425‬ه ـ مبوجــب‬\n      ‫الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 9/100/281‬يف‬\n      ‫‪1430/6/13‬ه ـ مبوجــب الوكالــة الصــادر مــن كتابــة العــدل الثانيــة‬\n      ‫شــمال محافظــة جــدة برقــم ‪ 52803‬يف ‪1433/6/14‬ه ـ واملخــول لــه يف‬\n      ‫الوكالــة حــق حضــور اجللســات واملرافعــة واملدافعــة والبيــع واإلفــراغ‬\n      ‫وقبــول الثمــن ‪...‬الــخ وبالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 33360147‬يف ‪1433/11/8‬ه ـ واملخــول لــه‬\n      ‫يف الوكالــة حــق البيــع والشــراء واإلفــراغ وقبولــه واالســتالم والتســليم‬\n      ‫ومراجعــة جميــع اجلهــات ذات العالقــة ‪ ...‬الــخ واملذكــورون هــم جميعــا‬\n      ‫ورثــة ‪ ...‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 9/100/259‬يف ‪1430/6/6‬ه ـ وبالوكالــة عــن ‪ ...‬و‪ ...‬ابنــي ‪...‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة‬\n      ‫برقــم ‪ 6149‬يف ‪1431/2/25‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع‬\n      ‫والشــراء واإلفــراغ وقبولــه واالســتالم والتســليم واملدافعــة واملخاصمــة ‪...‬‬\n      ‫الــخ وبالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة‬\n      ‫برقــم ‪ 5830‬يف ‪1431/2/22‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع‬\n      ‫والشــراء وقبــض الثمــن واالســتالم ‪ ..‬الــخ كمــا حضــر ‪ ...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابة العدل الثانية بغرب مكة برقم ‪ 33345186‬يف ‪1433/10/29‬هـ‬\n\n\n‫‪401‬‬\n\f‫واملخــول لــه يف الوكالــة حــق إقامــة الدعــاوى واملرافعة واملدافعة وســماع‬\n‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب‬\n‫اليمــن وإحضــار الشــهود واجلرح والتعديــل وقبول األحكام واالعتراض‬\n‫عليهــا وطلــب االســتئناف ‪...‬الــخ كمــا حضــر كل مــن ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬باألصالــة عــن نفســه وبصفتــه‬\n‫الناظــر علــى وصيــة والدتــه ‪ ...‬وذلــك مبوجــب الصــك الصــادر مــن كتابة‬\n‫العــدل الثانيــة مبكــة املكرمــة برقــم ‪ 64 /37‬يف ‪1410/12/26‬ه ـ و‪...‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬واملذكــورون مــع ‪...‬‬\n‫و‪ ...‬ولــدي ‪ ...‬هــم جميعــا ورثــة ‪ ...‬وذلــك مبوجــب صــك حصــر الورثــة‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 19‬يف ‪1427/6/5‬ه ـ كمــا حضــر ‪...‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬باألصالــة عــن نفســه‬\n‫وبالوكالــة عــن كل مــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪86384‬‬\n‫يف ‪1433/10/25‬ه ـ واملخــول لــه يف الوكالــة حــق البيع والشــراء وقبض‬\n‫الثمــن واالســتالم ‪ ..‬الــخ وبالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بالطائــف برقــم ‪ 33304580‬يف ‪1433/10/14‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق البيــع والشــراء وقبــض الثمــن واالســتالم ‪ ..‬الــخ وبالوكالة‬\n‫عــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n‫برقــم ‪ 85741‬يف ‪1433/10/22‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع‬\n‫والشــراء وقبــض الثمــن واالســتالم ‪ ..‬الــخ وبالوكالــة عــن ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن‬\n\n\n                                                                                 ‫‪402‬‬\n\f      ‫كتابــة العــدل الثانيــة يف املدينــة املنــورة برقــم ‪ 33322740‬يف‬\n      ‫‪1433/10/21‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع والشــراء وقبــض‬\n      ‫الثمــن واالســتالم ‪ ..‬الــخ واملذكــورون هــم جميعــا ورثــة ‪ ...‬وذلــك مبوجب‬\n      ‫صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة بالطائــف برقــم‬\n      ‫‪ 33207332‬يف ‪1433/4/24‬ه ـ وبســؤال املدعــي وكالــة عــن دعــواه‬\n      ‫ادعــى قائــا ‪ :‬لقــد تــويف مــورث موكلتــي ‪ ...‬وانحصــر ورثتــه يف والدتــه‬\n      ‫‪ ...‬ويف زوجته ‪ ...‬ويف أوالده البالغني ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ووذلك‬\n      ‫مبوجــب صــك حصــر ورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 9/5/5‬يف‬\n      ‫‪1413/1/7‬ه ـ ثــم توفيــت والدتــه ‪ ...‬بتاريــخ ‪1425/12/5‬ه ـ وانحصــر‬\n      ‫ورثتهــا يف أوالدهــا البالغــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬وذلــك‬\n      ‫مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 19‬يف‬\n      ‫‪1427/6/5‬ه ـ ثــم تــويف ‪ ...‬بتاريــخ ‪1430/5/14‬ه ـ وانحصــر ورثتــه يف‬\n      ‫أوالده البالغــن مــن زوجتــه املطلقــة منــه حــال حياتــه ‪ ...‬وهــم أمــا‪ ...‬و‪...‬‬\n      ‫و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ويف زوجتــه الباقيــة يف عصمتــه وعقــد نكاحــه‬\n      ‫إلــى حــن وفاتــه أمــة ‪ ...‬ويف ابنــه منهــا القاصــر ‪ ...‬وذلــك مبوجــب صــك‬\n      ‫حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 9/100/259‬يف‬\n      ‫‪1430/6/6‬ه ـ ثــم توفيــت ‪ ...‬بتاريــخ ‪1432/8/22‬ه ـ وانحصــر ورثتهــا يف‬\n      ‫أوالدها البالغني ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬وذلك مبوجب‬\n      ‫صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة بالطائــف برقــم‬\n      ‫‪ 33207332‬يف ‪1433/4/24‬ه ـ ولقــد تــرك مورثهــا ‪ ...‬عقــارا يقع يف ‪.....‬‬\n      ‫يف مكــة املكرمــة يحــده شــرقا ســكة نافــذة للجبــل وبهــا البــاب وغربــا‬\n      ‫ملــك ‪ ...‬وشــماال ملــك ‪ ...‬وجنوبــا ســكة نافــذة وذرعــه كمــا يلــي ‪ :‬طــول‬\n      ‫الضلــع الشــمالي ثمانيــة أمتــار وخمســة وثمانــون ســنتيمترا والضلــع‬\n\n\n‫‪403‬‬\n\f‫الشــرقي عشــرة أمتــار وثمانــون ســنتيمترا والضلــع اجلنوبــي عشــرة أمتــار‬\n‫وخمســة وعشــرون ســنتيمترا والضلــع الغربــي ثمانيــة أمتــار وخمســة‬\n‫ســنتيمترات وعــرض الســكة الشــرقية النافــذة للجبــل مــن جهتــي‬\n‫الشــمال واجلنــوب متــران وعــرض الســكة اجلنوبيــة النافــذة مــن جهــة‬\n‫الشــرق ثالثــة أمتــار وثالثــون ســنتيمترا ومــن جهــة الغــرب ثالثــة أمتــار‬\n‫واملســاحة اإلجماليــة ســبعة وثمانــون متــرا مربعــا وثمانيــة وأربعــون‬\n‫ســنتيمترا ( ‪87.48‬م‪ ) 2‬اململــوك لــه مبوجــب الصــك الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 22/182‬يف ‪1407/10/25‬ه ـ أطلــب احلكــم ببيــع‬\n‫العقــار املذكــور وإعطــاء كل وراث نصيبــه منــه هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليهــم أصالــة ووكالــة أجابــوا جميعــا بقولهــم ‪:‬‬\n‫مــا ذكــره املدعــي وكالــة يف دعــواه كلــه صحيــح جملــة وتفصيــا وال‬\n‫مانــع لدينــا مــن بيــع العقــار وإعطــاء كل وارث نصيبــه منه حســب الوجه‬\n‫الشــرعي هكــذا أجابــوا وقــرروا فجــرى ســؤال الطرفــن هــل علــى‬\n‫مورثكــم ديــن ؟ فأجابــوا جميعــا بأننــا ال نعلــم أن عليــه دينــا هكــذا‬\n‫قــرروا وبســؤالهم هــل لــه وصيــة ؟ فأجابــوا جميعــا ‪ :‬بأننــا ال نعلــم بــأن لــه‬\n‫وصيــة هكــذا قــرروا ثــم قــرر ‪ ...‬بقولــه ‪ :‬إن لوالدتــي ‪ ...‬وصيــة بالثلــث‬\n‫مــن مالهــا ثابتــة بالصــك الصــادر مــن كتابــة العــدل الثانيــة مبكــة‬\n‫املكرمــة برقــم ‪ 64 /37‬يف ‪1410/12/26‬ه ـ وأنــا الناظــر علــى الوصيــة‬\n‫مبوجــب الصــك املذكــور ومبــا أنهــا والــدة مالــك العقــار ‪ ...‬ولها الســدس‬\n‫مــن مالــه فإننــي أطلــب إخــراج ثلــث الســدس وإيداعــه يف بيــت املــال حلــن‬\n‫النظــر فيــه وتنفيــذه حســب الوصيــة هكــذا قــرر فجرى ســؤال الطرفني‬\n‫هــل لديكــم معارضــة يف وصيــة املذكــورة ؟ فأجابــوا جميعــا ‪ :‬بأنــه‬\n‫ليــس لدينــا معارضــة يف ذلــك مــا دام أن وصيتهــا ثابتــة لديكــم بالصــك‬\n\n\n                                                                                         ‫‪404‬‬\n\f      ‫املذكــور هكــذا قــرروا هــذا وقــد جــرى منــي االطــاع علــى جميــع‬\n      ‫الصكــوك املشــار إليهــا بعاليــه فوجدتهــا جميعــا مطابقــة ملــا عطــف‬\n      ‫عليهــا وقــد جــرى منــي االستفســار عــن صــك امللكيــة الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 22/182‬يف ‪1407/10/25‬ه ـ مــن قســم الســجالت يف‬\n      ‫احملكمــة وذلــك مبوجــب خطابنــا لهــم برقــم ‪ 33956071‬يف‬\n      ‫‪1433/5/22‬ه ـ فوردنــا اجلــواب منهــم شــرحا علــى خطابنــا املذكــور‬\n      ‫بأنــه ال يوجــد علــى ســجل الصــورة الضوئيــة املرفقــة ســوى مــا أحلــق عليــه‬\n      ‫حتــى تاريــخ ‪1433/5/23‬ه ـ أ‪.‬ه ـ فجــرى ســؤال الطرفــن هــل لديكــم‬\n      ‫مــا تريــدون إضافتــه ؟ فقالــوا ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه هكــذا‬\n      ‫قــرروا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى‬\n      ‫الصكــوك املشــار إليهــا بعاليــه ونظــرا ملطابقــة صــك ملكيــة العقــار‬\n      ‫املــراد بيعــه لســجله وســريان مفعولــه ومبــا أن الورثــة جميعــا يرغبــون بيــع‬\n      ‫العقــار محــل الدعــوى ونظــرا لكــون احلــق ال يعدوهــم ولكثــرة الورثــة‬\n      ‫وتعددهــم وصعوبــة قســمته بينهــم وجميعهــم بالغــون عــدا واحــد منهــم‬\n      ‫قاصــر ســنا وألنــه يصــار إلــى البيــع مــع عــدم إمــكان القســمة وحيــث‬\n      ‫قــرر الفقهــاء أنــه يجــب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة‬\n      ‫يك ُه فِ ي َهــا َأ ْي ‪:‬‬  ‫قــال يف مطالــب أولــي النهــى مــا نصــه « َو َمــنْ َد َعــا َشـ ِـر َ‬\n      ‫اضــي إ َلــى َب ْيـ ٍـع ُأ ْج ِبـ َـر َع َلــى ا ْل َب ْيـ ِـع َم َع ـ ُه َف ـ ِإنْ َأ َبــى َأ ْي ‪ْ :‬ام َت َنـ َـع‬\n                                                                                                                         ‫قِ ْسـ َـم ِة ال َّت َر ِ‬\n      ‫اكـ ٌـم َع َل ْيه َِمــا‪َ ،‬وقَ َسـ َـم الث ََّمـ َـن‬ ‫اع ـ ُه َح ِ‬      ‫يك ُه مِ ــنْ َب ْيـ ٍـع َم َع ـ ُه ِبيـ َـع َأ ْي ‪َ :‬ب َ‬\n                                                                                                                                     ‫َشـ ِـر ُ‬\n      ‫َصــا « ونظــرا لثبــوت وصيــة والــدة مالــك‬                                  ‫َب ْي َن ُه َمــا َع َلــى قَ ــدْ ِر حِ َّص َت ْيه َِمــا ن ًّ‬\n      ‫العقــار ‪ ...‬ونصيبهــا منــه الســدس لذلــك كلــه فقــد حكمــت ببيــع‬\n      ‫العقــار املوصــوف بعاليــه باملــزاد العلنــي وتســليم كل وارث نصيبــه منــه‬\n      ‫حســب الوجــه الشــرعي بعــد إحــراز الثلــث مــن نصيــب ‪ .....‬وهــو ثلــث‬\n\n\n‫‪405‬‬\n\f‫الســدس وحفظــه يف بيــت مــال احملكمــة لصالــح وصيتهــا الثابتــة شــرعا‬\n‫وبعــرض احلكــم علــى الطرفــن قــرروا جميعــا القناعــة بــه وألن مــن‬\n‫ضمــن الورثــة قاصــرا ووجــود وصيــة فقــد أمــرت برفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف مبكــة املكرمــة لتدقيــق احلكــم حســب‬\n‫التعليمــات‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/15‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n‫يــوم االثنــن ‪1434/1/12‬ه ـ افتتحــت اجللســة وكان قــد جــرى منــي‬\n‫بعــث املعاملــة حملكمــة االســتئناف مبكــة املكرمــة باخلطــاب رقــم‬\n‫‪ 33554752‬يف ‪1433/12/18‬ه ـ فعــادت إلــي بخطــاب فضيلــة رئيــس‬\n‫محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪ 332207878‬يف‬\n‫‪1434/1/6‬ه ـ وبرفقــه قــرار الدائــرة الثانيــة لألحــوال الشــخصية‬\n‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة برقــم ‪ 33482767‬يف ‪1433/12/29‬ه ـ املتضمــن بعــد‬\n‫املقدمــة مــا نصــه ‪ « :‬وبدراســة احلكــم وصــورة ضبطــه تقــرر إعادتهــا‬\n‫لفضيلــة حاكمهــا ملالحظــة‪ -:‬أن الورثــة مالكــي العقــار منهــم قاصــر‬\n‫ويف التركــة وصيــة وال بــد حينئــذ مــن حتقــق الغبطــة واملصلحــة جلهــة‬\n‫القاصــر والوصيــة يف الثمــن الــذي يبــاع بــه العقــار ومعرفــة الثمــن قبــل‬\n‫اإلذن ببيعــه فلمالحظــة ذلــك واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ ... .‬توقيعــه وختمــه‬\n‫الشــخصي ‪ .‬قاضــي اســتئناف د‪ ... /‬توقيعــه وختمــه الشــخصي ‪ .‬قاضــي‬\n‫اســتئناف ‪ ...‬موافــق علــى احلكــم موقــع يف األصــل ومجــاز ‪ ،‬وعليــه‬\n‫أجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم للعلــم النافــع والعمــل‬\n‫الصالــح بأنــه لــم يظهــر لــي ســوى مــا حكمــت بــه ملــا نــص عليــه الفقهــاء‬\n\n\n                                                                                      ‫‪406‬‬\n\f      ‫مــن أنــه يجــب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة كمــا‬\n      ‫ذكــرت ســابق ًا وكثــرة الورثــة وصعوبــة قســمة العقــار بينهــم وال يســوغ‬\n      ‫التوقــف عــن ذلــك لوجــود وصيــة أو لوجــود قاصــر ســن ًا مــا دام أن معظــم‬\n      ‫الورثــة يرغبــون يف بيــع العقــار وتســليم نصيبهــم منــه ومــع ذلــك فقــد‬\n      ‫أمــرت إيــداع نصيــب القاصــر يف بيــت مــال احملكمــة لصاحلــه لذلــك‬\n      ‫وبعــد اإلجابــة أمــرت بإحلــاق ذلــك يف صكــه وســجله وإعــادة املعاملــة‬\n      ‫حملكمــة االســتئناف مبكــة املكرمــة إلكمــال الزمهــا ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪1434/1/12‬هـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n      ‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ... /‬باحملكمــة العامــة مبكــة‬\n      ‫املكرمــة املــؤرخ يف ‪1433/11/21‬ه ـ واملســجل بعــدد ‪33461017‬‬\n      ‫املتضمــن دعــوى‪ ... /‬ضــد ورثــة‪ ... /‬يف اســتحقاق تركــة ‪ ،‬وبدراســة‬\n      ‫الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪407‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":398,"source_page_end":407,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"711a49b036cc0efcc6795fd188b76dec151e2ed56d969c8a0ef4900651aae35d","normalized_text_hash":"d633479f4e4ef6b61ccb5f4063353ce2731a1c86482af2d713f745e495a8ea74","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p398-33461017"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"9d55df4e-c3c7-5e4a-95f7-470b5396c255","document_type":"judgment","category":"judicial","subcategory":"general","title":"تركة -قسمة إجبار -ال وصية لوارث -من سعى يف نقض ما مت على يديه فسعيه مردود عليه -شراء عقار ليس عليه صك ال يفيد التملك وال يغني عن استخراج حجة االستحكام -ألحد الورثة حق الشفعة يف العقار املباع ملجاورته له -احلكم ببيع امليراث اململوك بالصك باملزاد العلني ولكل وارث نصيبه الشرعي.","document_number":"33440804","case_number":"33205648","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":"الدائرة احلقوقية األولى مبحكمة الاستئناف مبنطقة عسير .","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/28","year":"1434","subject":"تركة -قسمة إجبار -ال وصية لوارث -من سعى يف نقض ما مت على يديه فسعيه مردود عليه -شراء عقار ليس عليه صك ال يفيد التملك وال يغني عن استخراج حجة االستحكام -ألحد الورثة حق الشفعة يف العقار املباع ملجاورته له -احلكم ببيع امليراث اململوك بالصك باملزاد العلني ولكل وارث نصيبه الشرعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪33440804 :‬تاريخه‪1433/10/28:‬هـ‬\n                   ‫رقم القضية‪33205648:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34179279‬تاريخه‪1434/4/6 :‬هـ‬\n\n\n‫تركــة ‪ -‬قســمة إجبــار ‪ -‬ال وصيــة لــوارث ‪ -‬مــن ســعى يف نقــض مــا مت‬\n‫علــى يديــه فســعيه مــردود عليــه ‪ -‬شــراء عقــار ليــس عليــه صــك ال‬\n‫يفيــد التملــك وال يغنــي عــن اســتخراج حجــة االســتحكام ‪ -‬ألحــد‬\n‫الورثــة حــق الشــفعة يف العقــار املبــاع ملجاورتــه لــه ‪ -‬احلكــم ببيــع امليــراث‬\n        ‫اململــوك بالصــك باملــزاد العلنــي ولــكل وارث نصيبــه الشــرعي‪.‬‬\n\n\n\n\n‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (إن اهلل قــد أعطــى كل ذي حــق حقــه‬\n                                                     ‫فــا وصيــة لــوارث)‪.‬‬\n‫‪ .2‬القاعــدة الفقهيــة‪ :‬مــن ســعى يف نقــض مــا مت علــى يديــه فســعيه‬\n                                                          ‫مــردود عليــه‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليهمــا بأنــه تــويف مــورث موكليــه‬\n‫وانحصــر إرثــه يف موكليــه واملدعــى عليهمــا وقــد تــرك بيتــن وحوش ـ ًا‬\n‫ويطلــب قســمة التركــه‪ .‬اجــاب املدعــى عليهمــا باملصادقــه علــى‬\n‫ا واجــاب احدهمــا بــان المانــع مــن القســمه‬    ‫الدعــوى جملــه وتفصي ـ ً‬\n‫وســيتولى شــراء احــد البيتــن وموافــق علــى بيــع العقــار االخــر واعطائــه‬\n‫حصتــه منــه ‪ ،‬اضــاف املدعــى عليــه االخــر أنــه موافــق علــى قســمة‬\n\n                                                                                         ‫‪330‬‬\n\f      ‫البيــت الشــعبي وهــو ملــك لوالــده امــا البيــت االخــر اململــوك بصــك‬\n      ‫فهــو ملــك لــه ومورثهــم أخــرج صــك ًا عليــه لكونــه كان يعمــل يف‬\n      ‫القطــاع العســكري ويطلــب اثبــات ملكيتــه لــه ‪.‬وأضــاف أن والــده قــد‬\n      ‫اوصــى لــه بالعقــار ‪ ،‬انكــر املدعــى الوصيــه وأن االصــل انــه الوصيــة‬\n      ‫لــوراث علــى فــرض ثبوتهــا‪ ،‬جــرت الكتابــه لقســم اخلبــراء الجــل تثمــن‬\n      ‫العقــارات وقســمتها بالتراضــي مــا امكــن فــورد جوابهــم متضمن ـ ًا ان‬\n      ‫العقــار اململــوك بالصــك يقــدر مبلــغ ثالثمائــة الــف ريــال والعقــار الثانــي‬\n      ‫يقــدر بســتة اآلف ريــال والميكــن القســمة بــن الورثــه بطريــق التراضــي‬\n      ‫ولــن يقســم دون عــوض‪ ،‬واملدعــى عليــه يدعــي أن الصــك داخــل عليــه‬\n      ‫يف ملكــه مــن اجلهــة الشــرقية وحســب طبيعــة البيــت ومشــمول الصــك‬\n      ‫وجدنــا الصــك حســب طبيعــة البيــوت داخــل يف غرفتــن مــن بيت املدعى‬\n      ‫عليــه مت ســؤال املدعــى عليــه ‪ ...‬بشــأن الغرفتــن الداخلــه يف الصــك‬\n      ‫هــل ميلــك عليهــا صــك ًا مســتقال فأجــاب بالنفــي ‪ ،‬ثــم أبــرز املدعــي‬\n      ‫وكالــه وصيــه للمــورث مصدقــه مــن شــيخ القبيلــه وفيهــا قــول املــورث ان‬\n      ‫البيــت الــذي يســكن فيــه فهــو بيتــي وباقــي أوالدي واخواتهــم الثــاث و‬\n      ‫والدتهــم ومؤرخــه الوصية‪1421/5/11‬ه ـ ويبطــل هــذا الصــك مضمــون‬\n      ‫الصــك اآلخــر ويبطــل بذلــك الوصيــه املزعومه التي ابرزهــا املدعى عليه‬\n      ‫وقــرر اجلميــع موافقتهــم أن يشــتري املدعــى عليــه البيــت الشــعبي الــذي‬\n      ‫قدرتــه اللجنــه بســتة اآلف ريــال ‪ .‬بنــاء علــى ماتقــدم مــن الدعــوى ومبــا أن‬\n      ‫طــريف الدعــوى ســبق منهمــا حصــر التركــه ووقعــا علــى ذلــك مبــا فيهــم‬\n      ‫املدعــى عليــه ‪ ،‬ومبــا ان املدعــى عليــه ظهــر تناقضــه ومحاولــة تأخيــر‬\n      ‫البــت يف الدعــوى ‪ ،‬ومبــا أن القاعــدة الشــرعيه علــى ان مــن ســعى يف‬\n      ‫نقــض مــامت علــى يديــه فســعيه مــردود عليــه ‪ ،‬كيــف واليوجــد للمدعــى‬\n\n\n‫‪331‬‬\n\f‫عليــه صــك يدفــع هــذا الصــك ولذلــك جميعــا‪ -:‬ثبــت شــراء ‪ ...‬للبيــت‬\n‫الشــعبي املوصــوف وإلزامــه بدفــع قيمتــه للورثــه كل حســب نصيبــه‬\n‫كمــا مت احلكــم علــى جميــع الورثــة ببيــع البيــت اململــوك بالصــك باملــزاد‬\n‫العلنــي ولــكل وارث نصيبــه‪ ،‬اقتنــع املدعــى وكالــه واملدعــى عليــه‪....‬‬\n‫وقــرر املدعــى عليــه اآلخــر عــدم القناعــة مت التصديــق علــى احلكــم مــن‬\n        ‫الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة عســير ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة بخميس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بخميــس مشــيط برقــم ‪ 33205648‬وتاريــخ ‪ 1433/03/22‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33546382‬وتاريــخ ‪ 1433/03/22‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1433/10/28‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 00‬‬\n‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بصفتــه وكيــا عــن كل مــن ‪ ...‬و‪ ...‬و‪ ...‬أبنــاء‪ ...‬و‪ ...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل خميــس مشــيط رقــم ‪370705023155‬‬\n‫يف ‪ 1433/2/29‬ه ـ والتــي تخولــه حــق املطالبــة واملرافعــة واملدافعــة‬\n‫واملخاصمــة ولــه حــق اإلقــرار واإلنــكار والصلــح وقبــول احلكــم‬\n‫واالعتــراض وبصفتــه وكيــا عــن ‪ ...‬و‪ ...‬أبنــاء ‪ ...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض رقــم ‪ 3311678‬يف‬\n‫‪ 1433/3/1‬هـ والتي تخوله حق املطالبة واملرافعة واملدافعة واملخاصمة‬\n‫ولــه حــق اإلقــرار واإلنــكار والصلــح وقبــول احلكــم واالعتــراض‬\n‫وحضــر حلضــوره‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n\n                                                                                    ‫‪332‬‬\n\f      ‫و‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬فادعــى األول‬\n      ‫قائــا لقــد تــويف مــورث موكلــي ‪ ...‬مبوجــب صــك حصــر الورثــة رقــم‬\n      ‫‪32196793‬يف ‪1432/8/9‬ه ـ وانحصــر إرثــه يف موكلــي ويف املدعــى‬\n      ‫عليهــم وقــد خلــف املتوفــى التركــة التاليــة ‪ -1‬البيــت واحلــوش الواقــع يف‬\n      ‫قريــة ‪...‬اململــوك بالصــك الصــادر مــن محكمــة أحدرفيــدة برقــم ‪187‬يف‬\n      ‫‪1415/5/19‬ه ـ ‪ -2‬البيــت الشــعبي الواقــع يف قريــة ‪ ...‬وهــو عبــارة عــن‬\n      ‫منــزل متهــدم قــدمي ومســاحته صغيــرة جــدا ويقــع يف قريــة مهجــورة وال‬\n      ‫يوجــد لــه طريــق للســيارة يحــده مــن الغــرب ملــك ‪ ...‬ومــن اجلنــوب ملــك‬\n      ‫‪ ...‬ولــم نتمكــن مــن عمــل رفــع مســاحي عليــه لصغــر مســاحته ومبــا أن‬\n      ‫املدعــى عليهمــا ال يرغبــان يف قســمة التركــة فإننــا نطلــب إجبارهــم‬\n      ‫علــى ذلــك هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليهمــا صادقــا‬\n      ‫علــى الدعــوى جملــة وتفصيــا وأجــاب املدعــى عليــه ‪ ...‬ال مانــع لــدي‬\n      ‫مــن القســمة وســأتولى شــراء البيــت الشــعبي وأوافــق علــى بيــع العقــار‬\n      ‫الثانــي وإعطائــي حصتــي منــه وأضــاف املدعــى عليــه ‪ ...‬أمــا البيــت‬\n      ‫الشــعبي فأوافــق علــى قســمته وهــو ملــك لوالــدي وأمــا البيــت اململــوك‬\n      ‫بصــك فهــو ملــك لــي فوالــدي أخــرج عليــه صــك وأنــا كنــت أعمــل يف‬\n      ‫القطــاع العســكري يف أزمــة اخلليــج وأطلــب إثبــات ملكــي لــه هكــذا‬\n      ‫أجابــا بعــد ذلــك جــرى ســؤال الطرفــن هــل علــى مورثكــم ديــن أو لــه‬\n      ‫وصيــة فأجابــا ليــس عليــه ديــن وال وصيــة وأضــاف املدعــى عليــه ‪ ...‬بــأن‬\n      ‫والــدي قــد أوصــى لــي بكامــل البيــت املذكــور يف الدعــوى اململــوك‬\n      ‫بالصــك وأبــرز صــورة لورقــة يدعــي أنهــا وصيــة والــده وذكــر بأنــه ال‬\n      ‫يعلــم عــن محــل أصلهــا وهــي مؤرخــة يف ‪1402/12/25‬ه ـ بعــد ذلــك‬\n      ‫جــرى اإلطــاع علــى صــك حصــر الورثــة وعلــى الــوكاالت وعلــى أســاس‬\n\n\n‫‪333‬‬\n\f‫الصــك املذكــور فوجدتهــا طبــق ماذكــر كمــا ســبق منــا طلــب طــريف‬\n‫الدعــوى حصــر تركــة مورثهــم فوقــع اجلميــع يف تاريــخ ‪1433/5/9‬ه ـ‬\n‫محضــرا لــدي يفيــد انحصــار التركــة يف الصــك والبيــت الشــعبي‬\n‫املذكوريــن يف الدعــوى وصــادق املدعــى عليــه ‪ ...‬علــى ذلــك كمــا‬\n‫جــرى منــي بعــث الصــك املذكــور ملصــدره لإلفــادة عــن ســجله باخلطــاب‬\n‫رقــم ‪33668403‬يف ‪1433/4/10‬ه ـ فوردنــا خطابهــم رقــم ‪859‬يف‬\n‫‪1433/4/24‬هـ واملتضمن أن الصك ال يزال ســاري املفعول كما جرى‬\n‫منــي الكتابــة لقســم الصلــح بهــذه احملكمــة حملاولــة اإلصــاح بــن‬\n‫الطرفــن وذلــك بخطابــي رقــم ‪33546382‬يف ‪1433/4/10‬ه ـ فوردتنــي‬\n‫منهــم اإلفــادة بتعــذر ذلــك باخلطــاب رقــم ‪33546382‬يف ‪1433/4/19‬ه ـ‬\n‫وبعــرض مــا ذكــره املدعــى عليــه ‪ ...‬علــى املدعــي وكالــة أجــاب أمــا‬\n‫البيــت اململــوك بالصــك فهــو ملــك للمــورث ثابــت شــرعا والوصيــة التــي‬\n‫أبرزهــا املدعــى عليــه ‪ ...‬ال صحــة لهــا ثــم إنــه يف األصــل ال وصيــة لــوارث‬\n‫علــى فــرض ثبوتهــا ثــم إنهــا مؤرخــة يف عــام ‪1402‬ه ـ والصــك يف عــام‬\n‫‪1415‬ه ـ ثــم إن املــورث لــم يفــرغ الصــك وكان ذلــك بإمكانــه فهــو لــم‬\n‫يتوفــى إال يف عــام ‪1423‬ه ـ وقــد حضــر املدعــى عليــه ‪ ...‬لديكــم وقــرر‬\n‫بــأن البيــت لوالــده يف محضــر حصــر التركــة بعــد ذلــك جــرى دراســة‬\n‫الصــك الــذي يدعــي ‪ ...‬ملكيتــه فوجــد مايلــي ‪ -1‬املنهــي هــو مــورث‬\n‫طــريف الدعــوى ‪ -2‬الصــك يحــدد امللــك حــدا وذرعــا ومســاحة ‪ -3‬يف‬\n‫الســطر الثامــن عشــر حضــر املدعــى عليــه ‪ ...‬وكيــا عــن والــده يف‬\n‫إثبــات ملكيــة البيــت للمنهــي وقــرر لــدى القاضــي يف حينــه مصادقتــه‬\n‫علــى مــا أنهــى بــه موكلــه حــدا وذرعــا وملــكا ومســاحة ‪ -4‬أحضــر‬\n‫املدعــى عليــه ‪ ...‬البينــة علــى أن مورثــه املالــك للمنهــى عنــه ‪ -5‬أثبــت‬\n\n\n                                                                                      ‫‪334‬‬\n\f      ‫مصــدر الصــك امللــك للمــورث واكتســب احلكــم القطعيــة بتصديــق‬\n      ‫محكمــة االســتئناف (انتهــى) كمــا ســبق منــي الكتابــة لقســم اخلبــراء‬\n      ‫بهــذه احملكمــة باخلطــاب رقــم ‪33546382‬يف ‪1433/5/9‬ه ـ ألجــل‬\n      ‫تثمــن العقــارات وقســمتها بالتراضــي مــا أمكــن فــورد قرارهــم رقــم‬\n      ‫‪33546382‬يف ‪1433/6/9‬ه ـ واملتضمــن أنــه بالوقــوف برفــق مكتبــن‬\n      ‫عقاريــن اتضــح أن العقــار اململــوك بالصــك يقــدر مببلــغ ثالثمائــة ألــف‬\n      ‫ريــال والعقــار الثانــي منــزل قــدمي متهــدم ومســاحته صغيــرة جــدا ويقــع يف‬\n      ‫قريــة مهجــورة وال يوجــد لــه طريــق للســيارة إال مــع الــوادي ويقــدر بســتة‬\n      ‫آالف ريــال (انتهــى) بعــد ذلــك جــرت الكتابــة لقســم اخلبــراء وذلــك‬\n      ‫باخلطــاب رقــم ‪33788135‬يف ‪1433/7/5‬ه ـ بطلــب تطبيــق الصــك‬\n      ‫واإلفــادة عــن إمكانيــة القســمة بالتراضــي دون الرجــوع للبيــع باملــزاد‬\n      ‫العلنــي فوردنــا قرارهــم رقــم ‪331777814‬يف ‪1433/10/8‬ه ـ وفيــه ((‬\n      ‫نفيــد فضيلتكــم فإنــه مت وقوفنــا وجــرى تطبيــق الصــك فوجــد مطابقــا‬\n      ‫وال ميكــن القســمة بــن الورثــة بطريــق التراضــي ولــن ينقســم بــدون رد‬\n      ‫عــوض واملدعــى عليــه ‪ ...‬يدعــي أن الصــك داخــل عليــه يف ملكــه مــن‬\n      ‫اجلهــة الشــرقية وحســب طبيعــة البيــت ومشــمول الصــك وبيــت املدعــى‬\n      ‫عليــه املتشــابكة بجانــب بعــض فقــد وجدنــا الصــك حســب طبيعــة‬\n      ‫البيــوت داخــل يف غرفتــن مــن بيــت املدعــى عليــه (انتهــى) بعــد ذلــك‬\n      ‫جــرى ســؤال املدعــى عليــه ‪ ...‬عــن الغرفتــن الداخلــة يف الصــك هــل‬\n      ‫ميلــك عليهــا صــكا مســتقال فأجــاب ال وبســؤاله ملــاذا لــم تثبــت ملــكك‬\n      ‫أو تعــارض علــى صــك أبيــك فأجــاب لــم أكــن موجــودا وال أعلــم عــن‬\n      ‫الصــك املذكــور شــيئا إال حــن معارضــة البلديــة هكــذا أجــاب بعــد‬\n      ‫ذلــك جــرى عــرض مــا ذكــر علــى املدعــي وكالــة فأجــاب جميــع مــا‬\n\n\n‫‪335‬‬\n\f‫حــواه الصــك ملــك للمــورث واملدعــى عليــه ‪...‬يعانــد باقــي الورثــة وال‬\n‫يرغــب يف القســمة مــع أنــه مــن ســعى إلخــراج الصــك لوالــده وهــو مــن‬\n‫أحضــر البينــة يف ذلــك الوقــت هكــذا أجــاب وأضاف املدعــى عليه ‪ ...‬لم‬\n‫أحضــر البينــة أثنــاء نظــر احلجــة عنــد القاضــي هكــذا أضــاف ثــم أبــرز‬\n‫املدعــي وكالــة وصيــة للمــورث مصدقــة مــن شــيخ القبيلــة وفيهــا قــول‬\n‫املــورث (أمــا البيــت الــذي أنــا ســاكن فيــه ويحدنــي مــن الشــرق بيــت ‪...‬‬\n‫هــو بيتــي وباقــي أوالدي ‪ ...‬و‪ ...‬وأخواتهــم الثــاث ووالدتهــم ‪ )...‬والوصيــة‬\n‫مؤرخــة يف ‪1421/5/11‬ه ـ وأضــاف ال نطالــب بهــا ولكنهــا تؤكــد أن‬\n‫البيــت للمــورث يحــده مــن الشــرق املدعــى عليــه ‪...‬وهــذا مضمــون الصــك‬\n‫ويبطــل بذلــك الوصيــة املزعومــة التــي أبرزهــا ‪...‬هكــذا أضــاف بعــد‬\n‫ذلــك قــرر اجلميــع موافقتهــم بــأن يشــتري املدعــى عليــه ‪ ...‬البيــت الشــعبي‬\n‫الــذي قدرتــه اللجنــة بســتة آالف ريــال يكــون نصيــب الزوجــة ســبعمائة‬\n‫وخمســن ريــاال ونصيــب ‪ ...‬و‪ ...‬و‪ ...‬تســعمائة وأربعــة وخمســون ريــاال‬\n‫وخمســة وخمســون هللــة لــكل واحــد منهــم ونصيــب ‪ ...‬و‪ ...‬و‪ ...‬أربعمائــة‬\n‫وســبعة وســبعون ريــاال وســبعة وعشــرون هللــة لــكل واحــدة منهــم وبعــد‬\n‫ذلــك جــرى عــرض الوصيــة التــي أبرزهــا املدعــي وكالــة علــى املدعــى‬\n‫عليهمــا فأجــاب ‪...‬ال أقرهــا وال أنكرهــا وال أطالــب بهــا وأجــاب ‪...‬ال‬\n‫أعلــم عنهــا وال أطالــب بهــا فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة‬\n‫ومبــا أن طــريف الدعــوى ســبق منهمــا حصــر التركــة لــدي أوال ووقعــا‬\n‫علــى ذلــك مبــا فيهــم املدعــى عليــه ‪ ...‬ومبــا أن املدعــى عليــه ‪ ...‬ظهــر‬\n‫تناقضــه ومحاولتــه تأخيــر البــت يف هــذه القســمة وتعطيلهــا مــع أن البيت‬\n‫اململــوك بالصــك املشــار إليــه قــد حضــره ممثــا عــن والــده أثنــاء إثباتــه‬\n‫مصادقــا علــى ملكيــة والــده لــه مســاحة وحــدا وذرعــا وأحضــر علــى‬\n\n\n                                                                                     ‫‪336‬‬\n\f      ‫ذلــك البينــة يف حينهــا والقاعــدة الشــرعية تنــص علــى أن مــن ســعى يف‬\n      ‫نقــض مــامت علــى يديــه فســعيه مــردود عليــه كيــف وال يوجــد للمدعــى‬\n      ‫عليــه ‪ ...‬صــك يدفــع هــذا الصــك ومــا أبــرزه مــن وصيــة فمــردودة بالصــك‬\n      ‫الشــرعي املــؤرخ بعدهــا مبــا يزيــد عــن عشــر ســنوات عــاوة علــى أن‬\n      ‫إقــراره لدينــا ولــدى مصــدر احلجــة دليــل ال يقبــل الرجــوع عنــه ويف تأخيــر‬\n      ‫القضيــة أكثــر ضــرر واضــح وتعطيــل ال فائــدة منــه وعليــه وبنــاء علــى‬\n      ‫إقــرار املدعــى عليــه ‪...‬بشــراء البيــت الشــعبي وإقــرار البقيــة باملوافقــة‬\n      ‫مقابــل أن تدفــع لهــم أنصبائهــم واســتنادا علــى قــول املصطفــى صلــى اهلل‬\n      ‫عليــه وســلم ( إن اهلل قــد أعطــى كل ذي حــق حقــه فــا وصيــة لــوارث‬\n      ‫) لذلــك جميعــا فقــد ثبــت لــدي شــراء ‪ ...‬للبيــت الشــعبي املوصــوف يف‬\n      ‫الدعــوى وألزمتــه بدفــع قيمتــه للورثــة كل حســب نصيبــه املقــرر شــرعا‬\n      ‫وأفهمتــه بــأن شــراءه ال يفيــد التملــك وال يغنــي عــن اســتخراج حجــة‬\n      ‫االســتحكام كمــا حكمــت علــى جميــع الورثــة ببيــع البيــت اململــوك‬\n      ‫بالصــك املشــار إليــه باملــزاد العلنــي ولــكل وارث نصيبــه مــن قيمتــه نقدا‬\n      ‫وال مينــع أحــد الورثــة مــن الشــراء ويكــون األحــق بذلــك املدعــى عليــه‬\n      ‫‪...‬فلــه حــق الشــفعة وصرفــت النظــر عمــا دفــع بــه املدعــى عليــه ‪ ...‬مــن‬\n      ‫ملكيــة البيــت لعــدم ثبــوت موجبــه وبــكل ذلــك قضيــت وبعــرض ذلــك‬\n      ‫علــى الطرفــن اقنــع املدعــي وكالــة واملدعــى عليــه ‪ ...‬وقــرر املدعــى‬\n      ‫عليــه ‪ ...‬عــدم القناعــة فجــرى تســليمه صــورة مــن صــك احلكــم علــى‬\n      ‫أن يقــدم اعتراضــه خــال شــهر مــن تاريخــه وبــاهلل التوفيــق وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد وحــرر يف ‪1433/10/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪337‬‬\n\f‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 3416069‬وتاريــخ‬\n‫‪1434/01/06‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪... /‬‬\n‫برقــم ‪ 33440804‬وتاريــخ ‪1433/10/28‬ه ـ اخلــاص بدعــوى ‪ /‬ورثــة ‪...‬‬\n‫و‪ ...‬ضــد ‪ ... /‬و‪ ...‬يف تركــة وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املوافقــة علــى احلكــم واهلل‬\n‫املوفــق‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪338‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":330,"source_page_end":338,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0be3fb1663e4707229b234f192c95f453ed3fd7218451e48303f7682d6dca955","normalized_text_hash":"766dbb8524c6f0e0f3b066a8fde7b007986d169816a1145dc9384e79c05f4fd9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p330-33440804"},{"id":"7aed11a7-c981-56b5-ac53-3e1f84a6c66c","document_type":"judgment","category":"judicial","subcategory":"general","title":"تركة -دعوى محاسبة -تنازل املدعين عن إحالة الدعوى حملاسب قانوني -محاسبة إدارة تركة -محاولة الصلح بن الورثة - مطالبة مبحاسبة يف ريع عقارات -الرجوع عن اإلقرار بحق آلدمي غير مقبول -قول األمن مقبول بيمينه ما لم تقم بينة على خالفه -ثبوت الدعوى.","document_number":"33334176","case_number":"13838","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/9","year":"1434","subject":"تركة -دعوى محاسبة -تنازل املدعين عن إحالة الدعوى حملاسب قانوني -محاسبة إدارة تركة -محاولة الصلح بن الورثة - مطالبة مبحاسبة يف ريع عقارات -الرجوع عن اإلقرار بحق آلدمي غير مقبول -قول األمن مقبول بيمينه ما لم تقم بينة على خالفه -ثبوت الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33334176 :‬تاريخه‪1433/7/9 :‬هـ‬\n                            ‫رقم الدعوى‪13838 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪34312231‬تاريخه‪1434/9/3 :‬هـ‬\n\n\n      ‫تركــة ‪ -‬دعــوى محاســبة‪ -‬تنــازل املدعيــن عــن إحالــة الدعــوى حملاســب‬\n      ‫قانونــي ‪ -‬محاســبة إدارة تركــة ‪ -‬محاولــة الصلــح بــن الورثــة ‪-‬‬\n      ‫مطالبــة مبحاســبة يف ريــع عقــارات‪ -‬الرجــوع عــن اإلقــرار بحــق آلدمــي‬\n      ‫غيــر مقبــول‪ -‬قــول األمــن مقبــول بيمينــه مــا لــم تقــم بينــة علــى‬\n                                                        ‫خالفــه‪ -‬ثبــوت الدعــوى‪.‬‬\n\n\n\n\n      ‫مــا هــو معتبــر عنــد عامــة أهــل العلــم أن الرجــوع عــن اإلقــرار يف حقــوق‬\n                                                               ‫اآلدمــي غيــر معتبــر‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــا املدعــن بــأن مورثهــم خلــف مــن ضمــن تركتــه عــدة‬\n      ‫عقــارات موصوفــة يف دعواهــم وأن املدعــى عليــه هــو املتولــي علــى تأجيــر‬\n      ‫تلــك العقــارات منــذ وفــاة املــورث إال أنــه يســلم الورثــة مبالــغ ماليــة دون‬\n      ‫بيــان مقــدار نصيــب كل واحــد منهــم كمــا أنــه أقــر بــأن ملورثهــم لديــه‬\n      ‫مبالــغ ماليــة مذكــورة يف الدعــوى‪ ،‬ولــذا فقــد طلبــا توضيــح دخــل تلــك‬\n      ‫العقــارات للمــدة املاضيــة وإجــراء محاســبة عليهــا وعلــى املبالــغ التــي‬\n      ‫أقــر بهــا ملورثهــم وتســليمهم املتبقــي مــن نصيبهــم منهــا‪ ،‬أقــر املدعــى‬\n      ‫عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه لــم يقــر للورثــة إال مببلــغ واحــد‬\n\n‫‪339‬‬\n\f‫فقــط عبــارة عــن عجــز علــى التركــة كان يظــن أنــه يتحملــه ثــم علــم‬\n‫أنــه يكــون مــن التركــة فقــام بحســمه منهــا كمــا أنــه ســلم جــزء منــه‬\n‫للمكلــف بقســمة التركــة وأمــا املبلــغ الثانــي فهــو داخــل يف األول‬\n‫وجــزء منــه وليــس مبلغ ـ ًا مســتقال عنــه‪ ،‬حصــر املدعــون دعواهــم يف‬\n‫مطالبــة املدعــى عليــه باملبالــغ التــي أقــر بهــا للتركــة وتنازلــوا عــن طلــب‬\n‫احملاســبة‪ ،‬طلبــت احملكمــة مــن املدعــن بينــة علــى إقــرار املدعــى عليــه‬\n‫باملبلــغ الثانــي فعجــزوا عــن إحضارهــا وطلبــوا ميينــه علــى نفيــه وعلــى‬\n‫أنــه ســلم جــزء مــن املبلــغ األول للمكلــف بقســمة التركــة فأداهــا طبــق‬\n‫مــا طلــب منــه‪ ،‬طلبــت احملكمــة مــن املدعــى عليــه بينــة علــى مــا دفــع‬\n‫بــه مــن أن املبلــغ األول الــذي أقــر بــه عجــز علــى التركــة فعجــز عــن‬\n‫إثبــات ذلــك‪ ،‬املدعــى عليــه أقــر باملبلــغ األول لصالــح الورثــة ثــم رجــع عــن‬\n‫إقــراره والرجــوع عــن اإلقــرار يف حقــوق اآلدمــي غيــر معتبــر كمــا أنــه‬\n‫أدى اليمــن علــى تســليم جــزء منــه لقاســم التركــة‪ ،‬قضــت احملكمــة‬\n‫بإلــزام املدعــى عليــه بــأن يســلم للمدعــن املبلــغ األول بعــد خصــم مــا‬\n‫ادعــى تســليمه منــه لقاســم التركــة وصرفــت النظــر عــن مطالبــة الورثــة‬\n‫بباقــي املبلــغ املدعــى بــه بعــد حلــف املدعــى عليــه اليمــن املطلوبــة‪،‬‬\n‫قنــع املدعــون باحلكــم وعــارض عليــه املدعــى عليــه‪ ،‬قــررت محكمــة‬\n                                           ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪340‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬مســاعد رئيــس احملكمــة العامــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 13838‬وتاريــخ ‪1431/10/12‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 3154393‬وتاريــخ ‪ 1431/10/12‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪ 1432/08/12‬ه ـ افتتحــت اجللســة الســاعة ‪: 26‬‬\n      ‫‪ 10‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫األصيــل عــن نفســه والوكيــل عــن ‪ .... .....‬أصالــة عــن نفســه وبصفتــه‬\n      ‫وصي ـ ًا علــى ‪ .....‬مبوجــب صــك القوامــة الصــادر مــن هــذه احملكمــة‬\n      ‫ا عــن ‪ .....‬بالوكالــة‬      ‫برقــم ‪ 9/100/545‬وتاريــخ ‪1429/3/8‬ه ـ ووكيـ ً‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 24421‬وتاريخ‬\n      ‫‪1432/4/16‬ه ـ وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة باملدينــة املنــورة برقــم ‪ 18434‬وتاريــخ ‪1432/3/26‬ه ـ وعــن ‪.....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n      ‫برقــم ‪ 20900‬وتاريــخ ‪1432/4/7‬ه ـ كمــا حضــر ‪ .....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬األصيــل عــن نفســه والوكيــل عــن ‪.....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n      ‫برقــم ‪ 98727‬وتاريــخ ‪1429/11/4‬ه ـ وعــن ‪ ..... ..... ..... ..... ..... .....‬بنــات‬\n      ‫‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n      ‫املنــورة برقــم ‪ 18729‬وتاريــخ ‪1429/3/22‬ه ـ وعــن ‪ .....‬مبوجب الوكالة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 11777‬وتاريخ‬\n      ‫‪1429/2/23‬ه ـ وعــن ‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العدل‬\n\n‫‪341‬‬\n\f‫الثانيــة باملدينــة املنــورة برقــم ‪ 61496‬وتاريــخ ‪1429/10/15‬ه ـ وعــن ‪.....‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة‬\n‫برقــم ‪ 66053‬وتاريــخ ‪1429/11/7‬ه ـ وعــن‪ .....‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 61497‬وتاريخ‬\n‫‪1429/10/15‬ه ـ وادعيــا علــى احلاضــر معهمــا ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬قائلــن يف دعواهمــا عليــه لقــد تــويف‬\n‫مورثنــا ومــورث املدعــى عليــه ‪ .....‬بتاريــخ ‪1429/2/14‬ه ـ وخلــف مــن‬\n‫ضمــن تركتــه عمــارة يف حــي ‪...‬جوار مســجد ‪ ...‬مبحافظــة جدة اململوك‬\n‫لــه بالصــك الصــادر مــن محكمــة جــدة برقــم ‪ 1549‬وتاريــخ ‪/ 5 / 4‬‬\n‫‪ 1400‬ه ـ وعمــارة يف حــي ‪ .....‬تقاطــع شــارع األميــر ‪ ...‬مــع شــارع ‪...‬‬\n‫مبحافظــة جــدة اململــوك لــه بالصــك الصــادر مــن محكمــة جــدة برقــم‬\n‫‪ 1613‬وتاريــخ ‪1421/8/26‬ه ـ ومبنــى مؤجــر علــى مطبــخ املســمى‬\n‫مبطبــخ ‪...‬الواقــع يف حــي ‪ ...‬باملدينــة املنــورة اململــوك لــه بالصــك الصــادر‬\n‫مــن كتابــة العــدل األولــى باملدينــة املنــورة برقــم ‪ 1/1254‬وتاريــخ‬\n‫‪1401/11/25‬ه ـ ومنــذ وفــاة مورثنــا واملتولــي علــى هــذه العقــارات‬\n‫وتأجيرهــا املدعــى عليــه وقــد طلبنــا منه إيضاح حســابات هــذه العقارات‬\n‫ا فلــم‬  ‫وبيــان نصيــب كل واحــد مــن الورثــة منهــا وتســليمه كام ـ ً‬\n‫يتجــاوب معنــا وإمنــا يســلمنا مبالــغ دون بيــان مقــدار نصيــب كل واحــد‬\n‫منــا كمــا أنــه أقــر ببيعــه لورشــتني ملورثنــا مببلــغ ثالثمائــة وســتني ألــف‬\n‫ريــال وأقــر بــأن ملورثنــا يف حســابه مبلــغ تســعمائة وســبعة وثالثــن ألف ـ ًا‬\n‫وثالثمائــة وثمانيــة وخمســن ريــال إضافــة إلــى مبلــغ خمســمائة ألــف‬\n‫ريــال لديــه ملورثنــا وقــد طالبنــاه بإجــراء احملاســبة يف ذلــك ويتهــرب مــن‬\n‫ذلــك نطلــب إلزامــه بتوضيــح دخــل هــذه العقــارات للمــدة املاضيــة‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫ومحاســبته عليهــا وعلــى املبالــغ التــي أقــر بهــا وتســليمنا املتبقــي مــن‬\n      ‫نصيبنــا منهــا علم ـ ًا بأنــه ســلم القاســم مبلــغ مليــون وتســعمائة وثالثــة‬\n      ‫عشــر ألف ـ ًا وخمســمائة ريــال عــن نصيــب التركــة الــذي لديــه وكان‬\n      ‫نصيب كل ابن منها مبلغ تســعة وســبعني ألف ًا ومائة وخمســة وخمســن‬\n      ‫ريــا ًال هــذه دعوانــا وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه مــا‬\n      ‫ذكــره املدعيــان يف دعواهمــا مــن وفــاة مورثنــا وأنــه خلــف مــن ضمــن‬\n      ‫تركتــه العقــارات املذكــورة فهــذا صحيــح وقــد كنــت قائم ـ ًا علــى‬\n      ‫العقــارات التــي يف جــدة وهــي عمــارة حــي ‪...‬وعمــارة حــي ‪ ...‬مــن تاريــخ‬\n      ‫شــرائهما إلــى الوقــت احلاضــر أمــا املبنــى الــذي يف املدينــة واملؤجــر علــى‬\n      ‫مطبــخ ‪...‬فلــم أســتلم أجــاره إال مــن بعــد دخــول والــدي يف غيبوبــة عــام‬\n      ‫‪1427‬ه ـ حتــى الوقــت احلاضــر ومجمــوع أجــارات عمــارة حــي ‪...‬مــن تاريخ‬\n      ‫شــرائها إلــى نهايــة عــام ‪1431‬ه ـ هــو مبلــغ مليــون ومائتــن وســبعة‬\n      ‫وخمســن ألف ـ ًا وثمامنائــة وريــاالن ومجمــوع أجــارات عمــارة حــي ‪ ...‬مــن‬\n      ‫تاريــخ شــرائها حتــى نهايــة عــام ‪1431‬ه ـ هــو مبلــغ مليــون وثالثمائــة‬\n      ‫وتســعة وثالثــن ألفـ ًا وســتمائة وعشــرة ريــاالت ومجمــوع أجــارات مطبــخ‬\n      ‫‪...‬مــن عــام ‪1427‬ه ـ حتــى نهايــة عــام ‪1431‬ه ـ هــو مبلــغ مائتــن وســتني‬\n      ‫ألف ريال كما أنني قمت بتقبيل ورشــتني كان مورثهما مســتأجرهما‬\n      ‫مــن ‪ .....‬مبوافقــة الورثــة ومجمــوع القيمــة مــع أجــرة ســنة قبــل التقبيــل‬\n      ‫هــي مبلــغ ثالثمائــة وســتني ألــف ريــال وأمــا مــا ذكــره املدعيــان مــن أننــي‬\n      ‫ســبق أن أقريــت مببالــغ للتركــة علــي فصحيــح أننــي ســبق أن ذكــرت‬\n      ‫ذلــك للورثــة وملصفــي التركــة أن للتركــة لــدي مبلــغ تســعمائة وســبعة‬\n      ‫وثالثــن ألف ـ ًا وثالثمائــة وثمانيــة وخمســن ريــا ًال هــي عبــارة عــن دخــل‬\n      ‫العقــارات وبقيــة التركــة إلــى وفــاة والــدي ولــم أقــر بــأن للتركــة يف‬\n\n\n‫‪343‬‬\n\f‫ذمتــي خمســمائة ألــف ريــال إضافــة إلــى املبلــغ وإمنــا ذكــرت أن هنــاك‬\n‫عجــز علــى التركــة هــو عبــارة عــن خســائر يف األســهم مببالــغ كانــت‬\n‫لوالــدي واســتثمرتها يف محفظتــي يف األســهم حيــث كانــت اخلســائر‬\n‫قرابــة أربعمائــة ألــف ريــال إضافــة إلــى مبلــغ مائــة ألــف ريــال مــن املبالــغ‬\n‫التــي كانــت لوالــدي قمــت بصرفهــا علــى عائلــة والــدي يف حياتــه‬\n‫ومجمــوع ذلــك مبلــغ خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة‬\n‫وســتني ريــا ًال وكنــت أظــن أننــي أحتمــل هــذا املبلــغ ثــم علمت أن خســائر‬\n‫األســهم واملبالــغ التــي أنفقتهــا علــى العائلــة تكــون مــن التركــة فقمــت‬\n‫بحســمها مــن املبالــغ التــي للتركــة علــي وســلمت الباقــي للورثــة وملصفــي‬\n‫التركــة ولــم يبــق لهــم لــدي أي شــيء فجــرى ســؤاله عــن املبالــغ التــي‬\n‫اســتثمرها لوالــده يف األســهم مــن أيــن أخذهــا فقــال إن والــدي ســبق أن‬\n‫ســلمني مبلــغ خمســة ماليــن ومائتــن وســبعني ألــف ريــال منهــا مبلــغ‬\n‫اثنــن مليــون ومائــة ألــف ريــال اســتلمتها مبوجــب شــيكني مــن والــدي‬\n‫ومبلــغ ثالثــة مليــون وســبعني ألــف ريــال مبوجــب أربــع حــواالت مــن ر‪.....‬‬\n‫بحقــوق كانــت لديــه لوالــدي وطلــب منــي والــدي اســتالمها فقمــت‬\n‫بشــراء عمــارة حــي ‪...‬وعمــارة حــي ‪ ...‬وقطعتــي أرض املدينــة مببلــغ أربعــة‬\n‫مليــون وســبعمائة وســبعة عشــر ألف ـ ًا وســتمائة ريــال والباقــي مــن املبلــغ‬\n‫وقــدره خمســمائة واثنــن وخمســن ألف ـ ًا وأربعمائــة ريــال إضافــة إلــى‬\n‫مبلــغ مــن دخــل العمــارات ال أذكــره بالضبــط قمــت باســتثماره يف‬\n‫األســهم وقــد حصلــت فيــه خســارة إضافــة إلــى مصاريــف للعائلــة نقديــة‬\n‫باملبلــغ الــذي ذكــرت ولــم يتبــق لهــم لــدي أي مبلــغ وأنــا مســتعد بإجــراء‬\n‫احملاســبة وإبــراز مــا لــدي مــن مســتندات للمدعــن ملراجعتهــا والتأكــد‬\n‫منهــا كمــا أضــاف بــأن عمــارة حــي ‪ ...‬ال يوجــد لهــا عقــود إال ثالثــة‬\n\n\n                                                                                          ‫‪344‬‬\n\f      ‫عقــود يف أول أيــام التأجيــر ثــم اكتفيــت بســندات القبــض التــي يذكــر‬\n      ‫فيهــا مــدة األجــرة ومبلغهــا يدفــع مقدم ـ ًا دون أن يكتــب عقــد حتــى ال‬\n      ‫يلزمنــي بالبقــاء باقــي مــدة العقــد دون أن يدفــع األجــرة وأمــا عمــارة حــي‬\n      ‫‪...‬فقــد اكتفيــت بعقــود املالــك الســابق علــى املؤجريــن ولم أجــدد العقود‬\n      ‫لهــم والــذي يتابــع تأجيــر املبنــى هــي مؤسســة ‪ .....‬الواقعــة يف حي ‪ ...‬ســوق‬\n      ‫‪ ....‬وقــد ســلمني كشــف ًا باإلجــارات مفصلــة ويوجــد مــن ضمنهــا صــراف‬\n      ‫بنــك ‪...‬مببلــغ ســتة وخمســن ألف ـ ًا وثمامنائــة ريــال وبإمكانهــم مراجعــة‬\n      ‫املؤسســة والتأكــد مــن ذلــك وأمــا املبنــى املؤجــر علــى مطبــخ ‪...‬فلــم‬\n      ‫اســتلم إال مــن عــام ‪1427‬ه ـ حتــى عــام ‪1431‬ه ـ بعــد دخــول والــدي يف‬\n      ‫غيبوبــة حتــى وفاتــه وكان اإليجــار ســنتني خمســة وأربعــن ألــف ريــال‬\n      ‫وثــاث ســنوات ســتني ألــف ريــال علمـ ًا بــأن مبلــغ خمســة آالف ريــال مــن‬\n      ‫أجــار الســنتني األوليــن كان أخــي ‪ .....‬يســتلمها ويســلمها لعمــي صدقــة‬\n      ‫علــى عــادة الوالــد وابــن عمــي يعــرف ذلــك ويشــهد بــه وبهــذا يكــون‬\n      ‫مجمــوع مــا اســتلمته مــن أجــار املطبــخ هــو مبلــغ مائتــن وســتني ألــف‬\n      ‫ريــال وجــرى تزويــد املدعــن بالســندات املذكــورة ملراجعتهــا وإحضــار‬\n      ‫مــا لديهمــا مــن مالحظــات إن وجــدت يف اجللســة القادمــة كمــا قــرر‬\n      ‫املدعيــان طلبهمــا عقــد البنــك ‪...‬يف عمــارة حــي ‪...‬وكشــف مختصــر‬\n      ‫للمــودع واملســحوب ومقــدار اخلســارة واملبلــغ املتبقــي حملفظــة املدعــى‬\n      ‫عليــه وعقــود عمــارة حــي ‪ ...‬التــي ذكــر املدعــى عليــه أن بهــا ثالثــة عقــود‬\n      ‫غيــر ســندات القبــض فأبــرز املدعــى عليــه عقــد البنــك ‪ .....‬وعقــود عمارة‬\n      ‫حــي ‪ ...‬وقــال أمــا حركــة احملفظــة فقــد ســبق تزويــد املدعيــن بهــا‬\n      ‫وموجــود فيهــا كل مــا يريــدان مــن حركــة وبإمكانهمــا مراجعتهــا مــن‬\n      ‫قبــل محاســب قانونــي وأنــه راجــع البنــك وذكــر بأنــه ال يوجــد لديــه إال‬\n\n\n‫‪345‬‬\n\f‫كشــف بحركــة تــداول احملفظــة فقــط هكــذا قــرر لــذا طلبــت مــن‬\n‫املدعيــن إحضــار جميــع مــا لديهمــا مــن مالحظــات علــى الكشــوف‬\n‫املقدمــة مــن املدعــى عليــه يف اجللســة القادمــة ورفعــت اجللســة لذلــك ثــم‬\n‫يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعيــن عــن‬\n‫مالحظاتهمــا علــى الكشــوفات واحلســابات املقدمــة مــن املدعــى عليــه‬\n‫فقــاال إن الكشــوفات واحلســابات التــي قدمهــا هــي جلميــع الســنوات‬\n‫منــذ اســتالمه للعمايــر إجمــا ًال ولــم يفصــل للمبالــغ التــي وردت بعــد‬\n‫الوفــاة ونطلــب أن يفصــل املبالــغ التــي بعــد الوفــاة ألن املدعــى عليــه أبــرز‬\n‫لنــا كشــوفات بعــد وفــاة مورثنــا مباشــرة باملبالــغ التــي لديــه وعنــد‬\n‫حســمها مــن املبالــغ اإلجماليــة التــي أبرزهــا أمامكــم يتبــن أنــه تبقــى‬\n‫لنــا مبالــغ مســتحقة بعــد الوفــاة لديــه وليــس كمــا ذكــر بأنــه لــم يتبــق‬\n‫لديــه شــيء وقــد تعمــد ذكــر املبالــغ اإلجماليــة دون أن يفصــل مــا بعــد‬\n‫الوفــاة حتــى ال تخالــف الكشــوفات التــي أبرزهــا لنــا ســابق ًا ونطلــب‬\n‫إلزامــه بتفصيــل املبالــغ التــي قبــل الوفــاة واملبالــغ احملصلــة بعــد الوفــاة‬\n‫يتضــح لكــم عــدم انطبــاق الكشــوفات التــي يقدمهــا كمــا أن لدينــا‬\n‫مالحظــات أخــرى ســنحضرها يف اجللســة القادمــة لــذا طلبــت مــن‬\n‫املدعــى عليــه تفصيــل املبالــغ احملصلــة لديــه قبــل وفــاة مورثهــم ومــا‬\n‫حتصــل بعــد الوفــاة مــن دخــل عمــارة ‪ ...‬و‪ ...‬و‪...‬وأجــرة كل ســنة علــى‬\n‫حــده فاســتعد بذلــك ثــم يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال‬\n‫املدعــى عليــه عــن تفاصيــل املبالــغ احملصلــة لديــه املطلوبــة منــه فقــال‬\n‫إننــي أحضرتهــا وأبــرز كشــف مكــون مــن ســت وعشــرين ورقــة قــال إن‬\n‫فيهــا تفاصيــل احلســابات وجــرى تزويــد املدعيــان بنســخة منهــا وقــال ال‬\n‫مانــع لــدي مــن إجــراء احملاســبة علــى جميــع مــا لــدي وقــال املدعيــان أننــا‬\n\n\n                                                                                        ‫‪346‬‬\n\f      ‫أحضرنــا بعــض املالحظــات علــى حســابات املدعــى عليــه وأبــرزا ورقــة‬\n      ‫قــاال إن فيهــا بعــض املالحظــات كمــا أن لدينــا مالحظــات أخــرى لباقــي‬\n      ‫املبالــغ وفروقــات الدخــل الســنوي ســوف نحضرهــا يف اجللســة القادمــة‬\n      ‫بعــد اســتالمنا لتقاريــر املدعــى عليــه مفصلــة وقــال املدعــى عليــه إن‬\n      ‫املدعيــان يف كل جلســة يذكــران أن لديهمــا مالحظــات أخــرى‬\n      ‫ويطلبــان جلســة أخــرى مــن أجــل إطالــة القضيــة وإتعابــي وأنــا مســتعد‬\n      ‫بإجــراء احملاســبة التــي يطالــب بهــا املدعيــان لــدى محاســب قانونــي‬\n      ‫واليمــن علــى نفــي مــا يدعــون هكــذا قــرر لــذا أفهمــت الطرفــن‬\n      ‫باختيــار محاســب قانونــي إلجــراء احملاســبة بينهمــا ومــا يقــرره احملاســب‬\n      ‫القانونــي يكــون ملزم ـ ًا لهمــا علــى أن يتحمــل املدعيــان تكاليــف‬\n      ‫احملاســب ويف حــال ظهــور عجــز لــدى املدعــى عليــه فإنهــا تضــاف إلــى ما‬\n      ‫عليــه مــن عجــز فطلــب املدعيــان مهلــة للبحــث عــن محاســب واإلفــادة يف‬\n      ‫اجللســة القادمــة ثــم يف جلســة أخــرى حضــر املدعيــان واملدعــى عليــه‬\n      ‫وجــرى ســؤال املدعيــان عــن احملاســب القانونــي فقــاال إننــا ال نريــد إحالة‬\n      ‫املدعــى عليــه إلــى محاســب قانونــي ألن احلســابات واألوراق كلهــا عنــده‬\n      ‫ويســتطيع أن يغيــر فيهــا بــن فتــرة وأخــرى وإننــا نقصــر دعوانــا علــى‬\n      ‫أمريــن همــا ســؤاله عــن إقــراره بعــد وفــاة مورثنــا مباشــرة بــأن لديــه‬\n      ‫للورثــة مبلــغ تســعمائة وســبعة وثالثــن ألفـ ًا وثالثمائــة وثمانيــة وخمســن‬\n      ‫ريــا ًال وإقــراره للورثــة بــأن لهــم يف ذمتــه مبلغ ـ ًا آخــر هــو خمســمائة ألــف‬\n      ‫ريــال وعنــد ســؤالنا لــه يف وقتهــا عنهــا قــال ال تســألوني عــن مصدرهــا‬\n      ‫وإمنــا هــي لكــم علــي وعنــد إجــراء القســمة لــدى القاســم احملامي الشــيخ‬\n      ‫‪ ...‬أقر املدعى عليه مببلغ اخلمســمائة ألف ريال وقام احملامي بإضافتها‬\n      ‫إلــى مبلــغ كل وارث ثــم طلــب احملامــي الشــيكات وقــام بتعديــل املبالــغ‬\n\n\n‫‪347‬‬\n\f‫وحســم نصيــب كل وارث مــن مبلــغ اخلمســمائة ألــف ريــال علــى أن‬\n‫حتســم عليــه عنــد بيــع العقــارات ثــم أفادنــا احملامــي بــأن املدعــى عليــه‬\n‫أنكــر أن للورثــة مبلــغ خمســمائة ألــف ريــال نطلــب ســؤاله عــن هذيــن‬\n‫املبلغــن الذيــن أقــر بهمــا للورثــة وإلزامــه بدفــع نصيبنــا منهــا هــذا مــا‬\n‫نطلبــه وال نريــد إحالتنــا حملاســب قانونــي فجرى إفهامهمــا بأن دعواهما‬\n‫هــي بطلــب محاســبته علــى مــا ذكــروا يف دعواهمــا فقــاال إننــا نقصــر‬\n‫دعوانــا علــى ســؤاله عــن األمريــن اللذيــن ذكرنــا وال نريــد محاســبته‬\n‫عــن بقيــة مــا ذكرنــا يف دعوانــا ألن منشــأ اخلــاف هــو إقــراره بهذيــن‬\n‫املبلغــن ثــم إنــكاره لذلــك ونحــن متنازلــون عــن مطالبتنــا مبحاســبته‬\n‫عــن دخــل العمائــر أمــا مبلــغ املائــة ألــف ريــال مــن أجــرة مطبــخ ‪...‬التــي‬\n‫ذكــر أخــو املدعــى عليــه ‪ ...‬أنــه ســلمها للمدعــى عليــه وأنكــر املدعــى‬\n‫عليــه اســتالمها مــن أخيــه فســنقدم بهــا دعــوى أخــرى علــى املدعــى عليــه‬\n‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب بــأن مــا ذكــره املدعــون قــد‬\n‫ســبق أن أجبــت عنــه يف اجللســة األولــى وهــو أن صحيــح أننــي أقريــت أن‬\n‫للورثــة مبلــغ تســعمائة وســبعة وثالثــن ألفـ ًا وثالثمائــة وثمانيــة وخمســن‬\n‫ريــا ًال ولــم أقــر بــأن لهــم يف ذمتــي إضافــة عليهــا مبلــغ خمســمائة ألــف‬\n‫ريــال وإمنــا ذكــرت أن لهــم مبلــغ خمســمائة ألــف ريــال هــي مــن ضمــن‬\n‫مبلــغ التســعمائة الــذي أقريــت بــه حيــث أن مبلــغ التســعمائة ألــف هــو‬\n‫عبــارة عــن مبلــغ خمســمائة وثمانيــة وثمانــن ألفـ ًا ومائتني وتســعة وســتني‬\n‫ريــا ًال عبــارة عــن جــزء منهــا خســائر يف األســهم حيــث كنــت وكي ـ ً‬\n‫ا‬\n‫عــن والــدي يف اســتثمار أموالــه التــي ســلمني وحصلــت خســارة يف‬\n‫األســهم فظننــت أنــي أحتمــل هــذه اخلســارة وعندما ســألت بعض املشــايخ‬\n‫قالــوا لــي إن اخلســارة ال تتحملهــا فحســمت منهــا هــذا املبلــغ الــذي هــو‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫عبــارة عــن خســارة األســهم وجــزء منــه مصاريــف علــى عائلــة والــدي‬\n      ‫وعالجــه أثنــاء مرضــه وباقــي مبلــغ التســعمائة وســبعة وثالثــن ألف ـ ًا‬\n      ‫وثالثمائــة وثمانيــة وخمســن ريــا ًال احتســبتها مــن املبالــغ التــي لهــم‬\n      ‫وســلمتها لهــم عــن طريــق احملامــي بعــد أن أصــدرت فيهــا شــيكات‬\n      ‫بنصيــب كل وارث مــن املبالــغ املســتحقة لهــم يف التركــة ولــم يبــق لهــم‬\n      ‫يف ذمتــي أي مبلــغ وبعــرض ذلــك علــى املدعيــن قــاال الصحيــح مــا‬\n      ‫ذكرنــاه وقــد أقــر يف مجلــس واحــد مببلــغ التســعمائة كمــا أقــر يف‬\n      ‫نفــس املجلــس بــأن للورثــة عليــه مبلغ ـ ًا آخــر هــو خمســمائة ألــف ريــال‬\n      ‫ممــا يــدل علــى أن مبلــغ اخلمســمائة ألــف ريــال غيــر مبلــغ التســعمائة‬\n      ‫ولدينــا مــا يثبــت ذلــك وهــو شــهود مــن غيــر الورثــة وســنحضرهم يف‬\n      ‫اجللســة القادمــة لــذا أفهمتهمــا بإحضــار جميــع مــا لديهمــا مــن بينــات‬\n      ‫علــى ذلــك وأن املدعــي قــد أقــر بهمــا يف مجلــس واحــد فاســتعدا لذلــك‬\n      ‫ثــم يف جلســة أخــرى حضــر املدعيــان أصالــة ووكالــة كمــا حضــر‬\n      ‫املدعــى عليــه وجــرى ســؤال املدعيــن عــن بينتهمــا علــى إقــراره مببلــغ‬\n      ‫اخلمســمائة ألــف ريــال إضافــة إلــى مبلــغ التســعمائة ألــف ريــال يف مجلــس‬\n      ‫واحــد فقــاال إن الشــهود غيــر متجاوبــن معنــا يف احلضــور وقــد أخذنــا‬\n      ‫خطابــات لهــم إلبالغهــم باحلضــور ولــم يتجاوبــوا وال نســتطيع إحضارهــم‬\n      ‫ويحتمــل أن املدعــى عليــه قــد طلــب منهــم عــدم التدخــل وليــس لدينــا بينة‬\n      ‫غيــر ذلــك وأضافــا بأنــه يف الســندات التــي أبرزهــا ســابق ًا ذكــر أن لديــه‬\n      ‫ســيولة مببلــغ تســعمائة ألــف ريــال وهــو موجــودة يف الســندات التــي‬\n      ‫أبرزهــا للقاســم ثــم جــرى ســؤال املدعــى عليه عــن املبالغ التي اســتثمرها‬\n      ‫يف األســهم ويف شــراء العمائــر هــل كانــت بــإذن مــن مورثــه فقــال إن‬\n      ‫املبالــغ التــي ســلمني والــدي والتــي طلــب منــي حتصيلهــا مــن رحيمنــا ‪.....‬‬\n\n\n‫‪349‬‬\n\f‫طلــب منــي والــدي اســتثمارها لــه وكان قــد أصــدر لــي وكالــة عامــة‬\n‫وطلــب منــي التصــرف مبوجبهــا وأبــرز أصــل الوكالــة العامــة الصــادرة‬\n‫مــن كتابــة عــدل املدينــة برقــم ‪ 26‬وتاريــخ ‪1418/11/04‬ه ـ واملتضمنــة‬\n‫توكيــل ‪ .....‬للمدعــى عليــه وكالــة عامــة وقــال إننــي اجتهــدت يف‬\n‫اســتثمارها واشــتريت ببعــض املبالــغ العمائــر التــي ذكــرت وذلــك يف‬\n‫حيــاة والــدي وســجلتها باســمه كمــا أنــي اجتهــدت يف اســتثمار املبالــغ‬\n‫املتبقيــة لــدي يف األســهم بنــاء علــى طلــب والــدي باســتثمار املبالــغ لــه‬\n‫واجتهــدت يف ذلــك وحصلــت اخلســارة يف بعضهــا كمــا ذكــرت وكنــت‬\n‫أظــن أننــي أحتملهــا وتبــن لــي أننــي ال أحتملهــا فحســمتها مــن املبلــغ‬\n‫الــذي ذكــرت أنــه للتركــة عنــدي وســلمت الباقــي للقاســم وقــد‬\n‫أحصيــت كل مــا للتركــة عنــدي وســلمته للقاســم وقســمه بينهــم ولــم‬\n‫يبــق لهــم عنــدي أي مبلــغ إال األجــارات اجلديــدة لعــام ‪1433‬ه ـ ومســتعد‬\n‫بتســليمها للقاســم هكــذا أجــاب ثــم يف جلســة أخــرى حضــر الطرفــان‬\n‫وجــرى محاولــة الصلــح بــن الطرفــن مراعــاة للرحــم بينهــم ومبــا يحفــظ‬\n‫ا فلــم يتفقــا علــى شــيء وطلبــا احلكــم يف القضيــة‬   ‫حــق القاصــر كامـ ً‬\n‫ثــم يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعــى عليــه عــن‬\n‫تفاصيــل املبلــغ الــذي أقــر بــه فقــال إن املبلــغ التســعمائة وســبعة وثالثــن‬\n‫ألــف ريــا ًال وثالثمائــة وثمانيــة وخمســن ريــا ًال الــذي أقريــت بــه وأنــه‬\n‫للتركــة يف ذمتــي وكنــت كتبتــه يف بعــض األوراق التــي قدمتهــا‬\n‫للقاســم لكــن تبــن لــي أن جــزء ًا مــن املبلــغ وقــدره خمســمائة وثمانيــة‬\n‫وثمانــون ألف ـ ًا ومائتــن وتســعة وســتني ريــا ًال غيــر صحيحــة وأنهــا ال‬\n‫تلزمنــي حيــث أن جــزء ًا منهــا خســائر يف األســهم واجلــزء اآلخــر نفقــات‬\n‫نقديــة كنــت أنفقتهــا علــى األســرة فجــرى ســؤاله عمــا يثبت هــذه املبالغ‬\n\n\n                                                                                      ‫‪350‬‬\n\f      ‫فقــال ليــس لــدي مــا يثبــت ذلــك والنفقــات كانــت نقديــة فجــرى ســؤاله‬\n      ‫كيــف يحتســب مبالــغ مــن التركــة وهــو يعلــم أنهــا نفقــات لألســرة ثــم‬\n      ‫يتبــن لــه فيمــا بعــد أنهــا غيــر داخلــة يف التركــة فقــال ألنهــا كانــت‬\n      ‫نفقــات نقديــة بــدون شــيكات لــذا فقــد احتســبتها للتركــة ألنــه ليــس‬\n      ‫لــدي مــا يثبتهــا ثــم تبــن أنــه ال يشــترط أن تكــون النفقــات مثبتــه لــذا‬\n      ‫جــرى حســمها مــن املبلــغ فجــرى ســؤاله عــن مقــدار املبالــغ التــي خســرها‬\n      ‫يف األســهم فقــال إننــي ال أعلــم مقدارهــا بالضبــط وقــد قدمــت كشــف‬\n      ‫حســاب حملفظــة األســهم ملكتــب محاســبة لبيــان مقــدار اخلســارة‬\n      ‫بالضبــط فجــرى ســؤاله كيــف احتســب مجمــوع اخلســائر يف األســهم‬\n      ‫والنفقــات باملبلــغ الــذي ذكــر وهــو ال يعلــم مقدراهــا بالضبــط فقــال‬\n      ‫إننــي احتســبت املبالــغ النقديــة املوجــودة لــدي واعتبــرت املتبقــي مــن‬\n      ‫املبلــغ خســائر يف األســهم ونفقــات علــى األســرة ولــم آخــذ لهــم ريــا ًال‬\n      ‫واحــد ًا وكان يجيــب علــى ذلــك بتــردد ويدعــي أنــه لــم يفهــم الســؤال‬\n      ‫هكــذا أجــاب ثــم يف جلســة أخــرى حضــر املدعــى عليهمــا أصالــة‬\n      ‫ووكالــة ‪ ..... .....‬كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ .....‬الوكيــل عــن ‪ .....‬مبوجــب الوكالــة الصــادرة من كتابة‬\n      ‫العــدل الثانيــة باملدينــة املنــورة برقــم ‪ 25883‬وتاريــخ ‪1433/4/11‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وحضــور اجللســات وإقامــة‬\n      ‫وســماع الدعــاوى واجلــرح والتعديــل وطلــب تقدمي البينات وســماع الشــهود‬\n      ‫واســتجوابهم والطعــن فيهــم واإلجابــة واملطالبــة بكافــة احلقــوق‬\n      ‫واســتالمها مبوجــب شــيكات مصدقــة باســمه وللوكيــل احلــق يف‬\n      ‫اســتئناف األحــكام ومتييزهــا والقناعــة بهــا واالعتــراض عليهــا وتقســيم‬\n      ‫تركــة والــده قســمة إجبــار أو قســمة تراضــي حســب مــا يتــم االتفــاق‬\n\n\n‫‪351‬‬\n\f‫عليــه شــرع ًا واتخــاذ كافــة مــا تقتضيــه إجــراءات التقاضــي والدفــاع‬\n‫عنــه يف أي دعــوى تقــام منــه أو ضــده وقــال املدعــى عليــه وكالــة إن‬\n‫الطرفــن إخــوان وأطلــب إعطائــي مهلــة حملاولــة جمــع الطرفــن وإجــراء‬\n‫احملاســبة بينهمــا ومحاولــة تقريــب وجهــات النظــر لــذا جــرى رفــع اجللســة‬\n‫لذلــك كمــا طلبــت مــن املدعــى عليــه تفصيــل املبالــغ التــي ســلمها‬\n‫موكلــه للقاســم وقســمت بــن الورثــة فاســتعد بذلــك لــذا رفعــت اجللســة‬\n‫لذلــك ثــم يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال الطرفــن عــن‬\n‫الصلــح فقــاال إنــه لــم يتــم االتفــاق علــى شــيء وجــرى ســؤال املدعــى عليــه‬\n‫وكالــة عــن تفاصيــل املبالــغ التــي ســلمها موكلــه للقاســم فأبــرز ورقــة‬\n‫مــدون فيهــا بيــان باملبالــغ الــواردة واملنصرفــة ومــن ضمنهــا مبلــغ أربعمائة‬\n‫وســتة وعشــرين ألفـ ًا ومائــة وتســعة وســتني ريــا ًال رصيد بعد وفــاة مورثهم‬\n‫وقــال املدعــى عليــه إن هــذا املبلــغ هــو املتبقــي مــن مبلــغ التســعمائة‬\n‫وســبعة وثالثــن ألــف ريــال التــي ســبق أن أقــر بهــا قبــل حســم خســائر‬\n‫األســهم والنفقــات وبعــد أن حســم خســائر األســهم والنفقــات التــي بلغــت‬\n‫مبلــغ خمســمائة وأحــد عشــر ألفـ ًا ومائــة وتســعة وثمانــن ريــال ســلم هــذا‬\n‫املبلــغ املتبقــي للقاســم ضمــن مبلــغ مليــون وســتمائة وخمســة آالف ريــال‬\n‫كانــت تشــمل هــذا املبلــغ واملبالــغ األخــرى التــي لديــه مــن إيجــارات‬\n‫العمائــر وبعــرض ذلــك علــى املدعــن قالــوا إن املدعــى عليــه أصالــة قــد‬\n‫ســبق أن أقــر مبوجــب تقريــر ســابق أن مبالــغ خســائر األســهم والنفقــات‬\n‫بلغــت مبلــغ خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة وســتني‬\n‫ريــا ًال وذلــك بعــد حســم جميــع املبالــغ التــي ســلمها وليــس كمــا ذكــر‬\n‫وقــد ذكــر ذلــك يف ســند قدمــه بتاريــخ ‪1432/05/26‬ه ـ بتوقيعــه‬\n‫ومرفــق باملعاملــة ونطلــب إلزامــه بدفــع هــذا املبلــغ وباالطالع على الســند‬\n\n\n                                                                                       ‫‪352‬‬\n\f      ‫املرفــق باملعاملــة وجــد كمــا ذكــر املدعــون وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه قــال ســأرجع ملوكلــي يف ذلــك وأجيبكــم عــن ذلــك يف اجللســة‬\n      ‫القادمــة ثــم يف جلســة أخــرى حضــر املدعــون أصالــة ووكالــة ‪..... .....‬‬\n      ‫ابنــي ‪ .....‬كمــا حضــر املدعــي أصالــة مجــدي ‪ .....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وحضــر املدعــى عليــه وكالــة وجــرى‬\n      ‫ســؤال املدعــى عليــه وكالــة عمــا ذكــره املدعــون مــن إقــرار بأنــه حســم‬\n      ‫مبلــغ خمســمائة وثمانيــة وثمانــن ألفـ ًا ومائتــن وتســعة وســتني ريــا ًال مــن‬\n      ‫املبلــغ الــذي ســبق أن أقــر بــه فقــال إننــي رجعــت ملوكلــي وأفادنــي بأنــه‬\n      ‫حســم مبلــغ خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة وســتني‬\n      ‫ريــا ًال مــن مبلــغ التســعمائة ألف ـ ًا وســبعة وثالثــن ألف ـ ًا ومائتــن وثمانيــة‬\n      ‫وخمســن ريــا ًال الــذي ســبق أن أقــر بــه وباقــي املبلــغ ســلمه ‪ .....‬وقســم بــن‬\n      ‫الورثــة وبعــرض ذلــك علــى املدعــن قالــوا إننــا وموكلينــا نطالــب بهــذا‬\n      ‫املبلــغ الــذي حســمه ليدفــع للتركــة ويقســم بــن الورثــة حســب ميراثهــم‬\n      ‫الشــرعي وال نقبــل برجوعــه عــن إقــراره ونطلــب ميينــه علــى تســليمه‬\n      ‫لباقــي املبلــغ للقاســم وعلــى أنــه لــم يقــر مببلــغ خمســمائة ألــف ريــال‬\n      ‫أخــرى إضافــة إلــى مبلــغ التســعمائة وســبعة وثالثــن ألف ـ ًا ومائتــن‬\n      ‫وثمانيــة وخمســن ريــا ًال والتــي ســبق أن أنكرهــا وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال موكلــي مســتعد باليمــن التــي طلبهــا املدعــون لــذا‬\n      ‫طلبــت إحضــار موكلــه يف اجللســة القادمــة ثــم يف جلســة أخــرى حضــر‬\n      ‫املدعــون أصالــة ووكالــة كمــا حضــر املدعــى عليــه أصالــة وقــد جــرى‬\n      ‫االطــاع علــى صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 1/100/389‬وتاريــخ ‪1429/02/20‬ه ـ املتضمــن وفــاة ‪.....‬‬\n      ‫‪1429/02/14‬ه ـ وانحصــار إرثــه يف زوجاتــه ‪ .....‬و‪ .....‬و‪ .....‬ويف أوالده‬\n\n\n‫‪353‬‬\n\f‫‪..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... .....‬‬\n‫‪ ..... ..... ..... ..... .....‬بالغــون مــا عــدا ‪ .....‬معــاق عقلي ـ ًا وبعــرض اليمــن‬\n‫ا واهلل‬   ‫التــي طلبهــا املدعــون علــى املدعــى عليــه اســتعد بهــا ثــم حلــف قائـ ً‬\n‫العظيــم الــذي ال إلــه إال هــو إن املبلــغ الــذي ســبق أن أقريــت بــه للتركــة‬\n‫وقــدره تســعمائة وســبعة وثالثــن ألف ـ ًا ومائتــن وخمســن ريــا ًال قــد‬\n‫ســلمته ‪ .....‬ليقســمه بــن املســتحقني بعــد حســم خســائر االســهم‬\n‫والنفقــات وقدرهــا خمســمائة وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة‬\n‫وســتني ريــا ًال كمــا أننــي لــم أقــر مببلــغ خمســمائة ألــف ريــال زيــادة علــى‬\n‫مبلــغ التســعمائة وســبعة وثالثــن ألــف ومائتــن وثمانيــة وخمســن ريــا ًال‬\n‫وإمنــا هــي داخلــة فيــه واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى مــا ذكــره‬\n‫املدعــون مــن أنــه ســبق أن أقــر أن للورثــة يف ذمتــه مبلــغ تســعمائة وســبعة‬\n‫وثالثــن ألف ـ ًا ومائتــن وثمانيــة وخمســن ريــا ًال ثــم رجــع عــن إقــراره‬\n‫وذكــر بــأن جــزء ًا مــن املبلــغ خســائر يف األســهم ونفقــات نقديــة علــى‬\n‫الورثــة لــم يحســمها وقــد حســمها مــن املبلــغ وســلم الباقــي للقاســم‬\n‫وأنكــر إقــراره مببلــغ خمســمائة ألــف ريــال زيــادة علــى هــذا املبلــغ الــذي‬\n‫أقــر بــه وألن الرجــوع عــن اإلقــرار يف حقــوق اآلدمــي غيــر معتبــر عنــد‬\n‫عامــة أهــل العلــم ألن اإلقــرار مظهــر حلــق موجــود قبــل صــدوره وليــس‬\n‫منشــئ ًا حلــق لــم يكــن موجــود ًا وألن حقــوق العبــاد مبينــة علــى املشــاحة‬\n‫وملــا قــرره املدعــى عليــه عنــد ســؤاله مــن عــدم معرفتــه ملقــدار اخلســائر‬\n‫والنفقــات وعــدم اســتطاعته لتبيينهــا ممــا يؤكــد عــدم صحــة مــا ذكره‬\n‫مــن ســبب رجوعــه عمــا أقــر بــه إضافــة إلــى أن مــا ذكــره مــن مبــرر‬\n‫للرجــوع عــن اإلقــرار ال يقبــل مــن مثلــه ألن ذلــك ال يخفــى علــى مثلــه عــادة‬\n\n\n                                                                                                              ‫‪354‬‬\n\f      ‫ولطلــب املدعــن ميــن املدعــى عليــه بتســليمه لباقــي املبلــغ الــذي أقــر بــه‬\n      ‫للقاســم بعــد حســمه للمبلــغ الــذي ذكــر وعلــى نفــي إقــراره مببلــغ‬\n      ‫خمســمائة ألــف ريــال للورثــة زيــادة علــى مبلــغ التســعمائة وســبعة وثالثــن‬\n      ‫ألف ـ ًا ومائتــن وثمانيــة وخمســن ريــا ًال وحللــف املدعــى عليــه اليمــن‬\n      ‫املطلوبــة لــذا فقــد أفهمــت املدعــى عليــه أنــه يلزمــه دفــع مبلــغ خمســمائة‬\n      ‫وثمانيــة وثمانــن ألف ـ ًا ومائتــن وتســعة وســتني ريــا ًال لتقســم بــن جميــع‬\n      ‫ورثــة ‪ .....‬بالوجــه الشــرعي وصرفــت النظــر عــن مطالبــة الورثــة بباقــي‬\n      ‫املبلــغ املدعــى بــه بعــد حلــف املدعــى عليــه اليمــن املطلوبــة ومبــا تقــدم‬\n      ‫حكمــت وبعــرض ذلــك علــى الطرفــن أبــدى املدعــون قناعتهــم باحلكم‬\n      ‫أمــا املدعــى عليــه فلــم يقنــع باحلكــم وطلــب التمييــز وأجيــب لطلبــه‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                             ‫حرر يف ‪1433/07/08‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ‬\n      ‫افتتحت اجللســة وفيها حضر الطرفان وقد وردتنا املعاملة من محكمة‬\n      ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 33396939‬وتاريــخ ‪1433/8/28‬ه ـ‬\n      ‫املتضمــن مالحظــة أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة الثالثــة‬\n      ‫مايلــي‪ -1:‬اجلهــل مــن املدعــى عليــه فيمــا ذكــره يف محلــه فينبغــي‬\n      ‫مالحظــة ذلــك ‪ -2‬ذكــر املدعــى عليــه بوجــود اتفــاق مرفــق صورتــه‬\n      ‫وأن املدعــن أقــروا بأمانتــه فيتــم عــرض ذلــك علــى األطــراف وال يخفــى‬\n      ‫علــى فضيلتــه بــأن القــول قــول األمــن علــى ميينــه وعلــى فضيلتــه بــذل‬\n      ‫اجلهــد يف عــرض الصلــح بــن الطرفــن وال ســيما يف دعــوى عائليــة وعليــه‬\n      ‫أجيــب أصحــاب الفضيلــة بأنــه جــرى ســؤال املدعــى عليــه عمــا يذكــر‬\n      ‫مــن وجــود اتفــاق بــن الورثــة وأن املدعــن أقــروا بأمانــة موكلــه فقــال‬\n\n\n‫‪355‬‬\n\f‫نعــم يوجــد اتفــاق بــن موكلــي وبــن املدعــن بخصــوص التركــة وأبــرز‬\n‫صــورة اتفــاق مكونــة مــن ورقتــن بــن أبنــاء ‪ .....‬وقــال جــاء يف البنــد‬\n‫ا‬\n‫الثالــث مــا يلــي األخ ‪ .....‬كان والزال هــو األخ األكبــر وكان وكيـ ً‬\n‫لوالدنــا ومحــل ثقتــه ونحــن كذلــك نثــق فيــه ويف أمانتــه وعلــى ذلــك فهــو‬\n‫املســئول األول عــن حصــر التركــة يف احملكمــة ويتــم احلصــر يف مــدة‬\n‫أقصاهــا أســبوع مــن تاريــخ الورقــة وأضــاف بــأن هــذا يثبــت أن إخــوان‬\n‫موكلــي املدعــن شــهدوا لــه باألمانــة والثقــة خــال حيــاة والــده وبعــد‬\n‫وفاتــه فكيــف يتهمونــه بعــد ذلــك كمــا أنــه اســتعد بإجــراء احملاســبة‬\n‫لكنهــم رفضــوا ذلــك وبعــرض ذلــك علــى املدعــن قالــوا إن مــا جــاء يف‬\n‫الســند غيــر صحيــح والتوقيــع الــذي عليــه ليــس توقيعنــا كمــا أنــه لــم‬\n‫يحضــره طــوال اجللســات املاضيــة ممــا يــدل علــى عــدم صحتــه واملدعــي‬\n‫حــاول بعــد وفــاة مورثنــا توقيعنــا علــى أوراق باستشــارة محامــن ُليخــرج‬\n‫نفســه مــن أي محاســبة علــى أمــوال والــدي كمــا أنــه كان يتصــرف‬\n‫بأمــوال والــدي مــع أن والــدي كان يف غيبوبــة تامــة قبــل وفاتــه بأربــع‬\n‫ســنوات وكنــا نطلــب منــه عــدم التصــرف إال بعــد إقامتــه ولــي ولــم‬\n‫يســتجب لذلــك كمــا أنــه لــم يعــط الورثــة نصيبهــم مــن التركــة إال‬\n‫بعــد أن تقدمنــا بدعــوى عليــه يف احملكمــة إللزامــه بذلــك مــع وجــود‬\n‫ا يف الورثــة ومعــاق وســتة مــن إخوانــي بــدون وظيفــة أو‬    ‫قصــار ســن ًا وعقـ ً‬\n‫عمــل وتعمــد تــرك عشــرين شــقة مــن التركــة بــدون تأجيــر طــوال املــدة‬\n‫املاضيــة إضــرار ًا بالورثــة ألنــه وأشــقائه موظفــن بوظائــف كبيــرة وغيــر‬\n‫محتاجــن للتركــة كمــا أنــه جــاء يف البنــد األول مــن الســند املذكــور‬\n‫املصادقــة علــى الكشــوفات املقدمــة منــه وعددهــا خمــس أوراق وذكــر‬\n‫أنــه ال خــاف فيهــا وهــي التــي اســتند عليهــا يف إثبــات املبلــغ املدعــى بــه‬\n\n\n                                                                                        ‫‪356‬‬\n\f      ‫واآلن يرجــع عــن مبلــغ تســعمائة ألــف ريــال منهــا ويدعــي أنهــا خســارة‬\n      ‫يف األســهم فكيــف يقبــل منــه ذلــك كمــا جــرت محاولــة الصلــح بــن‬\n      ‫الطرفــن ومحاولــة تقريــب وجهــات النظــر وتذكيرهم بعظم حق الرحم‬\n      ‫فأصــر املدعيــان علــى احلكــم يف القضيــة وأن هــذا حــق للورثــة وفيهــم‬\n      ‫قصــار ولــم يتــم االتفــاق علــى شــيء أمــا مــا ذكــره أصحــاب الفضيلــة يف‬\n      ‫املالحظــة األولــى فاملدعــى عليــه متعلــم ومثلــه ال يعــذر باجلهــل يف مثــل مــا‬\n      ‫ذكــر خاصــة وأنــه لــم يبــن أي مســتند صالــح حلســم املبلــغ احملكــوم‬\n      ‫بــه والــذي ســبق أن أقــر بــه للتركــة ومــا ذكــره إمنــا هــي أمــور مجملــة ال‬\n      ‫ـزاء‬\n       ‫تســتند علــى أي حســابات أو مســتندات تثبــت ذلــك بــل ذكــر أن جـ ً‬\n      ‫كبيــر ًا منــه خســارة يف األســهم مــع عــدم وجــود أي حســابات لديــه تثبــت‬\n      ‫وجــود خســارة يف األســهم مــن عدمهــا ومقــدار اخلســارة إن وجــدت أمــا‬\n      ‫مــا ذكــره أصحــاب الفضيلــة مــن أن القــول قــول األمــن مــع ميينــه فــا‬\n      ‫يخفــى أن ذلــك يف حــال عــدم وجــود بينــة تثبــت خــاف ذلــك وهــي هنــا‬\n      ‫إقــراره الصريــح باســتحقاق التركــة للمبلــغ احملكــوم بــه عليــه فــا‬\n      ‫يقبــل رجوعــه بعــد مــدة عنــه إال ببينــة تثبــت ذلــك ولــم ُيحضــر املدعــي‬\n      ‫مــا يثبــت ذلــك لــذا لــم يظهــر لــي خــاف مــا حكمــت بــه وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                        ‫‪1433/11/1‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم األربعــاء املوافــق ‪1434/01/28‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر الطرفان وقــد عادت املعاملة من محكمة‬\n      ‫االســتئناف وبرفقهــا القــرار الصــادر مــن الدائــرة احلقوقيــة الثالثــة يف‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة رقــم ‪33473659‬‬\n      ‫وتاريــخ ‪1433/12/20‬ه ـ املتضمــن أنــه بدارســة احلكــم وصــورة ضبطــه‬\n\n\n‫‪357‬‬\n\f‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلتــه ملالحظــة أن مــا أجــاب بــه‬\n                   ‫عــن الفقــرة (‪ )2‬مــن قــرار محكمــة االســتئناف غيــر مـ ٍ‬\n‫ـوف ملــا طلــب منــه‬\n‫إذ نقــدر لفضيلتــه مــا أجــاب بــه إال أن مــا ذكــره املدعــى عليــه نحــو هــذا‬\n‫املبلــغ وســبب اإلقــرار بــه ثــم رجوعــه وادعائــه اخلســارة ومــا ذكــره مــن‬\n‫مصروفــات علــى العائلــة هــو محــل تأمــل فيتوجــه العــرض بذلــك علــى‬\n‫املدعيــن والتحقــق مــن حصــول اخلســارة يف هــذه األســهم بطلــب كشــف‬\n‫للمحفظــة وطلــب بيــان للمصروفــات العائليــة مــن نفقــات أو عــاج والــده‬\n‫وإذا تعــذر ذلــك فيرجــع فيــه للعــرف حــال مصادقــة املدعــن علــى بذلــه‬\n‫لهــذه النفقــات العائليــة والعــاج وإجــراء مــا يلــزم نحــوه حتري ـ ًا للحــق‬\n‫ـراء للذمــة إلكمــال الــازم اه ـ وعليــه أجيــب أصحــاب الفضيلــة‬        ‫وإبـ ً‬\n‫بأنــه جــرى محاولــة الصلــح بــن الطرفــن فلــم يتفقــا علــى شــيء وقــال‬\n‫املدعيــان إن رجــوع املدعــي عــن إقــراره ال يقبــل منــه وقــد أقــر إقــرار ًا‬\n‫تام ـ ًا باملبلــغ ومــا ذكــره مــن ســبب رجوعــه عــن اإلقــرار وأنــه بســبب‬\n‫عــدم احتســابه نفقــات فــا نوافــق عليــه ألنــه حســب حســاباته املفصلــة‬\n‫التــي أبرزهــا واملرفقــة باملعاملــة قــد صــرف مــا يزيــد علــى مبلــغ مليــون‬\n‫وخمســمائة ألــف ريــال مصاريــف للعائلــة مبوجــب شــيكات قبــل وفــاة‬\n‫والــدي فكيــف يزيــد علــى ذلــك بعــد هــذه احلســابات ويدعــي أن هنــاك‬\n‫مبلــغ مائــة ألــف ريــال زيــادة وهــو ال يصــرف شــيء إال بشــيك كمــا أن مــا‬\n‫يدعيــه مــن خســارة األســهم لــم يثبــت ذلــك ولــم يخــرج كشــف بهــا وقــد‬\n‫ســبق أن طلبتــم منــه ذلــك عــدة مــرات ولــم يحضــر ذلــك ويعتــذر بأعــذار‬\n‫كثيــرة وســبب رجوعــه عــن إقــراره هــو بســبب تقدمنــا بطلــب القســمة‬\n‫عــن طريــق احملكمــة وهــو كان يريــد أن تتــم خــارج احملكمــة وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قــال إن النفقات املذكورة يف احلســابات املرفقة‬\n\n\n                                                                                      ‫‪358‬‬\n\f      ‫باملعاملــة هــي املصروفــة مبوجــب شــيكات أمــا مبلــغ املائــة ألــف فقــد‬\n      ‫صــرف نقــد ًا بــدون شــيكات كمــا ســأعرض علــى موكلــي إحضــار ما‬\n      ‫يثبــت اخلســارة يف األســهم بكشــف مــن محاســب قانونــي مــن أول إيــداع‬\n      ‫املبالــغ العائــدة ملورثهــم يف احملفظــة وحتــى قســمة التركــة لــذا طلبــت‬\n      ‫منــه إحضــار مــا يثبــت ذلــك يف اجللســة القادمــة وعــدم املماطلــة يف ذلــك‬\n      ‫فاســتعد بذلــك ثــم يف جلســة أخــرى حضــر املدعيــان أصالــة ووكالــة‬\n      ‫كمــا حضــر املدعــى عليــه وكالــة وجــرى ســؤاله عمــا يثبــت اخلســارة يف‬\n      ‫األســهم فقال إن موكلي اســتخرج كشــف حســاب للمحفظة من تاريخ‬\n      ‫إنشــائها وحتــى هــذا اليــوم وقدمــه حملاســب قانونــي اســمه شــركة ‪.....‬‬\n      ‫وشــركاؤه وقــد طلــب احملاســب مهلــة شــهر ونصــف إلجــراء احملاســبة‬\n      ‫والتأكــد مــن وجــود الربــح أو اخلســارة وأطلــب إعطائــي مهلــة إلحضــار‬\n      ‫ذلــك فجــرى إفهامــه بأنــه ســبق أن قــرر موكلــه يف اجللســات املاضيــة أنــه‬\n      ‫قــدم كشــف حســاب للمحفظــة حملاســب قانونــي ولــم يحضــر مــا يثبــت‬\n      ‫ذلــك حتــى تاريخــه فقــال أطلــب إعطائــي هــذه املهلــة األخيــرة إلحضــار‬\n      ‫ذلــك فجــرى ســؤاله هــل احملفظــة خاصــة مبورثــه أم لــه فيهــا مبالــغ فقــال‬\n      ‫إننــي بعــد ســؤال موكلــي ذكــر لــي أنــه افتتــح احملفظــة مببلــغ ثالثمائــة‬\n      ‫ألــف ريــال خاصــة بــه ثــم أودع بعــد ذلــك مبلــغ ســتمائة ألــف ريــال مــن‬\n      ‫مبالــغ لوالــده وكان موكلــي يســحب مــن احملفظــة مبالــغ ويــودع أخــرى‬\n      ‫بعــد ذلــك وســأحضر مــا يثبــت اخلســارة يف اجللســة القادمــة ثــم يف جلســة‬\n      ‫أخــرى حضــر الطرفــان وجــرى ســؤال املدعــى عليــه عمــا يثبــت خســارة‬\n      ‫موكلــه يف األســهم فقــال إن احملاســب القانونــي رفــض إجــراء احملاســبة‬\n      ‫إال مببلــغ مائــة وعشــرين ألــف ريــال ورفــض موكلــي ذلــك الرتفــاع املبلــغ‬\n      ‫وقــد قمــت بإعــداد بيــان مــن ثــاث صفحــات بإجمالــي القيمــة املدفوعــة‬\n\n\n‫‪359‬‬\n\f‫للشــراء وعمــوالت البيــع وإجمالــي القيمــة احملصلــة مــن نتــاج بيــع األســهم‬\n‫فوجــدت أن هنــاك خســارة تعــادل مبلــغ أربعمائــة وثالثــة وعشــرين ألف ـ ًا‬\n‫وأربعمائــة وخمســة وعشــرين ريــا ًال وأربعــة وســتني هللــة وبهــذا يتبــن أن‬\n‫اخلســارة التــي ذكرهــا موكلــي صحيحــة وبعــرض ذلــك علــى املدعيــن‬\n‫قــاال إن هنــاك مبالــغ يف كشــف احلســاب الــذي ســبق أن أحضــره لــم‬\n‫تذكــر يف حركــة البيــع والشــراء باإلضافــة إلــى حــواالت كثيــرة لــم‬\n‫ا يف اجللســة القادمــة ومــا ذكــره مــن‬   ‫يشــر إليهــا وســنحضر ذلــك مفصـ ً‬\n‫حســابات ال نوافــق عليهــا ألنهــا ليســت مــن محاســب قانونــي وقــد ســبق‬\n‫أن التــزم بإحضــار مــا يثبــت ذلــك مــن محاســب قانونــي هكــذا قــررا ثــم‬\n‫يف جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعــن عمــا لديهمــا‬\n‫حيــال البيــان الــذي أبــرزه املدعــى عليــه يف اجللســة املاضيــة فقــاال إن بيــان‬\n‫املدعــى عليــه غيــر صحيــح ومخالــف للحقيقــة حســب كشــف حركــة‬\n‫احملفظــة حيــث بإجرائنــا محاســبة للمحفظــة تبــن أن يف احملفظــة‬\n‫أربــاح مببلــغ مليــون وســبعمائة وواحــد وخمســن ألف ـ ًا وأربعمائــة ريــال‬\n‫عبــارة عــن أربــاح مت ســحبها مــن احملفظــة مــن قبــل املدعــى عليــه ولــم‬\n‫يذكرهــا وبرفقــه بيــان مفصــل بهــا وبتأريخهــا ورقــم الصفحــة التــي‬\n‫تثبتهــا يف كشــف احلســاب وأبــرزا بيان ـ ًا مــن ورقتــن جــرى إرفاقــه‬\n‫باملعاملــة إضافــة إلــى ملحقــات صــور لهــذه املبالــغ يف كشــف احلســاب‬\n‫كمــا أضافــا بــأن البيــان الــذي أبــرزه املدعــى عليــه قــد أغفــل كثيــر ًا‬\n‫مــن احلــركات التــي متــت علــى احملفظــة وقــد بينــا بعض ـ ًا منهــا وأبــرزا‬\n‫بيان ـ ًا مــن ورقــة واحــدة موضــح فيــه املبلــغ والصفحــة التــي تشــير إليــه‬\n‫يف كشــف احلســاب وقــاال إن هــذا يبــن محاولــة املدعــى عليــه إخفــاء‬\n‫احلقيقــة كمــا أرفقــا صــور ًا مــن كشــف احلســاب مبــا يثبــت هــذه‬\n\n\n                                                                                         ‫‪360‬‬\n\f      ‫احلــركات كمــا أضافــا بــأن بيــان املدعــى عليــه فيــه أخطــاء كثيــرة‬\n      ‫وغيــر مطابــق ملــا جــاء يف كشــف احلســاب وأبــرزا بيانـ ًا مــن ورقــة واحــدة‬\n      ‫يوضــح األخطــاء املذكــورة يف املبالــغ ومــا يشــير إلــى أرقــام صفحاتهــا‬\n      ‫وصــور ًا مــن الصفحــة يف كشــف احلســاب وقــاال إن هــذا يوضــح ســبب‬\n      ‫رفــض املدعــى عليــه إحضــار تقريــر مــن محاســب قانونــي يثبــت اخلســارة‬\n      ‫ومحاولــة االيهــام باخلســارة بالبيــان الــذي أحضــره والــذي يخالــف‬\n      ‫احلقيقــة كمــا أوضحنــا وإن كل ذلــك محاولــة منــه إلنــكار مــا ســبق‬\n      ‫أن أثبتــه وأقــر بــه وحــاول الرجــوع عنــه عنــد اختالفنــا معــه ونحتفــظ‬\n      ‫بحقنــا مبطالبتــه باألربــاح التــي متــت علــى األســهم والتــي حــاول إخفاءهــا‬\n      ‫يف دعــوى مســتقلة وبعــرض ذلــك علــى املدعــى عليــه قــال إن مــا ذكــره‬\n      ‫املدعيــان مــن وجــود ســحوبات مــن موكلــي مــن احملفظــة فصحيــح وهــي‬\n      ‫أكثــر مــن املبلــغ الــذي ذكــراه حيــث ســحب مــن احملفظــة مبلــغ مليــون‬\n      ‫وثمامنائــة وأربعــة وســبعني ألف ـ ًا وأربعمائــة ريــال لكنــه يف املقابــل أودع‬\n      ‫مبالــغ يف احملفظــة تزيــد علــى مليونــن ومائــة ألــف ريــال مــع أن رأس‬\n      ‫املــال الــذي اســتثمره يف احملفظــة ال يتجــاوز ســتمائة ألــف ريــال ممــا‬\n      ‫يــدل علــى أن موكلــي أعــاد يف احملفظــة املبالــغ التــي ســحبها فجــرى‬\n      ‫ســؤاله عــن باقــي املالحظــات فقــال إنهــم اعتمــدوا علــى كشــف حســاب‬\n      ‫آخــر ســبق أن أحضــره موكلــي مــن البنــك وهــو غيــر الكشــف الــذي‬\n      ‫أحضــره موكلــي أخيــر ًا مــن البنــك والــذي ســحب مــن املقــر الرئيســي‬\n      ‫يف الريــاض وترتيــب الكشــفني يختلــف ممــا أحــدث املالحظــات التــي‬\n      ‫يذكرونهــا فجــرى إفهامــه بــأن تاريــخ كل حركــة ذكروهــا يحــدد‬\n      ‫مكانهــا فقــال إن الكشــف الــذي اعتمــدوا عليــه غيــر الكشــف الــذي‬\n      ‫لــدي ولــم أطلــع علــى كشــفهم الــذي ذكــروا هكــذا قــرر وبعــرض‬\n\n\n‫‪361‬‬\n\f‫ذلــك علــى املدعيــن قــاال إن املبالــغ التــي ســحبها مــن احملفظــة هــي غيــر‬\n‫حركــة البيــع والشــراء التــي تتــم داخــل احملفظــة وســحبه لهــا وإخراجهــا‬\n‫مــن احملفظــة دليــل علــى صرفــه للمبلــغ واملبالــغ التــي يذكــر أنــه أودعهــا‬\n‫تــدل علــى أن رأس املــال املــودع يف احملفظــة ليــس كمــا ذكــر وهــو‬\n‫مبلــغ ســتمائة ألــف ريــال بــل يــدل علــى أنــه أكثــر مــن ذلــك بكثيــر‬\n‫وأنــه يســحب مــن احملفظــة مبالــغ متــى أراد كمــا أنــه ال حاجــة ألن‬\n‫يســحب مبالــغ كبيــرة ثــم يودعهــا ألن املضاربــة بهــا تتــم وهــي باقيــة يف‬\n‫احملفظــة دون ســحب كمــا أن الســحوبات واإليداعــات لــم يذكرهــا يف‬\n‫الكشــف الــذي أحضــره يف اجللســة املاضيــة وبعــرض ذلــك علــى املدعــى‬\n‫عليــه قــال إن الكشــف الــذي أحضرتــه هــو بحــركات البيــع والشــراء‬\n‫فقــط ولــم أتطــرق للســحوبات وااليداعــات كمــا أضــاف املدعيــان أن‬\n‫ســحوبات املدعــى عليــه متــت بعــد دخــول مورثنــا يف غيبوبــة تامــة منــذ عــام‬\n‫‪2006‬م حســب التقاريــر الطبيــة حيــث بقــي يف غيبوبــة ملــدة عامــن ثــم‬\n‫تــويف وكثيــر مــن الســحوبات متــت بعــد هــذا التاريــخ وبعــرض ذلــك علــى‬\n‫املدعــى عليــه وكالــة قــال إن مــورث الطرفــن كان مقعــد ًا فقــط ولــم‬\n‫يكــن يف غيبوبــة إال يف الشــهرين األخيريــن تقريبـ ًا قبــل وفاتــه وبعــرض‬\n‫ذلــك علــى املدعيــن قــاال إن التقريــر الطبــي املرفــق باملعاملــة والصــادر‬\n‫مــن مستشــفى املدينــة يثبــت أنــه كان يف غيبوبــة منــذ دخولــه املستشــفى‬\n‫بتاريــخ ‪ 31‬ينايــر ‪2006‬م وأن تغذيتــه تتــم عــن طريــق أنبــوب مــن األنــف‬\n‫إلــى املعــدة وأن نســبة الوعــي ‪ 15/10‬كمــا أن مــوكل املدعــى عليــه‬\n‫مقــر بذلــك يف الكشــوفات التــي أحضرهــا هكــذا قــررا فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ولعــدم إحضــار املدعــى عليــه مــا يثبــت‬\n‫مــا يدعيــه مــن خســارة مــع وعــده بإحضــار ذلــك مــن محاســب قانونــي ثــم‬\n\n\n                                                                                      ‫‪362‬‬\n\f      ‫رجوعــه عــن ذلــك وملــا ذكــر بعاليــه مــن مــداوالت بــن الطرفــن تنفــي‬\n      ‫مــا يذكــره املدعــى عليــه مــن وجــود خســارة لــذا لــم يظهــر لــي خــاف‬\n      ‫مــا حكمــت بــه وليــس لــدي ســواه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/02‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة العامــة باملدينــة املنــورة والقائــم بعمــل‬\n      ‫املكتــب القضائــي الثانــي ففــي يــوم الثالثــاء املوافــق ‪1434/10/13‬ه ـ‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار الصــادر‬\n      ‫مــن الدائــرة احلقوقيــة الثالثــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة رقــم ‪ 34312231‬وتاريــخ ‪1434/09/03‬ه ـ املتضمــن مــا نصــه‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى منــا‬\n      ‫نحــن رئيــس الدائــرة الثالثــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة االطــاع علــى هــذا الصــك الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n      ‫القاضــي باحملكمــة العامــة باملدينــة املنــورة املســجل بعــدد ‪ .....‬وتاريــخ‬\n      ‫‪1433/07/09‬ه ـ املتضمــن دعــوى ع‪ .....‬أصالــة ووكالــة ضــد ‪.....‬‬\n      ‫يف تركــة‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق اه ـ‬\n      ‫قاضــي اســتئناف ‪ .....‬قاضــي اســتئناف ‪ .....‬رئيــس الدائــرة ‪ .....‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                                 ‫يف ‪1434/10/13‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم اخلميــس املوافــق ‪1434/11/06‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي ‪ .....‬وقــرر أنــه اســتلم مــن املدعــى‬\n      ‫عليــه ‪ .....‬مبلــغ مائــة وأربعــة وعشــرون ألف ـ ًا وتســعمائة وأربعــة وســبعون‬\n\n\n‫‪363‬‬\n\f‫ريــا ًال وســبع وثالثــون هللــة مــن املبلــغ احملكــوم بــه مبوجــب الشــيك‬\n‫املســحوب علــى بنــك ‪ .....‬برقــم ‪ 294498‬وتاريــخ ‪2013/08/27‬م وأنــه‬\n‫لــم يبــق لــه بذمــة املدعــى عليــه بخصــوص هــذه القضيــة أي شــيء وبهــذا‬\n‫تكــون الدعــوى منتهيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/11/06‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم يف يــوم االثنــن املوافــق ‪1434/11/10‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي ‪ .....‬وقــرر أنــه اســتلم مــن املدعــى‬\n‫عليــه ‪ .....‬مبلــغ مائتــن وخمســة وعشــرين ألفـ ًا وثالثمائــة وثالثــة وثمانــن‬\n‫ريــا ًال وتســعة وثمانــن هللــة مــن املبلــغ احملكــوم بــه مبوجــب الشــيك‬\n‫املســحوب علــى بنــك ‪ .....‬برقــم ‪ 294497‬وتاريــخ ‪2013/08/27‬م وأنــه‬\n‫لــم يبــق لــه وملوكليــه بذمــة املدعــى عليــه بخصــوص هــذه القضيــة أي‬\n‫شــيء وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم حــرر يف ‪1434/11/10‬هــ‪.‬‬\n\n\n\n\n                                                                                     ‫‪364‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":339,"source_page_end":364,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14925807a2b390394509e67a6b9b74e94fe47e8aa9e431781546c6438f6f7b92","normalized_text_hash":"873075aa555fd36bd56d6db0289e43fea97603b383ccf61d96e07580648f6260","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p339-33334176"},{"id":"b1c26d4e-5d92-5708-9f64-45959ba60e64","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وصية لبعض الورثة -ال وصية لوارث -ال يض ما زاد على ثلث التركة إال بإذن الورثة.","document_number":"33363338","case_number":"32322052","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/30","year":"1434","subject":"قسمة تركة -وصية لبعض الورثة -ال وصية لوارث -ال يض ما زاد على ثلث التركة إال بإذن الورثة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33363338 :‬تاريخه‪1433/7/30 :‬هـ‬\n                        ‫رقم الدعوى‪32322052 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34233526‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n      ‫قســمة تركــة ‪ -‬وصيــة لبعــض الورثــة ‪ -‬ال وصيــة لــوارث ‪ -‬ال ُيــض مــا‬\n                                        ‫زاد علــى ثلــث التركــة إال بــإذن الورثــة‪.‬‬\n\n\n\n                             ‫‪ .1‬قوله صلى اهلل عليه وسلم (ال وصية لوارث)‪.‬‬\n      ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم يف شــأن مــن أراد الوصيــة (الثلــث والثلث‬\n                                                                          ‫كثير)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليهــم بــأن مورثهــم خلــف عمــارة واســتراحة‬\n      ‫باعهــا أحــد املدعــى عليهــم مبائــة وخمســة عشــر ألــف ريــال وأربــع‬\n      ‫ســيارات تالفــة بيعــت بعشــرة آالف وتســعمائة ريــال ويطلــب ببيــع العمــارة‬\n      ‫وتســليم كل وارث نصيبــه الشــرعي‪ ،‬أجــاب املدعــى عليهــم باملصادقــة‬\n      ‫علــى الدعــوى وعــدم ممانعتهــم ببيعهــا وعلــى بيــع الســيارات واالســتراحة‬\n      ‫باملبالــغ املشــار إليهــا يف الدعــوى ومت توزيعهــا علــى الورثــة‪ ،‬وقــد أجابــت‬\n      ‫زوجــة مورثهــم بعــدم املوافقــة علــى بيــع العمــارة ألن املــورث أوصــى بهــا‬\n      ‫لبعــض الورثــة‪ ،‬اعتــرض املدعــي علــى الوصيــة ألن فيهــا جــور وصــادق‬\n      ‫علــى توزيــع قيمــة الســيارات واالســتراحة‪ ،‬قــرر املدعــي واملدعــى عليهــم‬\n      ‫بــأن البيــت ميثــل غالــب التركــة‪ ،‬ولقولــه صلى اهلل عليه وســلم (ال وصية‬\n\n‫‪365‬‬\n\f‫لــوارث)‪ ،‬وقولــه يف شــأن مــن أراد الوصيــة (الثلــث والثلــث كثيــر)‪ ،‬وملــا‬\n‫قــرره أهــل العلــم يف شــروط الوصيــة بــأن ال تزيــد علــى ثلــث التركــة‬\n‫وال يوصــى لــوارث وألن بعــض الورثــة لــم يوافــق علــى الوصيــة‪ ،‬ملــا تقــدم‬\n‫احلكــم ببيــع املنــزل محــل الدعــوى عــن طريــق جلنــة حتت إشــراف قاضي‬\n‫التنفيــذ وإيــداع ثلــث قيمتــه مــع ثلــث مــا مت بيعــه مــن بقيــة التركــة يف‬\n‫بيــت املــال إلــى حــن شــراء البــدل تنفيــذ ًا للوصيــة ويــوزع الباقــي علــى‬\n‫الورثــة حســب أنصبتهــم الشــرعية‪ ،‬اعتــرض بعــض املدعــى عليهــم علــى‬\n‫احلكــم‪ ،‬صــدق احلكــم بعــد مداولــة مــن دائــرة األحــوال الشــخصية‬\n                                               ‫مبحكمــة االســتئناف بالريــاض‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 32322052‬وتاريــخ ‪1432/08/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32978627‬وتاريــخ ‪1432/08/02‬ه ـ ففــي يــوم‬\n‫االربعــاء املوافــق ‪ 1433/3/9‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 22‬وفيهــا‬\n‫حضــر املدعــي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ 1034245447‬وحضر حلضوره املدعى عليهم ‪ ........‬سعودية مبوجب‬\n‫ســجل مدنــي رقــم ‪ ........‬و ‪ ........‬ســعودية مبوجــب ســجل مدنــي رقــم‬\n‫‪ ........‬و‪ ........‬ســعودية مبوجــب ســجل مدنــي رقــم ‪ ........‬واملعــرف بهــم‬\n‫من قبل ‪ ........‬سعودي مبوجب سجل مدني رقم ‪ ........‬و‪ ........‬سعودي‬\n‫مبوجــب ســجل مدنــي‪ ........‬ولــم يحضــر بقيــة الورثــة املدعــى عليهــم‬\n‫وهــم ‪ ........‬و‪ ........‬و‪ ........‬وال مــن ينــوب عنهــم ولــم يردنــا مــا يفيــد‬\n\n                                                                                      ‫‪366‬‬\n\f      ‫تبلغهــم وادعــى املدعــي قائــا يف دعــواه إن مورثــي ومــورث املدعــى‬\n      ‫عليهــم تــويف بتاريــخ ‪1429/10/7‬ه ـ وخلــف مــن ضمــن ورثتــه زوجتــه‬\n      ‫‪ ........‬وابنــه أنــا املدعــي ‪ ........‬وبناتــه ‪ ........ ........‬و‪ ........‬و‪ ........‬و‪........‬‬\n      ‫و‪ ........‬وقــد خلــف تركــة عبــارة عــن عمــارة يف حــي طويــق مبدينــة‬\n      ‫الريــاض مملوكــة لــه بالصــك الصــادر مــن كتابــة عــدل الريــاض‬\n      ‫األولــى برقــم ‪ 8/1592‬يف ‪1402/2/23‬ه ـ وإننــي أطلــب يف دعــواي هــذه‬\n      ‫ســؤال املدعــى عليهــم وبيــع العمــارة املذكــورة وتســليم كل وارث‬\n      ‫نصيبــه وإلــزام زوجتــه بتســليمنا صــك العمــارة املذكــورة هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليهــم أجابــوا جميعــا بــأن كل مــا ذكــره املدعــي يف‬\n      ‫دعــواه صحيــح وال مانــع لدينــا مــن بيــع العمــارة املذكــورة وتســليم كل‬\n      ‫وارث نصيبــه هــذا مــا لدينــا فجــرى ســؤالهم عــن صــك ملكيــة العقــار‬\n      ‫فقالــوا إنــه لــدى زوجــة مورثنــا ‪ ........‬وحضــر يف هــذه اجللســة ‪........‬‬\n      ‫ســعودي ‪ ........‬وقــال ‪ ........‬إننــي زوج ‪ ........‬وزوجــة املتوفــى خالتــي‬\n      ‫وأســتعد بإبالغهمــا باملوعــد القــادم وبنــاء عليــه فقــد قــررت رفــع اجللســة‬\n      ‫و يف جلســة اخــرى حضــر املدعــي أصالــة واملدعــى عليهــم ‪ ........‬و‪........‬‬\n      ‫و‪ ........‬بنــات ‪ ........‬املدونــة هوياتهــم ســابقا وحضــر حلضورهــم املدعــى‬\n      ‫عليهم ‪ ........‬ســعودية اجلنســية مبوجب الســجل املدني رقم ‪ ........‬و‪........‬‬\n      ‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬بصفتــه وكيــا عــن ‪........‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض‬\n      ‫برقــم ‪ 33108228‬يف ‪1433/6/8‬ه ـ املخــول لــه فيهــا بحــق املطالبــة‬\n      ‫واملرافعــة واملدافعــة واإلنــكار واإلقــرار والصلــح والتنــازل وقبــول‬\n      ‫األحــكام واالعتــراض عليهــا ‪ ،‬وقــد عــرف باملدعــى عليهــم جميعــا‬\n\n\n‫‪367‬‬\n\f‫كال مــن ‪ ........ :‬و‪ ........‬واملدونــة هويتهمــا ســابقا ‪ ،‬وبعــرض دعــوى‬\n‫املدعــي علــى بقيــة املدعــى عليهــم أجابــت املدعــى عليهــا ‪ ....‬قائلــة ‪ :‬إن مــا‬\n‫ذكــره املدعــي مــن وفــاة زوجــي ‪ ........‬وانحصــار ارثــه يف الورثــة‬\n‫املذكوريــن صحيــح وأمــا مــا ذكــره املدعــي مــن طلــب بيــع املنــزل‬\n‫املذكــور فأنــا ال أوافــق عليــه وذلــك أن العقــار املذكــور ملــك ملورثنــا‬\n‫وقــد أوصــى بــه يف حياتــه بــأن يكــون الدور الســفلي لبناتــه ‪ ........‬و‪........‬‬\n‫ووالدتهــم ‪ ........‬وعليهــم اضحيتــن وأمــا الــدور الثانــي فهــو لبناتــه‬\n‫املتزوجــات ‪ ........‬و‪ ........‬و‪ ........‬مــن احتــاج منهــن وابنــه ‪ ........‬وهــذا‬\n‫البيــت موصــى بــه للورثــة بــأن يســتفيدوا منــه وال أوافــق علــى بيعــه ‪،‬‬\n‫وأجابــت املدعــى عليهــا ‪ .....‬قائلــة ‪ :‬إن مــا ذكــره املدعــي مــن وفــاة مورثنا‬\n‫وانحصــار ارثــه يف الورثــة املذكوريــن وأنــه ميلــك املنــزل املذكــور كل‬\n‫هــذا صحيــح واملنــزل وقــف لوالــدي وال أوافــق علــى بيعــه هــذا مــا لــدي‬\n‫واجــاب املدعــى عليــه وكالــه ‪ ....‬قائــا‪ :‬مــا ذكــره املدعــي مــن وفــاة‬\n‫مــورث موكلتــي وانحصــار ارثــه يف الورثــة املذكوريــن وأنــه ميلــك املنــزل‬\n‫املذكــور كل هــذا صحيــح وموكلتــي ال توافــق علــى بيــع املنــزل‬\n‫لكونــه وقــف لوالدهــا هــذا مــا لــدي و بعــرض ذلــك علــى املدعــي قــال إن‬\n‫والــدي كان ميلــك يف حياتــه أربــع ســيارات تالفــه هــي ‪ ......‬موديــل‪1997‬م‬\n‫و‪ ......‬موديــل‪1990‬م وجرانــد كرافــان موديــل‪1994‬م وامبريــال‬\n‫كرايســلر موديــل‪1991‬م باعهــا وكيــل الورثــة ‪ ...‬هــذا احلاضــر مببلــغ‬\n‫عشــرة آالف وتســعمائة ريــال كمــا ميلــك مورثنــا اســتراحة يف جــو بعــد‬\n‫املزاحميــة ميلكهــا بصــك مت بيعهــا مببلــغ مائــة وخمســة عشــر ألــف ريــال‬\n‫وميلــك املنــزل محــل الدعــوى وأنــا ال ارضــى بوصيــة والــدي لوجــود اجلــور‬\n‫فيهــا إذ التصــرف فيهــا للمدعــى عليهــا ‪ ........‬وأطلــب بيعهــا وقيمــة‬\n\n\n                                                                                         ‫‪368‬‬\n\f      ‫الســيارات واالســتراحة مت توزيعهــا هــذا مــا لــدي ‪ ،‬وبعــرض ذلــك علــى‬\n      ‫املدعــى عليهــم أجابــوا بــأن مــا ذكــره املدعــي مــن حصــر التركــة وأنــه‬\n      ‫مت بيــع الســيارات واالســتراحة املذكــورة باملبالــغ املذكــورة صحيــح‬\n      ‫وقــد مت تســديد ديونــه ووزع الباقــي علينــا بحســب األنصبــة الشــرعية‬\n      ‫ه ـ ـ ــذا ما لـ ـ ــدينا هذا وأب ـ ــرزت املدعى عليها ‪ .......‬ال ـ ـ ــصك الصادر من‬\n      ‫كتابـ ــة ع ـ ـ ـ ــدل الريـ ـ ـ ــاض األولــى برقــم ‪ 8/1592‬يف‪1402/2/23‬ه ـ‬\n      ‫ووجدتــه مطابقــا ملــا جــاء يف دعــواه كمــا ابــرز صــك حصــر اإلرث‬\n      ‫الصــادر مــن هــذه احملكمــة رقــم‪ 32/100/141‬يف ‪1428/10/19‬ه ـ‬\n      ‫واملتضمــن ثبــوت وفــاة ‪ ........‬وانحصــار ارثــه يف زوجتــه ‪ ........‬ويف ابنــه‬\n      ‫‪ ........‬وبناتــه ‪ ........‬و‪ ........‬و‪ ........‬و‪ ، ........‬كمــا أبــرزت صــك صــادر‬\n      ‫مــن كتابــة عــدل الريــاض األولــى برقم‪1/82‬يف‪1412/11/4‬ه ـ‬\n      ‫املتضمــن اثبــات وصيــة ‪ ........‬ونــص احلاجــة منــه وأوصــي بالفيــا العائــدة‬\n      ‫لــي والواقعــة يف حــي ‪ ........‬بالريــاض اململــوك لــي مبوجــب الصــك‬\n      ‫الصــادر مــن عــدل الريــاض األولــى برقــم‪ 8/1592‬يف‪1402/2/3‬ه ـ بــان‬\n      ‫يكــون الــدور الســفلي منهــا بيــد بناتــي ‪ ........‬و‪ ........‬ووالدتهــم ‪........‬‬\n      ‫وعليهــم اضحيتــن لــي ولوالــدي مطلق الصقري ووالدتــي ‪ ........‬وزوجتي‬\n      ‫‪ ........‬امــا بالنســبة للــدور العلــوي مــن احتــاج الســكن مــن بناتــي‬\n      ‫املتزوجــات ‪ ........‬و‪ ........‬و‪ ........‬وابنــي ‪ ........‬فلــه ذلــك ويجــب عليهــم‬\n      ‫القيــام بتســديد قــروض البنــك ‪ ........‬مــع ســاكني الــدور الســفلي‬\n      ‫وكذلــك صيانــة العمــارة مــن جميــع احتياجاتهــا وان اســتغنوا عــن‬\n      ‫الســكن ومــا زاد مــن ايجارهــا فيقســم بينهــم حســب القســمة الشــرعية‬\n      ‫وقــال املدعــي واملدعــى عليهــم ان هــذه هــي وصيــة والدنــا هــذا مــا لدينــا‬\n      ‫كمــا قالــت املدعــى عليهمــا ‪ ........‬و‪ ..........‬اننــا نقــرر لديكــم توكيــل‬\n\n\n‫‪369‬‬\n\f‫‪ ........‬يحمــل الســجل املدنــي رقــم‪ ........‬يف هــذه الدعــوى ولــه حــق‬\n‫املرافعــة واملدافعــة واملخاصمــة واإلقــرار واإلنــكار وســماع البينــات‬\n‫واإلفــراغ وقبولــه واســتالم كل مــا يخصنــا فيمــا يتعلــق بالتركــة كمــا‬\n‫قــررت املدعــى عليهــا ج‪ ........‬قائلــة اننــي أوكل اخــي ‪ ........‬املدعــي يف‬\n‫هــذه الدعــوى ولــه حــق املرافعــة واملدافعــة وســماع الدعــوى واإلقــرار‬\n‫واإلنــكار واإلفــراغ واســتالم الثمــن وقــد شــهد علــى توكيلهــم جميعــا‬\n‫كاتبــه واملعرفــن املذكوريــن وبنــاء عليــه فقــد ثبــت لــدي توكيــل‬\n‫املدعــى عليهــم املذكــورات ‪ ........‬و‪ ........‬و‪ ........‬للــوكالء املذكوريــن‬\n‫وعليــه قــررت رفــع اجللســة و يف جلســة اخــرى حضــر املدعــي ‪........‬‬\n‫وحضــر حلضــوره املدعــى عليهــم كال مــن ‪ ........‬و‪ ........‬و‪ ........‬واملدعــى‬\n‫عليهــم وكالــة ‪ ........‬و‪ ........‬وقــد عــرف باملدعــى عليهــم احلاضــر ‪........‬‬\n‫و‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬هــذا وقــد‬\n‫وردنــا خطــاب كتابــة العــدل األولــى بالريــاض رقــم ‪ 331116733‬يف‬\n‫‪ 1433/6/23‬ه ـ املتضمــن أن الصــك رقــم ‪8/1592‬يف ‪ 1402/2/23‬ال‬\n‫زال ســاري املفعــول وقــال املدعــي واملدعــى عليهــم ‪ ........‬و‪ ........‬و‪........‬‬\n‫إننــا ال نوافــق علــى وصيــة والدنــا ونطلــب بيــع املنــزل كمــا قــال املدعــي‬\n‫واملدعــى عليهــم جميعــا إن املنــزل املذكــور ميثــل غالــب التركــة وبنــاء‬\n‫علــى مــا ســبق مــن الدعــوى واإلجابــة و لقولــه صلــى اهلل عليــه وســلم ال‬\n‫وصيــة لــوارث وقولــه صلــى اهلل عليــه وســلم الثلــث والثلــث كثيــر يف‬\n‫شــأن مــن أراد الوصيــة وقــد قــرر أهــل العلــم شــروطا للوصيــة هــي أن ال‬\n‫تخــرج عــن ثلــث التركــة وال يوصــى لــوارث ومبــا أن املدعــي واملدعــى‬\n‫عليهــم ‪ ........‬و‪ ........‬و‪ ........‬لــم يوافقــوا علــى وصيــة والدهــم ومبــا أن‬\n‫املدعــي واملدعــى عليهــم قــرروا أن املنــزل املذكــور ميثــل غالــب التركــة‬\n\n\n                                                                                      ‫‪370‬‬\n\f      ‫والوصيــة بــه تخــرج عــن الثلــث لذلــك كلــه فقــد حكمــت ببيــع املنــزل‬\n      ‫محــل الدعــوى عــن طريــق جلنــة حتــت إشــراف قاضــي التنفيــذ وقــررت‬\n      ‫إيــداع ثلــث قيمتــه مــع ثلــث مــا مت بيعــه مــن بقيــة التركــة يف بيــت املــال‬\n      ‫إلــى حــن شــراء البــدل تنفيــذا للوصيــة ويــوزع الباقــي علــى الورثــة حســب‬\n      ‫أنصبتهــم الشــرعية وبعــرض احلكــم علــى املدعــي واملدعــى عليهــم قــرر‬\n      ‫املدعــي واملدعــى عليهــم ‪ ........‬و‪ ........‬و‪ ........‬القناعــة أمــا املدعــى‬\n      ‫عليهــم وكالــة فلــم يقتنعــوا باحلكــم وطلبــوا رفــع املعاملــة إلــى محكمــة‬\n      ‫االســتئناف فأجبتهــم لطلبهــم وأفهمتهــم أنــه ســوف يســلم لهــم صــورة مــن‬\n      ‫نســخة احلكــم يــوم األثنــن املوافــق ‪ 1433/8/5‬ه ـ وأن لهــم مهلــة ثالثــن‬\n      ‫يومــا لتقــدمي لوائحهــم االعتراضيــة وإذا انتهــت املهلــة ولــم يتقدمــوا‬\n      ‫بلوائحهــم ســقط حقهــم يف االعتــراض ومت رفــع املعاملــة إلــى محكمــة‬\n      ‫االســتئناف حلــق الوقــف وبــه ختمــت اجللســة يف متــام الســاعة الثانيــة عشــر‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪ 1433/07/30‬ه ـ احلمــد هلل وحــده وبعــد‪ -:‬ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/04/24‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــر املدعــى عليهــم‪ ........ /‬و‪ ........‬و‪ ........‬بنــات ‪ ........‬املعــرف‬\n      ‫بهــم مــن قبــل‪ ........ /‬املدونــة هويتــه ســابقا‪ ،‬واملدعــى عليــه وكالــة‪/‬‬\n      ‫‪ ، ........‬وأمــا املدعــي‪ ، ........ /‬واملدعــى عليهــا‪ ........ /‬فلــم يحضــرا‪،‬‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم‪( :‬‬\n      ‫‪ )331753100‬يف ‪1433/11/2‬ه ـ ـ وبرفقهــا قــرار دائــرة األحــوال‬\n      ‫الشــخصية الثانيــة برقــم‪ )33431531(:‬وتاريــخ ‪1433/10/18‬ه ـ ـ‬\n      ‫املتضمــن مــا نصــه‪« :‬لوحــظ مــا يلــي ‪/1‬يظهــر أن العقــار موضــع الدعــوى‬\n      ‫مرهــون لصنــدوق التنميــة العقــاري ولــم جنــد‪ ،‬فضيلتــه خاطــب‬\n\n\n‫‪371‬‬\n\f‫الصنــدوق؛ ألخــذ مــا لديــه حيــال الرهــن‪ ،‬وأخــذ ذلــك يف االعتبــار عنــد‬\n‫احلكــم بالبيــع‪/2 .‬ذكــر املدعــى عليهــم املعترضــون يف الئحتهــم‬\n‫االعتراضيــة رغبتهــم يف عــدم بيــع العمــارة وإمنــا تثمينهــا وإبقــاء الثلــث‬\n‫الوصيــة ونصيبهــم فيهــا بعــد إخــراج نصيــب املدعــن ملــا ذكــروه مــن‬\n‫املبــررات املذكــورة ممــا يســتدعي النظــر يف ذلــك وحتــري األصلــح‬\n‫للجميــع ودفعــا للضــرر لقولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضرار)‬\n‫ممــا هــو مناســب وموافــق شــرعا»ا‪.‬ه ـ ـ ‪ ،‬وبعــرض ذلــك عليهــم‪ ،‬قالــوا‬\n‫جميعــا‪ :‬إن العقــار محــل الدعــوى كان مرهونــا‪ ،‬وقــد مت فــك الرهــن‬\n‫عنــه‪ ،‬وقالــت كال مــن ‪ ........‬و‪ ........‬و‪ : ........‬إننــا نطلــب بيــع العقــار‬\n‫وإعطــاء كل وارث نصيبــه بعــد فــرز قيمــة الثلــث للوصيــة‪ ،‬وقــال‬\n‫املدعــى عليــه وكالــة ‪ : ........‬إن موكلتــي يطلبــان إبقــاء الوصيــة بحالها‬\n‫حســبما ورد فيهــا‪ ،‬وإال بيــع العقــار وإعطــاء كل مــن الورثــة نصيبــه وال‬\n‫تســتطيعان شــراء نصيــب بقيــة الورثــة‪ ،‬هــذا مــا لــدي‪ .‬هــذا وقــد جــرى‬\n‫االطــاع علــى صــك العقــار املذكــور وقــد همــش عليــه بفــك الرهــن عــن‬\n‫العقــار‪ ،‬وقــال املعــرف املذكــور‪ :‬إننــي وكيــل عــن املدعــي ولــم أحضــر‬\n‫وكالتــي‪ ،‬وأطلــب إمهالــي إلحضارهــا‪ ،‬وبنــاء عليــه مت رفــع اجللســة ‪ ،‬ثم‬\n‫يف جلســة أخــرى حضــر املدعــى عليهــن ‪ .......‬و‪ ........‬و‪ ........‬بنــات ‪........‬‬\n‫املعــرف بهــن مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ........‬ولــم يحضــر املدعــي و ال بقيــة املدعــى عليهــم و بنــاء عليــه و مبــا ان‬\n‫املدعــى عليهــم يف اجللســة الســابقة قــرروا رغبتهــم يف بيــع العقــار وعــدم‬\n‫املوافقــة علــى الوصيــة بــه و انــه ميثــل اكثــر مــن الثلــث و مبــا انــه ال‬\n‫ميكــن القســمة اال ببيعــه لــذا فلــم يظهــر لــي مــا يؤثــر علــى مــا حكمــت‬\n‫بــه وقــرر بعــث املعاملــة الــى محكمــة االســتئناف و بــه ختمــت اجللســة يف‬\n\n\n                                                                                         ‫‪372‬‬\n\f      ‫متــام الســاعة الثالثــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/04/30‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331947006‬وتاريخ‪1434/5/11‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪........ /‬‬\n      ‫املســجل برقــم ‪ ........‬وتاريــخ‪ 1433/7/30‬ه ـ اخلــاص بدعــوى‪........ /‬‬\n      ‫ضــد ‪ ........ /‬بشــأن قســمة تركــه وقــد تضمــن الصــك حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصك وصــورة ضبطه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا رقــم ‪33431531‬‬\n      ‫وتاريــخ ‪1433/10/18‬ه ـ تقــرر الدائــرة املصادقــة بعــد اجلــواب األخيــر‪،‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪373‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":365,"source_page_end":373,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7fb06679eaaa82d4ef8c8eeb84731804083a77bc59b18eaca6591b95c8d23100","normalized_text_hash":"837bf7f5a3ee2d9258ae501315b04623e651094c3989c3a28d80752558286c6f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p365-33363338"},{"id":"1eebeb53-f2a9-5167-8132-56d580e46263","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة مورث وترك أرض -قيام بعض الورثة ببيع األرض ورفض البعض للبيع -مطالبة الرافضن إمتام البيع -إدخال مشتري األرض يف الدعوى -إثبات البيع بشاهد عدل ومين -إقرار جميع الورثة ببيع األرض -ثبوت بيع جميع الورثة -تقسيم مبلغ األرض على الورثة كل حسب نصيبه الشرعي وإيداع نصيب من يرفض االستالم بيت مال المحكمة وإفراغ الصك محل الدعوى بعد اكتساب احلكم القطعية .","document_number":"33411128","case_number":"32216222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/13","year":"1434","subject":"قسمة تركة -وفاة مورث وترك أرض -قيام بعض الورثة ببيع األرض ورفض البعض للبيع -مطالبة الرافضن إمتام البيع -إدخال مشتري األرض يف الدعوى -إثبات البيع بشاهد عدل ومين -إقرار جميع الورثة ببيع األرض -ثبوت بيع جميع الورثة -تقسيم مبلغ األرض على الورثة كل حسب نصيبه الشرعي وإيداع نصيب من يرفض االستالم بيت مال المحكمة وإفراغ الصك محل الدعوى بعد اكتساب احلكم القطعية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33411128 :‬تاريخه‪1433/9/13 :‬هـ‬\n                   ‫رقم الدعوى‪32216222 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3458162‬تاريخه‪1434/3/9 :‬هـ‬\n\n\n‫قســمة تركــة‪ -‬وفــاة مــورث وتــرك أرض‪ -‬قيــام بعــض الورثــة ببيــع‬\n‫األرض ورفــض البعــض للبيــع‪ -‬مطالبــة الرافضــن إمتــام البيع‪ -‬إدخال‬\n‫مشــتري األرض يف الدعــوى‪ -‬إثبــات البيــع بشــاهد عــدل وميــن‪ -‬إقــرار‬\n‫جميــع الورثــة ببيــع األرض‪ -‬ثبــوت بيــع جميــع الورثــة‪ -‬تقســيم مبلــغ‬\n‫األرض علــى الورثــة كل حســب نصيبــه الشــرعي وإيــداع نصيــب مــن‬\n‫يرفــض االســتالم بيــت مــال احملكمــة وإفــراغ الصــك محــل الدعــوى‬\n                                       ‫بعــد اكتســاب احلكــم القطعيــة ‪.‬‬\n\n\n\n‫حديــث أبــي هريــرة رضــي اهلل عنــه (أن النبــي صلــى اهلل عليــه وســلم‬\n                          ‫قضــى بالشــاهد واليمــن) أخرجــه أحمــد ‪.‬‬\n\n\n\n\n‫ادعــى املدعيــان أصالــة ووكالــة ضــد املدعــى عليــه أصالــة ووكالــة بــأن‬\n‫مورثهــم خلــف لهــم أرض ـ ًا وقــد باعــوا األرض مببلــغ أربعمائــة وخمســن‬\n‫ألــف ريــال والســعي عليهــم ولكــن املدعــى عليهمــا رفضا البيــع ويطلبون‬\n‫إلزامهمــا بالبيــع‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى أن مورثهــم خلــف‬\n‫لهــم األرض وأنكــر البيــع وصــادق علــى رفضــه البيــع وموكلــه وأن‬\n‫الســبب يف ذلــك هــو أن مورثهــم خلــف عمــارة بجــوار األرض وقــد رفــض‬\n\n                                                                                  ‫‪374‬‬\n\f      ‫املدعــون بيعهــا ويرغــب هــو وموكلــه ببيعهــا واألرض باملــزاد العلنــي‪،‬‬\n      ‫أجــاب املدعــون بأنهــم يعترضــون علــى بيعهــا باملــزاد العلنــي ألنهــا قــد‬\n      ‫تتضــرر مــن نقــص القيمــة عــن الســعر احلالــي‪ ،‬تداخــل املشــتري وقــرر‬\n      ‫بــأن الورثــة باعــوه األرض ومــن ضمنهــم املدعــى عليــه وأنــه خســر قرابــة‬\n      ‫عشــرة آالف إلكمــال الناقــص يف الصــك مــن إجــراءات التعقيب والرفع‬\n      ‫املســاحي‪،‬صادق املدعــون علــى البيــع وأنكــره املدعــى عليه‪،‬أحضــر‬\n      ‫املتداخــل بينــة وهمــا شــاهدان مت تعديلهمــا شــهدا طبــق مــا ذكــره‬\n      ‫بخصــوص البيــع‪ ،‬حلــف اليمــن املتممــة لبينتــه بعــد عرضهــا عليــه‪ ،‬بنــاء‬\n      ‫علــى شــهادة أحــد الشــهود واملعدلــة شــرع ًا واليمــن املتممــة لهــذه البينــة‪،‬‬\n      ‫وحلديــث (أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــاهد واليمــن)‬\n      ‫أخرجــه أحمــد‪ ،‬ثبــوت بيــع جميــع الورثــة مبــا فيهــم املدعــى عليهمــا‬\n      ‫األرض العائــدة ملورثهــم علــى املتداخــل بيع ـ ًا صحيح ـ ًا بثمــن قــدره‬\n      ‫أربعمائــة وثمانيــة وثالثــون ألف ـ ًا وخمســمائة ريــال واحلكــم بصحتــه‬\n      ‫ولزومــه علــى الورثــة‪ ،‬واحلكــم بإفــراغ الصــك محــل الدعــوى للمتداخــل‬\n      ‫بعــد اكتســاب احلكــم القطعيــة وتقســيم املبلــغ علــى الورثــة كل‬\n      ‫حســب نصيبــه الشــرعي وإيــداع نصيــب مــن يرفــض االســتالم ببيــت مــال‬\n      ‫احملكمــة‪ ،‬بعــث احلكــم لتبليــغ املدعــى عليهمــا بــه‪ ،‬صــدق احلكــم‬\n                                                            ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪375‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فلــدي‬\n‫أنــا ‪ .....‬القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء على املعاملة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم‬\n‫‪ 32216222‬وتاريــخ ‪1432/06/07‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 32674093‬وتاريــخ ‪1432/06/07‬ه ـ يف يــوم االربعــاء املوافــق‬\n‫‪1433/01/19‬ه ـ أفتتحــت اجللســة الســاعة الثامنــة والنصــف صباح ـ ًا‬\n‫ال مــن ‪ .....‬ســعودي اجلنســية مبوجــب‬       ‫وفيهــا حضــر ورثــة ‪ .....‬وهــم ك ً‬\n‫الســجل املدنــي رقــم ‪ ..... .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬و‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬أصالـ ًة‬\n‫عــن نفســه وبوكالتــه عــن ‪ ..... ..... ..... ..... ..... ..... .....‬أوالد ‪.....‬‬\n‫بالوكالتــن رقــم ‪ 38472‬يف ‪1431/6/18‬ه ـ ورقــم ‪ 11600‬يف‬\n‫‪1432/2/25‬ه ـ الصادرتــن مــن كتابــة عــدل املدينــة وحضــر حلضورهم‬\n‫املدعــى عليــه‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n‫أصالــة عــن نفســه وبوكالتــه عــن ‪ .....‬بالوكالــة رقــم ‪ 65614‬يف‬\n‫‪1432/11/10‬ه ـ الصــادرة مــن كتابــة عــدل املدينــة بصفتــه وارثــا ألمــه‬\n‫‪ .....‬وهــي أحــد بنــات ‪ .....‬وبســؤال احلاضريــن عــن دعواهــم أدعــو أصالــة‬\n‫ووكالــة علــى املدعــى عليهمــا قائلــن ‪ :‬إننــا مــن ورثــة والدنــا ‪ ....‬الــذي‬\n‫خلــف لنــا أرض يف حــارة ‪ .....‬مملوكــة ملورثنــا مبوجــب ‪ 1/750‬يف‬\n‫‪1400/6/22‬ه ـ الصــادر مــن كتابــة عــدل املدينــة املنــورة وقــد بعنــا‬\n‫األرض علــى املدعــو ‪ .....‬بقيمــة أربعمائــة وخمســن ألــف ريــال والســعي‬\n‫علينــا ورفــض البيــع املدعــى عليهمــا نطلــب إلزامهمــا بالبيــع ‪ .‬وبعــرض‬\n\n                                                                                       ‫‪376‬‬\n\f      ‫ا مــا ذكــره املدعــي‬   ‫ذلــك علــى املدعــى عليــه أصالــة ووكالــة أجــاب قائـ ً‬\n      ‫مــن أن والدنــا قــد خلــف لنــا األرض املذكــورة فصحيــح وأمــا البيــع فغير‬\n      ‫صحيــح ولــم نبــع علــى أحــد إطالقـ ًا ومــا ذكره مــن رفضي أنــا وموكلي‬\n      ‫للبيــع املذكــور فهــو صحيــح وســبب ذلــك أن مورثنــا قــد تــرك لنــا عمــارة‬\n      ‫قريبــة مــن هــذه األرض وقــد رفــض املدعــن بيــع هــذه العمــارة وإننــا‬\n      ‫نرغــب أنــا وموكلــي ببيــع األرض والعمــارة جميع ـ ًا باملــزاد العلنــي‬\n      ‫ونرفــض البيــع بغيــر هــذه الطريقــة كمــا نرفــض بيــع االرض لوحدهــا‬\n      ‫أضمــن حلقنــا؛ علمـ ًا أن هنــاك بعــض الورثــة وورثتهــم رافضــن للبيــع ولــم‬\n      ‫يحضــروا ولــم يوكلــوا حتــى اآلن أطلــب إلزامهــم ببيــع العمــارة التــي‬\n      ‫خلفهــا لنــا والدنــا عــن طريــق املــزاد العلنــي كمــا هــو املتبــع هكــذا‬\n      ‫اجــاب وبعــرض ذلــك علــى املدعــن أصالــة ووكالــة أجابــوا قائلــن‪ :‬أننــا‬\n      ‫ســبق وأن بعنــا علــى املذكــور هــذه وال نعلــم عــن بيــع املدعــى عليهــم‬\n      ‫شــيئ ًا وأننــا نعتــرض علــى بيعهــا باملــزاد ألنــه قــد نتضــرر من نقــص القيمة‬\n      ‫باملزاد عن الســعر احلالي ‪ .‬ويف نفس اجللســة حضر ‪ .....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وطلــب التداخــل يف الدعــوى وبســؤاله‬\n      ‫ا ‪ :‬إنــي يف شــهر ربيــع الثانــي مــن عــام‬  ‫عــن وجــه تداخلــه أجــاب قائ ـ ً‬\n      ‫‪1432‬ه ـ بــاع علــي جميــع الورثــة مبــا فيهــم احلاضــر ‪ .....‬مببلــغ أربعمائــة‬\n      ‫وخمســن ألــف ريــال مبــا فيهــا الداللــة وألــف وخمســمائة ريــال للمكتــب‬\n      ‫وحضــر الورثــة لكتابــة العــدل األولــى إال أن الــوكاالت املوجــودة وجــد‬\n      ‫بهــا أخــت متوفيــه فطلبــوا منهــم جتديــد الوكالــة علم ـ ًا أننــي أكملــت‬\n      ‫مــا نقــص يف الصــك مــن إجــراءات وكلفنــي عشــرة آالف ريــال للتعقيــب‬\n      ‫والكروكــي والرفــع املســاحي وحــررت شــيك مببلــغ أربعمائــة وثمانيــة‬\n      ‫وثالثــن ألفـ ًا وخمســمائة ريــال املبلــغ املتبقــي‪ .‬هكــذا تداخــل‪ .‬وبعــرض‬\n\n\n‫‪377‬‬\n\f‫ذلــك علــى املدعــن أجابــوا قائلــن مــا ذكــره املتداخــل كلــه صحيــح إال‬\n‫بيــع ‪ .....‬وموكليــه فــا نعــرف عنــه شــيئ ًا ‪.‬هكــذا أجابــوا‪ .‬وبعــرض ذلــك‬\n‫ا مــا ذكره مــن حضوري‬       ‫علــى املدعــى عليــه أصالــة ووكالــة أجــاب قائـ ً‬\n‫وبيعــي لــأرض فغيــر صحيــح إطالق ـ ًا ‪.‬هكــذا أجــاب‪ .‬والنتهــاء وقــت‬\n‫اجللســة رفعــت اجللســة ‪ ،‬ثــم يف يــوم الســبت املوافــق ‪1433/02/27‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة والنصــف صباحـ ًا وفيهــا حضــر املدعــي‬\n‫‪ .....‬واملدعــي ‪ .....‬واملتداخــل ‪ .....‬ولــم يحضــر املدعــي الثالــث ‪ .....‬ولــم‬\n‫يحضــر املدعــى عليــه أصالــة ووكالــة ولــم يوقــع علــى ضبــط اجللســة‬\n‫الســابقة املنعقــدة بتاريــخ ‪1433/1/19‬ه ـ ‪ ،‬وقــد حــرر محضــر بذلــك‬\n‫أســفل الضبــط وكان ذلــك بشــهادة كل مــن كاتــب الضبــط ‪.....‬‬\n‫والعســكري ‪ ......‬وذكــر املتداخــل أن لديــه شــهود علــى البيــع ويطلــب‬\n‫إمهالــه إلحضارهــم؛ لــذا رفعــت اجللســة إلــى يــوم األربعــاء املوافــق‬\n‫‪1433/03/09‬ه ـ الســاعة العاشــرة والنصــف ‪ ،‬ثــم يف يــوم األربعــاء‬\n‫‪1433/3/9‬ه ـ حضــر املدعــن الثالثــة و حضــر املتداخــل ولــم يحضــر‬\n‫املدعــى عليــه ولــم يتبلــغ مبوعــد هــذه اجللســة وقــد أحضــر املتداخــل معــه‬\n‫للشــهادة ‪ .....‬ســعودي اجلنســية بســجل مدنــي رقــم ‪ .....‬وبســؤاله عمــا‬\n‫لديــه قــال ‪ :‬إننــي أبلــغ مــن العمــر واحــد وأربعــن عامــا و أعمــل مســتخدم‬\n‫يف مدرســه ‪ .....‬اإلبتدائيــة وأقيــم يف املدينــة املنــورة و أعــرف املتداعــن‬\n‫واملتداخــل ‪ ....‬متــام املعرفــة وليــس لــي أي قرابــة باملتداعــن أمــا املتداخــل‬\n‫فأمــه ابنــة عمــي و أشــهد هلل تعالــى ‪ :‬أنــه قبــل أربعــة أشــهر مــن اآلن كنــا‬\n‫واقفــن أنــا و‪( ..........‬املشــتري) واملدعــى عليهمــا و‪ ، .....‬املدعــى عليــه‬\n‫و‪ .....‬عنــد بــاب بيــت خالــه ‪ .....‬يف حــي ‪ .....‬و ســمعت املدعــى عليهمــا ‪.....‬‬\n‫‪ .....‬يقــوالن نحــن بائعــن عليــك مــع بقيــة الورثــة والنيــة لــك‪ ،‬يقصــدون‬\n\n\n                                                                                        ‫‪378‬‬\n\f      ‫‪ .....‬فلمــا طلــب ‪ .....‬منهــم احلضــور لإلفــراغ اعتــذر ‪ .....‬بــأن لــه شــغل يف‬\n      ‫جــده ووعــد بــأن يحضــر بعــد عودتــه مــن جــده بــأن يحضــر لإلفــراغ ‪.‬‬\n      ‫هكــذا اشــهد‪ .‬ثــم طلبــت مــن املتداخــل زيــادة بينــه علــى ذلــك فقــال لــدي‬\n      ‫شــاهد وهــو املدعــي األول ‪ .....‬فأفهمتــه أنــه ال تقبــل شــهادته لعــدم انتفــاء‬\n      ‫التهمــة؛ فاســتعد باليمــن املتممــة لبينتــه ثــم طلبــت مــن املتداخــل إحضــار‬\n      ‫معدلني لبينته؛ لذا رفعت اجللسة إلى يوم السبت بتاريخ ‪1433/3/26‬هـ‬\n      ‫الســاعة العاشــرة والنصــف‪ ،‬ثــم يف يــوم الســبت املوافق‪1433/03/26‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العاشــرة والنصــف صباحــا‪ ،‬وفيهــا حضــر‬\n      ‫املدعــن الثالثــة وحضــر املتداخــل‪ ،‬وحضــرت ‪ .....‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وبعــد تعريفهــا مــن قبــل ابنهــا ‪.....‬‬\n      ‫ســعودي بالســجل املدنــي رقــم ‪ ، .....‬كمــا حضــر مــن ورثــة‪ .....‬ســعودي‬\n      ‫بالســجل املدني ‪ .....‬و‪ .....‬ســعودي بالســجل املدني رقم ‪ .....‬و‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، .....‬أصالــة عــن نفســه وبوكالته‬\n      ‫عــن بنتــن مــن ورثــة والدتــه ‪ .....‬وهمــا ‪ ..... .....‬بنتــي ‪ .....‬التــي تخــول لــه‬\n      ‫البيــع‪ ،‬والشــراء‪ ،‬واإلفــراغ‪ ،‬وقبولــه‪ ،‬واســتالم الثمــن‪ ،‬وتســليم املثمن‪،‬‬\n      ‫والتأجيــر واملداعــاة‪ ،‬واملخاصمــة‪ ،‬وســماع الدعــاوي‪ ،‬والــرد عليهــا‪،‬‬\n      ‫وإقامــة البينــة‪ ،‬والدفــع‪ ،‬وقبــول احلكــم‪ ،‬واالعتــراض عليــه‪ ،‬واســتالم‬\n      ‫جميــع مــا يخصنــا مــن إرث والدتنــا ‪ ، .....‬والعائــد لهــا مــن مورثهــا والدها‬\n      ‫‪ .‬ثــم جــرى ســؤال املتداخــل عمــا وعــد بــه مــن مزكــن لشــاهده فأحضــر‬\n      ‫ال مــن ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و‪.....‬‬        ‫ك ً‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وبســؤالهما عمــا‬\n      ‫لديهمــا قــاال ‪ :‬نشــهد هلل أن الشــاهد ‪ .....‬صاحــب ديــن وأمانــة وصــدق‬\n      ‫وصالــح للشــهادة‪ .‬هكــذا شــهدا ‪ .‬ثــم قــرر احلاضــرون جميع ـ ًا قائلــن ‪:‬‬\n\n\n‫‪379‬‬\n\f‫إن املدعــى عليــه وموكلــه لــم يحضــرا لظــرف لديهمــا وقــد جلســنا‬\n‫مجلــس صلــح واتفقنــا علــى بيــع هــذه األرض علــى املتداخــل ‪ .....‬مببلــغ‬\n‫أربعمائــة وخمســن ألــف ريــال مبــا فيهــا الداللــة البالغــة أحــد عشــر ألفــا‬\n‫وخمســمئة ريــال‪ ،‬وتأجيــل بيــع العمــارة املذكــورة يف جــواب املدعــى‬\n‫عليــه إلــى أجــل غيــر مســمى‪ ،‬وســيحضر املدعــى عليهمــا غــد ًا إلقــرار‬\n‫هــذا البيــع والتنــازل عــن طلــب بيــع العمــارة املذكــورة‪ .‬ونحــن نقــرر‬\n‫أمامكــم أنــه ال مانــع لدينــا مــن إفــراغ األرض املذكــورة للمتداخــل وال‬\n‫مانــع لدينــا مــن إيــداع قيمــة هــذه األرض لبيــت مــال احملكمــة وتســليمه‬\n‫للورثــة بعــد ذلــك كل حســب اســتطاعته وفراغــه يحضر ويســتلم نصيبه‬\n‫‪ .‬هكــذا قــرروا جميع ـ ًا ‪ .‬لــذا رفعــت اجللســة وحــدد لهــا موعــد غــد ًا‬\n‫األحــد املوافــق ‪1433/03/27‬ه ـ الســاعة الواحــدة ألخــذ موافقــة املدعى‬\n‫عليهمــا‪ .‬وتعهــد املدعــي ‪ .....‬بإحضــار املدعــى عليهمــا غــد ًا إلقــرار هــذا‬\n‫الصلــح مــع شــاهدين يشــهدان عليهــا بالصلــح ‪ .‬كمــا حــدد جلســة ثانيــة‬\n‫يــوم الســبت املوافــق ‪1433/05/22‬ه ـ الســاعة التاســعة والنصــف‬\n‫لالطــاع علــى صكــوك حصــر اإلرث للمتوفــن الثالثــة‪ ،‬والتأكــد مــن‬\n‫الــوكاالت والتأمــل يف مــا ســبق ضبطــه مــن دعــوى وإجابــات وإقــرارات‬\n‫‪.‬ثــم يف يــوم اإلثنــن املوافق‪1433/03/28‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الواحــدة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــى عليــه أصالــة عــن‬\n‫نفســه وبوكالتــه عــن املدعــى عليــه ‪ .....‬بالوكالــة رقــم ‪ 65614‬وتاريــخ‬\n‫‪1432/11/10‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة التــي‬\n‫تخــول لــه البيــع واإلفــراغ واســتالم ثمــن مــا يخصــه مــن األرض والعمــارة‬\n‫اململوكــة ملورثــه ‪ .....‬ويحــق لــه توكيــل الغيــر ‪ ،‬ثــم قــرر أصالــة عــن‬\n‫ا ‪ :‬إننــي أنــا وموكلــي‬    ‫نفســه وبوكالتــه عــن املدعــى عليــه ‪ .....‬قائ ـ ً‬\n\n\n                                                                                      ‫‪380‬‬\n\f      ‫املذكــور قــد بعنــا األرض العائــدة ملورثينــا الواقعــة يف حــي ‪ .....‬يف املدينــة‬\n      ‫املنــورة‪ ،‬واململوكــة لوالــدي رحمــه اهلل بالصــك رقــم ‪1/750‬‬\n      ‫يف‪1400/06/22‬ه ـ علــى املتداخــل ‪ .....‬مببلــغ أربعمائــة وخمســن ألــف‬\n      ‫ريــال مبــا فيهــا الداللــة البالغــة أحد عشــر ألفا وخمســمئة ريــال‪ ،‬وتأجيل‬\n      ‫بيــع العمــارة املذكــورة يف جوابــي ســابقا إلــى أجــل غيــر مســمى ‪،‬‬\n      ‫والتنــازل عــن طلــب بيــع العمــارة املذكــورة ‪ ،‬وال مانــع لدينــا مــن إيــداع‬\n      ‫قيمــة هــذه األرض لبيــت مــال احملكمــة وتســليمه للورثــة بعــد ذلــك كل‬\n      ‫حســب اســتطاعته وفراغــه يحضــر ويســتلم نصيبــه ‪ .‬هكــذا قــرر ‪ .‬وألن‬\n      ‫وكالتــه تخــول لــه البيــع واإلفــراغ واســتالم الثمــن فقــد ثبــت لــدي إقراره‬\n      ‫بالبيــع أعــاه علــى املتداخــل ورفعــت اجللســة ومت تبليــغ املدعــى عليــه‬\n      ‫أصالــة ووكالــة مبوعــد اجللســة القادمــة يف يــوم الســبت املوافــق‬\n      ‫‪1433/05/22‬ه ـ الســاعة التاســعة والنصــف ‪ .‬ثــم يف يــوم الســبت‬\n      ‫املوافق‪1433/05/22‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‪،‬‬\n      ‫وفيهــا حضــر املدعــن مــن ورثــة ‪ .....‬الثالثة املذكوريــن أصالة ووكالة‪،‬‬\n      ‫ولــم يحضــر املدعــى عليهمــا ‪ ،‬ولــم يوقــع املدعــى عليــه علــى مــا أقــر بــه‬\n      ‫لدينــا يف اجللســة املاضيــة والزالــت بطاقــة األحــوال التابعــة لــه لــدى‬\n      ‫املوظــف حتــى هــذه اجللســة‪ ،‬فقــررت الســير يف هــذه القضيــة غيابيــا‬\n      ‫وبعــث بطاقــة األحــوال التابعــة للمدعــى عليــه عــن طريــق الشــرطة‬\n      ‫لتســليمها لــه وتبليغــه باملوعــد القــادم‪ ،‬ثــم جــرى عــرض اليمــن املتممــة‬\n      ‫لبينتــه املتداخــل عليــه؛ فاســتعد بهــا‪ ،‬ثــم حلــف‪ ،‬قائــا ‪ :‬واهلل العظيــم‬\n      ‫الــذي ال إلــه إال هــو وال رب ســواه‪ ،‬أن املدعــى عليهمــا ‪ .....‬و‪ .....‬قــد باعــا‬\n      ‫علـ ّـي األرض الواقعــة يف حــي ‪ ، .....‬واململوكــة ملورثيهمــا بالصــك رقــم‬\n      ‫‪ 1/750‬يف ‪1400/6/22‬ه ـ مببلــغ أربعمئــة وخمســن ألــف ريــال‪ ،‬مبــا‬\n\n\n‫‪381‬‬\n\f‫فيهــا الداللــة أحــد عشــر ألــف ريــال وخمســمئة ريــال للرفــع املســاحي‪،‬‬\n‫يخصمــان مــن إجمالــي مبلــغ البيــع ‪ ،‬وواهلل إنــي صــادق يف ذلــك ‪ .‬هكذا‬\n‫حلــف ‪ .‬ثــم جــرى اإلطــاع علــى صــك التملــك الــذي أحضــره املدعــن‬\n‫والصــادر مــن كتابــة عــدل املدينــة املنــورة‪ ،‬برقــم ‪ 1/750‬يف‬\n‫‪1400/6/22‬ه ـ فوجــد يتضمــن متلــك ‪ .....‬لقطعــة األرض الواقعــة يف‬\n‫املغيســلة يف املدينــة املنــورة‪ ،‬واملبينــة حدودهــا وأطوالهــا ومســاحتها‬\n‫باطنــه‪ ،‬ثــم جــرى االطــاع علــى صــك حصــر الورثــة الصــادر مــن‬\n‫احملكمة العامة باملدينة املنورة‪ ،‬برقم ‪ 11/19‬وتاريخ ‪1415/4/27‬هـ‪،‬‬\n‫املتضمــن وفــاة ‪ ، .....‬بتاريــخ ‪1414/06/03‬ه ـ وانحصــار ورثتــه يف‬\n‫زوجتــه ‪ .....‬ويف أوالده منهــا ‪ .....‬و ‪ ..... ..... ..... ..... .....‬و ابنتيــه ‪، ..... .....‬‬\n‫و يف زوجتــه األخــرى ‪ ، .....‬و يف أوالده منهــا وهــم ‪ ..... ..... ..... .....‬ال‬\n‫وارث لــه ســواهم‪ ،‬كمــا جــرى اإلطــاع علــى صــك حصــر الورثــه رقــم‬\n‫‪ 6/31‬يف ‪1426/4/16‬ه ـ الصــادر مــن احملكمــة العامــة باملدينــة‬\n‫املنــورة‪ ،‬واملتضمــن وفــاة ‪ ، .....‬وانحصــار إرثهــا يف أوالدهــا ‪ ، .....‬و ‪.....‬‬\n‫و‪ .....‬و‪ .....‬و‪ .....‬أوالد ‪ ، .....‬ال وراث لهــا ســواهم ‪ ،‬كمــا جــرى اإلطــاع‬\n‫علــى صــك حصــر الورثــة رقــم ‪ 10/100/337‬يف ‪1430/11/02‬ه ـ‬\n‫الصــادر مــن احملكمــة العامــة باملدينــة املنــورة‪ ،‬واملتضمــن وفــاة ‪، .....‬‬\n‫وانحصار إرثها يف أوالدها ‪ ..... ..... ..... ..... ..... ..... .....‬و‪ .....‬أوالد‪، .....‬‬\n‫ال وارث لهــا ســواهم‪ ،‬وألن جميــع الورثــة أعــاه قــد حضــروا‪ ،‬وأقــروا‬\n‫بالبيــع أصالــة أو وكالــة‪ ،‬ســوى املدعــى عليهمــا ‪ ،‬والوارثــن ‪ .....‬و ‪.....‬‬\n‫‪ ،‬وبســؤال املدعــن عــن األخيريــن‪ ،‬أجابــوا قائلــن ‪ :‬إنهــم بائعــن معنــا‪،‬‬\n‫وال مانــع لديهــم مــن اإلفــراغ‪ ،‬ونتعهــد بإحضارهمــا يف اجللســة القادمــة‪،‬‬\n‫ألخــذ إقرارهمــا بالبيــع ‪ .‬هكــذا أجابــوا ‪ .‬ثــم جــرى رفــع اجللســة ملخاطبــة‬\n\n\n                                                                                                 ‫‪382‬‬\n\f      ‫مصــدر الصــك كتابــة العــدل املدينــة املنــورة‪ ،‬للتأكــد مــن ســريان‬\n      ‫مفعــول الصــك وهــل قابــل لإلفــراغ‪ ،‬ولــورود اجلــواب رفعــت اجللســة إلــى‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/7/8‬ه ـ الســاعة التاســعة صباحــا ‪ ،‬ثــم يف‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/07/08‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n      ‫‪ ،‬وفيهــا حضــر مــن املدعــن الثالثــة مــن ورثــة ‪ .....‬وحضــر املتداخــل‪،‬‬\n      ‫كمــا حضــر مــن بقيــة الورثــة وارث الزوجــة ‪ ،.....‬ســعودي اجلنســية ‪،‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وقــرر بطوعــه واختيــاره قائــا ‪ :‬إننــي‬\n      ‫بصفتــي وارثــا لوالدتــي ‪ .....‬وهــي زوجــة املالــك ‪ ، .....‬أقــرر أمامكــم‬\n      ‫طائعــا مختــارا بأنــي قــد بعــت نصيبــي مــن األرض محــل الدعــوى العائــدة‬\n      ‫لــزوج والدتــي املتوفــى ‪ ......‬علــى املتداخــل احلاضــر ‪ .....‬مببلــغ إجمالــي‬\n      ‫لــأرض قــدره أربعمئــة وخمســن ألــف مبــا فيهــا الداللــة ‪ ،‬وال مانــع لــدي‬\n      ‫مــن إفــراغ العقــار باســم املتداخــل يف أي وقــت ‪ ،‬وتســليم الورثــة حقوقهــم‬\n      ‫منهــا ‪ .‬هكــذا أقــر ‪ .‬كمــا حضــر اجللســة ‪ ، .....‬ســعودي اجلنســية ‪،‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وقــرر بطوعــه واختيــاره قائال ‪ :‬بصفتي‬\n      ‫وارثــا لوالدتــي ‪ .....‬وهــي بنــت املالــك املتوفــى والــد املدعــن ‪ ، ....‬أقــرر‬\n      ‫أمامكــم طائعــا مختــارا بأنــي قــد بعــت نصيبــي مــن األرض محــل‬\n      ‫الدعــوى العائــدة لــزوج والدتــي املتوفــى ‪ ......‬علــى املتداخــل احلاضــر ‪.....‬‬\n      ‫مببلــغ إجمالــي لــأرض قــدره أربعمئــة وخمســن ألــف مبــا فيهــا الداللــة‪،‬‬\n      ‫وال مانــع لــدي مــن إفــراغ العقــار باســمه ‪ ،‬وتســليم الورثــة حقوقهــم منهــا‬\n      ‫‪ .‬هكــذا أقــر ‪ .‬وبإقــرار األخيريــن يكــون جميــع الورثــة األحيــاء وورثــة‬\n      ‫املتوفــن منهــم قــد حضــروا‪ ،‬وأقــروا بالبيــع إمــا أصالــة أو وكالــة ‪ ،‬وأنه‬\n      ‫ال مانــع لديهــم مــن إفــراغ األرض محــل الدعــوى للمتداخــل احلاضــر ‪،‬‬\n      ‫وكان قــد مت إرســال الصــك إلــى كتابــة العــدل االولــى باملدينــة‬\n\n\n‫‪383‬‬\n\f‫للكشــف عــن ســجل الصــك ‪ ،‬واالستفســار عــن ســريان مفعولــه ‪ ،‬ولــم‬\n‫يردنــا اجلــواب منهــم حتــى موعــد هــذه اجللســة ‪ ،‬لــذا جــرى رفــع اجللســة‬\n‫إلــى يــوم الســبت املوافــق ‪1433/09/02‬ه ـ الســاعة احلاديــة عشــر ‪ .‬ثــم يف‬\n‫يــوم الســبت املوافق‪1433/09/02‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــر صباحـ ًا ‪ ،‬وفيهــا حضــر املدعــن أصالــة ووكالــة ‪ ،.....، .....‬و‪.....‬‬\n‫‪ ،‬كمــا حضــر املتداخــل ‪ ، .....‬ولــم يحضــر املدعــى عليهمــا ‪ ،‬ولــم أجــد‬\n‫يف طيــات املعاملــة مــا يفيــد تبلغهمــا ‪ ،‬وفيهــا جــرى اإلطــاع علــى اإلفــادة‬\n‫علــى الصــك محــل الدعــوى والــواردة مــن كتابــة العــدل األولــى باملدينــة‬\n‫املنــورة برقــم ‪ 1324745‬وتاريــخ ‪1433/7/19‬ه ـ واملتضمنــة ‪ :‬أن الصــك‬\n‫مطابقــة لســجله وســاري مفعولــه ‪ .‬أ ‪ .‬ه ـ ‪ .‬كمــا أحضــر املتداخل الشــيك‬\n‫رقم ‪ 861488‬يف ‪1433/9/12‬هـ والصادر من مصرف ‪ .....‬واملتضمن‬\n‫ـاء علــى مــا‬\n             ‫مبلــغ أربعمائــة وثمانيــة وثالثــون ألــف وخمســمائة ريــال ‪ .‬بنـ ً‬\n‫تقــدم مــن الدعــوى وإجابــات املدعــى عليهمــا ‪ ،‬وبنــاء علــى إقــرار املدعــي‬\n‫يف اجللســة اخلامســة ‪ ،‬وألن املدعــى عليــه حضــر اجللســة األولــى واجللســة‬\n‫اخلامســة ولكنــه عنــد حتريــر محضــر ضبــط اجللســة يخــرج مــن غيــر‬\n‫توقيــع ‪ ،‬لــذا فقــد توجــه لــي إحضــار البينــة علــى البيــع ‪ ،‬وألن جميــع‬\n‫الورثــة حضــروا وأقــروا لــدي بالبيــع علــى املتداخــل احلاضــر مبــا فيهــم‬\n‫املدعــى عليــه أصالــة ووكالــة ‪ ،‬وبنــاء علــى مــا شــهد بــه الشــاهد ‪ .....‬يف‬\n‫اجللســة الرابعــة واملعــدل طبــق األصــول الشــرعية‪ ،‬وبنــاء علــى اليمــن‬\n‫املتممــة لهــذه البينــة ‪ ،‬وملــا يف مســند اإلمــام أحمــد مــن حديــث أبــي‬\n‫هريــرة رضــي اهلل عنــه أن النبــي صلــى عليــه وســلم قضــى بالشــاهد‬\n‫واليمــن ‪ ،‬فقــد ثبــت لــدي بيــع جميــع ورثــة ‪ .....‬وورثــة ورثتــه املتوفــن مبــا‬\n‫فيهــم املدعــى عليهمــا ‪ ،‬لــأرض العائــدة ملورثيهــم واململوكــة لهــم‬\n\n\n                                                                                         ‫‪384‬‬\n\f      ‫بالصــك رقــم ‪ 1/ 750‬يف ‪1400/06/22‬ه ـ علــى ‪ .....‬بيعـ ًا صحيحـ ًا حــال‬\n      ‫ســامتهم وصحــة تصرفاتهــم بثمــن قــدره أربعمائــة وثمانيــة وثالثــون‬\n      ‫ألــف وخمســمائة ريــال ‪ ،‬وحكمــت بصحتــه ولزومــه علــى الورثــة‪،‬‬\n      ‫وحكمــت علــى املدعــى عليهمــا الغائبــن بذلــك ‪ ،‬وقــررت إفــراغ الصــك‬\n      ‫محــل الدعــوى باســم املتداخــل بعــد اكتســاب احلكــم القطعيــة ‪،‬‬\n      ‫وتقســيم املبلــغ علــى الورثــة كل حســب نصيبــه الشــرعي ‪ ،‬وإيــداع‬\n      ‫نصيــب مــن يرفــض االســتالم لبيــت مــال احملكمــة ‪ ،‬كمــا قــررت بعــث‬\n      ‫نســخة من هذا احلكم للمدعى عليهما الغائبني ‪ .....‬و‪ ، .....‬وإفهامهما‬\n      ‫بــأن لهمــا حــق االعتــراض علــى احلكــم ملــدة شــهر كامــل مــن تاريــخ‬\n      ‫اســتالمها لصــورة الصــك ‪ ،‬وأنهمــا إن لــم يقدمــا الئحــة اعتراضيــة‬\n      ‫خالل تلك املدة ‪ ،‬فإنه يسقط حقهما يف طلب االستئناف ‪ ،‬ويكتسب‬\n      ‫احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آله وصحبه وسلم ‪ .‬حرر يف ‪1433/09/02‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القائــم بعمــل الشــيخ ‪ : .....‬فقــد‬\n      ‫متــت الكتابــة لقســم احملضريــن باخلطــاب رقــم ‪ 331746158‬يف‬\n      ‫‪1433/9/24‬هـ واخلطاب رقم ‪ 331746207‬يف ‪1433/9/24‬هـ لتسليم‬\n      ‫احملكــوم عليهمــا‪ .....‬و‪ .....‬صــورة مــن صــك احلكــم لتقــدمي مــا لديهمــا‬\n      ‫خــال املــدة النظاميــة فأعيــد إلينــا اجلــواب من قســم احملضريــن متضمن ًا‬\n      ‫بأنــه مت االنتقــال ملوقــع املدعــى عليهمــا ولــم يجــدا أحــد ًا ومت الوقــوف‬\n      ‫مبرافقــة املدعــي والتــردد عــدة مــرات بأوقــات مختلفــة ولــم يجــدوا أحــد ًا‬\n      ‫ومت الوقــوف مــع عمــدة احلــي ونائبــه كمــا متــت الكتابــة لهمــا مــرة‬\n      ‫أخــرى باخلطــاب رقــم ‪ 331951176‬يف ‪1433/11/3‬ه ـ واخلطــاب رقــم‬\n      ‫‪ 331950593‬يف ‪1433/11/3‬ه ـ فــورد اجلــواب مــن قســم احملضريــن‬\n\n\n‫‪385‬‬\n\f‫متضمنـ ًا بأنــه مت االنتقــال ملوقــع املدعــى عليهمــا والتــردد عــدة مــرات وال‬\n‫يجيــب أحــد داخــل املنــزل وقــام شــخص باالتصــال بنــا وذكــر أنه وكيل‬\n‫املدعــى عليهمــا واســتعد باحلضــور الســتالم اخلطــاب ولكنــه لــم يحضــر‬\n‫ومت االتصــال عليــه ولــم يجــب كمــا وجــد مصادقــة عمــدة احلــي متضمنـ ًا‬\n‫‪ .‬أصــادق علــى أقــوال احملضــر حيــث مت الوقــوف علــى منــزل املذكوريــن‬\n‫حســب العنــوان املشــار إليــه ولــم جنــد أحــد‪ .‬كمــا متــت الكتابــة لســعادة‬\n‫مديــر شــرطة قبــاء باملدينــة املنــورة باخلطــاب رقــم ‪ 3439676‬و اخلطــاب‬\n‫رقــم ‪ 3439735‬لتســليم املدعــى عليهمــا صــورة مــن صــك احلكــم لتقــدمي‬\n‫مــا لديهمــا خــال املــدة النظاميــة فــورد اجلــواب مــن مديــر مركــز شــرطة‬\n‫قبــاء باملدينــة برقــم ‪ 464/13/6‬يف ‪1434/1/24‬هـ ورقم ‪463/13/6‬يف‬\n‫‪1434/1/24‬ه ـ متضمنـ ًا بأنــه مت الوقــوف مــع منــدوب احملكمــة ســابق ًا‬\n‫أكثــر مــن مــرة ومت طــرق البــاب ولــم يتجــاوب معنــا وأفــاد بعض ســكان‬\n‫احلــي بــأن ‪ .....‬انتقــل إلــى حــي‪ ......‬لــذا فقــد أمــرت ببعــث املعاملــة إلــى‬\n‫محكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪..‬‬\n‫فلــدي أنــا ‪ .....‬املــازم القضائــي يف احملكمــة العامــة باملدينــة املنــورة‬\n‫يــوم األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n‫عشــرة وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ال مــن ‪ ..... ..... ..... ..... .....‬أوالد‬\n                                         ‫‪ .....‬عــن نفســه ‪ ،‬وبوكالتــه عــن ك ً‬\n‫‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n‫املنــورة برقــم ‪ 38472‬وتاريــخ ‪1431/06/08‬ه ـ وجــرى تســليمه الشــيك‬\n‫املســحوب علــى مصــرف ‪ .....‬برقــم ‪ 995383‬وتاريــخ ‪2013/02/18‬م‬\n\n\n                                                                                         ‫‪386‬‬\n\f      ‫مببلــغ وقــدره مائتــان وخمســة وأربعــون ألفـ ًا وثالثمائــة وأربعــة وعشــرون‬\n      ‫ريــا ًال وثمانيــة وســتون هللــة ‪ . ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/10‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪..‬‬\n      ‫فلــدي أنــا ‪ .....‬املــازم القضائــي يف احملكمــة العامــة باملدينــة املنــورة‬\n      ‫ففــي يــوم األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الواحــدة بعــد الظهــر ‪ ،‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ، .....‬وجــرى تســليمه الشــيك املســحوب علــى‬\n      ‫مصــرف ‪ .....‬برقــم ‪ 995384‬وتاريــخ ‪2013/02/18‬م مببلــغ وقــدره‬\n      ‫الفـ ًا وســتمائة وأربعــة ريــاالت وتســع وأربعــون هللــة ‪،‬ويف‬\n                                                                    ‫أربعــة وأربعــون ً‬\n      ‫يــوم األحــد املوافق‪1434/04/14‬ه ـ افتتحــت اجللســة الســاعة الواحــدة‬\n      ‫‪ ،‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫اصالــة عــن نفســه ‪،‬ووكالــة عــن كل مــن ‪ .....‬و‪ .....‬بالوكالــة رقــم‬\n      ‫‪ 57739‬يف ‪1432/9/24‬ه ـ صــادرة مــن كتابــة عــدل املدينــة املنــورة‬\n      ‫وجــرى تســليمه الشــيك املســحوب علــى مصــرف ‪ .....‬برقــم ‪995388‬‬\n      ‫وتاريــخ ‪2013/02/18‬م مببلــغ وقــدره ســبعة آالف وثمامنائــة وثالثــة‬\n      ‫وســبعون ريــال وهــو نصيــب ‪ .....‬ونصيــب ‪ .....‬ونصيــب‪......‬ويف يــوم األثنــن‬\n      ‫املوافق‪1434/04/15‬ه ـ افتتحــت اجللســة الســاعة التاســعة ‪ ،‬وفيهــا‬\n      ‫حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬اصالــة‬\n      ‫عــن نفســه وجــرى تســليمه الشــيك املســحوب علــى مصــرف ‪ .....‬برقــم‬\n      ‫‪ 995390‬وتاريــخ ‪2013/02/18‬م مببلــغ وقــدره ثالثــة الــف وتســعة مائــة‬\n      ‫وســتة وثالثــون ريــال ‪ .‬ويف هــذا اليــوم الثالثــاء ‪1434/04/23‬هـ افتتحت‬\n      ‫اجللســة وفيهــا حضــر كل مــن‪ ..... :‬صاحــب الســجل املدنــي رقــم ‪.....‬‬\n\n\n‫‪387‬‬\n\f‫و‪ .....‬صاحــب الســجل املدنــي رقــم ‪ .....‬وجــرى تســليمهما الشــيكني‬\n‫رقــم ‪ 995387‬يف ‪2013/02/18‬م املســحوب علــى مصــرف‪ .....‬وميثــل‬\n‫مبلــغ وقــدره ســتة آالف وثمامنائــة وواحــد وخمســون ريــا ًال فقــط الغيــر‬\n‫ألمــر ‪ .....‬والشــيك رقــم ‪ 995393‬يف ‪2013/02/18‬م املســحوب علــى‬\n‫مصــرف ‪ .....‬وميثــل مبلــغ وقــدره ســبعة وأربعــون ألــف ومائتــان وتســعة‬\n‫وثالثــون ريــا ًال فقــط ال غيــر ألمــر‪، .....‬وحتــى ال يخفــى جــرى إثباتــه ويف‬\n‫هــذا اليــوم االربعاء‪1434/05/01‬ه ـ افتتحــت اجللســة وفيهــا حضــر كل‬\n‫مــن ‪ ..... :‬رقــم ســجل ‪ .....‬وجــرى تســليمها الشــيك رقــم ‪995392‬يف‪18‬‬\n‫‪2013/2/‬م ‪ .‬املســحوب علــى مصــرف ‪ .....‬وميثــل مبلــغ وقــدره ثالثــة‬\n‫وعشــرون ألفـ ًا وســتمائة وعشــرون ريــال وخمســة وثمانــون هللــه فقــط ال‬\n‫غيــر ‪ .‬وكمــا حضــر‪ .....‬ســجل مدنــي رقــم ‪ .....‬وجــرى تســليمه الشــيك‬\n‫رقــم ‪ 995391‬يف ‪2013/02/18‬م ‪ .‬املســحوب علــى مصــرف ‪ .....‬وميثــل‬\n‫مبلــغ وقــدره ثالثــة آالف وتســعمائة وســتة وثالثــون ريــاال وأربعــة وســتون‬\n‫هللــه فقــط ال غيــر ‪ .‬وحتــى ال يخفــى جــرى إثباتــه ثــم لــدي أنــا ‪ .....‬يف يــوم‬\n‫االربعاء‪1434/06/07‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة ظهــر ًا‬\n‫‪ ،‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n‫وجرى تســليمه الشــيك رقم ‪99539‬يف ‪2013/02/18‬م ‪ .‬املســحوب على‬\n‫مصــرف ‪ .....‬وميثــل مبلــغ وقــدره ثالثــة آالف وتســعة مائــة وســتة وثالثــن‬\n‫ريــا ًال فقــط ‪ ،‬وحتــى ال يخفــى جــرى حتريــره يف ‪1434/06/07‬ه ـ وباهلل‬\n       ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n\n\n                                                                                          ‫‪388‬‬\n\f      ‫الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي باحملكمــة العامــة باملدينــة‬\n      ‫املنــورة‪ ،‬واملســجل بع ــدد ‪ 33411128‬وتاريــخ ‪1433/9/13‬هـ‪ ،‬املتضمن‬\n      ‫دعــوى ورثــة ‪ .....‬ضــد ‪ ،.....‬احملكــوم في ــه مبــا دون باطنــه‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ ،‬واهلل املوفــق‬\n                      ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪389‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":374,"source_page_end":389,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dcf83cc7db62ea8b334857a41532febeb831c5346d2c56ecf5565e354a463aee","normalized_text_hash":"9ccda006723890ad41bf969f672739c71ee40978498df6b8ec78da438eca4405","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p374-33411128"},{"id":"5661a8b0-4ed8-5c85-8f41-484ff17bfc1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -مطالبة املدعية ببيع عقار مورثها وإعطائها نصيبهما الشرعي -تخلف املدعى عليهم عن احلضور عدا واحد -مصادقة املدعى عليه على الدعوى عدا صفة العقار (أرض فضاء) -صعوبة تقسيم العقار محل الدعوى -بيع العقار باملزاد العلني وقسمة ثمنه بن الورثة بحسب أنصابهم الشرعية -حكم غيابي والغائب على حجته متى حضر .","document_number":"33439471","case_number":"56230207","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/25","year":"1434","subject":"قسمة تركة -مطالبة املدعية ببيع عقار مورثها وإعطائها نصيبهما الشرعي -تخلف املدعى عليهم عن احلضور عدا واحد -مصادقة املدعى عليه على الدعوى عدا صفة العقار (أرض فضاء) -صعوبة تقسيم العقار محل الدعوى -بيع العقار باملزاد العلني وقسمة ثمنه بن الورثة بحسب أنصابهم الشرعية -حكم غيابي والغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33439471 :‬تاريخه‪1433/10/25 :‬هـ‬\n                   ‫رقم الدعوى‪56230207 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34301102‬تاريخه‪1434/8/21 :‬هـ‬\n\n\n ‫قســمة تركــة‪ -‬مطالبــة املدعيــة ببيع عقار مورثهــا وإعطائها نصيبهما‬\n ‫الشــرعي‪ -‬تخلــف املدعــى عليهــم عــن احلضــور عــدا واحــد‪ -‬مصادقــة‬\n ‫املدعــى عليــه علــى الدعــوى عــدا صفــة العقــار (أرض فضــاء)‪ -‬صعوبــة‬\n ‫تقســيم العقــار محــل الدعــوى ‪ -‬بيــع العقــار باملــزاد العلنــي وقســمة‬\n ‫ثمنــه بــن الورثــة بحســب أنصابهــم الشــرعية‪ -‬حكــم غيابــي والغائــب‬\n                                                  ‫علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n ‫‪ .1‬جــاء يف املقنــع ‪( 46/29‬وقســمة األمــاك جائــزة وهــي نوعــان قســمة‬\n ‫تراضــي وهــي مــا فيهــا ضــرر أورد عــوض من أحدهما كالــدور الصغار)‪.‬‬\n ‫‪ .2‬جاء يف الكايف ‪( 336/4‬وإذا كان يف القســمة رد عوض فهي بيع ألن‬\n ‫صاحــب الــرد بــذل املــال عوض ـ ًا عمــا حصــل لــه مــن حــق شــريكه وهــذا‬\n                                                                   ‫هــو البيــع)‪.‬‬\n ‫‪ .3‬جــاء يف اإلنصــاف ‪( 48/29‬مــن دعــى شــريكه إلــى البيــع يف قســمة‬\n             ‫التراضــي أجبــر فــإن أبــى بيــع عليهمــا وقســم الثمــن ‪.)...‬‬\n ‫‪ .4‬جــاء يف قواعــد ابــن رجــب ص ‪( 348‬فأمــا مــاال يقبــل القســمة فإنــه‬\n ‫يجبــر أحدهمــا علــى بيعــه إذا طلــب اآلخــر بيعــه نــص أحمــد علــى‬\n                                                                         ‫ذلــك)‪.‬‬\n         ‫‪ .5‬املادة ‪ 6/34‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n         ‫‪ .6‬املادة ‪ 4/56‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n                                                                                    ‫‪390‬‬\n\f      ‫ادعــت املدعيــة ضــد املدعــى عليهــم بأنــه تــويف والدهــا وانحصــر ارثــه‬\n      ‫يف زوجتيــه ويف أوالده ‪ ..........‬ولقــد خلــف مصنعـ ًا يقــع مبكــة املكرمــة‬\n      ‫واململــوك ملورثهــم مبوجــب الصــك الصــادر مــن هــذه احملكمــة وتطلــب‬\n      ‫احلكــم علــى الورثــة ببيــع ذلــك العقــار وإعطائهــا نصيبهــا منــه هكــذا‬\n      ‫ادعــت‪ ،‬لــم يحضــر مــن املدعــى عليهــم إال ‪ .....‬والســير يف القضيــة بنــاء‬\n      ‫علــى الالئحــة السادســة مــن املــادة الرابعــة والثالثــن مــن نظــام املرافعات‬\n      ‫الشــرعية‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وعــدم ممانعته‬\n      ‫مــن بيــع العقــار وتقســيم ثمنــه علــى الورثــة وأضــاف بــأن العقــار لــم يعــد‬\n      ‫مصنع ـ ًا وأصبــح أرض ـ ًا فضــاء‪ ،‬جــرى االستفســار عــن ســريان مفعــول‬\n      ‫صــك ملكيــة العقــار فــورد اجلــواب مــن مصــدره بــأن ســاري املفعــول‬\n      ‫ومطابــق لســجله‪ ،‬الكتابــة لهيئــة النظــر للوقــوف علــى العقــار محــل‬\n      ‫الدعــوى واإلفــادة هــل يف قســمته ضــرر أو رد عــوض فــورد جوابهــم‬\n      ‫املتضمــن بأنــه ال ميكــن قســمة العقــار علــى الورثــة ألنــه حــوش علــي‬\n      ‫شــارعني وهــو ســكني‪ ،‬ملــا تقــدم صــدر احلكــم ببيــع العقــار املوصــوف‬\n      ‫يف الدعــوى بواســطة املــزاد العلنــي ومــن ثــم قســمة ثمنــه بــن الورثــة‬\n      ‫بحســب أنصبائهــم الشــرعية‪ ،‬واحلكــم غيابــي يف حــق باقــي املدعــي‬\n      ‫عليهــم وســوف يتــم تبليغهــم باحلكــم والغائــب علــى حجتــه متــى حضــر‬\n      ‫اســتناد ًا علــى الالئحــة الرابعــة مــن املــادة السادســة واخلمســن مــن نظــام‬\n      ‫املرافعــات الشــرعية‪ ،‬بعــرض احلكــم علــى املتداعيــن قــررا القناعــة‬\n      ‫بــه‪ ،‬صــدق احلكــم بعــد مداولــة مــن الدائــرة احلقوقيــة األولــى مبحكمــة‬\n                                             ‫االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n‫‪391‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 56230207‬وتاريــخ ‪1432/03/04‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3222104‬وتاريــخ ‪1432/02/29‬ه ـ املتعلقــة‬\n‫بدعوى ‪.....‬ضد ورثة ‪.....‬ففي هذا اليوم الثالثاء املوافق‪1432/05/22‬هـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 10 : 50‬وفيهــا حضــرت املدعيــة ‪..... /‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬وحضــر حلضورهــا مــن املدعــى‬\n‫عليهــم املدعــو ‪ ...../‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪.....‬واملعــرف‬\n‫باملدعيــة وبنــاء علــى الالئحــة السادســة مــن املــادة الرابعــة والثالثــن‬\n‫مــن نظــام املرافعــات الشــرعية فقــد أذنــت للمدعيــة بتحريــر دعواهــا‬\n‫فادعــت قائلــة يف حتريــر دعواهــا لقــد تــويف والــدي ‪ ...‬وانحصــر ارثــه‬\n‫مبوجــب صــك حصــر اإلرث الصــادر مــن هــذه احملكمــة برقــم ‪1101‬‬\n‫يف ‪1397/8/14‬ه ـ املتضمــن وفاتــه يف ‪1397/4/28‬ه ـ وانحصــار ارثــه‬\n‫الشــرعي يف زوجتيــه الباقيتــن علــى عقــد نكاحــه إلــى حــن وفاتــه ‪......‬‬\n‫و‪.....‬ويف أوالده ‪..... ..... ..... .....‬ولقــد خلــف لنــا والدنــا املذكــور مصنعـ ًا‬\n‫يقــع مبكــة املكرمــة باملســفلة احملــدود شــرقا ملــك ‪ .....‬وغربــا الســكة‬\n‫النافــذة وشــماال الســكة النافــذة وبهــا بــاب وجنوبــا ملــك ‪.....‬واململــوك‬\n‫لوالدنــا مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 13/147‬يف‬\n‫‪1405/5/14‬ه ـ لــذا فإنــي أطلــب احلكــم علــى الورثــة ببيــع ذلــك العقــار‬\n‫وإعطائــي نصيبــي منــه حســب الفريضــة الشــرعية هــذه دعــواي ثــم‬\n‫ســألتها عــن باقــي الورثــة فأجابــت إن باقــي الورثــة لــم يأتــوا ولــم يحضــر‬\n\n                                                                                         ‫‪392‬‬\n\f      ‫منهــم ســوى هــذا احلاضــر ‪.....‬وأطلــب الســير يف دعــواي هــذه ألنــي‬\n      ‫متضــررة مــن حرمانــي حلقــي هكــذا قالــت ثــم عرضــت دعــوى املدعيــة‬\n      ‫علــى املدعــى عليــه احلاضــر فأجــاب قائــا إن مــا ورد يف دعــوى املدعيــة‬\n      ‫مــن وفــاة والدنــا بالتاريــخ املذكــور يف دعواهــا وانحصــار ورثتــه فيمــن‬\n      ‫ذكرتهــم بأســمائهم املدونــة يف صــك حصــر اإلرث املذكــور برقــم‬\n      ‫وتاريخــه يف الدعــوى فصحيــح ومــا ذكرتــه مــن أن والدنــا املذكــور‬\n      ‫خلــف العقــار املوصــوف يف دعواهــا بحــدوده واململــوك بالصــك الــذي‬\n      ‫ذكرتــه برقمــه وتاريخــه ومصــدره فصحيــح كذلــك وال أنكــر منــه‬\n      ‫شــيئا مطلقــا غيــر أن العقــار اآلن لــم يعــد مصنعــا كمــا ذكرتــه املدعيــة‬\n      ‫بــل أصبــح أرضــا فضــاء يف الوقــت احلاضــر وأمــا طلبهــا بيــع احملــدود‬\n      ‫املذكــور وقســمة ثمنــه وإعطائهــا نصيبهــا منــه فليــس لــدي أي مانــع‬\n      ‫يف ذلــك هكــذا أجــاب ثــم جــرى منــي اإلطــاع علــى صكــي امللكيــة‬\n      ‫وحصــر اإلرث فوجدتهمــا مطابقــن ملــا عطــف عليهمــا ثــم جــرى‬\n      ‫االستفســار عــن ســجالتهما فوردنــا جــواب مديــر الســجل باحملكمــة‬\n      ‫رقــم ‪ 32/596739‬يف ‪1432/5/23‬ه ـ املتضمــن أنــه ال يوجــد علــى‬\n      ‫ســجل الصــك رقــم ‪ 13/147‬يف ‪1405/5/14‬ه ـ أي شــرح يذكــر حتــى‬\n      ‫تاريخــه ‪1432/5/27‬ه ـ وكذلــك وردنــا جــواب مديــر الســجل رقــم‬\n      ‫‪ 32/596710‬يف ‪1432/5/23‬ه ـ املتضمــن أن صــورة الصــك رقم ‪4/27‬‬\n      ‫يف ‪1397/8/14‬ه ـ غيــر مطابقــة لســجلها نأمــل تزويدنــا بأصــل الصــك‬\n      ‫‪ .‬إ ‪ .‬ه ـ ‪ .‬ثــم قــررت الكتابــة لهيئــة النظــر للوقــوف علــى العقــار محــل‬\n      ‫الدعــوى واإلفــادة هــل يف قســمته ضــرر أو رد عــوض إضافــة إلــى طلــب‬\n      ‫صــورة مصدقــة مــن ســجل حصــر اإلرث وإلــى حــن ورود املعاملــة تأجلــت‬\n      ‫ويف يــوم الثالثــاء ‪ 1433/10/17‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n\n\n‫‪393‬‬\n\f‫املدعيــة وحضــر حلضورهــا املدعــى عليــه ‪.....‬وكانــت قــد وردتنــا إفــادة‬\n‫هيئــة النظــر ذات الــر قــم ‪ 3222104‬يف ‪1433/4/21‬ه ـ وتتضمــن فقــد‬\n‫مت الوقــوف علــى العقــار املذكــور وهــو عبــارة عــن حــوش علــى شــارعني‬\n‫وهــي ركنيــة ومت تطبيــق الصــك علــى العقــار ووجدنــا أنــه منطبــق علــى‬\n‫العقــار املذكــور وبالتالــي ال ميكــن قســمة العقــار علــى الورثــة ملــا ذكــر‬\n‫ســابق ًا ألنــه حــوش علــي شــارعني وهــو ســكني كمــا هــو موضــح أعــاه‬\n‫هــذا مــا نــراه واهلل الهــادي إلــى ســواء الســبيل والســبيل ‪.‬فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وملــا ورد يف قــرار هيئــة النظــر املرصــودة‬\n‫أعــاه وألن القســمة التــي فيهــا ضــرر هــي املعروفــة لــدى الفقهــاء بقســمة‬\n‫التراضــي قــال صاحــب املقنــع ( وقســمة األمــاك جائــزة وهــي نوعــان‬\n‫قســمة تراضــي وهــي مــا فيهــا ضــرر أورد عــوض مــن أحدهمــا كالــدور‬\n‫الصغــار ) أنظــره مــع الشــرح الكبيــر واإلنصــاف ‪ 46/29‬وقــال يف‬\n‫الــكايف ( وإذا كان يف القســمة رد عــوض فهــي بيــع ألن صاحــب‬\n‫الــرد بــذل املــال عوض ـ ًا عمــا حصــل لــه مــن حــق شــريكه وهــذا هــو‬\n‫البيــع )‪ 336/4‬وقــال صاحــب اإلنصــاف فائــدة ( مــن دعــى شــريكه‬\n‫إلــى البيــع يف قســمة التراضــي أجبــر فــإن أبــى بيــع عليهمــا وقســم الثمــن‬\n‫نقلــه امليمونــي وحنبــل وذكــره القاضــي وأصحابــه وذكــره يف اإلرشــاد‬\n‫والفصــول واإليضــاح واملســتوعب والترغيــب وغيرهــا) انظــره مــع الشــرح‬\n‫الكبيــر علــى املقنــع ‪ 48/29‬وقــال ابــن رجــب يف قواعــده ( فأمــا مــاال‬\n‫يقبــل القســمة فإنــه يجبــر أحدهمــا علــى بيعــه إذا طلــب اآلخــر بيعــه نــص‬\n‫أحمــد علــى ذلــك ) ص‪ 348‬بنــاء علــى ذلــك فقــد حكمــت ببيــع العقــار‬\n‫املوصــوف يف الدعــوى بواســطة املــزاد العلنــي ومــن ثــم قســمة ثمنــه بــن‬\n‫الورثــة بحســب أنصبائهــم الشــرعية وبذلــك حكمــت واعتبرتــه غيابي ـ ًا‬\n\n\n                                                                                       ‫‪394‬‬\n\f      ‫يف حــق باقــي املدعــي عليهــم وســوف يتــم تزويدهــم بنســخة منــه لتقــدمي‬\n      ‫مالديهــم حيالــه مــن اعتــراض خــال ثالثــن يوم ـ ًا مــن تاريــخ االســتالم‬\n      ‫والغائــب علــى حجتــه متــى حضــر اســتناد ًا علــى الالئحــة الرابعــة مــن‬\n      ‫املــادة السادســة واخلمســن مــن نظــام املرافعــات الشــرعية وبعرضــه‬\n      ‫علــى املتداعيــن احلاضريــن قــررا القناعــة بــه وبــاهلل التوفيــق حــرر يف‬\n                                                                      ‫‪1433/10/17‬ه ـ‬\n      ‫احلمــد هلل وحــده فقــد عــادت أوراق املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫برقــم ‪ 34329377‬يف ‪1434/3/10‬ه ـ وبرفقهــا قــرار مالحظــة الدائــرة‬\n      ‫احلقوقيــة األولــى ذو الرقــم ‪ 3453127‬يف ‪1434/03/02‬ه ـ ونــص‬\n      ‫احلاجــة منــه بدارســة احلكــم وصــوة ضبطــه تقــرر إعادتهــا للتمشــي‬\n      ‫باملادتــن ‪ 4/176‬واملــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية أه ـ عليــه‬\n      ‫فإنــي أجيــب أصحــاب الفضيلــة قضــاة اإلســتئناف وفقهــم اهلل تعالــى‬\n      ‫لــكل خيــر بأنــه بالرجــوع إلــى الالئحــة الرابعــة للمــادة ‪ 176‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ونصهــا «إذا كان احلكــم غيابي ـ ًا فيكــون تبليــغ‬\n      ‫احملكــوم عليــه أو وكيلــه نســخة احلكــم يف محــل إقامتــه أو عملــه‬\n      ‫وفــق إجــراءات التبليــغ ويبــدأ ميعــاد االعتــراض علــى احلكــم مــن تاريــخ‬\n      ‫التبليــغ وإذا لــم يقــدم اعتراضــه خــال املــدة املقــررة نظام ـ ًا يكتســب‬\n      ‫احلكــم القطعيــة وفــق املــادة ‪ »178‬والتــي نصهــا مــدة االعتــراض بطلــب‬\n      ‫التمييــز ثالثــون يومـ ًا فــإذا لــم يقــدم اخلصــم اعتراضـ ًا خــال هــذه املــدة‬\n      ‫ســقط حقــه يف طلــب التمييــز وعلــى احملكمــة اتخــاذ محضــر بذبــك‬\n      ‫يف ضبــط القضيــة والتهميــش علــى الصــك وســجله بــأن احلكــم قــد‬\n      ‫اكتســب القطعيــة وغيــر خــاف علــى أصحــاب الفضيلــة وفقهــم اهلل‬\n      ‫تعالــى بــأن مــا أشــير إليــه يف املادتــن املذكورتــن أعــاه هــي أمــور‬\n\n\n‫‪395‬‬\n\f‫إجرائيــة املقصــد منهــا حفــظ حــق احملكــوم عليــه الغائــب وغيــر خــاف‬\n‫علــى أصحــاب الفضيلــة كذلــك مــا جــاء يف املــادة السادســة مــن نظــام‬\n‫ا إذا نــص النظــام‬  ‫املرافعــات الشــرعية ونصهــا يكــون اإلجــراء باط ـ ً‬\n‫علــى بطالنــه أو شــابه عيــب تخلــف بســببه الغــرض مــن اإلجــراءات وال‬\n‫يحكــم بالبطــان إذا ثبــت حتقــق الغايــة مــن اإلجــراء وعليــه فإنــه ال‬\n‫ا فإنــه ال يعتــد بــه وجتــب‬  ‫ريــب أن األصــل أن اإلجــراء إذا وقــع باط ـ ً‬\n‫إعادتــه علــى وجــه الصحــة مــا أمكــن لكــن ثــم حالتــان يجــب حلظهمــا‬\n‫عنــد النظــر يف البطــان اإلجرائــي احلالــة األولــى تصحيــح اإلجــراء مــا‬\n‫أمكــن فــإذا أمكــن حمــل اإلجــراء الــذي يتجــه بطالنــه علــى إجــراء‬\n‫صحيــح حمــل عليــه وأعمــل فاإلجــراء مهمــا أمكــن حملــه علــى وجــه‬\n‫صحيــح لــم يصــر إلــى بطالنــه فمــن املقــرر عنــد الفقهــاء أن إعمــال‬\n‫الــكالم أولــى مــن إهمالــه ومثلــه اإلجــراء املتخــذ احلالــة الثانيــة تصحيــح‬\n‫اإلجــراء الــذي حتقــق الغــرض منــه ولــو توجــه فيــه البطــان وهــذه احلالــة‬\n‫اســتثناء يــرد علــى البطــان اإلجرائــي فــإذا حتقــق الغــرض والغايــة مــن‬\n‫اإلجــراء حمــل علــى الصحــة حفاظ ـ ًا علــى حقــوق املترافعــن وصيانــة‬\n‫للقضــاء مــن الضيــاع أخيــر ًا بينــت الفقــرة األولــى مــن الالئحــة التنفيذيــة‬\n‫للمــادة املذكــورة ســلف ًا أن الــذي يقــرر حتقــق الغايــة مــن اإلجــراء هــو‬\n‫ناظــر القضيــة ونصهــا «الــذي يقــدر حتقــق الغايــة مــن اإلجــراء هــو ناظــر‬\n‫القضيــة» وعليــه فلــم يظهــر مــا يؤثــر علــى مــا أجريتــه وأمــرت بإعــادة‬\n‫أوراق املعاملــة حملكمــة اإلســئتناف لتدقيقهــا وبــاهلل التوفيــق‪ .‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/04/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n\n\n                                                                                       ‫‪396‬‬\n\f      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪34329377‬‬\n      ‫وتاريــخ ‪1434/8/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪.....‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل بعــدد‬\n      ‫‪ 33439471‬وتاريــخ ‪1433/10/25‬هـ ـ واملتضمــن دعوى‪..... /‬ضد‪ /‬ورثة‬\n      ‫‪.....‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد االجــراء االخيــر واهلل املوفــق‪ .‬وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪397‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":390,"source_page_end":397,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"45136f27a14d0cad42d4a29c45bb1fb8825620f01f2515308ca070c537689768","normalized_text_hash":"32d5ac0c677ecb2733d9295de27f4f4dc36d3dc49e0121276f8509df50c9a3aa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p390-33439471"},{"id":"1903fe54-d013-5f6f-9d81-7d946bdabc8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة املورث والتركة عقار -وصية -املطالبة ببيع العقار واعطاء كل وارث نصيبه الشرعي -مصادقة املدعى عليهم (الورثة) على الدعوى -وجود قاصر ضمن الورثة -بيع العقار باملزاد العلني وتسليم كل وارث نصيبه شرع ا -رفع احلكم إلى محكمة اإلستئناف لوجود قاصر ضمن الورثة .","document_number":"33461017","case_number":"33208497","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"قسمة تركة -وفاة املورث والتركة عقار -وصية -املطالبة ببيع العقار واعطاء كل وارث نصيبه الشرعي -مصادقة املدعى عليهم (الورثة) على الدعوى -وجود قاصر ضمن الورثة -بيع العقار باملزاد العلني وتسليم كل وارث نصيبه شرع ا -رفع احلكم إلى محكمة اإلستئناف لوجود قاصر ضمن الورثة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33461017 :‬تاريخه‪1433/11/21 :‬هـ‬\n                    ‫رقم الدعوى‪33208497 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3426645‬تاريخه‪1434/2/2 :‬هـ‬\n\n\n ‫قســمة تركــة‪ -‬وفــاة املــورث والتركــة عقــار‪ -‬وصيــة‪ -‬املطالبــة ببيــع‬\n ‫العقــار واعطــاء كل وارث نصيبــه الشــرعي‪ -‬مصادقــة املدعــى عليهــم‬\n ‫(الورثــة) علــى الدعــوى‪ -‬وجــود قاصــر ضمــن الورثــة‪ -‬بيــع العقــار باملزاد‬\n ‫العلنــي وتســليم كل وارث نصيبــه شــرع ًا‪ -‬رفــع احلكــم إلــى محكمــة‬\n                                   ‫اإلســتئناف لوجــود قاصــر ضمــن الورثــة ‪.‬‬\n\n\n\n\n ‫مطالــب أولــى النهــى (ومــن دعــا شــريكه فيهــا أي قســمة التراضــي إلــى‬\n ‫بيــع أجبــر علــى البيــع معــه فــإن أبــى أي شــريكه مــن بيــع معــه بيــع‬\n ‫أي باعــه حاكــم عليهمــا وقســم الثمــن بينهمــا علــى قــدر حصيتهمــا‬\n                                                                       ‫نصــا) ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي وكالــة ضــد املدعــى عليهــم بــأن مــورث موكلتــه قد تويف‬\n ‫وخلــف عقــار ًا مملــوك ًا لــه بصــك شــرعي ويطلــب بيــع العقــار وإعطــاء‬\n ‫كل وارث نصيبــه‪ ،‬أجــاب املدعــى عليهــم باملصادقــة علــى الدعــوى‬\n ‫ا وعــدم ممانعتهــم مــن بيــع العقــار‪ ،‬ليــس علــى مورثهــم‬\n                                                             ‫جملــة وتفصي ـ ً‬\n ‫ديــن وال وصيــة‪ ،‬أحــد الورثــة وهــي والدتــه توفيــت وأوصــت بالثلــث مــن‬\n ‫مالهــا‪ ،‬جــرى االستفســار عــن صــك امللكيــة فــورد اجلــواب بأنــه مطابــق‬\n\n                                                                                   ‫‪398‬‬\n\f      ‫لســجله‪ ،‬مبــا أن الورثــة جميعــا ًيرغبــون ببيــع العقــار ولكثــرة الورثــة‬\n      ‫وصعوبــة قســمته بينهــم‪ ،‬وألنــه يصــار إلــى البيــع مــع عــدم إمــكان‬\n      ‫القســمة‪ ،‬وملــا قــرره الفقهــاء مــن وجــوب إجابــة مــن طلــب القســمة إلزالــة‬\n      ‫ضــرر الشــركة حيــث جــاء يف مطالــب أولــى النهــى (ومــن دعــا شــريكه‬\n      ‫فيهــا أي قســمة التراضــي إلــى بيــع أجبــر علــى البيــع معــه فــإن أبــى أي‬\n      ‫شــريكه)‪ ،‬ونظــر ًا لثبــوت وصيــة والــدة مالــك العقــار بالثلــث ونصيبهــا‬\n      ‫منــه الســدس‪ ،‬ملــا تقــدم احلكــم ببيــع العقــار باملــزاد العلني وتســليم كل‬\n      ‫وارث نصيبــه منــه حســب الوجــه الشــرعي بعــد إحــراز الثلــث مــن نصيــب‬\n      ‫والدتــه وهــو ثلــث الســدس وحفظــه يف بيــت املــال لصالــح وصيتهــا‪ ،‬قنــع‬\n      ‫األطــراف باحلكــم‪ ،‬وألن مــن ضمــن الورثــة قاصــر وللوصيــة رفعــت‬\n                                 ‫املعاملــة حملكمــة االســتئناف‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪،‬‬\n      ‫فلــدي ‪ ...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n      ‫املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة برقــم ‪ 33208497‬يف ‪1433/3/23‬ه ـ املقيــدة يف احملكمــة‬\n      ‫برقم ‪ 33554752‬يف ‪1433/3/23‬هـ ففي يوم االثنني ‪1433/11/15‬هـ‬\n      ‫الســاعة احلاديــة عشــرة والنصــف صباح ـ ًا افتتحــت اجللســة للنظــر يف‬\n      ‫دعوى ‪ ...‬ضد ورثة ‪ ...‬وفيها حضر ‪ ...‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بغــرب مكــة برقــم ‪ 33117836‬يف ‪1433/6/15‬ه ـ واملخــول لــه يف‬\n\n‫‪399‬‬\n\f‫الوكالــة حــق إقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن‬\n‫وإحضــار الشــهود واجلــرح والتعديــل وقبــول األحــكام واالعتــراض‬\n‫عليهــا وطلــب االســتئناف ‪...‬الــخ وحضــر حلضــوره ول‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬باألصالــة عــن نفســه وبالوكالــة عــن‬\n‫كل مــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬و‪ ...‬و‪ ...‬و‪...‬‬\n‫و‪ ...‬و‪ ...‬و‪ ...‬بنــات ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة مبكــة املكرمــة برقــم ‪ 2149‬يف ‪1432/1/20‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق إقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن‬\n‫وإحضــار الشــهود واجلــرح والتعديــل وقبــول األحــكام واالعتــراض‬\n‫عليهــا وطلــب االســتئناف ‪...‬الــخ واملذكــورون أعــاه عــدا املدعي وكالة‬\n‫مــع ‪ ...‬هــم جميعـ ًا ورثــة ‪ ...‬وذلــك مبوجــب صــك حصــر ورثــة الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 9/5/5‬يف ‪1413/1/7‬ه ـ وبالوكالــة عــن كل‬\n‫مــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة غــرب مكــة برقــم ‪ .......‬يف‪1431/2/24‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق إقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن‬\n‫وإحضــار الشــهود واجلــرح والتعديــل وقبــول األحــكام واالعتــراض عليها‬\n‫وطلــب االســتئناف ‪...‬الــخ وبالوكالــة عــن ‪ .....‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة مبكــة املكرمــة برقــم ‪ 6782‬يف ‪1431/2/29‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق البيــع واإلفــراغ واالســتالم ‪...‬الــخ وبالوكالــة عــن أمــه ‪...‬‬\n\n\n                                                                                    ‫‪400‬‬\n\f      ‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬أصالــة عــن نفســها‬\n      ‫وبصفتهــا الوليــة علــى ابنهــا القاصــر ‪ ...‬املولــود يف عــام ‪1425‬ه ـ مبوجــب‬\n      ‫الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 9/100/281‬يف‬\n      ‫‪1430/6/13‬ه ـ مبوجــب الوكالــة الصــادر مــن كتابــة العــدل الثانيــة‬\n      ‫شــمال محافظــة جــدة برقــم ‪ 52803‬يف ‪1433/6/14‬ه ـ واملخــول لــه يف‬\n      ‫الوكالــة حــق حضــور اجللســات واملرافعــة واملدافعــة والبيــع واإلفــراغ‬\n      ‫وقبــول الثمــن ‪...‬الــخ وبالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 33360147‬يف ‪1433/11/8‬ه ـ واملخــول لــه‬\n      ‫يف الوكالــة حــق البيــع والشــراء واإلفــراغ وقبولــه واالســتالم والتســليم‬\n      ‫ومراجعــة جميــع اجلهــات ذات العالقــة ‪ ...‬الــخ واملذكــورون هــم جميعــا‬\n      ‫ورثــة ‪ ...‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 9/100/259‬يف ‪1430/6/6‬ه ـ وبالوكالــة عــن ‪ ...‬و‪ ...‬ابنــي ‪...‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة‬\n      ‫برقــم ‪ 6149‬يف ‪1431/2/25‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع‬\n      ‫والشــراء واإلفــراغ وقبولــه واالســتالم والتســليم واملدافعــة واملخاصمــة ‪...‬‬\n      ‫الــخ وبالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة‬\n      ‫برقــم ‪ 5830‬يف ‪1431/2/22‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع‬\n      ‫والشــراء وقبــض الثمــن واالســتالم ‪ ..‬الــخ كمــا حضــر ‪ ...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابة العدل الثانية بغرب مكة برقم ‪ 33345186‬يف ‪1433/10/29‬هـ‬\n\n\n‫‪401‬‬\n\f‫واملخــول لــه يف الوكالــة حــق إقامــة الدعــاوى واملرافعة واملدافعة وســماع‬\n‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب‬\n‫اليمــن وإحضــار الشــهود واجلرح والتعديــل وقبول األحكام واالعتراض‬\n‫عليهــا وطلــب االســتئناف ‪...‬الــخ كمــا حضــر كل مــن ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬باألصالــة عــن نفســه وبصفتــه‬\n‫الناظــر علــى وصيــة والدتــه ‪ ...‬وذلــك مبوجــب الصــك الصــادر مــن كتابة‬\n‫العــدل الثانيــة مبكــة املكرمــة برقــم ‪ 64 /37‬يف ‪1410/12/26‬ه ـ و‪...‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬واملذكــورون مــع ‪...‬‬\n‫و‪ ...‬ولــدي ‪ ...‬هــم جميعــا ورثــة ‪ ...‬وذلــك مبوجــب صــك حصــر الورثــة‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 19‬يف ‪1427/6/5‬ه ـ كمــا حضــر ‪...‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬باألصالــة عــن نفســه‬\n‫وبالوكالــة عــن كل مــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪86384‬‬\n‫يف ‪1433/10/25‬ه ـ واملخــول لــه يف الوكالــة حــق البيع والشــراء وقبض‬\n‫الثمــن واالســتالم ‪ ..‬الــخ وبالوكالــة عــن ‪ ...‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بالطائــف برقــم ‪ 33304580‬يف ‪1433/10/14‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق البيــع والشــراء وقبــض الثمــن واالســتالم ‪ ..‬الــخ وبالوكالة‬\n‫عــن ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n‫برقــم ‪ 85741‬يف ‪1433/10/22‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع‬\n‫والشــراء وقبــض الثمــن واالســتالم ‪ ..‬الــخ وبالوكالــة عــن ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن‬\n\n\n                                                                                 ‫‪402‬‬\n\f      ‫كتابــة العــدل الثانيــة يف املدينــة املنــورة برقــم ‪ 33322740‬يف‬\n      ‫‪1433/10/21‬ه ـ واملخــول لــه يف الوكالــة حــق البيــع والشــراء وقبــض‬\n      ‫الثمــن واالســتالم ‪ ..‬الــخ واملذكــورون هــم جميعــا ورثــة ‪ ...‬وذلــك مبوجب‬\n      ‫صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة بالطائــف برقــم‬\n      ‫‪ 33207332‬يف ‪1433/4/24‬ه ـ وبســؤال املدعــي وكالــة عــن دعــواه‬\n      ‫ادعــى قائــا ‪ :‬لقــد تــويف مــورث موكلتــي ‪ ...‬وانحصــر ورثتــه يف والدتــه‬\n      ‫‪ ...‬ويف زوجته ‪ ...‬ويف أوالده البالغني ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ووذلك‬\n      ‫مبوجــب صــك حصــر ورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 9/5/5‬يف‬\n      ‫‪1413/1/7‬ه ـ ثــم توفيــت والدتــه ‪ ...‬بتاريــخ ‪1425/12/5‬ه ـ وانحصــر‬\n      ‫ورثتهــا يف أوالدهــا البالغــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬وذلــك‬\n      ‫مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 19‬يف‬\n      ‫‪1427/6/5‬ه ـ ثــم تــويف ‪ ...‬بتاريــخ ‪1430/5/14‬ه ـ وانحصــر ورثتــه يف‬\n      ‫أوالده البالغــن مــن زوجتــه املطلقــة منــه حــال حياتــه ‪ ...‬وهــم أمــا‪ ...‬و‪...‬‬\n      ‫و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ويف زوجتــه الباقيــة يف عصمتــه وعقــد نكاحــه‬\n      ‫إلــى حــن وفاتــه أمــة ‪ ...‬ويف ابنــه منهــا القاصــر ‪ ...‬وذلــك مبوجــب صــك‬\n      ‫حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 9/100/259‬يف‬\n      ‫‪1430/6/6‬ه ـ ثــم توفيــت ‪ ...‬بتاريــخ ‪1432/8/22‬ه ـ وانحصــر ورثتهــا يف‬\n      ‫أوالدها البالغني ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬وذلك مبوجب‬\n      ‫صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة بالطائــف برقــم‬\n      ‫‪ 33207332‬يف ‪1433/4/24‬ه ـ ولقــد تــرك مورثهــا ‪ ...‬عقــارا يقع يف ‪.....‬‬\n      ‫يف مكــة املكرمــة يحــده شــرقا ســكة نافــذة للجبــل وبهــا البــاب وغربــا‬\n      ‫ملــك ‪ ...‬وشــماال ملــك ‪ ...‬وجنوبــا ســكة نافــذة وذرعــه كمــا يلــي ‪ :‬طــول‬\n      ‫الضلــع الشــمالي ثمانيــة أمتــار وخمســة وثمانــون ســنتيمترا والضلــع‬\n\n\n‫‪403‬‬\n\f‫الشــرقي عشــرة أمتــار وثمانــون ســنتيمترا والضلــع اجلنوبــي عشــرة أمتــار‬\n‫وخمســة وعشــرون ســنتيمترا والضلــع الغربــي ثمانيــة أمتــار وخمســة‬\n‫ســنتيمترات وعــرض الســكة الشــرقية النافــذة للجبــل مــن جهتــي‬\n‫الشــمال واجلنــوب متــران وعــرض الســكة اجلنوبيــة النافــذة مــن جهــة‬\n‫الشــرق ثالثــة أمتــار وثالثــون ســنتيمترا ومــن جهــة الغــرب ثالثــة أمتــار‬\n‫واملســاحة اإلجماليــة ســبعة وثمانــون متــرا مربعــا وثمانيــة وأربعــون‬\n‫ســنتيمترا ( ‪87.48‬م‪ ) 2‬اململــوك لــه مبوجــب الصــك الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 22/182‬يف ‪1407/10/25‬ه ـ أطلــب احلكــم ببيــع‬\n‫العقــار املذكــور وإعطــاء كل وراث نصيبــه منــه هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليهــم أصالــة ووكالــة أجابــوا جميعــا بقولهــم ‪:‬‬\n‫مــا ذكــره املدعــي وكالــة يف دعــواه كلــه صحيــح جملــة وتفصيــا وال‬\n‫مانــع لدينــا مــن بيــع العقــار وإعطــاء كل وارث نصيبــه منه حســب الوجه‬\n‫الشــرعي هكــذا أجابــوا وقــرروا فجــرى ســؤال الطرفــن هــل علــى‬\n‫مورثكــم ديــن ؟ فأجابــوا جميعــا بأننــا ال نعلــم أن عليــه دينــا هكــذا‬\n‫قــرروا وبســؤالهم هــل لــه وصيــة ؟ فأجابــوا جميعــا ‪ :‬بأننــا ال نعلــم بــأن لــه‬\n‫وصيــة هكــذا قــرروا ثــم قــرر ‪ ...‬بقولــه ‪ :‬إن لوالدتــي ‪ ...‬وصيــة بالثلــث‬\n‫مــن مالهــا ثابتــة بالصــك الصــادر مــن كتابــة العــدل الثانيــة مبكــة‬\n‫املكرمــة برقــم ‪ 64 /37‬يف ‪1410/12/26‬ه ـ وأنــا الناظــر علــى الوصيــة‬\n‫مبوجــب الصــك املذكــور ومبــا أنهــا والــدة مالــك العقــار ‪ ...‬ولها الســدس‬\n‫مــن مالــه فإننــي أطلــب إخــراج ثلــث الســدس وإيداعــه يف بيــت املــال حلــن‬\n‫النظــر فيــه وتنفيــذه حســب الوصيــة هكــذا قــرر فجرى ســؤال الطرفني‬\n‫هــل لديكــم معارضــة يف وصيــة املذكــورة ؟ فأجابــوا جميعــا ‪ :‬بأنــه‬\n‫ليــس لدينــا معارضــة يف ذلــك مــا دام أن وصيتهــا ثابتــة لديكــم بالصــك‬\n\n\n                                                                                         ‫‪404‬‬\n\f      ‫املذكــور هكــذا قــرروا هــذا وقــد جــرى منــي االطــاع علــى جميــع‬\n      ‫الصكــوك املشــار إليهــا بعاليــه فوجدتهــا جميعــا مطابقــة ملــا عطــف‬\n      ‫عليهــا وقــد جــرى منــي االستفســار عــن صــك امللكيــة الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 22/182‬يف ‪1407/10/25‬ه ـ مــن قســم الســجالت يف‬\n      ‫احملكمــة وذلــك مبوجــب خطابنــا لهــم برقــم ‪ 33956071‬يف‬\n      ‫‪1433/5/22‬ه ـ فوردنــا اجلــواب منهــم شــرحا علــى خطابنــا املذكــور‬\n      ‫بأنــه ال يوجــد علــى ســجل الصــورة الضوئيــة املرفقــة ســوى مــا أحلــق عليــه‬\n      ‫حتــى تاريــخ ‪1433/5/23‬ه ـ أ‪.‬ه ـ فجــرى ســؤال الطرفــن هــل لديكــم‬\n      ‫مــا تريــدون إضافتــه ؟ فقالــوا ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه هكــذا‬\n      ‫قــرروا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى‬\n      ‫الصكــوك املشــار إليهــا بعاليــه ونظــرا ملطابقــة صــك ملكيــة العقــار‬\n      ‫املــراد بيعــه لســجله وســريان مفعولــه ومبــا أن الورثــة جميعــا يرغبــون بيــع‬\n      ‫العقــار محــل الدعــوى ونظــرا لكــون احلــق ال يعدوهــم ولكثــرة الورثــة‬\n      ‫وتعددهــم وصعوبــة قســمته بينهــم وجميعهــم بالغــون عــدا واحــد منهــم‬\n      ‫قاصــر ســنا وألنــه يصــار إلــى البيــع مــع عــدم إمــكان القســمة وحيــث‬\n      ‫قــرر الفقهــاء أنــه يجــب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة‬\n      ‫يك ُه فِ ي َهــا َأ ْي ‪:‬‬  ‫قــال يف مطالــب أولــي النهــى مــا نصــه « َو َمــنْ َد َعــا َشـ ِـر َ‬\n      ‫اضــي إ َلــى َب ْيـ ٍـع ُأ ْج ِبـ َـر َع َلــى ا ْل َب ْيـ ِـع َم َع ـ ُه َف ـ ِإنْ َأ َبــى َأ ْي ‪ْ :‬ام َت َنـ َـع‬\n                                                                                                                         ‫قِ ْسـ َـم ِة ال َّت َر ِ‬\n      ‫اكـ ٌـم َع َل ْيه َِمــا‪َ ،‬وقَ َسـ َـم الث ََّمـ َـن‬ ‫اع ـ ُه َح ِ‬      ‫يك ُه مِ ــنْ َب ْيـ ٍـع َم َع ـ ُه ِبيـ َـع َأ ْي ‪َ :‬ب َ‬\n                                                                                                                                     ‫َشـ ِـر ُ‬\n      ‫َصــا « ونظــرا لثبــوت وصيــة والــدة مالــك‬                                  ‫َب ْي َن ُه َمــا َع َلــى قَ ــدْ ِر حِ َّص َت ْيه َِمــا ن ًّ‬\n      ‫العقــار ‪ ...‬ونصيبهــا منــه الســدس لذلــك كلــه فقــد حكمــت ببيــع‬\n      ‫العقــار املوصــوف بعاليــه باملــزاد العلنــي وتســليم كل وارث نصيبــه منــه‬\n      ‫حســب الوجــه الشــرعي بعــد إحــراز الثلــث مــن نصيــب ‪ .....‬وهــو ثلــث‬\n\n\n‫‪405‬‬\n\f‫الســدس وحفظــه يف بيــت مــال احملكمــة لصالــح وصيتهــا الثابتــة شــرعا‬\n‫وبعــرض احلكــم علــى الطرفــن قــرروا جميعــا القناعــة بــه وألن مــن‬\n‫ضمــن الورثــة قاصــرا ووجــود وصيــة فقــد أمــرت برفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف مبكــة املكرمــة لتدقيــق احلكــم حســب‬\n‫التعليمــات‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/15‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n‫يــوم االثنــن ‪1434/1/12‬ه ـ افتتحــت اجللســة وكان قــد جــرى منــي‬\n‫بعــث املعاملــة حملكمــة االســتئناف مبكــة املكرمــة باخلطــاب رقــم‬\n‫‪ 33554752‬يف ‪1433/12/18‬ه ـ فعــادت إلــي بخطــاب فضيلــة رئيــس‬\n‫محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪ 332207878‬يف‬\n‫‪1434/1/6‬ه ـ وبرفقــه قــرار الدائــرة الثانيــة لألحــوال الشــخصية‬\n‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة برقــم ‪ 33482767‬يف ‪1433/12/29‬ه ـ املتضمــن بعــد‬\n‫املقدمــة مــا نصــه ‪ « :‬وبدراســة احلكــم وصــورة ضبطــه تقــرر إعادتهــا‬\n‫لفضيلــة حاكمهــا ملالحظــة‪ -:‬أن الورثــة مالكــي العقــار منهــم قاصــر‬\n‫ويف التركــة وصيــة وال بــد حينئــذ مــن حتقــق الغبطــة واملصلحــة جلهــة‬\n‫القاصــر والوصيــة يف الثمــن الــذي يبــاع بــه العقــار ومعرفــة الثمــن قبــل‬\n‫اإلذن ببيعــه فلمالحظــة ذلــك واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ ... .‬توقيعــه وختمــه‬\n‫الشــخصي ‪ .‬قاضــي اســتئناف د‪ ... /‬توقيعــه وختمــه الشــخصي ‪ .‬قاضــي‬\n‫اســتئناف ‪ ...‬موافــق علــى احلكــم موقــع يف األصــل ومجــاز ‪ ،‬وعليــه‬\n‫أجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم للعلــم النافــع والعمــل‬\n‫الصالــح بأنــه لــم يظهــر لــي ســوى مــا حكمــت بــه ملــا نــص عليــه الفقهــاء‬\n\n\n                                                                                      ‫‪406‬‬\n\f      ‫مــن أنــه يجــب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة كمــا‬\n      ‫ذكــرت ســابق ًا وكثــرة الورثــة وصعوبــة قســمة العقــار بينهــم وال يســوغ‬\n      ‫التوقــف عــن ذلــك لوجــود وصيــة أو لوجــود قاصــر ســن ًا مــا دام أن معظــم‬\n      ‫الورثــة يرغبــون يف بيــع العقــار وتســليم نصيبهــم منــه ومــع ذلــك فقــد‬\n      ‫أمــرت إيــداع نصيــب القاصــر يف بيــت مــال احملكمــة لصاحلــه لذلــك‬\n      ‫وبعــد اإلجابــة أمــرت بإحلــاق ذلــك يف صكــه وســجله وإعــادة املعاملــة‬\n      ‫حملكمــة االســتئناف مبكــة املكرمــة إلكمــال الزمهــا ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪1434/1/12‬هـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n      ‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ... /‬باحملكمــة العامــة مبكــة‬\n      ‫املكرمــة املــؤرخ يف ‪1433/11/21‬ه ـ واملســجل بعــدد ‪33461017‬‬\n      ‫املتضمــن دعــوى‪ ... /‬ضــد ورثــة‪ ... /‬يف اســتحقاق تركــة ‪ ،‬وبدراســة‬\n      ‫الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪407‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":398,"source_page_end":407,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"711a49b036cc0efcc6795fd188b76dec151e2ed56d969c8a0ef4900651aae35d","normalized_text_hash":"d633479f4e4ef6b61ccb5f4063353ce2731a1c86482af2d713f745e495a8ea74","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p398-33461017"}]$archive_payload$::jsonb) AS x LIMIT 25
